let _isLoadingMeetingConfig = false;
let _lastMeetingConfigLoadedAt = 0;
let _meetingConfigTimer = null;

function debouncedLoadCustomerMeetingConfig(delay = 600) {
  if (_meetingConfigTimer) clearTimeout(_meetingConfigTimer);
  _meetingConfigTimer = setTimeout(() => {
    loadCustomerMeetingConfig();
  }, delay);
}

async function loadCustomerMeetingConfig() {
  if (_isLoadingMeetingConfig) return;
  const now = Date.now();
  if (now - _lastMeetingConfigLoadedAt < 1200) {
    debouncedLoadCustomerMeetingConfig(1200);
    return;
  }
  _isLoadingMeetingConfig = true;
  _lastMeetingConfigLoadedAt = now;

  try {
    const cachedAvail = localStorage.getItem('halden_admin_meeting_availability');
    if (cachedAvail) {
      const p = JSON.parse(cachedAvail);
      if (Array.isArray(p) && p.length > 0) window.ADMIN_AVAILABILITY = p;
    }
    const cachedDis = localStorage.getItem('halden_disabled_calendar_dates');
    if (cachedDis) {
      const p = JSON.parse(cachedDis);
      if (Array.isArray(p)) window.DISABLED_CALENDAR_DATES = new Set(p);
    }
    
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      // 1. Fetch Availability
      const { data: availData } = await sb.from('admin_meeting_availability').select('*').order('day_of_week', { ascending: true });
      if (Array.isArray(availData) && availData.length > 0) {
        window.ADMIN_AVAILABILITY = availData.map(d => ({
          id: d.id,
          day_name: d.day_name,
          day_of_week: d.day_of_week,
          is_disabled: !!d.is_disabled,
          time_slots: Array.isArray(d.time_slots) ? d.time_slots : []
        }));
        localStorage.setItem('halden_admin_meeting_availability', JSON.stringify(window.ADMIN_AVAILABILITY));
      }
      
      // 2. Fetch Disabled Dates
      const { data: disData } = await sb.from('disabled_calendar_dates').select('date, is_disabled');
      if (Array.isArray(disData)) {
        window.DISABLED_CALENDAR_DATES = new Set(disData.filter(d => d.is_disabled !== false).map(d => String(d.date).trim()));
        localStorage.setItem('halden_disabled_calendar_dates', JSON.stringify([...window.DISABLED_CALENDAR_DATES]));
      }

      // 3. Fetch All Active Reservations (for capacity & overbooking check)
      const { data: resData } = await sb.from('reservations').select('id, date, status, proposed_meeting_times, meeting_times, selected_meeting_date, selected_meeting_time');
      if (Array.isArray(resData)) {
        window._allReservationsCache = resData;
      }

      // 4. Fetch All Scheduled Meetings (for booked slots)
      const { data: mtData } = await sb.from('meetings').select('id, date, time, timeEnd, time_end, status, reservationId, topic');
      if (Array.isArray(mtData)) {
        window._cachedBookedMeetings = mtData.filter(m => {
          const st = String(m.status || '').toLowerCase().trim();
          return st !== 'cancelled' && st !== 'rejected' && st !== 'completed';
        });
      }

      // 5. Fetch Other Customers' Active Selections (from active_selection_drafts & customer_cart)
      const curUid = (typeof getCartUserId === 'function' ? getCartUserId() : null) || window._clientSessionId;
      const otherDates = [];
      const otherSlots = [];

      // A. Active draft selections (Make a Reservation selections in other browser instances)
      try {
        const { data: draftData } = await sb.from('active_selection_drafts').select('*');
        if (Array.isArray(draftData)) {
          const thirtyMinsAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString();
          draftData.forEach(row => {
            if (String(row.id) === String(curUid)) return;
            if (row.updated_at && row.updated_at < thirtyMinsAgo) return;
            if (row.event_date) {
              const d = _normalizeDateKey(row.event_date) || row.event_date;
              if (!otherDates.includes(d)) otherDates.push(d);
            }
            if (row.meeting_date && row.meeting_time) {
              otherSlots.push({
                date: _normalizeDateKey(row.meeting_date) || row.meeting_date,
                time: row.meeting_time
              });
            }
          });
        }
      } catch (eDraft) { }

      // B. Other customers' cart selections
      try {
        const { data: cartData } = await sb.from('customer_cart').select('user_id, cart_data');
        if (Array.isArray(cartData)) {
          cartData.forEach(row => {
            if (String(row.user_id) === String(curUid)) return;
            try {
              const items = JSON.parse(row.cart_data || '[]');
              if (Array.isArray(items)) {
                items.forEach(it => {
                  if (it.date) {
                    const d = _normalizeDateKey(it.date) || it.date;
                    if (!otherDates.includes(d)) otherDates.push(d);
                  }
                  if (Array.isArray(it.meetingTimes)) {
                    it.meetingTimes.forEach(mt => {
                      if (mt.date) {
                        otherSlots.push({
                          date: _normalizeDateKey(mt.date) || mt.date,
                          time: mt.time || mt.timeRange || (mt.start + ' to ' + mt.end)
                        });
                      }
                    });
                  }
                });
              }
            } catch (e) { }
          });
        }
      } catch (eCart) { }

      window._otherUsersEventDates = otherDates;
      window._otherUsersMeetingSlots = otherSlots;
    }
  } catch (err) {
    console.warn('[Meeting Config] Load error:', err);
  } finally {
    _isLoadingMeetingConfig = false;
  }

  // Trigger UI re-evaluations (without triggering recursive active draft syncs)
  if (typeof renderMeetingTimes === 'function') renderMeetingTimes();
  if (typeof checkEventDateConflicts === 'function') checkEventDateConflicts();
  if (typeof renderCart === 'function') renderCart();
}

function navMeetingDay(dayId, direction) {
  if (!window.mtDayOffsets) window.mtDayOffsets = {};
  window.mtDayOffsets[dayId] = (window.mtDayOffsets[dayId] || 0) + (direction * 7);
  renderMeetingTimes();
}
window.navMeetingDay = navMeetingDay;

function selectMeetingSlot(dateStr, encodedSlotText) {
  if (typeof isDayHardDisabled === 'function' && isDayHardDisabled(dateStr)) {
    alert('This day of the week has been hard disabled for bookings and meetings.');
    return;
  }
  const slotText = decodeURIComponent(encodedSlotText);
  if (typeof window.isMeetingSlotBooked === 'function' && window.isMeetingSlotBooked(dateStr, slotText)) {
    if (typeof openErrorModal === 'function') openErrorModal("This meeting time slot has already been selected by another reservation and is no longer available.");
    else alert("This meeting time slot has already been selected.");
    return;
  }
  const evDateVal = document.getElementById('cpkg-date')?.value;
  if (evDateVal) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const evDateObj = new Date(evDateVal + 'T00:00:00');
    if (!isNaN(evDateObj.getTime())) {
      const diffDays = Math.ceil((evDateObj - today) / 86400000);
      const maxAllowedDays = Math.max(1, Math.floor(diffDays / 3));
      const maxDate = new Date(today);
      maxDate.setDate(today.getDate() + maxAllowedDays);
      const slotDateObj = new Date(dateStr + 'T00:00:00');
      if (slotDateObj > maxDate) {
        if (typeof openErrorModal === 'function') {
          openErrorModal("Meeting consultation dates cannot exceed 1/3 of the preparation timeframe towards your event date.");
        } else {
          alert("Meeting consultation dates cannot exceed 1/3 of the preparation timeframe towards your event date.");
        }
        return;
      }
    }
  }
  let start = '1:00 PM', end = '5:00 PM';
  if (slotText.includes(' to ')) {
    const p = slotText.split(' to ');
    start = p[0].trim();
    end = p[1].trim();
  } else if (slotText.includes(' - ')) {
    const p = slotText.split(' - ');
    start = p[0].trim();
    end = p[1].trim();
  }
  
  preferredMeetingTimes = [{
    date: dateStr,
    time: slotText,
    start: start,
    end: end,
    timeRange: slotText
  }];
  
  debouncedSyncCustomerActiveDraft();
  renderMeetingTimes();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
  if (typeof validateAllCpkgFields === 'function') validateAllCpkgFields();
  updateConflictSpeechBubble();
}
window.selectMeetingSlot = selectMeetingSlot;

let _syncDraftTimer = null;
function debouncedSyncCustomerActiveDraft() {
  if (_syncDraftTimer) clearTimeout(_syncDraftTimer);
  _syncDraftTimer = setTimeout(() => {
    syncCustomerActiveDraft();
  }, 400);
}
window.debouncedSyncCustomerActiveDraft = debouncedSyncCustomerActiveDraft;

async function syncCustomerActiveDraft() {
  try {
    const sb = window.supabaseClient || window.supabase;
    if (!sb) return;
    const curUid = (typeof getCartUserId === 'function' ? getCartUserId() : null) || window._clientSessionId;
    const evDate = document.getElementById('cpkg-date')?.value || '';
    const mt = (preferredMeetingTimes && preferredMeetingTimes.length > 0) ? preferredMeetingTimes[0] : null;
    const payload = {
      id: curUid,
      event_date: evDate ? (_normalizeDateKey(evDate) || evDate) : null,
      meeting_date: mt ? (_normalizeDateKey(mt.date) || mt.date) : null,
      meeting_time: mt ? (mt.time || mt.timeRange || (mt.start + ' to ' + mt.end)) : null,
      updated_at: new Date().toISOString()
    };
    await sb.from('active_selection_drafts').upsert(payload, { onConflict: 'id' });
    if (window._broadcastDraftChannel) {
      window._broadcastDraftChannel.send({
        type: 'broadcast',
        event: 'draft_selection_update',
        payload: { user_id: curUid, event_date: payload.event_date, meeting_date: payload.meeting_date, meeting_time: payload.meeting_time }
      });
    }
  } catch (e) { }
}
window.syncCustomerActiveDraft = syncCustomerActiveDraft;

function updateConflictSpeechBubble() {
  const bubble = document.getElementById('selection-conflict-bubble');
  const bubbleText = document.getElementById('selection-conflict-bubble-text');
  if (!bubble || !bubbleText) return;

  // Conflict speech bubble MUST only appear when Make a Reservation workspace overlay is open
  const ws = document.getElementById('custom-workspace-overlay');
  const isWsOpen = ws && (ws.classList.contains('open') || ws.style.display === 'block' || ws.style.display === 'flex');
  if (!isWsOpen) {
    bubble.style.display = 'none';
    return;
  }

  const dateInput = document.getElementById('cpkg-date');
  const evDateVal = dateInput?.value || '';
  const normDate = evDateVal ? (_normalizeDateKey(evDateVal) || evDateVal) : '';
  
  const isDateConflicted = normDate && (window._otherUsersEventDates || []).includes(normDate);
  
  const chosenMt = (preferredMeetingTimes && preferredMeetingTimes.length > 0) ? preferredMeetingTimes[0] : null;
  let isMtConflicted = false;
  if (chosenMt && chosenMt.date) {
    const mtDateNorm = _normalizeDateKey(chosenMt.date) || chosenMt.date;
    const mtTimeStr = chosenMt.time || chosenMt.timeRange || (chosenMt.start + ' to ' + chosenMt.end);
    isMtConflicted = (window._otherUsersMeetingSlots || []).some(s => s.date === mtDateNorm && s.time === mtTimeStr);
  }

  if (isDateConflicted || isMtConflicted) {
    let msg = 'The event date (or the meeting time) you selected is also being selected by someone else right now, if you want to ensure to secure your date, please checkout as soon as possible. Thank you.';
    if (isDateConflicted && isMtConflicted) {
      msg = 'The event date and meeting time you selected are also being selected by someone else right now, if you want to ensure to secure your date, please checkout as soon as possible. Thank you.';
    } else if (isDateConflicted) {
      msg = 'The event date you selected is also being selected by someone else right now, if you want to ensure to secure your date, please checkout as soon as possible. Thank you.';
    } else if (isMtConflicted) {
      msg = 'The meeting time you selected is also being selected by someone else right now, if you want to ensure to secure your date, please checkout as soon as possible. Thank you.';
    }
    bubbleText.textContent = msg;
    bubble.style.display = 'block';
  } else {
    bubble.style.display = 'none';
  }
}
window.updateConflictSpeechBubble = updateConflictSpeechBubble;

function checkEventDateConflicts() {
  const dateInput = document.getElementById('cpkg-date');
  const msgEl = document.getElementById('cpkg-date-conflict-msg');
  if (!dateInput) return;
  const val = dateInput.value;
  if (!val) {
    dateInput.classList.remove('glow-conflict-red', 'glow-conflict-yellow');
    if (msgEl) { msgEl.style.display = 'none'; msgEl.textContent = ''; }
    updateConflictSpeechBubble();
    return;
  }
  
  const normDate = _normalizeDateKey(val) || val;
  const resCount = (window._allReservationsCache || []).filter(r => {
    const rDate = _normalizeDateKey(r.date);
    const st = String(r.status || '').toLowerCase();
    return rDate === normDate && st !== 'cancelled' && st !== 'rejected';
  }).length;
  
  const isDateDisabled = window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(normDate);
  
  if (resCount >= 3 || isDateDisabled) {
    dateInput.classList.add('glow-conflict-red');
    dateInput.classList.remove('glow-conflict-yellow');
    if (msgEl) {
      msgEl.style.color = '#ef4444';
      msgEl.textContent = isDateDisabled 
        ? 'This date is disabled by admin for bookings. Please choose another date.'
        : 'Someone else took this date (fully booked: 3/3 reservations). Please select another date.';
      msgEl.style.display = 'block';
    }
    updateConflictSpeechBubble();
    return;
  }
  
  const isOtherSelecting = (window._otherUsersEventDates || []).includes(normDate);
  if (isOtherSelecting) {
    dateInput.classList.add('glow-conflict-yellow');
    dateInput.classList.remove('glow-conflict-red');
    if (msgEl) {
      msgEl.style.color = '#eab308';
      msgEl.textContent = 'Another customer currently has this date in their cart / selection.';
      msgEl.style.display = 'block';
    }
  } else {
    dateInput.classList.remove('glow-conflict-red', 'glow-conflict-yellow');
    if (msgEl) { msgEl.style.display = 'none'; msgEl.textContent = ''; }
  }
  // DO NOT call syncCustomerActiveDraft() from passive checkEventDateConflicts to prevent infinite loop
  updateConflictSpeechBubble();
}
window.checkEventDateConflicts = checkEventDateConflicts;

function subscribeToMeetingRealtimeSync() {
  try {
    const sb = window.supabaseClient || window.supabase;
    if (!sb || !sb.channel) return;
    sb.channel('customer_meeting_sync')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reservations' }, () => {
        debouncedLoadCustomerMeetingConfig(1000);
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'meetings' }, () => {
        debouncedLoadCustomerMeetingConfig(1000);
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'customer_cart' }, () => {
        debouncedLoadCustomerMeetingConfig(1000);
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'active_selection_drafts' }, payload => {
        const curUid = (typeof getCartUserId === 'function' ? getCartUserId() : null) || window._clientSessionId;
        if (payload && payload.new && String(payload.new.id) === String(curUid)) return;
        debouncedLoadCustomerMeetingConfig(800);
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'disabled_calendar_dates' }, () => {
        debouncedLoadCustomerMeetingConfig(1000);
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'admin_meeting_availability' }, () => {
        debouncedLoadCustomerMeetingConfig(1000);
      })
      .subscribe();

    if (!window._broadcastDraftChannel) {
      window._broadcastDraftChannel = sb.channel('halden_live_draft_broadcast');
      window._broadcastDraftChannel
        .on('broadcast', { event: 'draft_selection_update' }, payload => {
          const curUid = (typeof getCartUserId === 'function' ? getCartUserId() : null) || window._clientSessionId;
          if (payload && payload.payload && payload.payload.user_id !== curUid) {
            debouncedLoadCustomerMeetingConfig(800);
          }
        })
        .subscribe();
    }
  } catch (e) { }
}

// Gentle fallback polling every 12 seconds only when tab is visible
setInterval(() => {
  if (typeof document !== 'undefined' && !document.hidden) {
    debouncedLoadCustomerMeetingConfig(0);
  }
}, 12000);

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      loadCustomerMeetingConfig();
      subscribeToMeetingRealtimeSync();
      const el = document.getElementById('cpkg-date');
      if (el) {
        el.addEventListener('input', () => {
          checkEventDateConflicts();
          debouncedSyncCustomerActiveDraft();
        });
        el.addEventListener('change', () => {
          checkEventDateConflicts();
          debouncedSyncCustomerActiveDraft();
        });
      }
    });
  } else {
    loadCustomerMeetingConfig();
    subscribeToMeetingRealtimeSync();
    const el = document.getElementById('cpkg-date');
    if (el) {
      el.addEventListener('input', () => {
        checkEventDateConflicts();
        debouncedSyncCustomerActiveDraft();
      });
      el.addEventListener('change', () => {
        checkEventDateConflicts();
        debouncedSyncCustomerActiveDraft();
      });
    }
  }
}

// ==================== FOOD TASTING ELIGIBILITY HELPER ====================
window.isFoodTastingEligible = function (itemOrName) {
  if (!itemOrName) return false;
  const name = typeof itemOrName === 'string' ? itemOrName : (itemOrName.name || itemOrName.dish || '');
  if (!name || !name.trim()) return false;
  const lower = name.toLowerCase().trim();

  // 1. Explicit placeholder exclusions
  if (lower.includes('unlimited drink') || lower.includes('free choices') || lower.includes('free choice')) return false;

  // 2. Special items exclusion: master special items and child options
  if (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(itemOrName)) return false;
  if (typeof window.getSpecialParentKey === 'function' && window.getSpecialParentKey(itemOrName)) return false;
  if (lower.includes('mobile bar') || lower.includes('cocktail') || lower.includes('shooter') || lower.includes('mixes') || lower.includes('mocktail')) return false;
  if (lower.includes('ice cream machine') || lower.includes('ice cream bar')) return false;

  // 3. Equipment keywords
  const nonFoodKeywords = ['tong', 'chafing', 'spoon', 'fork', 'knife', 'plate', 'glass', 'cup', 'bowl', 'dispenser', 'table', 'chair', 'linen', 'napkin', 'tray', 'stove', 'warmer', 'equipment', 'pitcher', 'sandok', 'bucket', 'basket', 'cover', 'runner', 'skirt', 'food pan', 'water pan', 'standee', 'stylist', 'coordinator', 'booth', 'lighting', 'props', 'backdrop', 'audio', 'sound'];
  if (nonFoodKeywords.some(kw => lower.includes(kw))) return false;

  // 4. Catalog entry category verification
  const catPool = (Array.isArray(window.sbMenuItems) && window.sbMenuItems.length > 0) ? window.sbMenuItems : (typeof CAT !== 'undefined' ? CAT : []);
  const found = typeof itemOrName === 'object' && (itemOrName.cat || itemOrName.category) ? itemOrName : catPool.find(c => (c.name || '').toLowerCase() === lower);

  if (found) {
    const cCat = (found.cat || found.category || '').toLowerCase();
    const cIdent = (found.identify || '').toLowerCase();

    if (['equipment', 'decoration', 'entertainment', 'photography', 'special', 'addon', 'addons'].includes(cCat)) return false;
    if (['mobile_bar', 'drinks_package', 'ice_cream', 'special', 'mobile_bar_option'].includes(cIdent)) return false;
    if (found.is_special || found.isSpecialMaster || found.isMasterSpecial) return false;

    const validCats = ['food', 'dessert', 'drink', 'beverage', 'chicken', 'pork', 'beef', 'pasta', 'vegetables', 'shrimp', 'pancit / noodles', 'soup', 'rice'];
    return validCats.includes(cCat);
  }

  return true;
};


// ==================== PREMADE PACKAGE EXTRA ITEM & EVENT SETUP EQUIPMENT HELPERS ====================
// Helper: Excludes Event Setup equipment, auto-added food equipment rules, and 0-peso sub-options from additional charges
window.isEventSetupOrAutoEquipment = function (itemOrName, resObj) {
  if (!itemOrName) return false;
  let it = itemOrName;
  if (typeof it === 'string' && it.trim().startsWith('{') && it.trim().endsWith('}')) {
    try { it = JSON.parse(it); } catch (e) {}
  }
  if (typeof it === 'object' && it !== null) {
    if (it.isAutoAdded || it.isEventSetupEquipment || it.isSetupInherited || it.isFree || it.isFreebie || it.isFreeChoiceApplied || it.item_source === 'event_setup' || it.autoReason) {
      return true;
    }
  }
  const rawName = (typeof it === 'string' ? it : (it?.name || it?.item_name || '')).trim();
  const cleanName = rawName.toLowerCase();
  if (!cleanName || cleanName === 'free choices of food from menu') return true;

  if (resObj) {
    const fcName = (resObj.freeChoiceFoodItem || resObj.free_choice_food_item || '').toLowerCase().trim();
    if (fcName && fcName === cleanName) return true;
  }

  // 1. Check all Event Setups
  const setupsPool = [
    ...(typeof sbEventSetups !== 'undefined' && Array.isArray(sbEventSetups) ? sbEventSetups : []),
    ...(Array.isArray(window.sbEventSetups) ? window.sbEventSetups : []),
    ...(Array.isArray(window.EVENT_SETUPS) ? window.EVENT_SETUPS : [])
  ];
  for (const s of setupsPool) {
    if (!s) continue;
    if ((s.name || '').toLowerCase().trim() === cleanName) return true;
    let eqItems = s.equipment_items || s.items || [];
    if (typeof eqItems === 'string') {
      try { eqItems = JSON.parse(eqItems); } catch (e) { eqItems = []; }
    }
    if (Array.isArray(eqItems)) {
      if (eqItems.some(eq => String(typeof eq === 'object' ? (eq.name || eq.item_name) : eq).toLowerCase().trim() === cleanName)) {
        return true;
      }
    }
  }

  // 2. Check built-in Event Setup / Tableware / Buffet equipment names & keywords
  const setupEquipKeywords = [
    'tiffany chair', 'monoblock chair', 'chair cover', 'table cloth', 'table runner', 'table skirt',
    'fork', 'spoon', 'plate', 'dinner plate', 'dessert plate', 'dessert spoon', 'water glass', 'goblet',
    'cloth napkin', 'table napkin', 'chafing dish', 'food pan', 'food tray cover', 'serving fork',
    'serving spoon', 'serving tray', 'round serving tray', 'serving tongs', 'water pitcher', 'pitcher',
    'sandok', 'ladle', 'ice bucket', 'bread basket', 'round banquet table', 'rectangular table',
    'cocktail table', 'buffet table', 'soup bowl', 'soup spoon', 'dinner knife', 'steak knife',
    'salad plate', 'coffee cup', 'complete setup', 'buffet + styling', 'buffet only'
  ];
  if (setupEquipKeywords.some(kw => cleanName === kw || cleanName.includes(kw))) {
    return true;
  }

  // 3. Check catalog item category / identify
  const catItem = (typeof CAT !== 'undefined' && Array.isArray(CAT) ? CAT.find(c => (c.name || '').toLowerCase().trim() === cleanName || (it && it.id && c.id === it.id)) : null) ||
                  (typeof sbMenuItems !== 'undefined' && Array.isArray(sbMenuItems) ? sbMenuItems.find(m => (m.name || '').toLowerCase().trim() === cleanName || (it && it.id && m.id === it.id)) : null);
  const itemCat = ((catItem && (catItem.cat || catItem.category || catItem.identify)) || (typeof it === 'object' && (it.cat || it.category || it.identify)) || '').toLowerCase();
  const itemIdent = ((catItem && catItem.identify) || (typeof it === 'object' && it.identify) || '').toLowerCase();

  if (itemCat.includes('equipment') || itemCat.includes('setup') || itemIdent.includes('equipment') || itemIdent.includes('setup')) {
    return true;
  }
  if (itemIdent === 'mobile_bar_option' || itemIdent === 'ice_cream_option') {
    return true;
  }
  if (itemCat === 'drink' && itemIdent !== 'drinks_package' && itemIdent !== 'mobile_bar' && !cleanName.includes('unlimited drinks') && !cleanName.includes('mobile bar')) {
    return true;
  }

  // 4. If dynamic price is 0 (e.g. free sub-options), never treat as additional charge
  if (catItem) {
    const pax = parseInt((resObj && resObj.pax) || 50) || 50;
    const dp = (typeof getDynamicPrice === 'function') ? getDynamicPrice(catItem, pax) : (parseFloat(catItem.price || catItem.price_per_pax) || 0);
    if (!dp || dp <= 0) return true;
  } else if (typeof it === 'object' && it !== null && it.price !== undefined && (parseFloat(it.price) || 0) <= 0) {
    return true;
  }

  return false;
};

window.getPremadeBaseItemNames = function (resObj, fallbackObj) {
  const r = resObj || fallbackObj || {};
  const f = fallbackObj || {};
  const premadeName = (r.premadePackageName || r.premade_package_name || f.premadePackageName || f.premade_package_name || '').trim();
  const pkgName = (premadeName || r.package || r.packageName || r.package_name || f.package || f.packageName || '').trim();
  const pkgId = r.packageId || r.activePkgId || r.active_pkg_id || f.packageId || f.activePkgId || '';

  const expandSetupNames = (namesArr) => {
    const out = new Set(namesArr.map(n => String(n || '').toLowerCase().trim()).filter(Boolean));
    const setupsPool = [
      ...(typeof sbEventSetups !== 'undefined' && Array.isArray(sbEventSetups) ? sbEventSetups : []),
      ...(Array.isArray(window.sbEventSetups) ? window.sbEventSetups : []),
      ...(Array.isArray(window.EVENT_SETUPS) ? window.EVENT_SETUPS : [])
    ];
    if (setupsPool.length === 0) {
      try {
        const cachedEs = JSON.parse(localStorage.getItem('halden_event_setups_cache') || '[]');
        if (Array.isArray(cachedEs) && cachedEs.length > 0) setupsPool.push(...cachedEs);
      } catch(e) {}
    }
    setupsPool.forEach(s => {
      if (!s) return;
      if (s.name) out.add(String(s.name).toLowerCase().trim());
      let eqItems = s.equipment_items || s.items || [];
      if (typeof eqItems === 'string') {
        try { eqItems = JSON.parse(eqItems); } catch (e) { eqItems = []; }
      }
      if (Array.isArray(eqItems)) {
        eqItems.forEach(eq => {
          const eqName = typeof eq === 'object' ? (eq.name || eq.item_name) : eq;
          if (eqName) out.add(String(eqName).toLowerCase().trim());
        });
      }
    });
    return Array.from(out);
  };

  // Helper matching function
  const isMatch = (p) => {
    if (!p) return false;
    const pId = String(p.id || '');
    const pSlug = String(p.slug || '');
    const targetId = String(pkgId || '');
    if (targetId && (pId === targetId || pSlug === targetId || pId === 'sb-pkg-' + targetId || targetId === 'sb-pkg-' + pSlug || targetId === 'sb-pkg-' + pId)) {
      return true;
    }
    const pName = (p.name || p.title || '').toLowerCase().trim();
    if (premadeName && (pName === premadeName.toLowerCase() || pName.includes(premadeName.toLowerCase()) || premadeName.toLowerCase().includes(pName))) {
      return true;
    }
    if (pkgName && (pName === pkgName.toLowerCase() || (pName.length > 3 && (pkgName.toLowerCase().includes(pName) || pName.includes(pkgName.toLowerCase()))))) {
      return true;
    }
    return false;
  };

  // 1. First, search all pools for an object with an items array
  const allPools = [
    ...(Array.isArray(window.PKGS) ? window.PKGS : []),
    ...(typeof PKGS !== 'undefined' && Array.isArray(PKGS) ? PKGS : []),
    ...(Array.isArray(window.PREMADE_PACKAGES) ? window.PREMADE_PACKAGES : []),
    ...(Array.isArray(window.sbPremadePackages) ? window.sbPremadePackages : [])
  ];

  try {
    const cached = JSON.parse(localStorage.getItem('halden_premade_packages_cache') || '[]');
    if (Array.isArray(cached) && cached.length > 0) allPools.push(...cached);
  } catch(e) {}

  const pkgWithItems = allPools.find(p => isMatch(p) && ((Array.isArray(p.items) && p.items.length > 0) || (Array.isArray(p.freebieItems) && p.freebieItems.length > 0)));
  if (pkgWithItems) {
    const rawNames = [
      ...(Array.isArray(pkgWithItems.items) ? pkgWithItems.items : []),
      ...(Array.isArray(pkgWithItems.freebieItems) ? pkgWithItems.freebieItems : []),
      ...(Array.isArray(pkgWithItems.freebies) ? pkgWithItems.freebies : [])
    ];
    let sbPi = (typeof sbPremadePackageItems !== 'undefined' && Array.isArray(sbPremadePackageItems) && sbPremadePackageItems.length > 0)
      ? sbPremadePackageItems
      : (Array.isArray(window.sbPremadePackageItems) ? window.sbPremadePackageItems : []);
    if (sbPi.length === 0) {
      try {
        const cachedPi = JSON.parse(localStorage.getItem('halden_premade_package_items_cache') || '[]');
        if (Array.isArray(cachedPi) && cachedPi.length > 0) sbPi = cachedPi;
      } catch(e) {}
    }
    if (sbPi.length > 0 && (pkgWithItems.id || pkgWithItems.slug)) {
      const pId = String(pkgWithItems.id || '').replace(/^sb-pkg-/, '');
      const pSlug = String(pkgWithItems.slug || '');
      sbPi.filter(pi => String(pi.package_id) === pId || String(pi.package_id) === pSlug || String(pi.package_id) === String(pkgWithItems.id)).forEach(pi => {
        if (pi.item_name) rawNames.push(pi.item_name);
      });
    }
    return expandSetupNames(rawNames.map(n => String(typeof n === 'object' ? (n.name || n.item_name) : n)));
  }

  // 2. If no pkg has .items array, try matching with raw premade_packages + premade_package_items
  let sbPkgs = (typeof sbPremadePackages !== 'undefined' && Array.isArray(sbPremadePackages) && sbPremadePackages.length > 0)
    ? sbPremadePackages
    : (Array.isArray(window.sbPremadePackages) ? window.sbPremadePackages : []);
  let sbPkgItems = (typeof sbPremadePackageItems !== 'undefined' && Array.isArray(sbPremadePackageItems) && sbPremadePackageItems.length > 0)
    ? sbPremadePackageItems
    : (Array.isArray(window.sbPremadePackageItems) ? window.sbPremadePackageItems : []);

  if (sbPkgs.length === 0) {
    try {
      const cachedP = JSON.parse(localStorage.getItem('halden_premade_packages_cache') || '[]');
      if (Array.isArray(cachedP) && cachedP.length > 0) sbPkgs = cachedP;
    } catch(e) {}
  }
  if (sbPkgItems.length === 0) {
    try {
      const cachedPi = JSON.parse(localStorage.getItem('halden_premade_package_items_cache') || '[]');
      if (Array.isArray(cachedPi) && cachedPi.length > 0) sbPkgItems = cachedPi;
    } catch(e) {}
  }

  if (sbPkgs.length > 0 && sbPkgItems.length > 0) {
    const matchedSbPkg = sbPkgs.find(isMatch);
    if (matchedSbPkg) {
      const linked = sbPkgItems.filter(pi => String(pi.package_id) === String(matchedSbPkg.id) || String(pi.package_id) === String(matchedSbPkg.slug));
      if (linked.length > 0) {
        const names = [];
        linked.forEach(pi => {
          if (pi.item_name) names.push(String(pi.item_name).toLowerCase().trim());
          else if (pi.menu_item_id) {
            const mItem = (typeof sbMenuItems !== 'undefined' && Array.isArray(sbMenuItems) ? sbMenuItems.find(m => String(m.id) === String(pi.menu_item_id)) : null) ||
                          (typeof CAT !== 'undefined' && Array.isArray(CAT) ? CAT.find(c => String(c.id) === String(pi.menu_item_id)) : null);
            if (mItem && mItem.name) names.push(String(mItem.name).toLowerCase().trim());
          }
        });
        if (names.length > 0) return expandSetupNames(names);
      }
    }
  }

  // 3. Trigger background preload of premade packages and items if not yet cached
  if (window.supabaseClient && !window._sbPremadePreloading) {
    window._sbPremadePreloading = true;
    Promise.all([
      window.supabaseClient.from('premade_packages').select('*'),
      window.supabaseClient.from('premade_package_items').select('*'),
      window.supabaseClient.from('event_setups').select('*')
    ]).then(([pRes, piRes, esRes]) => {
      if (pRes && pRes.data) {
        window.sbPremadePackages = pRes.data;
        try { localStorage.setItem('halden_premade_packages_cache', JSON.stringify(pRes.data)); } catch(e) {}
      }
      if (piRes && piRes.data) {
        window.sbPremadePackageItems = piRes.data;
        try { localStorage.setItem('halden_premade_package_items_cache', JSON.stringify(piRes.data)); } catch(e) {}
      }
      if (esRes && esRes.data) {
        window.sbEventSetups = esRes.data;
        try { localStorage.setItem('halden_event_setups_cache', JSON.stringify(esRes.data)); } catch(e) {}
      }
    }).catch(() => {});
  }

  return [];
};

window.isReservationExtraPackageItem = function (resObj, rawItem, baseItemNames, fallbackObj) {
  if (!rawItem) return false;
  let it = rawItem;
  if (typeof it === 'string' && it.trim().startsWith('{') && it.trim().endsWith('}')) {
    try { it = JSON.parse(it); } catch(e) {}
  }
  const r = resObj || {};
  const f = fallbackObj || {};

  if (typeof window.isEventSetupOrAutoEquipment === 'function' && window.isEventSetupOrAutoEquipment(it, r.id ? r : f)) {
    return false;
  }

  const rawName = (typeof it === 'string' ? it : (it?.name || '')).trim();
  const cleanName = rawName.toLowerCase();
  if (!cleanName || cleanName === 'free choices of food from menu') return false;
  if (typeof it === 'object' && it !== null && (it.isFreeChoiceApplied || it.isFree)) return false;

  const bNames = Array.isArray(baseItemNames) ? baseItemNames : (typeof window.getPremadeBaseItemNames === 'function' ? window.getPremadeBaseItemNames(r, f) : []);
  if (bNames.length > 0 && bNames.includes(cleanName)) {
    return false;
  }

  if (typeof it === 'object' && it !== null && (it.isAdditional || it.addedAsExtra || it.isExtra)) {
    return true;
  }

  const fcName = (r.freeChoiceFoodItem || f.freeChoiceFoodItem || '').toLowerCase().trim();
  if (fcName && fcName === cleanName) return false;

  const rawSavedExtras = r.additional_items || r.additionalItems || r.execution_plan?.additional_items || r.executionPlan?.additional_items ||
                         f.additional_items || f.additionalItems || f.execution_plan?.additional_items || f.executionPlan?.additional_items;
  if (Array.isArray(rawSavedExtras)) {
    const cleanSavedExtras = rawSavedExtras.filter(ex => !(typeof window.isEventSetupOrAutoEquipment === 'function' && window.isEventSetupOrAutoEquipment(ex, r.id ? r : f)));
    const matched = cleanSavedExtras.some(ex => {
      const exName = (typeof ex === 'string' ? ex : (ex?.name || '')).toLowerCase().trim();
      return exName && exName === cleanName;
    });
    if (matched) return true;
    if (cleanSavedExtras.length > 0) return false;
  }

  if (bNames.length > 0 && !bNames.includes(cleanName)) {
    return true;
  }
  return false;
};

// Helper: Computes the clean extra items breakdown for a reservation on the Customer Portal
window.computeCustomerExtraItemsBreakdown = function (resObj) {
  const r = resObj || {};
  const pkgOriginRaw = String(r.package_origin || r.packageOrigin || r.package_type || r.pricingMode || r.pricing_mode || '').toLowerCase();
  const isCustom = pkgOriginRaw.includes('custom') || pkgOriginRaw.includes('item');
  if (isCustom && !r.premadePackageName && !r.premade_package_name) {
    return { extraItemsBreakdown: [], extraItemsTotal: 0 };
  }

  const pax = parseInt(r.pax) || 50;
  const baseNames = window.getPremadeBaseItemNames(r);
  const rawItems = (r.packageItems || r.package_items || []).map(ri => {
    if (typeof ri === 'string' && ri.trim().startsWith('{') && ri.trim().endsWith('}')) {
      try { return JSON.parse(ri); } catch (e) { return ri; }
    }
    return ri;
  });

  const savedExtras = r.additional_items || r.additionalItems || r.execution_plan?.additional_items || r.executionPlan?.additional_items || [];
  const breakdown = [];
  const seen = new Set();

  rawItems.forEach(it => {
    if (!window.isReservationExtraPackageItem(r, it, baseNames)) return;
    const rawName = (typeof it === 'string' ? it : (it?.name || '')).trim();
    const cleanName = rawName.toLowerCase();
    if (!cleanName || seen.has(cleanName)) return;
    seen.add(cleanName);

    const catItem = (typeof CAT !== 'undefined' && Array.isArray(CAT)) ? CAT.find(c => (c.name || '').toLowerCase().trim() === cleanName) : null;
    const matchedSaved = Array.isArray(savedExtras) ? savedExtras.find(ex => (typeof ex === 'object' && ex && (ex.name || '').toLowerCase().trim() === cleanName)) : null;
    let p = 0;
    if (catItem) {
      p = (typeof getDynamicPrice === 'function') ? (getDynamicPrice(catItem, pax) || 0) : (parseFloat(catItem.price) || 0);
    } else {
      p = parseFloat((typeof it === 'object' && it?.price) || (matchedSaved && matchedSaved.price)) || 0;
    }
    if (p > 0) {
      breakdown.push({ name: (catItem && catItem.name) || rawName, price: p });
    }
  });

  if (breakdown.length === 0 && Array.isArray(savedExtras) && savedExtras.length > 0) {
    const currentNames = rawItems.map(it => (typeof it === 'string' ? it : (it?.name || '')).toLowerCase().trim()).filter(Boolean);
    savedExtras.forEach(ex => {
      if (window.isEventSetupOrAutoEquipment(ex, r)) return;
      const exName = (typeof ex === 'string' ? ex : (ex?.name || '')).trim();
      const cleanEx = exName.toLowerCase();
      if (!cleanEx || seen.has(cleanEx)) return;
      if (currentNames.length > 0 && !currentNames.includes(cleanEx)) return;
      seen.add(cleanEx);

      const catItem = (typeof CAT !== 'undefined' && Array.isArray(CAT)) ? CAT.find(c => (c.name || '').toLowerCase().trim() === cleanEx) : null;
      let p = catItem ? ((typeof getDynamicPrice === 'function') ? (getDynamicPrice(catItem, pax) || 0) : (parseFloat(catItem.price) || 0)) : (parseFloat(ex?.price) || 0);
      if (p > 0) {
        breakdown.push({ name: (catItem && catItem.name) || exName, price: p });
      }
    });
  }

  const total = breakdown.reduce((sum, x) => sum + (x.price || 0), 0);
  return { extraItemsBreakdown: breakdown, extraItemsTotal: total };
};


// ── Overnight Time Confirmation Modal ─────────────────────────────────────
// Opens only when the Make a Reservation workspace is open on index.html.
// All text inside the modal is black in light mode and white in dark mode.
if (!window.showOvernightTimeConfirmModal) {
  window.showOvernightTimeConfirmModal = function({ startStr, endStr, onYes, onNo }) {
    const ws = document.getElementById('custom-workspace-overlay');
    if (ws && !ws.classList.contains('open')) return;

    let existing = document.getElementById('overnight-time-confirm-overlay');
    if (existing) existing.remove();

    const to12h = (t) => {
      if (!t) return '';
      let [h, m] = t.split(':').map(Number);
      if (isNaN(h)) return t;
      const ap = h >= 12 ? 'PM' : 'AM';
      h = h % 12 || 12;
      return h + ':' + String(m || '00').padStart(2, '0') + ' ' + ap;
    };

    const start12 = to12h(startStr);
    const end12 = to12h(endStr);
    const timeDisplay = start12 + ' - ' + end12;

    const isLight = document.documentElement.getAttribute('data-theme') === 'light' || document.body.getAttribute('data-theme') === 'light';
    const textColor = isLight ? '#000000' : '#ffffff';
    const cardBg = isLight ? '#faf7f2' : '#1e1a15';

    const overlay = document.createElement('div');
    overlay.id = 'overnight-time-confirm-overlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.75); z-index:9999999; display:flex; align-items:center; justify-content:center; padding:20px;';

    overlay.innerHTML = `
      <style>
        #overnight-time-confirm-overlay .overnight-modal-card { background: #1e1a15; color: #ffffff; }
        #overnight-time-confirm-overlay .overnight-modal-text { color: #ffffff !important; }
        [data-theme="light"] #overnight-time-confirm-overlay .overnight-modal-card { background: #faf7f2; color: #000000; }
        [data-theme="light"] #overnight-time-confirm-overlay .overnight-modal-text { color: #000000 !important; }
      </style>
      <div class="overnight-modal-card" style="background:${cardBg}; color:${textColor}; border:1.5px solid var(--gold, #c49a3c); border-radius:14px; max-width:480px; width:100%; padding:24px; box-shadow:0 10px 30px rgba(0,0,0,0.6); font-family:'DM Sans',sans-serif;">
        <div class="overnight-modal-text" style="font-size:12px; color:${textColor}; font-weight:700; text-transform:uppercase; letter-spacing:1px; margin-bottom:8px;">Event Time Frame Notice</div>
        <div class="overnight-modal-text" style="font-size:15px; font-weight:700; color:${textColor}; margin-bottom:12px;">The time you inputted is: <span class="overnight-modal-text" style="color:${textColor}; font-weight:800;">${timeDisplay}</span></div>
        <p class="overnight-modal-text" style="font-size:13px; line-height:1.6; color:${textColor}; margin:0 0 22px 0;">
          Are you pertaining to your event reaching the next day for your reservation (ie being overnight for example)? If so, then click yes to proceed. If that's not what you mean, then click no please, and you may go ahead and replace the end part of your time range.
        </p>
        <div style="display:flex; gap:12px; justify-content:flex-end;">
          <button id="btn-overnight-no" style="flex:1; padding:10px 16px; background:#4b5563; color:#ffffff; border:none; border-radius:8px; font-size:13px; font-weight:700; cursor:pointer;">No</button>
          <button id="btn-overnight-yes" style="flex:1; padding:10px 16px; background:#16a34a; color:#ffffff; border:none; border-radius:8px; font-size:13px; font-weight:700; cursor:pointer;">Yes</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    document.getElementById('btn-overnight-yes').onclick = function() {
      overlay.remove();
      if (typeof onYes === 'function') onYes();
    };

    document.getElementById('btn-overnight-no').onclick = function() {
      overlay.remove();
      if (typeof onNo === 'function') onNo();
    };
  };
}

window.toggleOther = function (id) { const select = document.getElementById(id); const otherInput = document.getElementById(id + '-other'); if (select && otherInput) { if (select.value === 'Others') { otherInput.style.display = 'block'; otherInput.focus(); } else { otherInput.style.display = 'none'; otherInput.value = ''; } } }; window.getSmartV = function (id) { if (id === 'cpkg-timeframe') { const start = document.getElementById('cpkg-timeframe-start')?.value || ''; const end = document.getElementById('cpkg-timeframe-end')?.value || ''; if (start && end) return start + ' - ' + end; return ''; } const el = document.getElementById(id); if (!el) return ''; if (el.tagName === 'SELECT') { if (el.value === 'Others') { const otherEl = document.getElementById(id + '-other'); return (otherEl?.value || '').trim(); } } return (el.value || '').trim(); }; window.smartAssign = function (id, val) { if (id === 'cpkg-timeframe') { if (val && val.includes('-')) { const parts = val.split('-'); const sEl = document.getElementById('cpkg-timeframe-start'); const eEl = document.getElementById('cpkg-timeframe-end'); if (sEl) sEl.value = parts[0].trim(); if (eEl) eEl.value = parts[1].trim(); } return; } const el = document.getElementById(id); if (!el) return; if (el.tagName === 'SELECT' && document.getElementById(id + '-other')) { const opts = Array.from(el.options).map(o => o.value); if (val && !opts.includes(val)) { el.value = 'Others'; const otherEl = document.getElementById(id + '-other'); if (otherEl) { otherEl.style.display = 'block'; otherEl.value = val; } } else { el.value = val || ''; const otherEl = document.getElementById(id + '-other'); if (otherEl) { otherEl.style.display = 'none'; otherEl.value = ''; } } return; } el.value = val || ''; };
window.formatTimeAMPM = function (timeStr) {
  if (!timeStr) return '';
  if (/am|pm/i.test(timeStr)) return timeStr;
  return timeStr.replace(/(\d{1,2}):(\d{2})/g, (match, h, m) => {
    let hour = parseInt(h, 10);
    const ampm = hour >= 12 ? 'PM' : 'AM';
    hour = hour % 12;
    if (hour === 0) hour = 12;
    return `${hour}:${m} ${ampm}`;
  });
};
window.getCatPriority = function (cat) {
  const c = (cat || '').toLowerCase();
  if (c === 'food') return 1;
  if (c === 'dessert' || c === 'desserts') return 2;
  if (c === 'drink' || c === 'drinks') return 3;
  if (c === 'decoration' || c === 'decor') return 4;
  if (c === 'equipment') return 5;
  return 6;
};
window.sortCatByFoodFirst = function (arr) {
  if (!Array.isArray(arr)) return [];
  return arr.sort((a, b) => {
    const pA = window.getCatPriority(a.cat);
    const pB = window.getCatPriority(b.cat);
    if (pA !== pB) return pA - pB;
    return (a.name || '').localeCompare(b.name || '');
  });
};

window.isReservationMalabon = function (resObj, extraData) {
  if (!resObj && !extraData) return false;
  const sources = [resObj, extraData].filter(Boolean);
  const fields = [
    'venue', 'venueName', 'venueAddress', 'venueAddr',
    'venue_name', 'venue_address', 'city', 'venueCity',
    'venueLocation', 'venue_location', 'location',
    'fullAddress', 'gpsVenueAddress', 'gps_venue_address'
  ];
  let combined = '';
  for (const s of sources) {
    if (typeof s === 'string') {
      combined += ' ' + s;
    } else if (typeof s === 'object') {
      for (const k of fields) {
        if (s[k]) combined += ' ' + String(s[k]);
      }
    }
  }
  return combined.toLowerCase().includes('malabon');
};

// Global Helper: Compute accurate Pricing Details breakdown matching admin meeting room
function computePricingDetails(resObj, currentPax, currentTotal) {
  const parseCur = v => { if (typeof v === 'number') return v; const c = String(v || '').replace(/[^\d.-]/g, ''); return parseFloat(c) || 0; };

  const cache = (typeof activeMeetingResCache !== 'undefined' && activeMeetingResCache && resObj && activeMeetingResCache.id && resObj.id && activeMeetingResCache.id === resObj.id)
    ? activeMeetingResCache
    : (resObj || (typeof activeMeetingResCache !== 'undefined' ? activeMeetingResCache : {}));

  const _cMode   = String(cache.pricingMode   || cache.pricing_mode   || '').toLowerCase();
  const _cOrigin = String(cache.packageOrigin || cache.package_origin || '').toLowerCase();
  const _cTiers  = cache.priceTiers || cache.price_tiers || (resObj && (resObj.priceTiers || resObj.price_tiers));
  const _cPph    = parseCur(cache.pricePerHead || cache.price_per_head || cache._pricePerPax || (resObj && (resObj.pricePerHead || resObj.price_per_head)) || 0);

  const isMajorlySet =
    _cMode.includes('majorly') || _cMode.includes('tiered') ||
    _cOrigin.includes('majorly') ||
    (Array.isArray(_cTiers) && _cTiers.length > 0);

  const isDynamic = !isMajorlySet && (
    _cMode.includes('dynamic') || _cMode.includes('per_head') ||
    _cOrigin.includes('dynamic') ||
    _cPph > 0
  );

  const origin = isMajorlySet ? 'majorly set' : (isDynamic ? 'dynamically set' : 'custom');
  const pax = parseInt(currentPax || cache._tempPax || cache.pax || (resObj && resObj.pax)) || 0;

  const _isMalabon = (typeof window.isReservationMalabon === 'function')
    ? window.isReservationMalabon(resObj || cache, cache)
    : false;

  let perHead = parseCur(
    cache.pricePerHead || cache.price_per_head || cache._pricePerPax ||
    (resObj && (resObj.pricePerHead || resObj.price_per_head)) || 0
  );

  const totalAmt = currentTotal || parseCur(cache._tempAmount || cache.amount || (resObj && resObj.amount) || 0);

  const storedOtc = parseCur(
    cache.outOfTownCharge || cache.out_of_town_charge ||
    (resObj && (resObj.outOfTownCharge || resObj.out_of_town_charge)) || 0
  );

  let serviceChargePct = parseCur(
    cache.service_charge_pct || cache.serviceChargePct ||
    (resObj && (resObj.service_charge_pct || resObj.serviceChargePct)) || 0
  );
  if (serviceChargePct < 0) serviceChargePct = 0;
  if (serviceChargePct > 99) serviceChargePct = 99;

  let basePrice = 0;
  let otc = 0;

  if (isMajorlySet) {
    const tiers = cache.priceTiers || cache.price_tiers || (resObj && (resObj.priceTiers || resObj.price_tiers)) || [];
    let matchTier = Array.isArray(tiers) ? tiers.find(t => parseInt(t.pax || t.label || t.min_pax) === pax) : null;
    if (!matchTier) {
      let pool = [
        ...(Array.isArray(window.sbPremadePackages) ? window.sbPremadePackages : []),
        ...(Array.isArray(window.PREMADE_PACKAGES) ? window.PREMADE_PACKAGES : []),
        ...(typeof PKGS !== 'undefined' && Array.isArray(PKGS) ? PKGS : [])
      ];
      if (pool.length === 0) {
        try {
          const cached = JSON.parse(localStorage.getItem('halden_premade_packages_cache') || '[]');
          if (Array.isArray(cached) && cached.length > 0) pool = cached;
        } catch(e) {}
      }
      const pkgName = cache.premadePackageName || cache.premade_package_name || cache.package || cache.packageName || cache.package_name || (resObj && (resObj.premadePackageName || resObj.premade_package_name || resObj.package || resObj.packageName)) || '';
      const pkgId = cache.packageId || cache.activePkgId || cache.active_pkg_id || (resObj && (resObj.packageId || resObj.activePkgId || resObj.active_pkg_id)) || '';
      const foundPkg = pool.find(p =>
        (pkgId && (String(p.id) === String(pkgId) || String(p.slug) === String(pkgId))) ||
        (pkgName && (p.name || p.title || '').toLowerCase() === pkgName.toLowerCase()) ||
        (pkgName && p.name && (pkgName.toLowerCase().includes(p.name.toLowerCase()) || p.name.toLowerCase().includes(pkgName.toLowerCase())))
      );
      if (foundPkg && Array.isArray(foundPkg.priceTiers || foundPkg.price_tiers)) {
        matchTier = (foundPkg.priceTiers || foundPkg.price_tiers).find(t => parseInt(t.pax || t.label || t.min_pax) === pax);
      }
    }

    if (matchTier && matchTier.price) {
      basePrice = parseCur(matchTier.price);
      otc = _isMalabon ? 0 : Math.round(basePrice * 0.05);
    } else {
      const savedBase = parseCur(cache.basePrice || cache.base_price || (resObj && (resObj.basePrice || resObj.base_price)) || 0);
      if (savedBase > 0) {
        basePrice = savedBase;
        otc = _isMalabon ? 0 : (storedOtc > 0 ? storedOtc : Math.round(basePrice * 0.05));
      } else {
        const storedExtra = parseCur(cache.additional_items_charge || cache.additionalItemsCharge || (resObj && (resObj.additional_items_charge || resObj.additionalItemsCharge)) || 0);
        const rawNet = Math.max(0, totalAmt - (storedOtc > 0 ? storedOtc : 0) - storedExtra);
        basePrice = serviceChargePct > 0 ? Math.round(rawNet / (1 + serviceChargePct / 100)) : rawNet;
        otc = _isMalabon ? 0 : (storedOtc > 0 ? storedOtc : 0);
      }
    }
  } else if (isDynamic) {
    if (perHead <= 0 && pax > 0 && totalAmt > 0) {
      const baseFromTotal = _isMalabon ? totalAmt : Math.round(totalAmt / 1.05);
      perHead = Math.round(baseFromTotal / pax);
    }
    basePrice = pax * perHead;
    otc = _isMalabon ? 0 : (storedOtc > 0 ? storedOtc : Math.round(basePrice * 0.05));
  } else {
    const rawNoOtc = (storedOtc > 0 && totalAmt >= storedOtc) ? (totalAmt - storedOtc) : totalAmt;
    basePrice = serviceChargePct > 0 ? Math.round(rawNoOtc / (1 + serviceChargePct / 100)) : rawNoOtc;
    otc = _isMalabon ? 0 : (storedOtc > 0 ? storedOtc : Math.round(basePrice * 0.05));
  }

  let extraItemsTotal = 0;
  const extraItemsBreakdown = [];
  if (isMajorlySet || isDynamic) {
    const itemsList = Array.isArray(cache.packageItems) ? cache.packageItems : (Array.isArray(resObj && resObj.packageItems) ? resObj.packageItems : (Array.isArray(cache.package_items) ? cache.package_items : (Array.isArray(resObj && resObj.package_items) ? resObj.package_items : [])));
    const baseItemNames = typeof window.getPremadeBaseItemNames === 'function' ? window.getPremadeBaseItemNames(cache, resObj) : [];

    itemsList.forEach(rawIt => {
      let it = rawIt;
      if (typeof it === 'string' && it.trim().startsWith('{') && it.trim().endsWith('}')) {
        try { it = JSON.parse(it); } catch(e) {}
      }
      const rawName = (typeof it === 'string') ? it : (it?.name || '');
      const cleanName = rawName.toLowerCase().trim();
      const catItem = (typeof CAT !== 'undefined' && Array.isArray(CAT)) ? CAT.find(c => (c.name || '').toLowerCase() === cleanName || (it && it.id && c.id === it.id)) : null;
      const itObj = catItem ? { ...catItem, ...(typeof it === 'object' ? it : {}) } : (typeof it === 'object' ? it : { name: rawName, price: 0 });
      const isSetupOrFree = (typeof window.isEventSetupOrAutoEquipment === 'function') && window.isEventSetupOrAutoEquipment(it, resObj || cache);
      const isExtra = !isSetupOrFree && (typeof window.isReservationExtraPackageItem === 'function'
        ? window.isReservationExtraPackageItem(cache, it, baseItemNames, resObj)
        : !!(it && (it.isAdditional || it.addedAsExtra || it.isExtra)));

      if (isExtra && itObj) {
        let itemP = 0;
        if (catItem) {
          itemP = (typeof getDynamicPrice === 'function') ? getDynamicPrice(catItem, pax) : (parseFloat(catItem.price) || 0);
        } else {
          const savedExtras = (cache && (cache.additional_items || cache.additionalItems || cache.execution_plan?.additional_items || cache.executionPlan?.additional_items)) ||
                              (resObj && (resObj.additional_items || resObj.additionalItems || resObj.execution_plan?.additional_items || resObj.executionPlan?.additional_items)) || [];
          const matchedSaved = Array.isArray(savedExtras) ? savedExtras.find(ex => (typeof ex === 'object' && ex && (ex.name || '').toLowerCase().trim() === cleanName)) : null;
          itemP = parseFloat((it && it.price) || itObj.price || (matchedSaved && matchedSaved.price)) || 0;
        }
        if (!Number.isFinite(itemP) || isNaN(itemP)) itemP = 0;
        if (itemP > 0) {
          extraItemsTotal += itemP;
          extraItemsBreakdown.push({
            name: (catItem && catItem.name) || rawName || itObj.name || 'Extra Item',
            price: itemP
          });
        }
      }
    });

    if (extraItemsBreakdown.length === 0) {
      const savedExtras = (cache && (cache.additional_items || cache.additionalItems || cache.execution_plan?.additional_items || cache.executionPlan?.additional_items)) ||
                          (resObj && (resObj.additional_items || resObj.additionalItems || resObj.execution_plan?.additional_items || resObj.executionPlan?.additional_items));
      if (Array.isArray(savedExtras) && savedExtras.length > 0) {
        const currentNames = itemsList.map(x => (typeof x === 'string' ? x : (x?.name || '')).toLowerCase().trim()).filter(Boolean);
        savedExtras.forEach(ex => {
          if (typeof window.isEventSetupOrAutoEquipment === 'function' && window.isEventSetupOrAutoEquipment(ex, resObj || cache)) return;
          const exName = typeof ex === 'string' ? ex : (ex?.name || '');
          const cleanEx = exName.toLowerCase().trim();
          if (cleanEx && (currentNames.length === 0 || currentNames.includes(cleanEx))) {
            const catItem = (typeof CAT !== 'undefined' && Array.isArray(CAT)) ? CAT.find(c => (c.name || '').toLowerCase() === cleanEx) : null;
            let p = catItem ? ((typeof getDynamicPrice === 'function') ? getDynamicPrice(catItem, pax) : (parseFloat(catItem.price) || 0)) : (parseFloat(ex?.price) || 0);
            if (!Number.isFinite(p) || isNaN(p)) p = 0;
            if (p > 0) {
              extraItemsTotal += p;
              extraItemsBreakdown.push({ name: (catItem && catItem.name) || exName, price: p });
            }
          }
        });
      } else if (itemsList.length === 0 && (cache.additional_items_charge || cache.additionalItemsCharge || (resObj && (resObj.additional_items_charge || resObj.additionalItemsCharge)))) {
        extraItemsTotal = parseFloat(cache.additional_items_charge || cache.additionalItemsCharge || (resObj && (resObj.additional_items_charge || resObj.additionalItemsCharge))) || 0;
      }
    }
  }

  basePrice = Number.isFinite(basePrice) ? basePrice : 0;
  extraItemsTotal = Number.isFinite(extraItemsTotal) ? extraItemsTotal : 0;
  otc = Number.isFinite(otc) ? otc : 0;

  const serviceChargeAmt = (serviceChargePct > 0 && (basePrice + extraItemsTotal) > 0) ? Math.round((basePrice + extraItemsTotal) * (serviceChargePct / 100)) : 0;
  const finalTotal = basePrice + otc + extraItemsTotal + serviceChargeAmt;

  return {
    origin,
    isMajorlySet,
    isDynamic,
    pax,
    perHead,
    basePrice,
    extraItemsTotal,
    extraItemsBreakdown,
    otc,
    serviceChargePct,
    serviceChargeAmt,
    finalTotal: Number.isFinite(finalTotal) ? finalTotal : 0,
    grandTotal: Number.isFinite(finalTotal) ? finalTotal : 0
  };
}
window.computePricingDetails = computePricingDetails;
