window.openErrorModal = function (msg, customTitle) {
  console.log('Opening Error Modal:', msg);
  const overlay = document.getElementById('error-overlay');
  const msgEl = document.getElementById('error-msg');
  const titleEl = document.getElementById('error-title');
  if (overlay && msgEl) {
    if (titleEl) {
      titleEl.textContent = customTitle || 'A slight mishap';
    }
    // Format as bullet list if the message contains multiple lines
    const lines = msg.split(/\n+/).map(s => s.trim()).filter(s => s.length > 0);
    if (lines.length > 1) {
      // Build a nice bullet list
      const ul = document.createElement('ul');
      ul.style.cssText = 'text-align:left; list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:8px;';
      lines.forEach(line => {
        const li = document.createElement('li');
        li.style.cssText = 'display:flex; align-items:flex-start; gap:8px; font-size:13px;';
        const bullet = document.createElement('span');
        bullet.textContent = '•';
        bullet.style.cssText = 'color:var(--gold, #cba153); font-size:16px; line-height:1.2; flex-shrink:0;';
        const text = document.createElement('span');
        text.textContent = line.replace(/^[•\-]\s*/, '');
        li.appendChild(bullet);
        li.appendChild(text);
        ul.appendChild(li);
      });
      msgEl.innerHTML = '';
      msgEl.appendChild(ul);
    } else {
      msgEl.textContent = msg;
    }
    overlay.classList.add('on');
    overlay.style.display = 'flex'; // Force display
  } else {
    console.error('Error modal elements not found!', { overlay, msgEl });
    alert(msg);
  }
};

window.closeErrorModal = function () {
  const overlay = document.getElementById('error-overlay');
  if (overlay) {
    overlay.classList.remove('on');
    overlay.style.display = 'none'; // Re-hide
  }
};

