// ===== SUPABASE EQUIPMENT LOADER =====
// Fetches live equipment from the Supabase equipment_inventory table,
// removes the hardcoded eq1-eq10 items from CAT, and injects the
// real inventory so both the Full Catalog and Custom Package Builder
// always reflect what's actually in the database.
async function loadEquipmentFromSupabase() {
  try {
    // Supabase must already be initialized on the page (via index.html script block)
    const supabaseClient = window.supabaseClient || window.supabase;
    if (!supabaseClient) {
      console.warn('[Equipment Loader] Supabase client not found on window. Skipping live equipment load.');
      return;
    }

    const { data: rows, error } = await supabaseClient
      .from('equipment_inventory')
      .select('id, name, category, type, total_qty, available_qty, status, condition, value, notes, price, pricing_type, allocation_type, description, image_url, is_disabled, is_batch, batch_id, parent_asset_id')
      .neq('status', 'disposed')
      .neq('is_disabled', true)
      .order('category', { ascending: true })
      .order('name', { ascending: true });

    if (error) {
      console.error('[Equipment Loader] Supabase error:', error.message);
      return;
    }

    if (!rows || rows.length === 0) {
      console.warn('[Equipment Loader] No equipment rows returned from Supabase.');
      return;
    }

    // 1. Strip out ALL hardcoded equipment items (eq1-eq10, etc.)
    CAT = CAT.filter(item => item.cat !== 'equipment');

    // 2. Map each Supabase row → CAT item format (excluding decorations, batches, and special overrides)
    const filteredRows = rows.filter(row => {
      const isSoupBowlP20 = row.name.toLowerCase() === 'soup bowl' && (parseFloat(row.price) === 20 || (row.description && row.description.toLowerCase().includes('ceramic')));
      const isDecoration = (row.category || '').toLowerCase().includes('decoration');
      const isBatch = row.is_batch === true ||
                      row.is_batch === 'true' ||
                      !!row.batch_id ||
                      !!row.parent_asset_id ||
                      /\(BATCH/i.test(row.name || '') ||
                      /\bBATCH-\d+/i.test(row.name || '') ||
                      (row.name || '').toLowerCase().includes('(batch');
      return !isSoupBowlP20 && !isDecoration && !isBatch;
    });

    const supabaseEquipItems = filteredRows.map(row => {
      const isShotGlass = row.name.toLowerCase() === 'shot glass';
      const isSandok = row.name.toLowerCase() === 'sandok';
      const isFoodCover = row.name.toLowerCase().includes('food tray cover') || row.name.toLowerCase().includes('food pan cover');

      let itemPrice = parseFloat(row.price) || 0;
      if (isShotGlass || isSandok) itemPrice = 15;
      else if (isFoodCover) itemPrice = 20;

      // Build a readable description from the database fields if description is missing
      const qtyText = `${row.available_qty ?? row.total_qty ?? 0} units available`;
      const condText = row.condition ? ` • Condition: ${row.condition}` : '';
      const notesText = row.notes ? ` • ${row.notes}` : '';
      const typeText = row.type ? `${row.type} ` : '';
      const defaultDesc = `${typeText}(${qtyText}${condText}${notesText})`;

      // Sanitize description to strip internal [SHOPPING_UNIT:...] tags from customer display
      const rawDesc = row.description ? row.description.replace(/\s*\[SHOPPING_UNIT:[^\]]+\]/gi, '').trim() : '';
      const finalDesc = rawDesc || defaultDesc;

      return {
        id: `eq-sb-${row.id}`,
        supabaseId: row.id,
        name: row.name,
        cat: 'equipment',
        category: row.category,
        type: row.type,
        image: row.image_url || getEquipmentImage(row.category, row.type, row.name),
        image_url: row.image_url || null,
        price: itemPrice,
        desc: finalDesc,
        rating: 4.5,
        reviews: 0,
        totalQty: row.total_qty || 0,
        availableQty: row.available_qty || 0,
        status: row.status,
        condition: row.condition,
        pricingType: (isShotGlass || isSandok) ? 'per_pax' : (row.pricing_type || 'fixed'),
        allocationType: (isShotGlass || isSandok) ? 'per_pax' : (row.allocation_type || 'fixed')
      };
    });

    // 3. Merge into CAT
    CAT.push(...supabaseEquipItems);

    // 4. Re-render both catalog views
    renderFullCatalog();
    renderCat();

    console.log(`[Equipment Loader] ✅ Loaded ${supabaseEquipItems.length} equipment items from Supabase.`);

  } catch (err) {
    console.error('[Equipment Loader] Unexpected error:', err);
  }
}

// Helper: pick a relevant stock image based on category/type/name
function getEquipmentImage(category, type, name) {
  const t = (type || '').toLowerCase();
  const c = (category || '').toLowerCase();
  const n = (name || '').toLowerCase();
  const combined = `${c} ${t} ${n}`;

  if (combined.includes('chair')) return 'https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('table')) return 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('linen') || combined.includes('cloth') || combined.includes('napkin') || combined.includes('runner') || combined.includes('cover')) return 'https://images.unsplash.com/photo-1530103043477-c7f44b4131de?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('plate') || combined.includes('bowl') || combined.includes('saucer')) return 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('glass') || combined.includes('flute') || combined.includes('cup')) return 'https://images.unsplash.com/photo-1571506165871-ee72a35bc9d4?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('spoon') || combined.includes('fork') || combined.includes('knife') || combined.includes('tong') || combined.includes('serving') || combined.includes('cutlery') || combined.includes('silverware') || combined.includes('flatware')) return 'https://images.unsplash.com/photo-1578916171728-46686eac8d58?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('tray')) return 'https://images.unsplash.com/photo-1576402187878-974f70c890a5?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('chafing') || combined.includes('warmer') || combined.includes('pan') || combined.includes('lid') || combined.includes('dish')) return 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('basket') || combined.includes('bucket') || combined.includes('pitcher')) return 'https://images.unsplash.com/photo-1466027397211-20d0f2449a3e?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('av') || combined.includes('speaker') || combined.includes('microphone')) return 'https://images.unsplash.com/photo-1558231580-994d580436a5?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('lighting') || combined.includes('light')) return 'https://images.unsplash.com/photo-1514300074170-efdfc066741d?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('power') || combined.includes('generator')) return 'https://images.unsplash.com/photo-1504328345606-18bbc8c9d7d1?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('tent')) return 'https://images.unsplash.com/photo-1523413363574-c3c4e30467c0?auto=format&fit=crop&q=80&w=800';

  // Generic fallback
  return 'https://images.unsplash.com/photo-1466027397211-20d0f2449a3e?auto=format&fit=crop&q=80&w=800';
}

