// ============================================================================
// SHARED DISTANCE FEES & OUT OF TOWN ENGINE
// Office Reference: 18 Basilio St, Manila, Metro Manila (14.6138, 120.9948)
// ============================================================================
const HALDEN_OFFICE_COORDS = { lat: 14.6138, lon: 120.9948, address: "18 Basilio St, Manila, Metro Manila" };
window.HALDEN_OFFICE_COORDS = HALDEN_OFFICE_COORDS;

function computeDistanceKm(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth's mean radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}
window.computeDistanceKm = computeDistanceKm;

function getDistanceRules() {
  if (Array.isArray(window.DISTANCE_FEE_RULES) && window.DISTANCE_FEE_RULES.length > 0) {
    return window.DISTANCE_FEE_RULES;
  }
  try {
    const cached = localStorage.getItem('halden_distance_fee_rules');
    if (cached) {
      window.DISTANCE_FEE_RULES = JSON.parse(cached);
      return window.DISTANCE_FEE_RULES;
    }
  } catch(e) {}
  const defaults = [
    {
      id: 'default-5pct-rule',
      rule_name: 'Original Out of Town Rule',
      min_km: 0,
      percentage: 5,
      is_default_rule: true,
      is_disabled: false
    }
  ];
  window.DISTANCE_FEE_RULES = defaults;
  return defaults;
}
window.getDistanceRules = getDistanceRules;

async function loadDistanceFeeRulesFromSupabase() {
  const sb = window.supabaseClient || window.supabase;
  let loaded = [];
  if (sb) {
    try {
      const { data, error } = await sb.from('distance_fee_rules').select('*').order('min_km', { ascending: true });
      if (!error && Array.isArray(data) && data.length > 0) {
        loaded = data;
      }
    } catch(e) {
      console.warn('Could not load distance_fee_rules from Supabase:', e);
    }
  }
  if (!loaded.length) {
    try {
      const cached = localStorage.getItem('halden_distance_fee_rules');
      if (cached) loaded = JSON.parse(cached);
    } catch(e) {}
  }
  if (!loaded.length) {
    loaded = [
      {
        id: 'default-5pct-rule',
        rule_name: 'Original Out of Town Rule',
        min_km: 0,
        percentage: 5,
        is_default_rule: true,
        is_disabled: false
      }
    ];
  }
  if (!loaded.some(r => r.is_default_rule)) {
    loaded.unshift({
      id: 'default-5pct-rule',
      rule_name: 'Original Out of Town Rule',
      min_km: 0,
      percentage: 5,
      is_default_rule: true,
      is_disabled: false
    });
  }
  window.DISTANCE_FEE_RULES = loaded;
  try { localStorage.setItem('halden_distance_fee_rules', JSON.stringify(loaded)); } catch(e) {}
  return loaded;
}
window.loadDistanceFeeRulesFromSupabase = loadDistanceFeeRulesFromSupabase;

function getDistanceFeeRate(venueAddr = '', coords = null) {
  const rules = getDistanceRules();
  const defaultRule = rules.find(r => r.is_default_rule) || { percentage: 5, is_disabled: false };

  // 1. Original 5% rule takes top priority if not disabled
  if (!defaultRule.is_disabled) {
    return {
      percentage: defaultRule.percentage != null ? parseFloat(defaultRule.percentage) : 5,
      isPriorityDefault: true,
      ruleName: defaultRule.rule_name || 'Original 5% Default Rule',
      distKm: null
    };
  }

  // 2. Original rule is disabled -> match custom distance rules based on km from 18 Basilio St, Manila
  const activeCustom = rules
    .filter(r => !r.is_default_rule && !r.is_disabled && r.min_km > 0)
    .sort((a,b) => (parseFloat(b.min_km) || 0) - (parseFloat(a.min_km) || 0));

  if (activeCustom.length === 0) {
    return { percentage: 0, isPriorityDefault: false, ruleName: 'No active distance rule', distKm: null };
  }

  let distKm = 0;
  const c = coords || window.lastMapCoords;
  if (c && (c.lat != null || c.latitude != null) && (c.lon != null || c.lng != null || c.longitude != null)) {
    const lat = parseFloat(c.lat != null ? c.lat : c.latitude);
    const lon = parseFloat(c.lon != null ? c.lon : (c.lng != null ? c.lng : c.longitude));
    distKm = computeDistanceKm(HALDEN_OFFICE_COORDS.lat, HALDEN_OFFICE_COORDS.lon, lat, lon);
  } else if (venueAddr) {
    const kmMatch = String(venueAddr).match(/(\d+)\s*(?:km|kilometers?)/i);
    if (kmMatch) {
      distKm = parseFloat(kmMatch[1]);
    }
  }

  const matched = activeCustom.find(r => distKm >= parseFloat(r.min_km));
  if (matched) {
    return {
      percentage: parseFloat(matched.percentage) || 0,
      isPriorityDefault: false,
      ruleName: matched.rule_name || `${matched.min_km} km Rule`,
      distKm: Math.round(distKm)
    };
  }

  return { percentage: 0, isPriorityDefault: false, ruleName: 'Within Base Range', distKm: Math.round(distKm) };
}
window.getDistanceFeeRate = getDistanceFeeRate;

