// ===== PACKAGES =====
function renderPkgs() {
  const grid = document.getElementById('pkgs-grid');
  if (!grid) return;

  let items = PKGS.filter(p => !p.hidden);

  // Occasion Filter
  if (curPkgOccasion !== 'all') {
    items = items.filter(p => {
      const occ = p.occasion.toLowerCase();
      const cur = curPkgOccasion.toLowerCase();
      // Match simple keywords
      if (cur === 'birthday' && (occ.includes('birthday') || occ.includes('debut'))) return true;
      return occ.includes(cur);
    });
  }

  // Search Filter
  if (pkgSearch.trim() !== '') {
    const q = pkgSearch.toLowerCase();
    items = items.filter(p => p.name.toLowerCase().includes(q) || p.desc.toLowerCase().includes(q) || p.occasion.toLowerCase().includes(q));
  }

  if (items.length === 0) {
    grid.innerHTML = `<div style="grid-column:1/-1; text-align:center; padding:60px 20px; color:var(--text-dim);">
      <div style="font-size:16px; font-weight:700; color:var(--text);">No packages found</div>
      <div style="font-size:13px; margin-top:4px;">Try adjusting your filter or search terms.</div>
    </div>`;
    return;
  }

  grid.innerHTML = items.map(p => {
    let priceDisplay = '';
    let tiers = p.priceTiers || p.price_tiers || [];
    if (typeof tiers === 'string') {
      try { tiers = JSON.parse(tiers); } catch (e) { tiers = []; }
    }
    if (Array.isArray(tiers) && tiers.length > 0) {
      const sortedTiers = [...tiers].sort((a, b) => (Number(a.price) || 0) - (Number(b.price) || 0));
      priceDisplay = `₱${(Number(sortedTiers[0].price) || 0).toLocaleString()} starting`;
    } else if (p.pricingMode === 'per_head') {
      priceDisplay = `₱${(p.pricePerHead || 0).toLocaleString()} / head`;
    } else {
      const fp = p.fixedPrice || 0;
      priceDisplay = `₱${fp.toLocaleString()} fixed`;
    }

    return `
      <div class="cat-card pkg-catalog-card">
        <div class="cat-thumb" style="background:#ffffff url('${p.image}') center/contain no-repeat; height:240px;">
          <div class="pkg-cat-badge">${p.badge || 'Dynamically Set'}</div>
        </div>
        <div class="cat-info">
          <div class="cat-n">${p.name}</div>
          <div class="cat-d">${p.desc}</div>
          <ul class="pkg-inc-list">${(p.items || []).slice(0, 6).map(it => `<li>${it}</li>`).join('')}${(p.items || []).length > 6 ? `<li style="list-style:none; opacity:0.6; padding-left:0;">+ ${(p.items || []).length - 6} more items...</li>` : ''}</ul>
          <div class="pkg-footer-row" style="margin-top:15px;">
            <div class="cat-p">${priceDisplay}</div>
            <button class="btn-add" onclick="openPremadePackageModal('${p.id}')">View Details</button>
          </div>
        </div>
      </div>`;
  }).join('');
}
window.renderPkgs = renderPkgs;


function getEquipmentAllocatedQty(item, pax, pkgItems) {
  if (!item) return 1;
  // If user explicitly specified customQty, use it! (1 to 999, locked)
  if (item.customQty !== undefined && item.customQty !== null && parseInt(item.customQty) > 0) {
    let q = parseInt(item.customQty, 10);
    if (isNaN(q) || q < 1) q = 1;
    if (q > 999) q = 999;
    return q;
  }

  const p = parseInt(pax) || (parseInt(document.getElementById('cpkg-pax')?.value) || 50);
  const rule = String(item.allocationType || item.allocationRule || item.pricingType || '').toLowerCase().trim();
  const nameLow = String(item.name || '').toLowerCase().trim();

  // Pattern matching per_X_per_item
  const mPerItem = rule.match(/^per_(\d+)_per_item:(.+)$/i);
  if (mPerItem) return Math.max(1, parseInt(mPerItem[1]) || 1);

  if (rule === 'per_pax' || rule === 'per pax') {
    return Math.max(1, p);
  } else if (rule === 'per_5_pax') {
    return Math.max(1, Math.ceil(p / 5));
  } else if (rule === 'per_8_pax') {
    return Math.max(1, Math.ceil(p / 8));
  } else if (rule === 'per_10_pax') {
    return Math.max(1, Math.ceil(p / 10));
  } else if (rule === 'per_20_pax') {
    return Math.max(1, Math.ceil(p / 20));
  } else if (rule === 'per_table') {
    return Math.max(1, Math.ceil(p / 8));
  } else if (rule === 'per_menu_item') {
    const list = Array.isArray(pkgItems) ? pkgItems : (typeof customPkgItems !== 'undefined' ? customPkgItems : []);
    const foodCount = list.filter(i => !i.isAutoAdded && (i.cat === 'food' || i.cat === 'dessert')).length;
    return Math.max(1, foodCount || 1);
  } else if (rule === 'every_vip') {
    const vipCheck = document.getElementById('cpkg-vip-check');
    const vipCnt = parseInt(document.getElementById('cpkg-vip-count')?.value) || 0;
    if (vipCheck && vipCheck.checked) return Math.max(1, vipCnt || 1);
    return 1;
  } else if (rule === 'fixed' || rule === 'flat') {
    return 1;
  }

  // Name-based fallbacks strictly matching Halden catering equipment rules (without buffers)
  if (nameLow.includes('chair') || nameLow.includes('cover') || nameLow.includes('plate') ||
      nameLow.includes('spoon') || nameLow.includes('fork') || nameLow.includes('glass') ||
      nameLow.includes('napkin') || nameLow.includes('knife') || nameLow.includes('saucer') ||
      nameLow.includes('cup') || nameLow.includes('bowl')) {
    return Math.max(1, p);
  }
  if (nameLow.includes('table cloth') || nameLow.includes('table runner') || nameLow.includes('table skirt')) {
    return Math.max(1, Math.ceil(p / 5));
  }
  if (nameLow.includes('round banquet table') || nameLow.includes('banquet table')) {
    return Math.max(1, Math.ceil(p / 10));
  }
  if (nameLow.includes('rectangular table')) {
    return Math.max(1, Math.ceil(p / 8));
  }
  if (nameLow.includes('chafing dish') || nameLow.includes('serving tray') || nameLow.includes('serving spoon') || nameLow.includes('serving fork')) {
    const list = Array.isArray(pkgItems) ? pkgItems : (typeof customPkgItems !== 'undefined' ? customPkgItems : []);
    const foodCount = list.filter(i => !i.isAutoAdded && (i.cat === 'food' || i.cat === 'dessert')).length;
    return Math.max(1, foodCount || 1);
  }

  if (item.isPerPax) return Math.max(1, p);
  return 1;
}
window.getEquipmentAllocatedQty = getEquipmentAllocatedQty;

function isItemPerPaxScalable(item) {
  if (!item) return false;
  const cat = String(item.cat || item.category || '').toLowerCase();
  // Equipment, decor, and add-ons are NOT portion pax scalable
  if (cat === 'equipment' || cat === 'decor' || cat === 'decoration' || cat === 'addon' || cat === 'add-on') return false;
  const itemNameLow = String(item.name || '').toLowerCase();
  if (itemNameLow.includes('unlimited drinks') || item.identify === 'drinks_package') return true;
  if (itemNameLow.includes('ice cream') || itemNameLow.includes("halden's ice cream")) return true;
  if (cat === 'special' || cat === 'special items' || cat === 'special_items') return true;
  if (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(item)) return true;
  if (item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar') return false;
  if (item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option' || item.isFree) return false;
  if (item.isIndividual) return true;
  if (item.allocationType === 'per_pax' || item.pricingType === 'per_pax') return true;
  const subcat = String(item.subcategory || '').toLowerCase();
  const foodCats = ['chicken','beef','pork','fish','seafood','pasta','noodle','vegetable','vegetables','dessert','appetizer','salad','soup','rice','food'];
  if (cat === 'food' || cat === 'dessert' || item.identify === 'meals' || foodCats.includes(cat) || foodCats.includes(subcat)) {
    return true;
  }
  return false;
}
window.isItemPerPaxScalable = isItemPerPaxScalable;

function getDynamicPrice(item, pax, pkgItems) {
  if (!item) return 0;
  if (item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar') return 0;
  if (item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option') return 0;
  if (item.isFree) return 0;

  // Use customPax if explicitly set on item (for custom portion scaling)
  const hasCustomPax = item.customPax !== undefined && item.customPax !== null && parseInt(item.customPax) > 0;
  const p = hasCustomPax ? parseInt(item.customPax) : (parseInt(pax) || 0);

  // Equipment pricing: based on allocated quantity or locked custom quantity
  if (item.cat === 'equipment') {
    const list = Array.isArray(pkgItems) ? pkgItems : (typeof customPkgItems !== 'undefined' ? customPkgItems : []);
    const eqQty = (item.customQty !== undefined && item.customQty !== null && parseInt(item.customQty) > 0)
      ? parseInt(item.customQty)
      : (window.getEquipmentAllocatedQty ? window.getEquipmentAllocatedQty(item, p, list) : 1);
    const unitP = (item.unitPrice !== undefined && item.unitPrice !== null) ? Number(item.unitPrice) : (Number(item.price) || 0);
    let basePrice = unitP * eqQty;
    if (item.selectedOptionModifier && Number(item.selectedOptionModifier) > 0) {
      basePrice += Number(item.selectedOptionModifier);
    }
    return basePrice;
  }

  // Master special item: Unlimited Drinks is ALWAYS strictly ₱20/pax (per guest rate: unit_price x pax)
  const nmLower = (item.name || '').toLowerCase();
  if (nmLower.includes('unlimited drinks') || item.identify === 'drinks_package') {
    const unitRate = Number(item.price != null ? item.price : (item.price_per_pax || 20)) || 20;
    return unitRate * p;
  }

  let basePrice = item.price || 0;
  if (p <= 0) {
    basePrice = item.price || 0;
  } else if (item.isIndividual) {
    basePrice = item.price * p;
  } else if (item.batchSize) {
    basePrice = Math.ceil(p / item.batchSize) * item.price;
  } else {
    const alloc = item.allocationType || item.pricingType;
    if (alloc === 'included') basePrice = 0;
    else if (alloc === 'per_pax') basePrice = item.price * p;
    else if (alloc === 'per_5_pax') basePrice = Math.ceil(p / 5) * item.price;
    else if (alloc === 'per_10_pax') basePrice = Math.ceil(p / 10) * item.price;
    else if (alloc === 'per_20_pax') basePrice = Math.ceil(p / 20) * item.price;
    else if (alloc === 'per_menu_item') {
      const _pkgItems = (typeof customPkgItems !== 'undefined' && Array.isArray(customPkgItems)) ? customPkgItems : ((typeof window.customPkgItems !== 'undefined' && Array.isArray(window.customPkgItems)) ? window.customPkgItems : []);
      const foodItemCount = _pkgItems.filter(i => !i.isAutoAdded && i.cat === 'food').length;
      basePrice = item.price * (foodItemCount > 0 ? foodItemCount : 1);
    } else if (alloc === 'per_character') {
      basePrice = item.price * (p > 0 ? p : 1);
    } else if (item.cat === 'food' || item.cat === 'dessert' || item.identify === 'meals' || (item.category && ['chicken','beef','pork','fish','seafood','pasta','noodle','vegetable','vegetables','dessert','appetizer','salad','soup','rice','food'].includes(String(item.category).toLowerCase())) || (item.subcategory && ['chicken','beef','pork','fish','seafood','pasta','noodle','vegetable','vegetables','dessert','appetizer','salad','soup','rice','food'].includes(String(item.subcategory).toLowerCase()))) {
      basePrice = item.price * p;
    } else {
      basePrice = item.price;
    }
  }

  if (item.selectedOptionModifier && Number(item.selectedOptionModifier) > 0) {
    basePrice += Number(item.selectedOptionModifier);
  }
  return basePrice;
}
window.getDynamicPrice = getDynamicPrice;

function getBatchInfo(item, pax) {
  if (!item) return '';
  const hasCustomPax = item.customPax !== undefined && item.customPax !== null && parseInt(item.customPax) > 0;
  const p = hasCustomPax ? parseInt(item.customPax) : (parseInt(pax) || 0);

  if (item.cat === 'equipment') {
    const unitP = (item.unitPrice !== undefined && item.unitPrice !== null) ? Number(item.unitPrice) : (Number(item.price) || 0);
    if (item.customQty) {
      return `${item.customQty} pcs (customized & locked) · ₱${unitP.toLocaleString()}/pc`;
    }
    const eqQty = window.getEquipmentAllocatedQty ? window.getEquipmentAllocatedQty(item, p) : 1;
    return `${eqQty} pcs · ₱${unitP.toLocaleString()}/pc`;
  }

  if (hasCustomPax) return `customized for ${p} pax`;

  const alloc = item.allocationType || item.pricingType;

  if (alloc === 'included') return 'included';
  if (alloc === 'per_menu_item') {
    const _pkgItems = (typeof customPkgItems !== 'undefined' && Array.isArray(customPkgItems)) ? customPkgItems : ((typeof window.customPkgItems !== 'undefined' && Array.isArray(window.customPkgItems)) ? window.customPkgItems : []);
    const foodItemCount = _pkgItems.filter(i => !i.isAutoAdded && i.cat === 'food').length;
    return `per menu item (${foodItemCount}x)`;
  }
  if (alloc === 'per_pax' || item.isIndividual) return 'per pax';
  if (alloc === 'per_5_pax') return `per 5 pax (${Math.ceil(p / 5) || 1} units for ${p || 5} pax)`;
  if (alloc === 'per_10_pax') return `per 10 pax (${Math.ceil(p / 10) || 1} batches for ${p || 10} pax)`;
  if (alloc === 'per_20_pax') return `per 20 pax (${Math.ceil(p / 20) || 1} batches for ${p || 20} pax)`;
  if (alloc === 'per_character') return `per character (₱${item.price.toLocaleString()} each)`;

  if (item.batchSize) return `batch of ${item.batchSize}`;

  return 'flat rate (fixed)';
}
window.getBatchInfo = getBatchInfo;

// ===== CATALOG PAGINATION SYSTEM (DESKTOP ONLY) =====
// Displays 4 rows (16 items per page). When on page 1: 1, 2, 3, 4, 5, ...
// When moved to page 2: 2, 3, 4, 5, 6, ...
let fullCatPage = 1;
let curCatPage = 1;
const CATALOG_PAGE_SIZE = 16; // 4 rows x 4 columns on desktop

function renderCatalogPagination(containerId, currentPage, totalPages, pageChangeFn) {
  const container = document.getElementById(containerId);
  if (!container) return;

  // Desktop view only (hide on mobile or when only 1 page)
  if (window.innerWidth <= 768 || totalPages <= 1) {
    container.innerHTML = '';
    container.style.display = 'none';
    return;
  }

  container.style.display = 'flex';

  let html = '';

  // Quick jump to first page button (<<) if past page 2
  if (currentPage > 2) {
    html += `<button type="button" class="cat-page-btn" onclick="${pageChangeFn}(1)" title="First Page" aria-label="First Page">&laquo;</button>`;
  }

  // Prev button (<)
  const prevDisabled = currentPage <= 1 ? 'disabled' : '';
  const prevClick = currentPage > 1 ? `${pageChangeFn}(${currentPage - 1})` : '';
  html += `<button type="button" class="cat-page-btn" ${prevDisabled} onclick="${prevClick}" aria-label="Previous Page">&lsaquo;</button>`;

  // Sliding 5-page window starting directly with currentPage:
  // e.g. Page 1 -> 1, 2, 3, 4, 5, ...
  // e.g. Page 2 -> 2, 3, 4, 5, 6, ...
  const windowSize = 5;
  const startPage = Math.max(1, currentPage);
  const endPage = Math.min(totalPages, startPage + windowSize - 1);

  for (let p = startPage; p <= endPage; p++) {
    const isActive = p === currentPage ? 'active' : '';
    html += `<button type="button" class="cat-page-btn ${isActive}" onclick="${pageChangeFn}(${p})">${p}</button>`;
  }

  // Ellipsis (...) and last page button if more pages exist beyond endPage
  if (endPage < totalPages) {
    html += `<span class="cat-page-ellipsis" onclick="${pageChangeFn}(${Math.min(totalPages, endPage + 1)})" title="Next pages">&hellip;</span>`;
    html += `<button type="button" class="cat-page-btn" onclick="${pageChangeFn}(${totalPages})" title="Last Page (${totalPages})">${totalPages}</button>`;
  }

  // Next button (>)
  const nextDisabled = currentPage >= totalPages ? 'disabled' : '';
  const nextClick = currentPage < totalPages ? `${pageChangeFn}(${currentPage + 1})` : '';
  html += `<button type="button" class="cat-page-btn" ${nextDisabled} onclick="${nextClick}" aria-label="Next Page">&rsaquo;</button>`;

  container.innerHTML = html;
}
window.renderCatalogPagination = renderCatalogPagination;

window.setFullCatPage = function (p) {
  fullCatPage = p;
  renderFullCatalog();
  const el = document.getElementById('full-catalog');
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

window.setCatPage = function (p) {
  curCatPage = p;
  renderCat();
  const el = document.getElementById('cat-grid');
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

// Responsive resize debounce to switch between desktop pagination and mobile swipe seamlessly
let _catResizeTimeout = null;
window.addEventListener('resize', function () {
  clearTimeout(_catResizeTimeout);
  _catResizeTimeout = setTimeout(function () {
    if (typeof renderCat === 'function') renderCat();
    if (typeof renderFullCatalog === 'function') renderFullCatalog();
  }, 200);
});

// ===== CATALOG =====
function renderCat() {
  const grid = document.getElementById('cat-grid');
  if (!grid) return;
  let items = [];
  if (curCat === 'all') {
    items = window.sortCatByFoodFirst([...CAT]);
    items.sort((a, b) => (window.isSpecialParentItem(b) ? 1 : 0) - (window.isSpecialParentItem(a) ? 1 : 0));
  } else if (curCat === 'special') {
    items = CAT.filter(i => window.isSpecialParentItem(i));
  } else {
    items = CAT.filter(i => i.cat === curCat);
    items.sort((a, b) => (window.isSpecialParentItem(b) ? 1 : 0) - (window.isSpecialParentItem(a) ? 1 : 0));
  }

  const noteEl = document.getElementById('free-choice-note');
  if (noteEl) {
    const hasFreeChoice = customPkgItems.some(c => c.name === 'Free Choices of Food From Menu');
    noteEl.style.display = (activePkg && hasFreeChoice) ? 'block' : 'none';
  }

  items = items.filter(i => {
    if (i.hidden || i.is_available === false) return false;
    // Exclude equipment batches from make a reservation catalog
    if (i.cat === 'equipment') {
      if (i.is_batch || i.batch_id || i.parent_asset_id) return false;
      if (/\(BATCH/i.test(i.name || '') || /\bBATCH-\d+/i.test(i.name || '') || (i.name || '').toLowerCase().includes('(batch')) return false;
    }
    return window.isParentSpecialItemInPackage(i, customPkgItems);
  });
  // Hide Free Choices placeholder from catalog view
  items = items.filter(i => i.name !== 'Free Choices of Food From Menu');

  // Premade Packages Filter: Remove all items that are not part of the premade package
  if (activePkg) {
    const pkgItemIds = new Set(activePkg.itemIds || []);
    const pkgItemNames = new Set((activePkg.items || []).map(x => (typeof x === 'string' ? x : (x.name || '')).toLowerCase().trim()));
    const curPkgIds = new Set(customPkgItems.map(c => c.id));
    const curPkgNames = new Set(customPkgItems.map(c => (c.name || '').toLowerCase().trim()));

    items = items.filter(i => {
      const n = (i.name || '').toLowerCase().trim();
      return pkgItemIds.has(i.id) || pkgItemNames.has(n) || curPkgIds.has(i.id) || curPkgNames.has(n);
    });
  }

  // Search Filter
  if (customSearch.trim()) {
    const q = customSearch.toLowerCase();
    items = items.filter(i => i.name.toLowerCase().includes(q) || i.desc.toLowerCase().includes(q));
  }

  if (!items.length) {
    grid.innerHTML = '<div class="cat-empty"><p>No items found.</p></div>';
    const pContainer = document.getElementById('cat-pagination');
    if (pContainer) { pContainer.innerHTML = ''; pContainer.style.display = 'none'; }
    return;
  }
  if (aiPicks && Array.isArray(aiPicks) && aiPicks.length > 0) {
    // Push AI Recommended items to top of the catalog without filtering out other items
    items = [...items].sort((a, b) => {
      const aPick = aiPicks.includes(a.id) ? 1 : 0;
      const bPick = aiPicks.includes(b.id) ? 1 : 0;
      return bPick - aPick;
    });
  }
  const countEl = document.getElementById('cat-count');
  if (countEl) {
    const aiCount = (aiPicks && Array.isArray(aiPicks)) ? items.filter(i => aiPicks.includes(i.id)).length : 0;
    countEl.innerHTML = (aiCount > 0)
      ? `<strong>${items.length} items</strong> &bull; ${aiCount} AI Recommended placed at top`
      : `<strong>${items.length}</strong> items`;
  }

  // Desktop pagination: only 4 rows (16 items per page)
  const isDesktop = window.innerWidth > 768;
  const totalCatItems = items.length;
  let displayItems = items;
  if (isDesktop) {
    const totalPages = Math.max(1, Math.ceil(totalCatItems / CATALOG_PAGE_SIZE));
    if (curCatPage > totalPages) curCatPage = totalPages;
    if (curCatPage < 1) curCatPage = 1;
    const startIndex = (curCatPage - 1) * CATALOG_PAGE_SIZE;
    displayItems = items.slice(startIndex, startIndex + CATALOG_PAGE_SIZE);
    renderCatalogPagination('cat-pagination', curCatPage, totalPages, 'setCatPage');
  } else {
    const pContainer = document.getElementById('cat-pagination');
    if (pContainer) { pContainer.innerHTML = ''; pContainer.style.display = 'none'; }
  }

  grid.innerHTML = displayItems.map(item => {
    const inPkg = customPkgItems.find(c => c.id === item.id);
    const isPick = aiPicks && aiPicks.includes(item.id);
    const isDim = false;
    const pax = document.getElementById('cpkg-pax')?.value || 0;
    const p = parseInt(pax) || 0;
    const dp = getDynamicPrice(inPkg || item, p);
    const batchInfo = getBatchInfo(inPkg || item, p);
    const isSubOption = item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option' || (item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar');
    const colorInfo = window.getSpecialItemColorInfo(item);
    const theme = window.getTheme ? window.getTheme() : 'dark';

    const catLower = (item.cat || item.category || '').toLowerCase();
    const hasFreeChoice = customPkgItems.some(c => c.name === 'Free Choices of Food From Menu');
    const isFoodOrDessert = (catLower === 'food' || catLower === 'dessert') && !window.isSpecialParentItem(item);
    const isSpecificDrink = catLower === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar' && !window.isSpecialParentItem(item);

    let isRestricted = false;
    if (!inPkg && activePkg) {
      if (hasFreeChoice && isFoodOrDessert) {
        isRestricted = false;
      } else if (!isSpecificDrink) {
        isRestricted = true;
      }
    }

    let cardStyle = '';
    if (colorInfo) {
      const cardBg = theme === 'dark' ? colorInfo.bgDark : colorInfo.bgLight;
      cardStyle += ` background:${cardBg}; border:1.5px solid ${colorInfo.border};`;
    }
    if (isRestricted) {
      cardStyle += ' opacity:0.6;';
    }

    const isEquipment = (item.cat === 'equipment' || (inPkg && inPkg.cat === 'equipment'));
    const addonCats = ['decor', 'decoration', 'decorations', 'addon', 'add-on', 'addons', 'entertainment', 'photography'];
    const isDecorOrAddon = addonCats.includes(String(item.cat || '').toLowerCase()) || (inPkg && addonCats.includes(String(inPkg.cat || '').toLowerCase()));
    const isDrinksPkg = inPkg && (item.identify === 'drinks_package' || item.identify === 'mobile_bar');
    const canCustomizePax = !activePkg && inPkg && isItemPerPaxScalable(item);
    const canCustomizeEquipment = !activePkg && inPkg && isEquipment;
    const canCustomizeDecorOrAddon = !activePkg && inPkg && isDecorOrAddon;
    const canCustomizeDrinks = !activePkg && inPkg && isDrinksPkg;

    let customizePaxHtml = '';
    if (canCustomizePax) {
      const isCustomBoxOpen = !!inPkg._showCustomizePax;
      const totalPaxNum = parseInt(document.getElementById('cpkg-pax')?.value || 50) || 50;
      const curPortion = inPkg.customPax || totalPaxNum;
      const curSpecs = inPkg.specifications || '';
      customizePaxHtml = `
        <div style="margin-top:8px;" onclick="event.stopPropagation()">
          <button type="button" class="btn-customize-pax ${isCustomBoxOpen ? 'active' : ''}" onclick="toggleCustomizePax('${item.id}')">
            ${inPkg.customPax ? `Custom Pax: ${inPkg.customPax} pax` : 'Customize Pax'}
          </button>
          ${isCustomBoxOpen ? `
            <div class="item-custom-pax-box">
              <label style="display:block; font-size:11px; font-weight:700; margin-bottom:4px;">Portion Pax (Max: 999):</label>
              <div style="display:flex; align-items:center; gap:8px;">
                <input type="number" min="1" max="999" maxlength="3" value="${curPortion}" class="custom-pax-input" style="width:75px; padding:4px 6px; font-size:12px; border-radius:6px;" oninput="updateItemCustomPax('${item.id}', this.value, false)" onchange="updateItemCustomPax('${item.id}', this.value, true)" />
                <span>pax</span>
                ${inPkg.customPax ? `<button type="button" class="btn-ghost" style="font-size:10px; padding:2px 6px;" onclick="resetItemCustomPax('${item.id}')">Reset</button>` : ''}
              </div>
              <label style="display:block; font-size:11px; font-weight:700; margin:8px 0 4px;">Specifications:</label>
              <input type="text" placeholder="e.g. Mild spicy, allergen notes..." value="${esc(curSpecs)}" class="custom-specs-input" style="width:100%; padding:4px 6px; font-size:11.5px; border-radius:6px;" oninput="updateItemCustomSpecs('${item.id}', this.value)" onchange="updateItemCustomSpecs('${item.id}', this.value)" />
            </div>
          ` : ''}
        </div>
      `;
    } else if (canCustomizeEquipment) {
      const isCustomBoxOpen = !!inPkg._showCustomizeItem;
      const totalPaxNum = parseInt(document.getElementById('cpkg-pax')?.value || 50) || 50;
      const defaultQty = window.getEquipmentAllocatedQty ? window.getEquipmentAllocatedQty(item, totalPaxNum) : 1;
      const curQty = (inPkg.customQty !== undefined && inPkg.customQty !== null) ? inPkg.customQty : defaultQty;
      const curSpecs = inPkg.specifications || '';
      customizePaxHtml = `
        <div style="margin-top:8px;" onclick="event.stopPropagation()">
          <button type="button" class="btn-customize-pax ${isCustomBoxOpen ? 'active' : ''}" onclick="toggleCustomizeItem('${item.id}')">
            ${inPkg.customQty ? `Custom Count: ${inPkg.customQty} pcs` : 'Customize Equipment'}
          </button>
          ${isCustomBoxOpen ? `
            <div class="item-custom-pax-box">
              <label style="display:block; font-size:11px; font-weight:700; margin-bottom:4px;">Allocated Quantity (1 - 999):</label>
              <div style="display:flex; align-items:center; gap:8px;">
                <input type="number" min="1" max="999" value="${curQty}" class="custom-qty-input" style="width:75px; padding:4px 6px; font-size:12px; border-radius:6px;" oninput="updateItemCustomQty('${item.id}', this.value, false)" onchange="updateItemCustomQty('${item.id}', this.value, true)" />
                <span>pcs</span>
                ${inPkg.customQty ? `<button type="button" class="btn-ghost" style="font-size:10px; padding:2px 6px;" onclick="resetItemCustomQty('${item.id}')">Reset</button>` : ''}
              </div>
              <label style="display:block; font-size:11px; font-weight:700; margin:8px 0 4px;">Specifications / Notes:</label>
              <input type="text" placeholder="e.g. Specific layout, color preference..." value="${esc(curSpecs)}" class="custom-specs-input" style="width:100%; padding:4px 6px; font-size:11.5px; border-radius:6px;" oninput="updateItemCustomSpecs('${item.id}', this.value)" onchange="updateItemCustomSpecs('${item.id}', this.value)" />
            </div>
          ` : ''}
        </div>
      `;
    } else if (canCustomizeDecorOrAddon || canCustomizeDrinks) {
      const isCustomBoxOpen = !!inPkg._showCustomizeItem;
      const curSpecs = inPkg.specifications || '';
      customizePaxHtml = `
        <div style="margin-top:8px;" onclick="event.stopPropagation()">
          <button type="button" class="btn-customize-pax ${isCustomBoxOpen ? 'active' : ''}" onclick="toggleCustomizeItem('${item.id}')">
            ${inPkg.specifications ? 'Customized Notes' : 'Customize Notes'}
          </button>
          ${isCustomBoxOpen ? `
            <div class="item-custom-pax-box">
              <label style="display:block; font-size:11px; font-weight:700; margin-bottom:4px;">Specifications / Preferences:</label>
              <div style="display:flex; align-items:center; gap:8px;">
                <input type="text" placeholder="e.g. Color palette, styling notes, flavors..." value="${esc(curSpecs)}" class="custom-specs-input" style="width:100%; padding:4px 6px; font-size:11.5px; border-radius:6px;" oninput="updateItemCustomSpecs('${item.id}', this.value)" onchange="updateItemCustomSpecs('${item.id}', this.value)" />
                ${inPkg.specifications ? `<button type="button" class="btn-ghost" style="font-size:10px; padding:2px 6px;" onclick="resetItemCustomSpecs('${item.id}')">Clear</button>` : ''}
              </div>
            </div>
          ` : ''}
        </div>
      `;
    }

    return `
      <div class="cat-card ${isPick ? 'ai-pick' : ''} ${isDim ? 'dimmed' : ''}" onclick="openDishModal('${item.id}')" style="${cardStyle}">
        ${item.image ? `<div class="cat-thumb" style="background:#ffffff url('${item.image}') center/contain no-repeat;"></div>` : ''}
        <div class="cat-info">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; gap:6px; flex-wrap:wrap;">
            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
              <div class="cat-cat-lbl" style="margin:0;">${(item.subcategory || item.cat).toUpperCase()}</div>
              ${item.best_seller ? '<span class="tag-best-seller">Best Seller</span>' : ''}
            </div>
            ${isPick ? '<span style="font-size:10px; color:var(--gold); font-weight:700;"> AI RECOMMENDED</span>' : ''}
            ${isRestricted ? '<span style="font-size:10px; font-weight:800; color:var(--red); text-transform:uppercase; letter-spacing:1px;">LOCKED</span>' : ''}
          </div>
          <div class="cat-n">${item.name}</div>
          <div class="cat-d">${item.desc}</div>
          ${(isSubOption || activePkg) ? '' : `<div class="cat-p" style="color:var(--primary); font-weight:700; margin-top:8px;">&#8369;${dp.toLocaleString()} <span style="font-size:10px; color:var(--text-dim); font-weight:400;">${batchInfo}</span></div>`}
          ${(isEquipment && !activePkg) ? `
            <div style="font-size:12px; font-weight:700; color:var(--gold); margin:6px 0; background:rgba(196,154,60,0.1); border:1px solid rgba(196,154,60,0.3); border-radius:6px; padding:4px 8px; display:inline-block;">
              Quantity Needed: <strong>${window.getEquipmentAllocatedQty ? window.getEquipmentAllocatedQty(inPkg || item, p, customPkgItems) : 1} pcs</strong>${inPkg && inPkg.customQty ? ' <span style="color:#22c55e; font-size:10px; font-weight:700;">(Customized &amp; Locked)</span>' : ''}
            </div>
          ` : ''}
          ${activePkg ? `
            <button class="btn-add added" style="margin-top:12px; opacity:0.75; cursor:not-allowed;" title="Included in package" disabled>
              Locked &bull; Included in Package
            </button>
          ` : `
            <button class="btn-add ${inPkg ? 'added' : ''}" onclick="event.stopPropagation(); toggleItem('${item.id}')" style="margin-top:12px;">
              ${inPkg ? '&#10003; Added' : '+ Add to Package'}
            </button>
            ${customizePaxHtml}
          `}
        </div>
      </div>`;
  }).join('');
}

function toggleCustomizePax(itemId) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  inPkg._showCustomizePax = !inPkg._showCustomizePax;
  renderCat();
}
window.toggleCustomizePax = toggleCustomizePax;

function updateItemCustomPax(itemId, newPaxVal, shouldReRenderCat = true) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  let p = parseInt(newPaxVal, 10);
  if (isNaN(p) || p < 1) p = 1;
  // Allow pax customization to go above the base reservation pax up to 3 digits (limit 999)
  if (p > 999) {
    alert('Custom portion pax cannot exceed 3 digits (999 pax).');
    p = 999;
  }
  inPkg.customPax = p;
  if (shouldReRenderCat && typeof renderCat === 'function') renderCat();
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
  if (typeof updateConflictSpeechBubble === 'function') updateConflictSpeechBubble();
}
window.updateItemCustomPax = updateItemCustomPax;

function resetItemCustomPax(itemId) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  delete inPkg.customPax;
  delete inPkg.specifications;
  inPkg._showCustomizePax = false;
  renderCat();
  renderCustomPkg();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
}
window.resetItemCustomPax = resetItemCustomPax;


function toggleCustomizeItem(itemId) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  inPkg._showCustomizeItem = !inPkg._showCustomizeItem;
  renderCat();
}
window.toggleCustomizeItem = toggleCustomizeItem;

function updateItemCustomQty(itemId, newQtyVal, shouldReRenderCat = true) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  let q = parseInt(newQtyVal, 10);
  if (isNaN(q) || q < 1) q = 1;
  if (q > 999) q = 999;
  inPkg.customQty = q;
  inPkg.isLocked = true;
  // Recalculate dynamic price for customQty
  inPkg.snapshotPrice = (parseFloat(inPkg.price) || 0) * q;
  if (shouldReRenderCat && typeof renderCat === 'function') renderCat();
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
}
window.updateItemCustomQty = updateItemCustomQty;

function resetItemCustomQty(itemId) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  delete inPkg.customQty;
  if (typeof renderCat === 'function') renderCat();
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
}
window.resetItemCustomQty = resetItemCustomQty;

function resetItemCustomSpecs(itemId) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  delete inPkg.specifications;
  if (typeof renderCat === 'function') renderCat();
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
}
window.resetItemCustomSpecs = resetItemCustomSpecs;

function updateItemCustomSpecs(itemId, specsVal) {
  const inPkg = customPkgItems.find(c => c.id === itemId);
  if (!inPkg) return;
  inPkg.specifications = String(specsVal || '').trim();
  if (typeof saveCustomPkgStateToStorage === 'function') saveCustomPkgStateToStorage();
}
window.updateItemCustomSpecs = updateItemCustomSpecs;

window.renderCat = renderCat;
// ===== FULL CATALOG (READ ONLY) =====

function renderFullCatalog() {
  const grid = document.getElementById('full-grid');
  if (!grid) return;
  let items = curFullCat === 'all' ? window.sortCatByFoodFirst([...CAT]) : CAT.filter(i => i.cat === curFullCat);
  // Hide special items, hidden/unavailable items, batch equipment, and Free Choice placeholder from full catalog
  items = items.filter(i => {
    if (i.hidden || i.is_available === false || window.isSpecialParentItem(i) || i.name === 'Free Choices of Food From Menu') return false;
    if (i.cat === 'equipment') {
      if (i.is_batch || i.batch_id || i.parent_asset_id) return false;
      if (/\(BATCH/i.test(i.name || '') || /\bBATCH-\d+/i.test(i.name || '') || (i.name || '').toLowerCase().includes('(batch')) return false;
    }
    return true;
  });

  // Search Filter
  if (fullSearch.trim()) {
    const q = fullSearch.toLowerCase();
    items = items.filter(i => i.name.toLowerCase().includes(q) || i.desc.toLowerCase().includes(q));
  }

  if (!items.length) {
    grid.innerHTML = '<div class="cat-empty"><p>No items found.</p></div>';
    const pContainer = document.getElementById('full-cat-pagination');
    if (pContainer) { pContainer.innerHTML = ''; pContainer.style.display = 'none'; }
    return;
  }

  // Desktop pagination: only 4 rows (16 items per page)
  const isDesktop = window.innerWidth > 768;
  const totalFullItems = items.length;
  let displayItems = items;
  if (isDesktop) {
    const totalPages = Math.max(1, Math.ceil(totalFullItems / CATALOG_PAGE_SIZE));
    if (fullCatPage > totalPages) fullCatPage = totalPages;
    if (fullCatPage < 1) fullCatPage = 1;
    const startIndex = (fullCatPage - 1) * CATALOG_PAGE_SIZE;
    displayItems = items.slice(startIndex, startIndex + CATALOG_PAGE_SIZE);
    renderCatalogPagination('full-cat-pagination', fullCatPage, totalPages, 'setFullCatPage');
  } else {
    const pContainer = document.getElementById('full-cat-pagination');
    if (pContainer) { pContainer.innerHTML = ''; pContainer.style.display = 'none'; }
  }

  grid.innerHTML = displayItems.map(item => {
    const pax = document.getElementById('cpkg-pax')?.value || 0;
    const p = parseInt(pax) || 0;
    const dp = getDynamicPrice(item, p);
    const batchInfo = getBatchInfo(item, p);
    const isSubOption = item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option' || (item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar');
    return `
      <div class="full-cat-card" onclick="openDishModal('${item.id}')">
        ${item.image ? `<div class="full-cat-thumb" style="background-image:url('${item.image}'); background-size:cover; background-position:center center; background-repeat:no-repeat;"></div>` : ''}
        <div class="full-cat-info" style="padding:20px;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; gap:6px; flex-wrap:wrap;">
            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
              <div class="cat-cat-lbl">${(item.subcategory || item.cat).toUpperCase()}</div>
              ${item.best_seller ? '<span class="tag-best-seller">Best Seller</span>' : ''}
            </div>
          </div>
          <div class="full-cat-name">${item.name}</div>
          ${isSubOption ? '' : `<div class="full-cat-price" style="color:var(--primary); font-weight:700; margin-bottom:8px;">&#8369;${dp.toLocaleString()} <span style="font-size:10px; color:var(--text-dim); font-weight:400;">${batchInfo}</span></div>`}
          <div class="full-cat-desc">${item.desc}</div>
        </div>
      </div>`;
  }).join('');
}
window.renderFullCatalog = renderFullCatalog;

function setCat(cat, btn) {
  document.querySelectorAll('.fb').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  curCat = cat;
  curCatPage = 1;
  renderCat();
}

function jumpCat(cat) {
  curCat = cat;
  curCatPage = 1;
  document.querySelectorAll('.fb').forEach(b => {
    const matches = b.getAttribute('onclick')?.includes(`'${cat}'`) || (cat === 'all' && b.textContent.trim() === 'All');
    b.classList.toggle('active', !!matches);
  });
  renderCat(); go('#catalog');
}

// ===== SELECT PREMADE PACKAGE =====
function openPkgModal(id) {
  const p = PKGS.find(x => x.id === id);
  if (!p) return;

  document.getElementById('pm-title').textContent = p.name;
  document.getElementById('pm-desc').textContent = p.desc;
  document.getElementById('pm-badge').textContent = p.badge || 'MAJORITY SET';
  document.getElementById('pm-theme').textContent = p.theme;
  document.getElementById('pm-occasion').textContent = p.occasion;
  
  const imgWrap = document.getElementById('pm-image-wrap');
  const imgEl = document.getElementById('pm-image');
  if (p.image) {
    imgEl.src = p.image;
    imgWrap.style.display = 'flex';
  } else {
    imgWrap.style.display = 'none';
  }

  const btn = document.getElementById('pm-select-btn');
  const tierSelector = document.getElementById('pm-tier-selector');

  const priceEl = document.getElementById('pm-price');
  const priceSubEl = document.getElementById('pm-price-sub');

  let tiers = p.priceTiers || p.price_tiers || [];
  if (typeof tiers === 'string') {
    try { tiers = JSON.parse(tiers); } catch (e) { tiers = []; }
  }
  const hasTiers = Array.isArray(tiers) && tiers.length > 0;

  if (hasTiers) {
    if (tierSelector) tierSelector.style.display = 'block';
    const select = document.getElementById('pm-tier-select');
    if (select) {
      select.innerHTML = tiers.map((t, idx) => `<option value="${idx}">${t.label || (t.pax + ' pax')} : \u20b1${Number(t.price || 0).toLocaleString()}</option>`).join('');
    }
    window.pmSelectedTier = tiers[0];

    // Update main price block
    if (priceEl) priceEl.textContent = '\u20b1' + Number(tiers[0].price || 0).toLocaleString();
    if (priceSubEl) priceSubEl.textContent = 'fixed for ' + (tiers[0].label || (tiers[0].pax + ' pax'));

    btn.textContent = 'Select Package';
    btn.onclick = () => { promptPremadePackageModalNotice(p.id, window.pmSelectedTier); };
  } else if (p.pricingMode === 'majorly_set') {
    if (tierSelector) tierSelector.style.display = 'none';
    if (priceEl) priceEl.textContent = '\u20b1' + (p.fixedPrice || 0).toLocaleString();
    if (priceSubEl) priceSubEl.textContent = 'fixed for ' + (p.fixedPax || 0) + ' pax';

    btn.textContent = 'Select Package';
    btn.onclick = () => { promptPremadePackageModalNotice(p.id, null); };
  } else {
    if (tierSelector) tierSelector.style.display = 'none';
    if (priceEl) priceEl.textContent = '\u20b1' + (p.pricePerHead || 0).toLocaleString();
    if (priceSubEl) priceSubEl.textContent = 'per pax';

    btn.textContent = 'Select Package';
    btn.onclick = () => { promptPremadePackageModalNotice(p.id, null); };
  }

  // Grouping helpers: Aligns strictly with Edit Pre-made Package categories
  // (Food, Desserts, Drinks, Equipment, Decorations, Add-ons). Eliminates 'Other' completely.
  const setupEquipSet = new Set((p.setupEquipItems || []).map(x => (x || '').toLowerCase().trim()));
  const allSetupNames = new Set((window.EVENT_SETUPS || []).map(s => (s.name || '').toLowerCase().trim()).filter(Boolean));
  if (p.eventSetupName) allSetupNames.add(p.eventSetupName.toLowerCase().trim());

  // Filter out event setup titles (e.g. "Complete Setup") so they do not render as item pills
  const filterValidPackageItems = (names) => {
    return (names || []).filter(n => {
      if (!n || !n.trim()) return false;
      return !allSetupNames.has(n.toLowerCase().trim());
    });
  };

  const getGroup = (name) => {
    const nLower = (name || '').toLowerCase().trim();

    // 1. Inherent setup equipment is strictly Equipment
    if (setupEquipSet.has(nLower)) return 'Equipment';

    // 2. Direct lookup in CAT
    const item = CAT.find(c => c.name.toLowerCase() === nLower);
    if (item) {
      const id = (item.identify || '').toLowerCase();
      const cat = (item.cat || item.category || '').toLowerCase();
      if (id === 'equipment' || cat === 'equipment') return 'Equipment';
      if (id === 'meals' || id === 'food' || id === 'rice' || cat === 'food' || cat === 'rice' || cat === 'vegetables' || cat === 'beef' || cat === 'pork' || cat === 'chicken' || cat === 'seafood' || cat === 'pasta' || cat === 'noodles' || cat === 'soup') return 'Food';
      if (id === 'desserts' || id === 'dessert' || id === 'ice_cream' || id === 'ice_cream_option' || cat === 'dessert' || cat === 'desserts') return 'Desserts';
      if (id === 'drinks' || id === 'drinks_package' || id === 'drink' || id === 'mobile_bar' || id === 'mobile_bar_option' || cat === 'drink' || cat === 'drinks') return 'Drinks';
      if (id === 'decoration' || id === 'decor' || cat === 'decoration' || cat === 'decorations') return 'Decorations';
      if (id === 'addon' || id === 'entertainment' || id === 'special' || cat === 'entertainment' || cat === 'addon') return 'Add-ons';
    }

    // 3. Fallback semantic name matching (matching admin catalog categories)
    if (nLower.includes('chair') || nLower.includes('table') || nLower.includes('cloth') || nLower.includes('linen') || nLower.includes('runner') || nLower.includes('skirt') || nLower.includes('plate') || nLower.includes('fork') || nLower.includes('spoon') || nLower.includes('glass') || nLower.includes('chafing') || nLower.includes('tray') || nLower.includes('pitcher') || nLower.includes('sandok') || nLower.includes('bucket') || nLower.includes('basket') || nLower.includes('tong') || nLower.includes('cover') || nLower.includes('pan') || nLower.includes('dish')) {
      return 'Equipment';
    }
    if (nLower.includes('cake') || nLower.includes('dessert') || nLower.includes('ice cream') || nLower.includes('pandan') || nLower.includes('tapioca') || nLower.includes('pastry') || nLower.includes('flan') || nLower.includes('sweet')) {
      return 'Desserts';
    }
    if (nLower.includes('drink') || nLower.includes('beverage') || nLower.includes('cocktail') || nLower.includes('juice') || nLower.includes('tea') || nLower.includes('coffee') || nLower.includes('bar') || nLower.includes('punch')) {
      return 'Drinks';
    }
    if (nLower.includes('decor') || nLower.includes('balloon') || nLower.includes('centerpiece') || nLower.includes('arch') || nLower.includes('standee') || nLower.includes('styling') || nLower.includes('backdrop') || nLower.includes('flower') || nLower.includes('banner')) {
      return 'Decorations';
    }
    if (nLower.includes('coordinator') || nLower.includes('host') || nLower.includes('emcee') || nLower.includes('photo') || nLower.includes('video') || nLower.includes('booth') || nLower.includes('magician') || nLower.includes('sound') || nLower.includes('light') || nLower.includes('entertainer') || nLower.includes('band')) {
      return 'Add-ons';
    }

    // 4. Default to Food for all prepared dishes and culinary items (never 'Other')
    return 'Food';
  };

  const groupOrder = { 'Food': 1, 'Desserts': 2, 'Drinks': 3, 'Equipment': 4, 'Decorations': 5, 'Add-ons': 6 };

  const getGroupIcon = (g) => {
    switch (g) {
      case 'Food': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 13a10 10 0 0 0-20 0M2 13h20M12 3v2"/></svg>';
      case 'Desserts': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-8a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8"/><path d="M4 16h16"/><path d="M4 12h16"/><path d="M12 3l-1.5 4"/></svg>';
      case 'Drinks': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 5h12l-1.5 16h-9z"/><path d="M8 2l2 3M16 2l-2 3"/></svg>';
      case 'Equipment': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg>';
      case 'Decorations': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1 4-10z"/><path d="M2 12h20"/></svg>';
      case 'Add-ons': return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>';
      default: return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="2"/></svg>';
    }
  };

  const renderGroupedItems = (rawNames, isFreebie = false) => {
    // Filter out setup names from individual pills
    const names = filterValidPackageItems(rawNames);
    const groups = {};
    names.forEach(n => {
      const g = getGroup(n);
      if (!groups[g]) groups[g] = [];
      groups[g].push(n);
    });

    const sortedGroups = Object.keys(groups).sort((a, b) => (groupOrder[a] || 99) - (groupOrder[b] || 99));

    let html = '';
    sortedGroups.forEach(g => {
      let groupHeaderExtraHtml = '';
      if (g === 'Equipment') {
        let setupSlug = p.eventSetupSlug || p.event_setup_slug;
        if (!setupSlug && p.eventSetupName) {
          const matchingSetup = (window.EVENT_SETUPS || []).find(s => s.name.toLowerCase() === p.eventSetupName.toLowerCase());
          if (matchingSetup) setupSlug = matchingSetup.slug;
        }
        if (!setupSlug) {
          const pSlugLower = (p.slug || p.name || '').toLowerCase();
          if (pSlugLower.includes('kiddie')) setupSlug = 'complete_setup_basic_chairs';
          else setupSlug = 'complete_setup';
        }

        const setupObj = (window.EVENT_SETUPS || []).find(s => s.slug === setupSlug) || { name: p.eventSetupName || 'Complete Setup' };
        // Clean neutral text without emoticons and without colored pill background
        groupHeaderExtraHtml = `
          <div style="width:100%; margin-bottom:12px;">
            <span style="display:inline-flex; align-items:center; gap:6px; color:#cba153; font-weight:700; font-size:12px; letter-spacing:0.8px; text-transform:uppercase;">
              ${setupObj.name}
            </span>
          </div>
        `;
      }

      html += `
        <div style="display:flex; align-items:flex-start; border-bottom: 1px dashed rgba(203,161,83,0.3); padding: 18px 0;">
          <div style="display:flex; align-items:center; width: 150px; gap: 15px; flex-shrink:0; padding-top:4px;">
            <div style="width:40px; height:40px; border-radius:50%; border:1px solid rgba(203,161,83,0.4); display:flex; align-items:center; justify-content:center; color:#cba153;">
              ${getGroupIcon(g)}
            </div>
            <div class="pm-cat-title" style="font-weight:800; color:#3d2b1a; font-size:12px; letter-spacing:1px; text-transform:uppercase;">${g}</div>
          </div>
          <div style="display:flex; flex-wrap:wrap; gap:10px; flex:1;">
            ${groupHeaderExtraHtml}
      `;
      groups[g].sort((a, b) => a.localeCompare(b)).forEach(it => {
        const checkIcon = `<svg width="14" height="14" viewBox="0 0 24 24" fill="#cba153" style="min-width:14px;"><circle cx="12" cy="12" r="12"/><path d="M7 12l3 3 7-7" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
        const pillBg = isFreebie ? '#f9f1e1' : '#fdfbf7';
        const pillBorder = isFreebie ? 'border: 1px solid #cba153;' : 'border: 1px solid rgba(203,161,83,0.25);';
        const pillClass = isFreebie ? 'pm-pill pm-pill-freebie' : 'pm-pill';

        html += `
          <span class="${pillClass}" style="display:inline-flex; align-items:center; gap:8px; padding: 6px 14px; border-radius: 20px; font-size:13px; color:#5c4f44; background:${pillBg}; ${pillBorder}">
            ${checkIcon}
            ${it}
          </span>
        `;
      });
      html += `</div></div>`;
    });
    return html;
  };

  // Main package items excluding freebies
  const mainItemNames = p.items ? p.items.filter(it => !((p.freebieItems || []).includes(it))) : [];
  const itemGrid = document.getElementById('pm-items');
  itemGrid.className = '';
  itemGrid.innerHTML = renderGroupedItems(mainItemNames, false);

  // Freebies section
  let freebiesHtml = '';
  if (p.freebieItems && p.freebieItems.length > 0) {
    freebiesHtml = `
      <div style="margin-top:20px;">
        <div style="position:relative; text-align:center; margin-bottom:10px; margin-top: 30px;">
          <div style="position:absolute; top:50%; left:0; right:0; height:1px; background:rgba(203,161,83,0.4); z-index:1;"></div>
          <span style="position:relative; z-index:2; background:#fcf9f2; padding:0 15px; color:#cba153; font-size:11px; font-weight:800; letter-spacing:1.5px; text-transform:uppercase;">FREEBIES INCLUDED</span>
        </div>
        ${renderGroupedItems(p.freebieItems, true)}
      </div>`;
  }

  // Inject freebies after pm-items
  let freebiesEl = document.getElementById('pm-freebies');
  if (!freebiesEl) {
    freebiesEl = document.createElement('div');
    freebiesEl.id = 'pm-freebies';
    itemGrid.parentNode.insertBefore(freebiesEl, itemGrid.nextSibling);
  }
  freebiesEl.innerHTML = freebiesHtml;

  document.getElementById('pkg-modal-overlay').classList.add('on');
  document.body.style.overflow = 'hidden';
}
function closePkgModal() {
  document.getElementById('pkg-modal-overlay').classList.remove('on');
  document.body.style.overflow = '';
  document.body.style.overflow = '';
}
window.openPkgModal = openPkgModal;
window.openPremadePackageModal = openPkgModal;
window.closePkgModal = closePkgModal;

window.onPmTierChange = function () {
  const p = PKGS.find(x => x.name === document.getElementById('pm-title').textContent);
  if (!p) return;
  let tiers = p.priceTiers || p.price_tiers || [];
  if (typeof tiers === 'string') {
    try { tiers = JSON.parse(tiers); } catch (e) { tiers = []; }
  }
  if (!Array.isArray(tiers) || tiers.length === 0) return;
  const select = document.getElementById('pm-tier-select');
  if (!select) return;
  const tier = tiers[select.value];
  if (!tier) return;

  const priceEl = document.getElementById('pm-price');
  const priceSubEl = document.getElementById('pm-price-sub');

  if (priceEl) priceEl.textContent = '\u20b1' + Number(tier.price || 0).toLocaleString();
  if (priceSubEl) priceSubEl.textContent = 'fixed for ' + (tier.label || (tier.pax + ' pax'));

  window.pmSelectedTier = tier;
};

// ── PREMADE PACKAGE LOCKED MODIFICATION NOTICE MODAL ──
let _pendingPremadePkgNotice = null;

function promptPremadePackageModalNotice(pkgId, tier) {
  _pendingPremadePkgNotice = { pkgId, tier };
  const o = document.getElementById('premade-pkg-locked-overlay');
  const m = document.getElementById('premade-pkg-locked-modal');
  if (o) {
    o.style.display = 'block';
    o.classList.add('on');
  }
  if (m) {
    m.style.display = 'flex';
    m.classList.add('open');
    m.style.visibility = 'visible';
    m.style.opacity = '1';
    m.style.pointerEvents = 'all';
  }
}
window.promptPremadePackageModalNotice = promptPremadePackageModalNotice;

function closePremadePkgLockedModal() {
  _pendingPremadePkgNotice = null;
  const o = document.getElementById('premade-pkg-locked-overlay');
  const m = document.getElementById('premade-pkg-locked-modal');
  if (o) {
    o.style.display = 'none';
    o.classList.remove('on');
  }
  if (m) {
    m.style.display = 'none';
    m.classList.remove('open');
    m.style.visibility = 'hidden';
    m.style.opacity = '0';
    m.style.pointerEvents = 'none';
  }
}
window.closePremadePkgLockedModal = closePremadePkgLockedModal;

function confirmPremadePkgLockedProceed() {
  const pending = _pendingPremadePkgNotice;
  closePremadePkgLockedModal();
  if (pending && pending.pkgId) {
    applyPremadePkg(pending.pkgId, pending.tier);
    closePkgModal();
    if (typeof openCustomPanel === 'function') openCustomPanel();
  }
}
window.confirmPremadePkgLockedProceed = confirmPremadePkgLockedProceed;

function applyPremadePkg(id, tier = null) {
  const p = PKGS.find(x => x.id === id);
  if (!p) return;

  // Clear auto-allocations from any previous custom state
  if (typeof renderAutoAllocations === 'function') renderAutoAllocations([]);
  // Also clear all text fields from the previous custom state
  const _fieldsToClear = ['cpkg-desc', 'cpkg-pax', 'cpkg-date', 'cpkg-timeframe', 'cpkg-calltime', 'cpkg-budget', 'cpkg-venue', 'cpkg-venue-location'];
  _fieldsToClear.forEach(fid => { const fel = document.getElementById(fid); if (fel) fel.value = ''; });
  // Reset time inputs
  const _tsEl = document.getElementById('cpkg-timeframe-start');
  const _teEl = document.getElementById('cpkg-timeframe-end');
  if (_tsEl) _tsEl.value = '';
  if (_teEl) _teEl.value = '';
  // Reset VIP
  const _vipCheck = document.getElementById('cpkg-vip-check');
  if (_vipCheck) { _vipCheck.checked = false; if (typeof toggleVIPFields === 'function') toggleVIPFields(); }
  // Reset meeting times
  if (typeof preferredMeetingTimes !== 'undefined') { preferredMeetingTimes = []; }
  if (typeof renderMeetingTimes === 'function') renderMeetingTimes();

  activePkg = p;
  window.activeTier = tier;
  const titleEl = document.getElementById('cpkg-title-text') || document.querySelector('.cpkg-title');
  if (titleEl) titleEl.textContent = p.name;

  // Fill text fields using smartAssign to properly handle theme and occasion matching
  if (window.smartAssign) {
    if (p.theme) window.smartAssign('cpkg-theme', p.theme);
    if (p.occasion) window.smartAssign('cpkg-occasion', p.occasion);
  } else {
    const themeEl = document.getElementById('cpkg-theme');
    const occEl = document.getElementById('cpkg-occasion');
    if (themeEl) themeEl.value = p.theme;
    if (occEl) occEl.value = p.occasion;
  }
  const paxEl = document.getElementById('cpkg-pax');
  if (tier && paxEl) paxEl.value = tier.pax;
  const pkgPm = (p.pricingMode || p.pricing_mode || '').toLowerCase();
  const isPerHead = pkgPm === 'per_head' || pkgPm === 'per head' || pkgPm === 'dynamically_set' || pkgPm === 'dynamically set' || (!pkgPm && p.pricePerHead > 0 && !p.fixedPrice);
  const tiers = p.priceTiers || p.price_tiers || [];
  if (tiers.length > 0 && !isPerHead) {
    window.activeTier = tier || tiers[0];
    const paxVal = window.activeTier.pax || parseInt(window.activeTier.label) || p.fixedPax || 50;
    if (paxEl) paxEl.value = paxVal;
  } else {
    if (p.fixedPax && paxEl) paxEl.value = p.fixedPax;
    else if (paxEl && (!paxEl.value || parseInt(paxEl.value) === 0)) paxEl.value = 50;
    window.activeTier = null;
  }

  // Add items to package
  customPkgItems = [];
  const freeIds = new Set(p.freeItemIds || []);
  const freebieIds = new Set(p.freebieItemIds || []);

  p.itemIds.forEach(iid => {
    const item = CAT.find(i => i.id === iid);
    if (item) {
      const newItem = { ...item };
      if (freeIds.has(iid) || freebieIds.has(iid)) {
        newItem.isFree = true;
      } else if (item.name.toLowerCase().includes('rice') ||
        (item.cat === 'dessert' && item.price < 1500)) {
        newItem.isFree = true;
      }
      customPkgItems.push(newItem);
    }
  });

  // Add freebie items too (shown as free)
  (p.freebieItemIds || []).forEach(iid => {
    if (customPkgItems.find(c => c.id === iid)) return; // already added
    const item = CAT.find(i => i.id === iid);
    if (item) {
      customPkgItems.push({ ...item, isFree: true, isFreebie: true });
    }
  });

  // Automatically select the corresponding Event Setup for the premade package & lock it
  const setupEl = document.getElementById('cpkg-event-setup');
  if (setupEl) {
    let targetSlug = p.eventSetupSlug || p.event_setup_slug;
    if (!targetSlug && p.eventSetupName) {
      const matchingSetup = (window.EVENT_SETUPS || []).find(s => s.name.toLowerCase() === p.eventSetupName.toLowerCase());
      if (matchingSetup) targetSlug = matchingSetup.slug;
    }
    if (!targetSlug) {
      const slug = (p.slug || p.name || '').toLowerCase();
      if (slug.includes('kiddie')) targetSlug = 'complete_setup_basic_chairs';
      else targetSlug = 'complete_setup';
    }
    setupEl.value = targetSlug;
    setupEl.disabled = true;
    setupEl.style.cursor = 'not-allowed';
    setupEl.style.opacity = '0.75';
    setupEl.title = 'Event setup is locked for pre-made packages.';
    if (typeof onEventSetupChange === 'function') onEventSetupChange();
  }

  renderCat();
  renderCustomPkg();
  updateDawContextBar();

  // Force-save immediately after applying premade package (bypass _draftLoaded guard)
  window._draftLoaded = true;
  saveCustomPkgStateToStorage();

  // Scroll to workspace
  go('#catalog');

  // Show a mini notification
  if (typeof openErrorModal === 'function') {
    openErrorModal(`Successfully applied ${p.name}! You can now see the items in your workspace and modify them.`, 'Success!');
  }
}
window.applyPremadePkg = applyPremadePkg;

