window.finalizePackage = finalizePackage;

function executeFinalizePackageValidation() {
  if (!currentUser) {
    window.pendingFinalize = true;
    openAuth();
    showAuthMsg('login-msg', 'success', 'Please log in or create an account to save and finalize your package. Your selections will be preserved.');
    return;
  }

  // Validate required fields safely
  const getV = window.getSmartV;

  const desc = getV('cpkg-desc');
  const theme = getV('cpkg-theme');
  const pax = getV('cpkg-pax');
  const date = getV('cpkg-date');
  const occasion = getV('cpkg-occasion');
  const venueLocation = getV('cpkg-venue-location');
  const venue = getV('cpkg-venue');
  const timeframe = getV('cpkg-timeframe');

  const callTime = document.getElementById('cpkg-calltime')?.value || '';
  const eventSetupSlug = document.getElementById('cpkg-event-setup')?.value || '';

  let errors = [];
  let missing = [];

  if (!desc) missing.push('Event Description');
  if (!occasion) missing.push('Occasion');
  if (!theme) missing.push('Theme / Style');
  if (!eventSetupSlug) missing.push('Setup Type');
  if (!pax) missing.push('Pax (Guest Count)');
  if (!callTime) missing.push('Call Time');
  if (!date) missing.push('Event Date');
  if (!timeframe) missing.push('Event Time Frame');
  if (!venueLocation) missing.push('Venue Location (City)');
  if (!venue) missing.push('Venue / Location (Map Pin)');

  if (missing.length > 0) {
    errors.push('Please fill in the following required fields:\n- ' + missing.join('\n- '));
  }

  // PAX validation
  if (pax) {
    const paxNum = parseInt(pax);
    if (isNaN(paxNum) || paxNum < 10) {
      errors.push('Guest count too few. It is not efficient to book a catering service for such a small number of people. Please enter at least 10 guests.');
    } else if (paxNum > 200) {
      errors.push('The business cannot cater to a guest count above 200. Please reconsider and lower your guest count.');
    }
  }

  // VIP count validation
  const vipEnabled = document.getElementById('cpkg-vip-check')?.checked;
  const vipCountStr = document.getElementById('cpkg-vip-count')?.value;
  const vipCount = parseInt(vipCountStr) || 0;
  if (vipEnabled) {
    if (!vipCountStr || vipCount <= 0) {
      errors.push('You have chosen to include VIPs but have not specified the number of VIPs. Please enter a valid VIP count.');
    } else if (pax && vipCount > parseInt(pax)) {
      errors.push('VIPs cannot exceed total guest count (Pax).');
    }
  }

  // Meeting slot validation (skipped if customer is modifying an existing active reservation)
  if (!window._isModifyingActiveReservation) {
    if (typeof preferredMeetingTimes !== 'undefined' && preferredMeetingTimes.length === 0) {
      errors.push('You must add at least one preferred time slot for a meeting before you can finalize your package.');
    }
  }

  // Event date validation
  if (date) {
    const eventDate = new Date(date + 'T00:00:00');
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const todayMs = today.getTime();
    const eventDateMs = eventDate.getTime();

    if (isNaN(eventDateMs) || eventDateMs < todayMs) {
      errors.push('The event date you selected has already passed. Please select a valid future date.');
    } else {
      const minDaysAhead = 14; 
      const maxYearsAhead = 50; 
      const msPerDay = 86400000;
      if ((eventDateMs - todayMs) < minDaysAhead * msPerDay) {
        errors.push(`Your event date is too soon. The business requires a minimum of ${minDaysAhead} days notice for event preparation. Please select a date at least ${minDaysAhead} days from today.`);
      }
      const maxDateLimitObj = new Date(todayMs);
      maxDateLimitObj.setFullYear(maxDateLimitObj.getFullYear() + maxYearsAhead);
      if (eventDateMs > maxDateLimitObj.getTime()) {
        errors.push(`The event date you selected is too far into the future. The business does not accept bookings more than ${maxYearsAhead} years in advance.`);
      }
    }
  }

  // Timeframe validation (min 1 hour)
  let tfStart = null, tfEnd = null;
  if (timeframe) {
    const tfParts = timeframe.split('-').map(s => s.trim());
    if (tfParts.length < 2) {
      errors.push('Please select a valid event time frame with a start and end time.');
    } else {
      const toMinutes = (t) => {
        const [h, m] = t.split(':').map(Number);
        return (isNaN(h) || isNaN(m)) ? null : h * 60 + m;
      };
      tfStart = toMinutes(tfParts[0]);
      tfEnd = toMinutes(tfParts[1]);
      if (tfStart === null || tfEnd === null) {
        errors.push('Please select a valid event time frame with a start and end time.');
      } else {
        let tfDuration = tfEnd - tfStart;
        if (tfDuration <= 0) {
          tfDuration = (tfEnd + 1440) - tfStart;
        }
        if (tfDuration < 60) {
          errors.push('The event time frame is a little too short for an event. Please make it reasonably longer for the service to be worth it. (Minimum: 1 hour)');
        }
      }
    }
  }

  // Call Time validation
  if (callTime && tfStart !== null) {
    const toMin2 = (t) => { const [h, m] = t.split(':').map(Number); return (isNaN(h) || isNaN(m)) ? null : h * 60 + m; };
    const ctMin = toMin2(callTime);
    if (ctMin !== null && ctMin > tfStart) {
      errors.push('The call time cannot be later than the event start time. Call time must be at or before the event start.');
    }
  }

  // Strict category validation
  const isCustomSetup = eventSetupSlug === 'custom';
  const hasFood = customPkgItems.some(i => i.cat === 'food' || i.cat === 'dessert');
  const hasUnlimitedDrinks = customPkgItems.some(i => i.identify === 'drinks_package');
  const hasSpecificDrink = customPkgItems.some(i => i.cat === 'drink' && i.identify !== 'drinks_package');

  if (!hasFood) {
    errors.push('Food selections are required. Please select at least one item from the Food category before finalizing.');
  }
  if (hasUnlimitedDrinks && !hasSpecificDrink) {
    errors.push('You have selected the Unlimited Drinks package, but you must also select at least one specific type of drink to serve. Please add your drink choices from the Drinks tab.');
  }

  if (errors.length > 0) {
    if (typeof openErrorModal === 'function') openErrorModal(errors.join('\n\n'));
    else alert(errors.join('\n\n'));
    return;
  }

  // ── Custom Setup confirmation modal gate ──
  if (isCustomSetup && !window._customSetupConfirmed) {
    openCustomSetupConfirmModal();
    return;
  }

  // ── Check same-day capacity (Max 3 reservations per date) ──
  (async () => {
    try {
      const sb = window.supabaseClient || window.supabase;
      if (sb && date) {
        const { data: dateRes, error } = await sb
          .from('reservations')
          .select('id, date, status')
          .eq('date', date)
          .neq('status', 'cancelled')
          .neq('status', 'rejected');

        if (!error && dateRes && dateRes.length >= 3) {
          const dateInput = document.getElementById('cpkg-date');
          if (dateInput) dateInput.value = '';
          const msg = 'The date you selected is already fully booked. Please select a different date for your reservation.';
          if (typeof openErrorModal === 'function') openErrorModal(msg);
          else alert(msg);
          return;
        }
      }
    } catch (e) {
      console.warn('Could not check reservation date capacity:', e);
    }

    // All validations passed : show Reservation & Payment Notice before adding to cart
    openPreCheckoutNoticeModal();
  })();
}


function finalizePackageInternal(name) {
  const getV = window.getSmartV;
  const desc = getV('cpkg-desc');
  const theme = getV('cpkg-theme');
  const pax = getV('cpkg-pax');
  const date = getV('cpkg-date');
  const occasion = getV('cpkg-occasion');
  const venueLocation = getV('cpkg-venue-location');
  const venue = getV('cpkg-venue');
  const timeframe = getV('cpkg-timeframe');
  const callTime = document.getElementById('cpkg-calltime')?.value || '';

  // Event Setup : mandatory
  const eventSetupSlug = document.getElementById('cpkg-event-setup')?.value || '';
  if (!eventSetupSlug) {
    if (typeof openErrorModal === 'function') openErrorModal('Please select an Event Setup before finalizing your package.');
    else alert('Please select an Event Setup before finalizing your package.');
    return;
  }
  const _eventSetupObj = (window.EVENT_SETUPS || []).find(s => s.slug === eventSetupSlug) || null;
  const eventSetupName = _eventSetupObj?.name || eventSetupSlug;
  let eventSetupEquipment = _eventSetupObj?.equipment_items || [];
  if (typeof eventSetupEquipment === 'string') {
    try { eventSetupEquipment = JSON.parse(eventSetupEquipment); } catch (e) { eventSetupEquipment = []; }
  }
  if (!Array.isArray(eventSetupEquipment)) eventSetupEquipment = [];

  let basePackageTotal = 0;
  let additionalCharges = 0;
  const extraItemsList = [];
  const pCountNum = parseInt(pax) || 0;

  if (activePkg) {
    const pm = (activePkg.pricingMode || activePkg.pricing_mode || '').toLowerCase();
    const tiers = activePkg.priceTiers || activePkg.price_tiers || [];
    const isPerHead = pm === 'per_head' || pm === 'per head' || pm === 'dynamically_set' || pm === 'dynamically set' || (!pm && activePkg.pricePerHead > 0 && !activePkg.fixedPrice);

    if (window.activeTier && window.activeTier.price) {
      basePackageTotal = window.activeTier.price;
    } else if (tiers.length > 0 && !isPerHead) {
      const matched = tiers.find(t => (t.pax === pCountNum || parseInt(t.label) === pCountNum));
      basePackageTotal = matched ? matched.price : (tiers[0].price || 0);
    } else if (isPerHead) {
      basePackageTotal = (activePkg.pricePerHead || 0) * pCountNum;
    } else {
      basePackageTotal = activePkg.fixedPrice || activePkg.price || 0;
    }

    // Add cost for items that are NOT part of the original premade package template
    const origItemIds = new Set(activePkg.itemIds || []);
    customPkgItems.forEach(item => {
      const isOriginal = origItemIds.has(item.id);
      if (!isOriginal && !item.isFree && !item.isAutoAdded && !item.isFreebie) {
        const itemPrice = getDynamicPrice(item, pCountNum);
        additionalCharges += itemPrice;
        extraItemsList.push({
          id: item.id,
          name: item.name,
          price: itemPrice
        });
      }
    });
  } else {
    basePackageTotal = customPkgItems.reduce((s, i) => s + getDynamicPrice(i, pCountNum), 0);
  }

  const subtotalBeforeOutOfTown = basePackageTotal + additionalCharges;
  const venueAddr = (venue || venueLocation || '').trim();
  const isOutOfTown = venueAddr !== '' && !venueAddr.toLowerCase().includes('malabon');
  const otcRateObj = (typeof getDistanceFeeRate === 'function') ? getDistanceFeeRate(venueAddr, window.lastMapCoords) : { percentage: 5 };
  const otcPct = otcRateObj.percentage || 0;
  const outOfTownCharge = (isOutOfTown && otcPct > 0) ? Math.round(subtotalBeforeOutOfTown * (otcPct / 100)) : 0;
  const finalTotal = subtotalBeforeOutOfTown + outOfTownCharge;

  const summary = {
    id: 'custom_' + Date.now(),
    isCustom: true,
    pricingMode: activePkg?.pricingMode || 'item-based',
    activePkgId: activePkg?.id || null,
    selectedTier: window.activeTier || null,
    fixedPax: activePkg?.fixedPax || null,
    fixedPrice: activePkg?.fixedPrice || null,
    pricePerHead: activePkg?.pricePerHead || 0,
    name: name.trim(),
    premadePackageName: (activePkg && activePkg.name) ? activePkg.name : null,
    desc, theme, pax, date, time: timeframe, occasion, venue, venueLocation,
    callTime,
    outOfTownCharge,
    additionalCharges,
    additionalChargesItems: extraItemsList,
    isVIP: document.getElementById('cpkg-vip-check')?.checked || false,
    vipCount: parseInt(document.getElementById('cpkg-vip-count')?.value) || 0,
    vipService: document.getElementById('cpkg-vip-service')?.value || '',
    meetingTimes: [...preferredMeetingTimes],
    items: customPkgItems.map(i => ({ ...i, snapshotPrice: getDynamicPrice(i, pax) })),
    total: finalTotal,
    price: finalTotal,
    baseTotal: basePackageTotal,
    icon: '',
    eventSetup: eventSetupName,
    eventSetupSlug,
    eventSetupEquipment,
    priceTiers: (activePkg && (activePkg.priceTiers || activePkg.price_tiers) && (activePkg.priceTiers || activePkg.price_tiers).length > 0)
      ? (activePkg.priceTiers || activePkg.price_tiers)
      : null
  };

  if (cart.length >= 3) {
    if (typeof openErrorModal === 'function') openErrorModal('Your cart already has 3 packages. Please remove or checkout a package before adding another.');
    else alert('Your cart already has 3 packages. Please remove or checkout one first.');
    return;
  }

  cart.push(summary);
  saveCartToSupabase();
  renderCart();
  const drawer = document.getElementById('cart-drawer');
  if (drawer) drawer.classList.add('open');
  const overlay = document.getElementById('cart-overlay');
  if (overlay) overlay.classList.add('on');

  // Reset custom setup confirmation flag
  window._customSetupConfirmed = false;

  // Full reset : clear all state so the workspace is completely blank
  try { localStorage.removeItem('halden_custom_pkg_draft'); } catch (e) { }
  customPkgItems = [];
  activePkg = null;
  window.activeTier = null;
  preferredMeetingTimes = [];
  renderMeetingTimes();

  const titleEl = document.querySelector('.cpkg-title');
  if (titleEl) titleEl.textContent = 'Custom Package';

  ['cpkg-desc', 'cpkg-theme', 'cpkg-pax', 'cpkg-date', 'cpkg-timeframe', 'cpkg-occasion', 'cpkg-venue-location', 'cpkg-venue', 'cpkg-budget', 'cpkg-calltime'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  // Reset event setup to default (Complete Setup) and unlock
  const _esSel = document.getElementById('cpkg-event-setup');
  if (_esSel) {
    _esSel.disabled = false;
    _esSel.style.cursor = 'pointer';
    _esSel.style.opacity = '1';
    _esSel.value = 'complete_setup';
    _esSel.removeAttribute('title');
    onEventSetupChange();
  }
  // Reset time inputs
  const tsEl = document.getElementById('cpkg-timeframe-start');
  const teEl = document.getElementById('cpkg-timeframe-end');
  if (tsEl) tsEl.value = '';
  if (teEl) teEl.value = '';

  // Reset VIP fields
  const vipCheck = document.getElementById('cpkg-vip-check');
  if (vipCheck) { vipCheck.checked = false; toggleVIPFields(); }

  renderCustomPkg();  // auto-allocator will see 0 pax + empty items → no system additions
  renderCat();

  // Close items view if open
  const panel = document.getElementById('cpkg-panel');
  const view = document.getElementById('cpkg-selected-items-view');
  if (panel) panel.classList.remove('view-items-open');
  if (view) view.classList.remove('open');

  console.log('Finalize successful');
}

window.resetCustomPackage = function () {
  try { localStorage.removeItem('halden_custom_pkg_draft'); } catch (e) { }
  customPkgItems = [];
  activePkg = null;
  window.activeTier = null;
  preferredMeetingTimes = [];
  editingPkgName = '';
  if (typeof renderMeetingTimes === 'function') renderMeetingTimes();

  const titleEl = document.getElementById('cpkg-title-text') || document.querySelector('.cpkg-title');
  if (titleEl) titleEl.textContent = 'My Custom Package';

  // Unlock event setup dropdown
  const setupEl = document.getElementById('cpkg-event-setup');
  if (setupEl) {
    setupEl.disabled = false;
    setupEl.style.cursor = 'pointer';
    setupEl.style.opacity = '1';
    setupEl.value = 'complete_setup';
    setupEl.removeAttribute('title');
    if (typeof onEventSetupChange === 'function') onEventSetupChange();
  }

  ['cpkg-desc', 'cpkg-theme', 'cpkg-pax', 'cpkg-date', 'cpkg-occasion', 'cpkg-venue-location', 'cpkg-venue', 'cpkg-budget', 'cpkg-calltime', 'cpkg-occasion-other', 'cpkg-theme-other'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.value = '';
      if (id.endsWith('-other')) el.style.display = 'none';
    }
  });

  const tsEl = document.getElementById('cpkg-timeframe-start');
  const teEl = document.getElementById('cpkg-timeframe-end');
  if (tsEl) tsEl.value = '';
  if (teEl) teEl.value = '';

  const vipCheck = document.getElementById('cpkg-vip-check');
  if (vipCheck) { vipCheck.checked = false; if (typeof toggleVIPFields === 'function') toggleVIPFields(); }

  const paxEl = document.getElementById('cpkg-pax');
  const paxSel = document.getElementById('cpkg-pax-select');
  if (paxEl) { paxEl.style.display = 'block'; paxEl.value = ''; paxEl.readOnly = false; paxEl.title = ''; }
  if (paxSel) { paxSel.style.display = 'none'; paxSel.innerHTML = ''; paxSel.disabled = false; }

  const budgetEl = document.getElementById('cpkg-budget');
  if (budgetEl) {
    budgetEl.readOnly = false;
    budgetEl.placeholder = 'e.g. 50000';
    budgetEl.style.opacity = '1';
    budgetEl.style.cursor = 'text';
  }

  const panel = document.getElementById('cpkg-panel');
  const view = document.getElementById('cpkg-selected-items-view');
  if (panel) panel.classList.remove('view-items-open');
  if (view) view.classList.remove('open');

  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof renderCat === 'function') renderCat();
  if (typeof renderFullCatalog === 'function') renderFullCatalog();
  if (typeof updateDawContextBar === 'function') updateDawContextBar();
};

window.openResetConfirmModal = function () {
  const modal = document.getElementById('reset-confirm-modal');
  if (modal) modal.classList.remove('hidden');
};

window.closeResetConfirmModal = function (e) {
  if (!e || e.target.id === 'reset-confirm-modal' || e.target.classList.contains('close-reset-modal')) {
    const modal = document.getElementById('reset-confirm-modal');
    if (modal) modal.classList.add('hidden');
  }
};

window.confirmResetPackage = function () {
  window.resetCustomPackage();
  const modal = document.getElementById('reset-confirm-modal');
  if (modal) modal.classList.add('hidden');
};


function runEquipmentAutoAllocation() {
  if (window._blockAutoAlloc) return;

  // Capture any existing customizations on auto-added items before stripping
  const prevCustomizations = new Map();
  customPkgItems.forEach(item => {
    if (item.customQty || item.specifications || item.isLocked) {
      prevCustomizations.set((item.name || '').toLowerCase(), {
        customQty: item.customQty,
        specifications: item.specifications,
        isLocked: item.isLocked
      });
    }
  });

  // Always strip previously auto-allocated items before recalculating
  customPkgItems = customPkgItems.filter(item => !item.isAutoAdded);

  const vipCheck = document.getElementById('cpkg-vip-check');
  const hasVip = !!(vipCheck && vipCheck.checked);

  // ── Pre-made Package Setup Equipment & VIP Auto-Allocation ──
  // Pre-made package template items are fixed, but associated event setup equipments
  // and VIP guest equipment must dynamically auto-allocate and appear in Selected Items!
  if (activePkg) {
    const autoAdded = [];

    // Auto-allocate event setup equipment items associated with this premade package
    const setupSlug = document.getElementById('cpkg-event-setup')?.value || activePkg.eventSetupSlug || activePkg.event_setup_slug || 'complete_setup';
    const setupObj = (window.EVENT_SETUPS || []).find(s => s.slug === setupSlug) || (window.EVENT_SETUPS || [])[0];
    let setupItems = setupObj?.equipment_items || [];
    if (typeof setupItems === 'string') {
      try { setupItems = JSON.parse(setupItems); } catch (e) { setupItems = []; }
    }
    if (!Array.isArray(setupItems) || setupItems.length === 0) {
      setupItems = ['Tiffany Chair', 'Round Banquet Table', 'Table Cloth', 'Table Runner', 'Chair Cover', 'Cloth Napkin', 'Plate', 'Spoon', 'Fork', 'Water Glass'];
    }

    setupItems.forEach(n => {
      let catItem = CAT.find(i => i.name.toLowerCase() === n.toLowerCase());
      if (!catItem && n.toLowerCase() === 'plate') catItem = CAT.find(i => i.name.toLowerCase() === 'dinner plate');
      if (!catItem && n.toLowerCase() === 'dinner plate') catItem = CAT.find(i => i.name.toLowerCase() === 'plate');
      if (catItem) {
        if (!customPkgItems.find(i => i.name.toLowerCase() === catItem.name.toLowerCase())) {
          const cloned = { ...catItem, isEventSetupEquipment: true, isAutoAdded: true, isFree: true, autoReason: 'Included in Event Setup.' };
          customPkgItems.push(cloned);
          autoAdded.push(cloned);
        }
      }
    });

    if (hasVip) {
      CAT.forEach(catItem => {
        if (catItem.cat === 'equipment' && (catItem.allocationType === 'every_vip' || catItem.pricingType === 'every_vip')) {
          if (catItem.name && catItem.name.includes('(BATCH-')) return;
          if (customPkgItems.find(i => i.name.toLowerCase() === catItem.name.toLowerCase())) return;
          const cloned = { ...catItem, isAutoAdded: true, autoReason: 'Auto-allocated for VIP guests.' };
          customPkgItems.push(cloned);
          autoAdded.push(cloned);
        }
      });
    }
    renderAutoAllocations(autoAdded);
    return;
  }

  const pax = document.getElementById('cpkg-pax')?.value || 0;
  const pCount = parseInt(pax) || 0;
  const setupSlug = document.getElementById('cpkg-event-setup')?.value || '';
  const isCustomSetup = (setupSlug === 'custom');

  // Custom Setup: completely remove all auto-allocated equipment
  if (isCustomSetup) {
    customPkgItems = customPkgItems.filter(item => !item.isAutoAdded && !item.isEventSetupEquipment);
    renderAutoAllocations([]);
    return;
  }

  if (pCount <= 0 && customPkgItems.length === 0 && !hasVip) {
    renderAutoAllocations([]);
    return;
  }

  const autoAdded = [];

  const addAutoItem = (name, reason) => {
    if (window._userRemovedAutoAllocations && window._userRemovedAutoAllocations.has(name.toLowerCase())) return;
    if (customPkgItems.find(i => i.name.toLowerCase() === name.toLowerCase())) return;
    let catItem = CAT.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (!catItem && name.toLowerCase() === 'plate') catItem = CAT.find(i => i.name.toLowerCase() === 'dinner plate');
    if (!catItem && name.toLowerCase() === 'dinner plate') catItem = CAT.find(i => i.name.toLowerCase() === 'plate');
    if (catItem) {
      if (customPkgItems.find(i => i.name.toLowerCase() === catItem.name.toLowerCase())) return;
      const cloned = { ...catItem, isAutoAdded: true, autoReason: reason };
      if (prevCustomizations.has(cloned.name.toLowerCase())) {
        const prev = prevCustomizations.get(cloned.name.toLowerCase());
        if (prev.customQty) cloned.customQty = prev.customQty;
        if (prev.specifications) cloned.specifications = prev.specifications;
        if (prev.isLocked) cloned.isLocked = prev.isLocked;
      }
      customPkgItems.push(cloned);
      autoAdded.push(cloned);
    }
  };

  // ── Setup-filtered base equipment (Custom Packages) ──
  // Only auto-add items that are in the currently selected event setup.
  if (pCount > 0 && !isCustomSetup) {
    const setupObj = (window.EVENT_SETUPS || []).find(s => s.slug === setupSlug);
    let setupItems = setupObj?.equipment_items || [];
    if (typeof setupItems === 'string') {
      try { setupItems = JSON.parse(setupItems); } catch (e) { setupItems = []; }
    }
    if (!Array.isArray(setupItems)) setupItems = [];

    if (setupItems.length > 0) {
      setupItems.forEach(n => addAutoItem(n, 'Auto-allocated based on your Event Setup.'));
    } else {
      ['Tiffany Chair', 'Round Banquet Table', 'Table Cloth', 'Table Runner',
        'Chair Cover', 'Cloth Napkin', 'Plate', 'Spoon', 'Fork', 'Water Glass']
        .forEach(n => addAutoItem(n, 'Auto-allocated based on guest count.'));
    }
  }

  // ── VIP-triggered equipment (Custom Packages) ──
  if (hasVip) {
    CAT.forEach(catItem => {
      if (catItem.cat === 'equipment' && (catItem.allocationType === 'every_vip' || catItem.pricingType === 'every_vip')) {
        if (catItem.name && catItem.name.includes('(BATCH-')) return;
        addAutoItem(catItem.name, 'Auto-allocated for VIP guests.');
      }
    });
  }

  // ── Food-triggered equipment (always added regardless of setup) ──
  let foodCount = 0, hasSoup = false, hasDessert = false, hasSteak = false, hasSalad = false, hasCoffee = false;
  customPkgItems.forEach(i => {
    if (window.isSpecialParentItem && window.isSpecialParentItem(i)) return; // Master special items do not trigger food equipment
    if (!i.isAutoAdded && i.cat === 'food') foodCount++;
    if (i.subcategory === 'Soup') hasSoup = true;
    if (i.cat === 'dessert') hasDessert = true;
    const n = i.name.toLowerCase();
    if (n.includes('steak') || n.includes('roast') || n.includes('lengua')) hasSteak = true;
    if (n.includes('salad') || n.includes('appetizer')) hasSalad = true;
    if (n.includes('coffee')) hasCoffee = true;
  });

  if (foodCount > 0) {
    ['Serving Spoon', 'Serving Fork', 'Serving Tray', 'Food Pan (Full Size)',
      'Chafing Dish', 'Chafing Dish Lid', 'Serving Tongs', 'Soup Bowl', 'Soup Spoon']
      .forEach(n => addAutoItem(n, `Auto-allocated for ${foodCount} menu item(s).`));
  }
  if (hasSoup) { addAutoItem('Soup Bowl', 'Required for soup.'); addAutoItem('Soup Spoon', 'Required for soup.'); }
  if (hasDessert) { addAutoItem('Dessert Plate', 'Required for dessert.'); addAutoItem('Dessert Spoon', 'Required for dessert.'); }
  if (hasSteak) addAutoItem('Dinner Knife', 'Required for meat entrées.');
  if (hasSalad) addAutoItem('Salad Plate', 'Required for salad/appetizer.');
  if (hasCoffee) addAutoItem('Coffee Cup', 'Required for coffee service.');

  // Also apply rules loaded from food_equipment_rules table if available
  if (Array.isArray(window.FOOD_EQUIPMENT_RULES) && window.FOOD_EQUIPMENT_RULES.length > 0) {
    window.FOOD_EQUIPMENT_RULES.forEach(rule => {
      let matched = false;

      // Check trigger categories
      let triggerCats = rule.trigger_categories;
      if (typeof triggerCats === 'string') { try { triggerCats = JSON.parse(triggerCats); } catch (e) { } }
      if (Array.isArray(triggerCats) && triggerCats.length > 0) {
        triggerCats.forEach(tc => {
          const tcl = (tc || '').toLowerCase();
          if ((tcl === 'food' || tcl === 'meal') && foodCount > 0) matched = true;
          if (tcl === 'dessert' && hasDessert) matched = true;
          if ((tcl === 'drink' || tcl === 'beverage') && customPkgItems.some(i => (i.category || i.cat || i.identify || '').toLowerCase().includes('drink'))) matched = true;
        });
      }

      // Check trigger items
      let triggerItems = rule.trigger_items;
      if (typeof triggerItems === 'string') { try { triggerItems = JSON.parse(triggerItems); } catch (e) { } }
      if (Array.isArray(triggerItems) && triggerItems.length > 0) {
        triggerItems.forEach(ti => {
          if (customPkgItems.some(i => (i.name || '').toLowerCase() === (ti || '').toLowerCase())) {
            matched = true;
          }
        });
      }

      // Fallback single trigger_keyword
      if (!matched && rule.trigger_keyword) {
        const triggerKey = rule.trigger_keyword.toLowerCase();
        if (triggerKey === 'dessert' && hasDessert) matched = true;
        else if (triggerKey === 'soup' && hasSoup) matched = true;
        else if (triggerKey === 'steak' && hasSteak) matched = true;
        else if (triggerKey === 'salad' && hasSalad) matched = true;
        else if (triggerKey === 'coffee' && hasCoffee) matched = true;
        else if (triggerKey === 'food' && foodCount > 0) matched = true;
        else if (customPkgItems.some(i => (i.name || '').toLowerCase().includes(triggerKey))) matched = true;
      }

      if (matched) {
        const eqItems = Array.isArray(rule.equipment_items) && rule.equipment_items.length > 0
          ? rule.equipment_items
          : (rule.equipment_name ? [rule.equipment_name] : []);

        eqItems.forEach(eqName => {
          addAutoItem(eqName, `Auto-included based on setup rule.`);
        });
      }
    });
  }

  renderAutoAllocations(autoAdded);
}

function renderAutoAllocations(autoAdded) {
  const fab = document.getElementById('auto-alloc-fab');
  const badge = document.getElementById('auto-alloc-badge');
  const list = document.getElementById('auto-alloc-list');
  if (!fab || !list) return;

  if (autoAdded.length === 0) {
    fab.style.display = 'none';
    list.innerHTML = '';
    return;
  }

  if (badge) badge.textContent = autoAdded.length;
  if (typeof _refreshAutoAllocFabVisibility === 'function') {
    _refreshAutoAllocFabVisibility();
  } else {
    const workspace = document.getElementById('custom-workspace-overlay');
    const isCustomOpen = workspace && workspace.classList.contains('open');
    fab.style.display = isCustomOpen ? 'flex' : 'none';
  }

  list.innerHTML = autoAdded.map(item => `
    <div style="display:flex; justify-content:space-between; align-items:center; background:var(--cream); padding:10px; border-radius:8px; border:1px solid var(--border);">
      <div>
        <div style="font-weight:700; font-size:13px; color:var(--text);">${item.name}</div>
        <div style="font-size:11px; color:var(--text-dim); margin-top:2px;">${item.autoReason}</div>
      </div>
    </div>
  `).join('');
}

window.openAutoAllocModal = function () {
  const overlay = document.getElementById('auto-alloc-overlay');
  const modal = document.getElementById('auto-alloc-modal');
  if (overlay) overlay.style.display = 'block';
  if (modal) modal.classList.add('open');
}

window.closeAutoAllocModal = function () {
  const overlay = document.getElementById('auto-alloc-overlay');
  const modal = document.getElementById('auto-alloc-modal');
  if (overlay) overlay.style.display = 'none';
  if (modal) modal.classList.remove('open');
}

// ── validateCallTime: Ensures call time <= event start time ──
window.validateCallTime = function () {
  const ctEl = document.getElementById('cpkg-calltime');
  const tsEl = document.getElementById('cpkg-timeframe-start');
  if (!ctEl || !tsEl) return;
  const ctVal = ctEl.value; // 'HH:MM'
  const tsVal = tsEl.value; // 'HH:MM'
  if (!ctVal || !tsVal) return;
  const toMin = (v) => { const [h, m] = v.split(':').map(Number); return h * 60 + m; };
  if (toMin(ctVal) > toMin(tsVal)) {
    // Auto-clamp call time to event start time
    ctEl.value = tsVal;
    if (typeof openErrorModal === 'function') {
      openErrorModal('Call time cannot be later than the event start time. It has been set to match the event start time.');
    }
  }
};

window.handleMajorlySetPaxChange = function (selectEl) {
  if (!activePkg) return;
  const val = selectEl.value;
  if (!val) return;

  const selectedPax = parseInt(val);
  const selectedOption = selectEl.options[selectEl.selectedIndex];
  const selectedPrice = parseFloat(selectedOption?.dataset?.price || 0);

  if (!isNaN(selectedPax) && selectedPax > 0) {
    const paxInput = document.getElementById('cpkg-pax');
    if (paxInput) paxInput.value = selectedPax;

    const tiers = activePkg.priceTiers || activePkg.price_tiers || [];
    const foundTier = tiers.find(t => (t.pax === selectedPax || parseInt(t.label) === selectedPax));
    if (foundTier) {
      window.activeTier = foundTier;
    } else if (selectedPrice > 0) {
      window.activeTier = { pax: selectedPax, price: selectedPrice, label: `${selectedPax} Pax` };
    }
  }

  if (typeof renderCat === 'function') renderCat();
  if (typeof renderFullCatalog === 'function') renderFullCatalog();
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof updateDawContextBar === 'function') updateDawContextBar();
};

function renderCustomPkg() {
  if (typeof checkEventDateConflicts === 'function') checkEventDateConflicts();
  if (typeof renderMeetingTimes === 'function') renderMeetingTimes();
  if (typeof validateAllCpkgFields === 'function') validateAllCpkgFields();

  // Sync workspace title with selected premade package or custom title
  const titleEl = document.getElementById('cpkg-title-text') || document.querySelector('.cpkg-title');
  if (titleEl) {
    titleEl.textContent = activePkg ? activePkg.name : (typeof editingPkgName !== 'undefined' && editingPkgName ? editingPkgName : 'My Custom Package');
  }

  runEquipmentAutoAllocation();
  const tot = document.getElementById('cpkg-total');
  const cnt = document.getElementById('cpkg-count');
  if (!tot || !cnt) return;

  // Handle Majorly Set pax dropdown vs input toggle
  const paxInp = document.getElementById('cpkg-pax');
  const paxSel = document.getElementById('cpkg-pax-select');
  const pm = (activePkg?.pricingMode || activePkg?.pricing_mode || '').toLowerCase();
  const isPerHeadPkg = pm === 'per_head' || pm === 'per head' || pm === 'dynamically_set' || pm === 'dynamically set' || (!pm && activePkg?.pricePerHead > 0 && !activePkg?.fixedPrice);
  const isMajorlySet = !!activePkg && !isPerHeadPkg;

  if (isMajorlySet && paxInp && paxSel) {
    paxInp.style.display = 'none';
    paxSel.style.display = 'block';

    const tiers = activePkg.priceTiers || activePkg.price_tiers || [];
    if (tiers.length > 0) {
      paxSel.disabled = false;
      const currentSelectedPax = parseInt(paxInp.value) || (window.activeTier?.pax) || tiers[0].pax || (tiers[0].label ? parseInt(tiers[0].label) : 0);

      const optionsHtml = tiers.map(t => {
        const tPax = t.pax || parseInt(t.label) || 0;
        const tPrice = t.price || 0;
        // Strictly select based on currentSelectedPax so it doesn't double-select if window.activeTier is outdated
        const isSelected = (tPax === currentSelectedPax);
        return `<option value="${tPax}" data-price="${tPrice}" ${isSelected ? 'selected' : ''}>${tPax} Pax : &#8369;${tPrice.toLocaleString()}</option>`;
      }).join('');

      paxSel.innerHTML = optionsHtml;

      // Always sync activeTier to the selected dropdown option so prices don't mismatch
      if (paxSel.selectedIndex >= 0) {
        const selOpt = paxSel.options[paxSel.selectedIndex];
        if (selOpt && selOpt.value) {
          const sPax = parseInt(selOpt.value);
          const sPrice = parseFloat(selOpt.dataset.price);
          window.activeTier = tiers.find(t => (t.pax === sPax || parseInt(t.label) === sPax)) || { pax: sPax, price: sPrice, label: `${sPax} Pax` };
          paxInp.value = sPax;
        }
      }
    } else {
      const curPax = parseInt(paxInp.value) || activePkg.fixedPax || 50;
      paxSel.innerHTML = `<option value="${curPax}" selected>${curPax} Pax</option><option value="" disabled>no other options</option>`;
      paxSel.disabled = false;
    }
  } else if (paxInp && paxSel) {
    paxInp.style.display = 'block';
    paxSel.style.display = 'none';
    paxInp.readOnly = false;
    paxInp.title = '';
  }

  const pax = document.getElementById('cpkg-pax')?.value || 0;
  const pCount = parseInt(pax) || 0;

  let basePackageTotal = 0;
  let additionalCharges = 0;
  const extraItemsList = [];

  if (activePkg) {
    const pm = (activePkg.pricingMode || activePkg.pricing_mode || '').toLowerCase();
    const tiers = activePkg.priceTiers || activePkg.price_tiers || [];
    const isPerHead = pm === 'per_head' || pm === 'per head' || pm === 'dynamically_set' || pm === 'dynamically set' || (!pm && activePkg.pricePerHead > 0 && !activePkg.fixedPrice);

    if (window.activeTier && window.activeTier.price) {
      basePackageTotal = window.activeTier.price;
    } else if (tiers.length > 0 && !isPerHead) {
      const matched = tiers.find(t => (t.pax === pCount || parseInt(t.label) === pCount));
      basePackageTotal = matched ? matched.price : (tiers[0].price || 0);
    } else if (isPerHead) {
      basePackageTotal = (activePkg.pricePerHead || 0) * pCount;
    } else {
      basePackageTotal = activePkg.fixedPrice || activePkg.price || 0;
    }

    // Add cost for items that are NOT part of the original premade package template
    const origItemIds = new Set(activePkg.itemIds || []);
    customPkgItems.forEach(item => {
      const isOriginal = origItemIds.has(item.id);
      if (!isOriginal && !item.isFree && !item.isAutoAdded && !item.isFreebie) {
        const itemPrice = getDynamicPrice(item, pCount);
        additionalCharges += itemPrice;
        extraItemsList.push({
          id: item.id,
          name: item.name,
          price: itemPrice
        });
      }
    });
  } else {
    basePackageTotal = customPkgItems.reduce((s, i) => s + getDynamicPrice(i, pCount), 0);
  }

  const subtotalBeforeOutOfTown = basePackageTotal + additionalCharges;
  const venueLocInput = document.getElementById('cpkg-venue-location')?.value || '';
  const venueInput = document.getElementById('cpkg-venue')?.value || '';
  const checkLoc = (venueLocInput || venueInput).trim();
  const isOutOfTown = checkLoc !== '' && !checkLoc.toLowerCase().includes('malabon');
  const otcRateObj = (typeof getDistanceFeeRate === 'function') ? getDistanceFeeRate(checkLoc, window.lastMapCoords) : { percentage: 5 };
  const otcPct = otcRateObj.percentage || 0;
  const outOfTownCharge = (isOutOfTown && otcPct > 0) ? Math.round(subtotalBeforeOutOfTown * (otcPct / 100)) : 0;
  const finalDisplayTotal = subtotalBeforeOutOfTown + outOfTownCharge;

  const budgetInput = document.getElementById('cpkg-budget');
  if (budgetInput) {
    if (isMajorlySet) {
      budgetInput.value = '';
      budgetInput.readOnly = true;
      budgetInput.placeholder = 'Budget locked for majorly set package';
      budgetInput.style.opacity = '0.65';
      budgetInput.style.cursor = 'not-allowed';
    } else if (isPerHeadPkg) {
      budgetInput.value = '';
      budgetInput.readOnly = true;
      budgetInput.placeholder = 'Budget locked for dynamically set package';
      budgetInput.style.opacity = '0.65';
      budgetInput.style.cursor = 'not-allowed';
    } else {
      budgetInput.readOnly = false;
      if (budgetInput.placeholder && budgetInput.placeholder.includes('Budget locked')) {
        budgetInput.placeholder = 'e.g. 50000';
      }
      budgetInput.style.opacity = '1';
      budgetInput.style.cursor = 'text';
    }
  }
  const budget = parseFloat(budgetInput?.value) || 0;
  const priceSum = document.getElementById('cpkg-price-summary');
  if (priceSum) {
    priceSum.textContent = '₱' + finalDisplayTotal.toLocaleString();
    if (budget > 0 && finalDisplayTotal > budget) priceSum.style.background = 'var(--red)';
    else priceSum.style.background = 'var(--primary)';
  }

  // Update out-of-town charge text under estimated package total
  let otcNoteEl = document.getElementById('cpkg-out-of-town-summary-note');
  if (otcNoteEl) {
    if (outOfTownCharge > 0) {
      otcNoteEl.style.display = 'block';
      otcNoteEl.innerHTML = `Out of town charges (+${otcPct}%): +&#8369;${outOfTownCharge.toLocaleString()}`;
    } else {
      otcNoteEl.style.display = 'none';
      otcNoteEl.innerHTML = '';
    }
  }

  // Update out-of-town charge display
  let otcEl = document.getElementById('cpkg-out-of-town-row');
  if (!otcEl) {
    const totEl = document.getElementById('cpkg-total')?.parentElement;
    if (totEl) {
      otcEl = document.createElement('div');
      otcEl.id = 'cpkg-out-of-town-row';
      otcEl.style.cssText = 'font-size:11px; margin-top:4px; font-weight:600; display:none;';
      totEl.appendChild(otcEl);
    }
  }
  if (otcEl) {
    if (outOfTownCharge > 0) {
      otcEl.style.display = 'block';
      otcEl.innerHTML = `<span style="color:var(--gold);">Out of town charges (+${otcPct}%): +&#8369;${outOfTownCharge.toLocaleString()}</span>`;
    } else {
      otcEl.style.display = 'none';
    }
  }

  tot.textContent = '\u20b1' + finalDisplayTotal.toLocaleString();
  cnt.textContent = customPkgItems.length;

  let eqSumEl = document.getElementById('cpkg-equipment-subtotal-row');
  if (!eqSumEl) {
    const totEl = document.getElementById('cpkg-total')?.parentElement;
    if (totEl) {
      eqSumEl = document.createElement('div');
      eqSumEl.id = 'cpkg-equipment-subtotal-row';
      eqSumEl.style.cssText = 'font-size:11px; margin-top:3px; color:var(--gold); font-weight:600;';
      totEl.appendChild(eqSumEl);
    }
  }
  if (eqSumEl) {
    let eqTot = 0;
    customPkgItems.forEach(i => {
      if ((i.cat || '').toLowerCase() === 'equipment') {
        eqTot += getDynamicPrice(i, pCount);
      }
    });
    if (eqTot > 0) {
      eqSumEl.style.display = 'block';
      eqSumEl.innerHTML = `Equipment &amp; Setup: &#8369;${eqTot.toLocaleString()}`;
    } else {
      eqSumEl.style.display = 'none';
    }
  }

  const cats = {
    food: document.getElementById('cpkg-list-food'),
    drink: document.getElementById('cpkg-list-drink'),
    dessert: document.getElementById('cpkg-list-dessert'),
    equipment: document.getElementById('cpkg-list-equipment'),
    fun: document.getElementById('cpkg-list-fun'),
    addons: document.getElementById('cpkg-list-addons'),
    free: document.getElementById('cpkg-list-free')
  };

  // Group items by category rule (equipments always group to equipment regardless of free/included status)
  const groups = { food: [], drink: [], dessert: [], equipment: [], fun: [], addons: [], free: [] };
  customPkgItems.forEach(item => {
    if (item.cat === 'equipment' || item.cat === 'decoration') groups.equipment.push(item);
    else if (item.isFree) groups.free.push(item);
    else if (item.cat === 'food') groups.food.push(item);
    else if (item.cat === 'drink') groups.drink.push(item);
    else if (item.cat === 'dessert') groups.dessert.push(item);
    else if (item.cat === 'entertainment') groups.fun.push(item);
    else if (item.cat === 'photography') groups.addons.push(item);
  });

  Object.keys(cats).forEach(key => {
    const el = cats[key];
    if (!el) return;
    if (!groups[key].length) {
      el.innerHTML = `<div class="cpkg-cat-empty">No items selected</div>`;
    } else {
      el.innerHTML = groups[key].map(item => {
        const pax = document.getElementById('cpkg-pax')?.value || 0;
        const p = parseInt(pax) || 0;
        const dp = getDynamicPrice(item, p);

        let priceDisplay = '&#8369;' + dp.toLocaleString();
        if (item.cat === 'equipment') {
          // Always display price for auto-allocated equipment
          priceDisplay = '&#8369;' + dp.toLocaleString();
        } else if (item.isEventSetupEquipment || (activePkg && (item.isAutoAdded || item.isFree || (activePkg.itemIds && activePkg.itemIds.includes(item.id))))) {
          priceDisplay = '<span style="color:var(--primary); font-size:11px; font-weight:700; text-transform:uppercase;">INCLUDED IN PACKAGE</span>';
        } else if (item.isFree) {
          priceDisplay = '<span style="color:var(--gold); font-weight:800;">FREE</span>';
        } else if (activePkg && activePkg.itemIds && activePkg.itemIds.includes(item.id)) {
          priceDisplay = '<span style="color:var(--primary); font-size:11px; font-weight:700; text-transform:uppercase;">INCLUDED IN PACKAGE</span>';
        } else if (item.isAutoAdded) {
          priceDisplay = '&#8369;' + dp.toLocaleString();
        } else if ((item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar') || item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option') {
          priceDisplay = '<span style="color:var(--primary); font-size:11px; font-weight:700; text-transform:uppercase;">Included</span>';
        }

        const colorInfo = window.getSpecialItemColorInfo(item);
        const theme = window.getTheme ? window.getTheme() : 'dark';
        let rowStyle = '';
        if (colorInfo) {
          const rowBg = theme === 'dark' ? colorInfo.bgDark : colorInfo.bgLight;
          rowStyle = `background:${rowBg}; border-left:3px solid ${colorInfo.border}; border-radius:6px; padding:8px 12px; margin-bottom:6px;`;
        }

        const isMandatoryItem = activePkg && (item.isAutoAdded || (activePkg.itemIds && activePkg.itemIds.includes(item.id)));
        const rmButton = isMandatoryItem 
          ? `<button class="cpkg-item-rm" style="opacity:0.35; cursor:not-allowed;" title="Included in package" disabled>&times;</button>`
          : `<button class="cpkg-item-rm" onclick="removePkgItem('${item.id}')">&times;</button>`;

        let decorOptionSelector = ''; // Hide decoration design options in Make a Reservation area

        let customSpecsInfo = '';
        if (item.cat === 'equipment') {
          const eqQty = window.getEquipmentAllocatedQty ? window.getEquipmentAllocatedQty(item, p) : 1;
          customSpecsInfo = `<div style="font-size:11px; color:var(--gold); margin-top:3px;">Quantity: <strong>${eqQty} pcs</strong>${item.specifications ? ` &bull; <em>${esc(item.specifications)}</em>` : ''}</div>`;
        } else if (item.customPax || item.specifications) {
          customSpecsInfo = `<div style="font-size:11px; color:var(--gold); margin-top:3px;">Portion: <strong>${item.customPax || p} pax</strong>${item.specifications ? ` &bull; <em>${esc(item.specifications)}</em>` : ''}</div>`;
        }

        return `
        <div class="cpkg-item-row" style="${rowStyle}">
          <div class="cpkg-item-inf">
            <div class="cpkg-item-name">${item.name}</div>
            ${customSpecsInfo}
            <div class="cpkg-item-price">${priceDisplay}</div>
          </div>
          ${rmButton}
        </div>`;
      }).join('');
    }
  });

  saveCustomPkgStateToStorage();
}
window.renderCustomPkg = renderCustomPkg;

window.selectPkgDecorOption = function(itemId, optTitle) {
  const item = customPkgItems.find(c => c.id === itemId);
  if (!item) return;
  item.selectedOption = optTitle || '';
  const opt = (item.options || []).find(o => o.title === optTitle);
  item.selectedOptionModifier = (opt && Number(opt.price_modifier)) || 0;
  item.selectedOptionImage = (opt && opt.image_url) || '';
  renderCustomPkg();
};

window._draftLoaded = false;

function saveCustomPkgStateToStorage() {
  if (!window._draftLoaded) return; // Prevent overwriting stored draft during page startup
  try {
    const budget = document.getElementById('cpkg-budget')?.value || '';
    const desc = document.getElementById('cpkg-desc')?.value || '';
    const occasion = window.getSmartV ? window.getSmartV('cpkg-occasion') : '';
    const theme = window.getSmartV ? window.getSmartV('cpkg-theme') : '';
    const setupType = document.getElementById('cpkg-event-setup')?.value || '';
    const pax = document.getElementById('cpkg-pax')?.value || '';
    const calltime = document.getElementById('cpkg-calltime')?.value || '';
    const date = document.getElementById('cpkg-date')?.value || '';
    const tfStart = document.getElementById('cpkg-timeframe-start')?.value || '';
    const tfEnd = document.getElementById('cpkg-timeframe-end')?.value || '';
    const venueLoc = document.getElementById('cpkg-venue-location')?.value || '';
    const venue = document.getElementById('cpkg-venue')?.value || '';
    const vipCheck = document.getElementById('cpkg-vip-check')?.checked || false;
    const vipCount = document.getElementById('cpkg-vip-count')?.value || '';
    const vipService = document.getElementById('cpkg-vip-service')?.value || '';

    const draft = {
      budget, desc, occasion, theme, setupType, pax, calltime, date,
      tfStart, tfEnd, venueLoc, venue, vipCheck, vipCount, vipService,
      items: (customPkgItems || []).map(i => ({
        id: i.id,
        name: i.name,
        cat: i.cat,
        price: i.price,
        isFree: i.isFree,
        isFreebie: i.isFreebie,
        isFreeChoiceApplied: i.isFreeChoiceApplied,
        isAutoAdded: i.isAutoAdded,
        identify: i.identify,
        customPax: i.customPax ? parseInt(i.customPax) : null,
        customQty: i.customQty ? parseInt(i.customQty) : null,
        specifications: i.specifications || '',
        _showCustomizePax: !!i._showCustomizePax,
        _showCustomizeItem: !!i._showCustomizeItem,
        customizedPrice: i.customizedPrice || null
      })),
      activePkgId: activePkg ? activePkg.id : null,
      activePkgName: activePkg ? activePkg.name : null,
      activePkgSlug: activePkg ? activePkg.slug : null,
      activePkgSnapshot: activePkg ? JSON.parse(JSON.stringify(activePkg)) : null,
      activeTier: window.activeTier || null,
      editingPkgName: (typeof editingPkgName !== 'undefined') ? editingPkgName : '',
      meetingTimes: (typeof preferredMeetingTimes !== 'undefined') ? preferredMeetingTimes : []
    };

    localStorage.setItem('halden_custom_pkg_draft', JSON.stringify(draft));
  } catch (e) { }
}

function loadCustomPkgStateFromStorage() {
  try {
    const saved = localStorage.getItem('halden_custom_pkg_draft');
    if (saved) {
      const draft = JSON.parse(saved);
      if (draft) {
        if (draft.budget) {
          const el = document.getElementById('cpkg-budget');
          if (el) el.value = draft.budget;
        }
        if (draft.desc) {
          const el = document.getElementById('cpkg-desc');
          if (el) el.value = draft.desc;
        }
        if (draft.occasion && window.smartAssign) window.smartAssign('cpkg-occasion', draft.occasion);
        if (draft.theme && window.smartAssign) window.smartAssign('cpkg-theme', draft.theme);
        if (draft.setupType) {
          const el = document.getElementById('cpkg-event-setup');
          if (el) {
            el.value = draft.setupType;
            if (typeof onEventSetupChange === 'function') onEventSetupChange();
          }
        }
        if (draft.pax) {
          const el = document.getElementById('cpkg-pax');
          if (el) el.value = draft.pax;
          const selEl = document.getElementById('cpkg-pax-select');
          if (selEl) selEl.value = draft.pax;
        }
        if (draft.calltime) {
          const el = document.getElementById('cpkg-calltime');
          if (el) el.value = draft.calltime;
        }
        if (draft.date) {
          const el = document.getElementById('cpkg-date');
          if (el) el.value = draft.date;
        }
        if (draft.tfStart) {
          const el = document.getElementById('cpkg-timeframe-start');
          if (el) el.value = draft.tfStart;
        }
        if (draft.tfEnd) {
          const el = document.getElementById('cpkg-timeframe-end');
          if (el) el.value = draft.tfEnd;
        }
        if (draft.venueLoc) {
          const el = document.getElementById('cpkg-venue-location');
          if (el) el.value = draft.venueLoc;
        }
        if (draft.venue) {
          const el = document.getElementById('cpkg-venue');
          if (el) el.value = draft.venue;
          const overlayEl = document.getElementById('cpkg-venue-overlay');
          const venueLocEl = document.getElementById('cpkg-venue-location');
          if (overlayEl && venueLocEl) {
            venueLocEl.disabled = true;
            venueLocEl.style.opacity = '0.6';
            venueLocEl.style.cursor = 'not-allowed';
            overlayEl.style.display = 'block';
          }
        }
        if (draft.vipCheck) {
          const vCheck = document.getElementById('cpkg-vip-check');
          if (vCheck) {
            vCheck.checked = true;
            if (typeof toggleVIPFields === 'function') toggleVIPFields();
          }
          if (draft.vipCount) {
            const vCnt = document.getElementById('cpkg-vip-count');
            if (vCnt) vCnt.value = draft.vipCount;
          }
          if (draft.vipService) {
            const vSvc = document.getElementById('cpkg-vip-service');
            if (vSvc) vSvc.value = draft.vipService;
          }
        }

        if (draft.items && Array.isArray(draft.items) && draft.items.length > 0) {
          customPkgItems = draft.items.map(savedItem => {
            const catMatch = (CAT || []).find(c => c.id === savedItem.id || c.name === savedItem.name);
            return {
              ...(catMatch || {}),
              ...savedItem,
              customPax: savedItem.customPax ? parseInt(savedItem.customPax) : null,
              customQty: savedItem.customQty ? parseInt(savedItem.customQty) : null,
              specifications: savedItem.specifications || '',
              _showCustomizePax: !!savedItem._showCustomizePax,
              _showCustomizeItem: !!savedItem._showCustomizeItem
            };
          });
        }

        if (draft.editingPkgName) {
          editingPkgName = draft.editingPkgName;
        }

        // Restore selected premade package (without re-clearing items since we restored them above)
        if (draft.activePkgId || draft.activePkgName) {
          const allPkgs = window.PKGS || [];
          const matchedPkg = allPkgs.find(p => p.id === draft.activePkgId)
            || allPkgs.find(p => draft.activePkgSlug && p.slug === draft.activePkgSlug)
            || allPkgs.find(p => draft.activePkgName && p.name === draft.activePkgName)
            || draft.activePkgSnapshot; // fallback: use the saved snapshot directly
          console.log("[Draft] Restoring premade pkg. draft.activePkgId="+draft.activePkgId+" draft.activePkgName="+draft.activePkgName+" PKGS.length="+allPkgs.length+" matched="+(matchedPkg?matchedPkg.name:"none"));
          if (matchedPkg) {
            activePkg = matchedPkg;
            const titleEl = document.getElementById('cpkg-title-text') || document.querySelector('.cpkg-title');
            if (titleEl) titleEl.textContent = matchedPkg.name;

            // Restore activeTier for tiered packages
            if (draft.activeTier) {
              window.activeTier = draft.activeTier;
            } else {
              // Rebuild activeTier from pax value if not explicitly saved
              const pkgPm = (matchedPkg.pricingMode || matchedPkg.pricing_mode || '').toLowerCase();
              const isPerHead = pkgPm === 'per_head' || pkgPm === 'per head' || pkgPm === 'dynamically_set' || pkgPm === 'dynamically set';
              const tiers = matchedPkg.priceTiers || matchedPkg.price_tiers || [];
              if (tiers.length > 0 && !isPerHead) {
                const savedPax = parseInt(draft.pax) || 0;
                const matchedTier = tiers.find(t => (t.pax === savedPax || parseInt(t.label) === savedPax));
                window.activeTier = matchedTier || tiers[0];
              } else {
                window.activeTier = null;
              }
            }

            // Re-lock the event setup dropdown for premade packages
            const setupEl = document.getElementById('cpkg-event-setup');
            if (setupEl) {
              if (draft.setupType) {
                setupEl.value = draft.setupType;
              } else {
                let targetSlug = matchedPkg.eventSetupSlug || matchedPkg.event_setup_slug;
                if (!targetSlug && matchedPkg.eventSetupName) {
                  const matchingSetup = (window.EVENT_SETUPS || []).find(s => s.name.toLowerCase() === matchedPkg.eventSetupName.toLowerCase());
                  if (matchingSetup) targetSlug = matchingSetup.slug;
                }
                if (!targetSlug) {
                  const slug = (matchedPkg.slug || matchedPkg.name || '').toLowerCase();
                  targetSlug = slug.includes('kiddie') ? 'complete_setup_basic_chairs' : 'complete_setup';
                }
                if (targetSlug) setupEl.value = targetSlug;
              }
              setupEl.disabled = true;
              setupEl.style.cursor = 'not-allowed';
              setupEl.style.opacity = '0.75';
              setupEl.title = 'Event setup is locked for pre-made packages.';
              if (typeof onEventSetupChange === 'function') onEventSetupChange();
            }
          }
        } else {
          activePkg = null;
          const titleEl = document.getElementById('cpkg-title-text') || document.querySelector('.cpkg-title');
          if (titleEl) titleEl.textContent = (typeof editingPkgName !== 'undefined' && editingPkgName ? editingPkgName : 'My Custom Package');
        }

        // Restore preferred meeting times
        if (draft.meetingTimes && Array.isArray(draft.meetingTimes) && draft.meetingTimes.length > 0) {
          if (typeof preferredMeetingTimes !== 'undefined') {
            preferredMeetingTimes = draft.meetingTimes;
            if (typeof renderMeetingTimes === 'function') renderMeetingTimes();
          }
        }
      }
    }
  } catch (e) {
    console.warn('[Draft] Failed to restore custom package state:', e);
  } finally {
    window._draftLoaded = true; // Enable saving draft for future changes
    if (typeof attachCpkgFormAutoSave === 'function') attachCpkgFormAutoSave();
    if (typeof renderCustomPkg === 'function') renderCustomPkg();
    if (typeof renderCat === 'function') renderCat();
  }
}
window.saveCustomPkgStateToStorage = saveCustomPkgStateToStorage;
window.loadCustomPkgStateFromStorage = loadCustomPkgStateFromStorage;

// Auto-save form inputs & changes to local draft
function attachCpkgFormAutoSave() {
  const form = document.getElementById('cpkg-form');
  if (!form || form._autoSaveAttached) return;
  form._autoSaveAttached = true;
  form.addEventListener('input', () => {
    saveCustomPkgStateToStorage();
  });
  form.addEventListener('change', () => {
    saveCustomPkgStateToStorage();
  });
}
window.attachCpkgFormAutoSave = attachCpkgFormAutoSave;

// ===== FLOATING CUSTOM PACKAGE PANEL =====
function openCustomPanel() {
  const workspace = document.getElementById('custom-workspace-overlay');
  if (workspace && workspace.classList.contains('open')) {
    if (typeof closeCustomPanel === 'function') closeCustomPanel();
    return;
  }
  if (workspace) workspace.classList.add('open');
  document.body.classList.add('cpkg-open');
  document.documentElement.classList.add('cpkg-open');
  document.body.style.overflow = 'hidden';
  document.documentElement.style.overflow = 'hidden';
  // Enforce event date min/max on open
  enforceDateLimits();
  if (typeof _refreshAutoAllocFabVisibility === 'function') _refreshAutoAllocFabVisibility();
  // Ensure catalog renders with current state
  if (typeof renderCat === 'function') renderCat();
  // Ensure custom package state, title, and totals are rendered
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  // Ensure form auto-save listeners are attached
  if (typeof attachCpkgFormAutoSave === 'function') attachCpkgFormAutoSave();
  if (typeof loadCustomerMeetingConfig === 'function') loadCustomerMeetingConfig();
  if (typeof renderMeetingTimes === 'function') renderMeetingTimes();
  if (typeof checkEventDateConflicts === 'function') checkEventDateConflicts();
  // Validate fields immediately so they glow
  if (typeof validateAllCpkgFields === 'function') validateAllCpkgFields();
}
window.openCustomPanel = openCustomPanel;

function _refreshAutoAllocFabVisibility() {
  const ws = document.getElementById('custom-workspace-overlay');
  const isOpen = ws && ws.classList.contains('open');
  const fab = document.getElementById('auto-alloc-fab');
  if (fab) {
    // Only show if custom panel is open AND there are auto-allocations (badge > 0)
    const badge = document.getElementById('auto-alloc-badge');
    const count = badge ? parseInt(badge.textContent) || 0 : 0;
    fab.style.display = (isOpen && count > 0) ? 'flex' : 'none';
  }
}
window._refreshAutoAllocFabVisibility = _refreshAutoAllocFabVisibility;

function closeCustomPanel() {
  const existingOvernight = document.getElementById('overnight-time-confirm-overlay');
  if (existingOvernight) existingOvernight.remove();
  const workspace = document.getElementById('custom-workspace-overlay');
  if (!workspace || !workspace.classList.contains('open')) return;
  // Save state on close so refresh always has latest snapshot
  saveCustomPkgStateToStorage();
  workspace.classList.add('closing');
  const fab = document.getElementById('auto-alloc-fab');
  if (fab) fab.style.display = 'none';
  setTimeout(() => {
    workspace.classList.remove('open');
    workspace.classList.remove('closing');
    document.body.classList.remove('cpkg-open');
    document.documentElement.classList.remove('cpkg-open');
    document.body.style.overflow = '';
    document.documentElement.style.overflow = '';
  }, 220);
}
window.closeCustomPanel = closeCustomPanel;

function enforceDateLimits() {
  const dateEl = document.getElementById('cpkg-date');
  if (dateEl) {
    const today = new Date();
    const minDate = new Date(today);
    minDate.setDate(today.getDate() + 14);
    const maxDate = new Date(today);
    maxDate.setFullYear(today.getFullYear() + 20);
    const fmt = d => d.toISOString().split('T')[0];
    dateEl.min = fmt(minDate);
    dateEl.max = fmt(maxDate);
  }
}
window.enforceDateLimits = enforceDateLimits;

// ===== MEETING DATE: enforce 7-day window on modal open =====
const _origOpenMeetingTimeModal = window.openMeetingTimeModal;
window.openMeetingTimeModal = function() {
  if (typeof _origOpenMeetingTimeModal === 'function') _origOpenMeetingTimeModal();
  const mtDateEl = document.getElementById('mt-date-input');
  if (mtDateEl) {
    const today = new Date();
    const minD = new Date(today); minD.setDate(today.getDate() + 1);
    const maxD = new Date(today); maxD.setDate(today.getDate() + 7);
    const fmt = d => d.toISOString().split('T')[0];
    mtDateEl.min = fmt(minD);
    mtDateEl.max = fmt(maxD);
  }
  if (typeof validateMeetingTimeModal === 'function') validateMeetingTimeModal();
};

// ===== FIELD VALIDATION ENGINE =====
function validateCpkgField(fieldId) {
  const el = document.getElementById(fieldId);
  if (!el) return true;

  const val = el.value ? el.value.trim() : '';
  const rule = el.getAttribute('data-rule') || 'This field is required.';
  const required = el.getAttribute('data-required') === 'true';
  let isValid = true;
  let errorMsg = '';

  if (required && !val && !el.disabled) {
    isValid = false;
    errorMsg = rule;
  } else {
    // Field-specific extra rules
    if (fieldId === 'cpkg-pax') {
      const n = parseInt(val);
      if (isNaN(n) || n < 10) { isValid = false; errorMsg = 'Guest count must be at least 10.'; }
      else if (n > 200) { isValid = false; errorMsg = 'Guest count cannot exceed 200.'; }
    }
    if (fieldId === 'cpkg-date' && val) {
      const today = new Date(); today.setHours(0,0,0,0);
      const chosen = new Date(val + 'T00:00:00');
      const minD = new Date(today); minD.setDate(today.getDate() + 14);
      const maxD = new Date(today); maxD.setFullYear(today.getFullYear() + 50);
      if (chosen < minD) { isValid = false; errorMsg = 'Your event date is too soon. The business requires a minimum of 14 days notice for event preparation. Please select a date at least 14 days from today.'; }
      else if (chosen > maxD) { isValid = false; errorMsg = 'The event date you selected is too far into the future. The business does not accept bookings more than 50 years in advance.'; }
    }
        if (fieldId === 'cpkg-vip-count') {
      const n = parseInt(val);
      const paxEl = document.getElementById('cpkg-pax');
      const pax = paxEl ? parseInt(paxEl.value) || 0 : 0;
      if (isNaN(n) || n < 1) { isValid = false; errorMsg = 'VIP count must be at least 1.'; }
      else if (n > pax) { isValid = false; errorMsg = 'VIP count cannot exceed total guest count (Pax).'; }
    }
    if (fieldId === 'cpkg-timeframe-end' && val) {
      const startEl = document.getElementById('cpkg-timeframe-start');
      const startVal = startEl ? startEl.value : '';
      if (startVal) {
        const toMin = t => { const [h,m] = t.split(':').map(Number); return h*60+m; };
        const sm = toMin(startVal);
        const em = toMin(val);
        if (em <= sm) {
          const overnightDur = (em + 1440) - sm;
          if (overnightDur < 60) {
            isValid = false;
            errorMsg = 'Event duration must be at least 1 hour.';
          } else if ((window._cpkgOvernightConfirmedFor || localStorage.getItem('halden_overnight_confirmed')) === (startVal + '-' + val)) {
            window._cpkgOvernightConfirmedFor = startVal + '-' + val;
            isValid = true;
            errorMsg = '';
          } else {
            isValid = false;
            errorMsg = 'Overnight time range needs confirmation.';
            const wsOverlay = document.getElementById('custom-workspace-overlay');
            if (!wsOverlay || wsOverlay.classList.contains('open')) {
              showOvernightTimeConfirmModal({
                startStr: startVal,
                endStr: val,
                onYes: () => {
                  window._cpkgOvernightConfirmedFor = startVal + '-' + val;
                  try { localStorage.setItem('halden_overnight_confirmed', startVal + '-' + val); } catch (e) {}
                  validateCpkgField('cpkg-timeframe-end');
                  if (typeof renderCustomPkg === 'function') renderCustomPkg();
                },
                onNo: () => {
                  window._cpkgOvernightConfirmedFor = null;
                  try { localStorage.removeItem('halden_overnight_confirmed'); } catch (e) {}
                  const endInput = document.getElementById('cpkg-timeframe-end');
                  if (endInput) { endInput.value = ''; endInput.focus(); }
                  validateCpkgField('cpkg-timeframe-end');
                }
              });
            }
          }
        } else {
          if (em - sm < 60) {
            isValid = false;
            errorMsg = 'Event duration must be at least 1 hour.';
          } else {
            window._cpkgOvernightConfirmedFor = null;
          }
        }
      }
    }
  }

  // Apply or remove error class
  if (!isValid) {
    el.classList.remove('field-valid');
    el.classList.add('field-error');
    // Create/update tooltip sibling
    let tooltip = el.parentElement ? el.parentElement.querySelector('.cpkg-field-tooltip') : null;
    if (!tooltip) {
      tooltip = document.createElement('span');
      tooltip.className = 'cpkg-field-tooltip';
      if (el.parentElement) {
        el.parentElement.style.position = 'relative';
        el.parentElement.appendChild(tooltip);
      }
    }
    tooltip.textContent = errorMsg;
    // Show tooltip on hover via CSS, but also show briefly on validate
    el.title = errorMsg;
  } else {
    el.classList.remove('field-error');
    if (val || fieldId === 'cpkg-event-setup') el.classList.add('field-valid'); // green glow
    el.title = '';
    const tooltip = el.parentElement ? el.parentElement.querySelector('.cpkg-field-tooltip') : null;
    if (tooltip) tooltip.remove();
  }

  return isValid;
}
window.validateCpkgField = validateCpkgField;

function validateAllCpkgFields() {
  let allValid = true;
  
  const btn = document.getElementById('cpkg-add-meeting-btn');
  if (btn) {
    if (typeof preferredMeetingTimes !== 'undefined' && preferredMeetingTimes.length > 0) {
      btn.classList.remove('field-error');
      btn.classList.add('field-valid');
    } else {
      btn.classList.add('field-error');
      btn.classList.remove('field-valid');
      allValid = false;
    }
  }

  const fields = [
    'cpkg-desc', 'cpkg-occasion', 'cpkg-theme', 'cpkg-event-setup',
    'cpkg-pax', 'cpkg-calltime', 'cpkg-date',
    'cpkg-timeframe-start', 'cpkg-timeframe-end',
    'cpkg-venue-location', 'cpkg-venue'
  ];
  const vipCheck = document.getElementById('cpkg-vip-check')?.checked;
  if (vipCheck) {
    fields.push('cpkg-vip-count');
  } else {
    const vEl = document.getElementById('cpkg-vip-count');
    if (vEl) {
      vEl.classList.remove('field-error');
      vEl.classList.remove('field-valid');
    }
  }
  fields.forEach(id => {
    if (!validateCpkgField(id)) allValid = false;
  });
  return allValid;
}
window.validateAllCpkgFields = validateAllCpkgFields;

// Run enforceDateLimits on page load
document.addEventListener('DOMContentLoaded', enforceDateLimits);

function toggleSelectedItemsView() {
  const panel = document.getElementById('cpkg-panel');
  const view = document.getElementById('cpkg-selected-items-view');
  if (!panel || !view) return;

  if (view.classList.contains('open')) {
    view.classList.remove('open');
    panel.classList.remove('view-items-open');
  } else {
    view.classList.add('open');
    panel.classList.add('view-items-open');
  }
}
window.toggleSelectedItemsView = toggleSelectedItemsView;

// ===== CART (finalized packages) =====
function selectCartPkg(idx) {
  if (selectedCartIdx === idx) {
    selectedCartIdx = null; // deselect if clicking again
  } else {
    selectedCartIdx = idx;
  }
  renderCart();
}
window.selectCartPkg = selectCartPkg;

function checkoutSelected() {
  if (selectedCartIdx === null) return;
  startCheckout('cartItem', selectedCartIdx);
}
window.checkoutSelected = checkoutSelected;

function renderCartCardHTML(pkg, options = {}) {
  if (!pkg) return '';
  const { isSelected = false, pi = null, showSelectionBadge = false, showActionButtons = true } = options;

  // Check if date or meeting slot is taken
  const pkgDateIso = _normalizeDateKey(pkg.date) || pkg.date;
  const isDateFull = (window._allReservationsCache || []).filter(r => {
    const rd = _normalizeDateKey(r.date);
    const st = String(r.status || '').toLowerCase();
    return rd === pkgDateIso && st !== 'cancelled' && st !== 'rejected';
  }).length >= 3;
  const isDateDisabled = window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(pkgDateIso);
  
  const chosenMt = (pkg.meetingTimes && pkg.meetingTimes[0]) || null;
  let isMtTaken = false;
  if (chosenMt && chosenMt.date) {
    const mtDateIso = _normalizeDateKey(chosenMt.date) || chosenMt.date;
    isMtTaken = (window._cachedBookedMeetings || []).some(m => {
      const md = _normalizeDateKey(m.date) || m.date;
      const st = String(m.status || '').toLowerCase();
      return md === mtDateIso && st !== 'cancelled' && (m.time === chosenMt.time || (chosenMt.time && chosenMt.time.includes(m.time)));
    });
  }

  let isMtOtherSelecting = false;
  if (chosenMt && chosenMt.date) {
    const mtDateIso = _normalizeDateKey(chosenMt.date) || chosenMt.date;
    const mtTimeStr = chosenMt.time || chosenMt.timeRange || (chosenMt.start + ' to ' + chosenMt.end);
    isMtOtherSelecting = (window._otherUsersMeetingSlots || []).some(s => s.date === mtDateIso && s.time === mtTimeStr);
  }

  const isDateOtherSelecting = (window._otherUsersEventDates || []).includes(pkgDateIso);
  const isConflict = isDateFull || isDateDisabled || isMtTaken;
  const isYellowDemand = !isConflict && (isDateOtherSelecting || isMtOtherSelecting);

  pkg._isConflict = isConflict;
  const conflictGlowClass = isConflict 
    ? 'cart-card-red-glow' 
    : (isYellowDemand ? 'cart-card-yellow-glow' : 'cart-card-green-glow');

  const selStyle = (isSelected && showActionButtons)
    ? 'border:1px solid #cba153; background:#fbf7ef; box-shadow:0 0 10px rgba(203,161,83,0.2);'
    : 'border:1px solid rgba(203,161,83,0.25); background:#fffdf9;';

  const pCount = parseInt(pkg.pax) || 0;
  const isMajorlySet = pkg.activePkgId && (pkg.pricingMode === 'majorly_set' || pkg.pricingMode === 'majorly set' || !pkg.pricingMode || pkg.pricingMode === 'tiered');
  const isPerHead = pkg.activePkgId && pkg.pricingMode === 'per_head';
  const isCustomBuild = !pkg.activePkgId;

  let typeBadge = '';
  if (pkg.pricingMode === 'tiered' && pkg.selectedTier) {
    typeBadge = `<span style="color:#cba153; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px;">Tiered Package &bull; ${pkg.selectedTier.label}</span>`;
  } else if (isMajorlySet) {
    typeBadge = `<span style="color:#cba153; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px;">Majorly Set Package</span>`;
  } else if (isPerHead) {
    typeBadge = `<span style="color:#cba153; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px;">Dynamically Set Package</span>`;
  } else {
    typeBadge = `<span style="color:#cba153; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px;">Custom Package Build</span>`;
  }

  let extraTimingHtml = '';
  const fmtCallTime = window.formatTimeAMPM ? window.formatTimeAMPM(pkg.callTime) : pkg.callTime;
  const fmtTimeFrame = window.formatTimeAMPM ? window.formatTimeAMPM(pkg.time) : pkg.time;
  if (fmtCallTime || fmtTimeFrame) {
    extraTimingHtml += `<div style="font-size:11px; color:#5c4f44; margin-top:8px; padding:6px 10px; background:#f7f2e8; border-radius:6px; display:flex; flex-wrap:wrap; gap:10px;">`;
    if (fmtCallTime) extraTimingHtml += `<div><strong>Call Time:</strong> ${fmtCallTime}</div>`;
    if (fmtTimeFrame) extraTimingHtml += `<div><strong>Time Frame:</strong> ${fmtTimeFrame}</div>`;
    extraTimingHtml += `</div>`;
  }

  let extraMeetingsHtml = '';
  if (pkg.meetingTimes && pkg.meetingTimes.length > 0) {
    extraMeetingsHtml += `<div style="font-size:11px; color:#5c4f44; margin-top:6px; padding:6px 10px; background:#fbf7ef; border:1px solid rgba(203,161,83,0.25); border-radius:6px;">`;
    extraMeetingsHtml += `<div style="font-size:10px; font-weight:800; color:#cba153; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:4px;">Proposed Meeting Times:</div>`;
    pkg.meetingTimes.forEach(mt => {
      const formattedRange = window.formatTimeAMPM ? window.formatTimeAMPM(`${mt.start} - ${mt.end}`) : `${mt.start} - ${mt.end}`;
      extraMeetingsHtml += `<div style="margin-bottom:2px;">&bull; ${mt.date} (${formattedRange})</div>`;
    });
    extraMeetingsHtml += `</div>`;
  }

  let extraSetupHtml = '';
  const setupName = pkg.eventSetup || (pkg.eventSetupSlug ? (window.EVENT_SETUPS || []).find(s => s.slug === pkg.eventSetupSlug)?.name || pkg.eventSetupSlug.replace(/_/g, ' ') : '');
  if (setupName) {
    extraSetupHtml = `<div style="font-size:11px; color:#5c4f44; margin-top:6px; padding:6px 10px; background:#f7f2e8; border:1px solid rgba(203,161,83,0.3); border-radius:6px; display:flex; align-items:center; gap:6px;">
      <strong>Event Setup:</strong> <span style="color:#cba153; font-weight:700;">${setupName}</span>
    </div>`;
  }

  let cartDetailsRowsHtml = `<div style="margin-top:8px; display:flex; flex-direction:column; gap:4px; font-size:12px; color:#5c4f44; background:#fbf7ef; border:1px solid rgba(203,161,83,0.25); border-radius:8px; padding:8px 10px; width:100%; box-sizing:border-box;">`;
  cartDetailsRowsHtml += `<div style="display:flex; justify-content:space-between; width:100%;"><span><strong>Theme:</strong> ${pkg.theme || 'N/A'}</span><span><strong>Occasion:</strong> ${pkg.occasion || 'N/A'}</span></div>`;
  cartDetailsRowsHtml += `<div><strong>Guest Count (Pax):</strong> ${pkg.pax || 0} pax</div>`;
  cartDetailsRowsHtml += `<div><strong>Venue Address:</strong> ${pkg.venue || pkg.venueLocation || 'N/A'}</div>`;
  if (pkg.isVIP || pkg.vipCount > 0) {
    cartDetailsRowsHtml += `<div><strong>VIP Guests:</strong> ${pkg.vipCount || 0} pax (${pkg.vipService || 'properly catered'})</div>`;
  }
  if (pkg.desc || pkg.description) {
    cartDetailsRowsHtml += `<div style="word-break:break-word; overflow-wrap:anywhere; max-width:100%; line-height:1.5;"><strong>Event Description:</strong> <span style="white-space:pre-wrap;">${esc(pkg.desc || pkg.description)}</span></div>`;
  }
  cartDetailsRowsHtml += `</div>`;

  const itemsList = pkg.items || [];
  const itemsHtml = itemsList.map(item => {
    let priceSuffix = '';
    if (isCustomBuild && typeof item === 'object') {
      let itemScaledPrice = typeof item.snapshotPrice === 'number' ? item.snapshotPrice : 0;
      if (!itemScaledPrice && typeof getDynamicPrice === 'function') {
        itemScaledPrice = getDynamicPrice(item, pCount);
      }
      if (itemScaledPrice) {
        priceSuffix = `<span style="font-weight:700; color:#cba153; text-align:right; white-space:nowrap; margin-left:auto;">₱${itemScaledPrice.toLocaleString()}</span>`;
      }
    }
    const itemName = typeof item === 'string' ? item : (item.name || item);
    const customPaxBadge = (typeof item === 'object' && item.customPax) ? `<span style="font-size:11px; color:#cba153; font-weight:700; margin-left:6px;">(${item.customPax} pax portion)</span>` : '';
    const customQtyBadge = (typeof item === 'object' && item.customQty) ? `<span style="font-size:11px; color:#cba153; font-weight:700; margin-left:6px;">(${item.customQty} pcs count)</span>` : '';
    const specsNote = (typeof item === 'object' && item.specifications) ? `<div style="font-size:10.5px; color:#8c7653; padding-left:14px; font-style:italic;">Note: ${esc(item.specifications)}</div>` : '';
    return `<div style="margin-bottom:4px;"><div style="display:flex; justify-content:space-between; align-items:center; width:100%; gap:12px;"><span style="flex:1; text-align:left;">&bull; ${itemName} ${customPaxBadge}${customQtyBadge}</span>${priceSuffix}</div>${specsNote}</div>`;
  }).join('');

  let pricingBreakdownHtml = '<div style="margin-top:12px; padding-top:10px; border-top:1px dashed rgba(203,161,83,0.3); font-size:12px; color:#5c4f44; width:100%; box-sizing:border-box;">';

  // 1. Calculate or extract Base Package Price
  let basePrice = 0;
  let paxLabel = pCount;
  if (pkg.selectedTier && pkg.selectedTier.price) {
    paxLabel = pkg.selectedTier.pax || pCount;
    basePrice = pkg.selectedTier.price;
  } else if (pkg.fixedPrice) {
    paxLabel = pkg.fixedPax || pCount;
    basePrice = pkg.fixedPrice;
  } else if (isPerHead) {
    const pHead = pkg.pricePerHead || 500;
    basePrice = pCount * pHead;
  } else {
    basePrice = pkg.baseTotal || 0;
  }

  // 2. Identify and calculate Additional Charges from added items
  let additionalCharges = pkg.additionalCharges || 0;
  let extraItems = Array.isArray(pkg.additionalChargesItems) ? [...pkg.additionalChargesItems] : [];

  if (pkg.activePkgId) {
    const origPkg = (window.PKGS || (typeof PKGS !== 'undefined' ? PKGS : [])).find(p => p.id === pkg.activePkgId);
    if (origPkg && Array.isArray(origPkg.itemIds)) {
      const origIds = new Set(origPkg.itemIds);
      const computedExtras = [];
      let computedExtraTotal = 0;
      (pkg.items || []).forEach(item => {
        const iid = typeof item === 'object' ? item.id : item;
        if (!origIds.has(iid) && !item.isFree && !item.isAutoAdded && !item.isFreebie) {
          const itemPrice = typeof item.snapshotPrice === 'number' && item.snapshotPrice > 0
            ? item.snapshotPrice
            : (typeof getDynamicPrice === 'function' ? getDynamicPrice(item, pCount) : 0);
          computedExtraTotal += itemPrice;
          computedExtras.push({
            name: typeof item === 'object' ? (item.name || item.id) : String(item),
            price: itemPrice
          });
        }
      });
      if (computedExtraTotal > 0 || computedExtras.length > 0) {
        additionalCharges = computedExtraTotal;
        extraItems = computedExtras;
      }
    }
  }

  // 3. Render Base Pricing Rule
  if (isMajorlySet) {
    pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; font-weight:700; color:#3d2b1a;">
      <span>Pricing Rule (${paxLabel} pax):</span>
      <span style="text-align:right; white-space:nowrap; margin-left:auto;">₱${basePrice.toLocaleString()}</span>
    </div>`;
  } else if (isPerHead) {
    const pHead = pkg.pricePerHead || 500;
    pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; font-weight:700; color:#3d2b1a;">
      <span>Pricing Rule (${pCount} pax @ ₱${pHead.toLocaleString()}/head):</span>
      <span style="text-align:right; white-space:nowrap; margin-left:auto;">₱${basePrice.toLocaleString()}</span>
    </div>`;
  } else {
    pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; font-weight:700; color:#3d2b1a;">
      <span>Items Subtotal:</span>
      <span style="text-align:right; white-space:nowrap; margin-left:auto;">₱${basePrice.toLocaleString()}</span>
    </div>`;
  }

  // 4. Render Additional Charges if any items were added
  if (additionalCharges > 0) {
    pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; color:#cba153; font-weight:700; margin-top:4px;">
      <span>Additional Charges (${extraItems.length} added ${extraItems.length === 1 ? 'item' : 'items'}):</span>
      <span style="text-align:right; white-space:nowrap; margin-left:auto;">+₱${additionalCharges.toLocaleString()}</span>
    </div>`;
    extraItems.forEach(ei => {
      pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; width:100%; font-size:11px; color:#786553; padding-left:8px; margin-top:1px;">
        <span>&bull; ${ei.name}</span>
        <span style="text-align:right; white-space:nowrap; margin-left:auto;">+₱${ei.price.toLocaleString()}</span>
      </div>`;
    });
  }

  // 5. Render Out of Town Charge
  const outOfTownCharge = pkg.outOfTownCharge || 0;
  if (outOfTownCharge > 0) {
    pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; color:#a84300; font-weight:600; margin-top:4px;">
      <span>Out of Town Charge (+5%):</span>
      <span style="text-align:right; white-space:nowrap; margin-left:auto;">+₱${outOfTownCharge.toLocaleString()}</span>
    </div>`;
  }

  // 6. Calculate & Self-Heal Total Amount
  const calculatedTotal = basePrice + additionalCharges + outOfTownCharge;
  const finalTotalAmt = (pkg.total && pkg.total > 0 && pkg.total >= basePrice) ? pkg.total : calculatedTotal;
  const pkgTotal = finalTotalAmt;

  // Self-heal cart item in memory if it was saved with total: 0
  if (!pkg.total || pkg.total === 0 || pkg.total < basePrice) {
    pkg.total = finalTotalAmt;
    pkg.price = finalTotalAmt;
    pkg.baseTotal = basePrice;
    pkg.additionalCharges = additionalCharges;
    pkg.additionalChargesItems = extraItems;
    if (typeof saveCartToSupabase === 'function') {
      setTimeout(() => saveCartToSupabase(), 0);
    }
  }

  const chkAmtAttr = (!showActionButtons) ? 'id="chk-final-amt"' : '';
  pricingBreakdownHtml += `<div style="display:flex; justify-content:space-between; align-items:center; width:100%; font-size:14px; font-weight:800; color:#cba153; margin-top:6px; padding-top:6px; border-top:1px dashed rgba(203,161,83,0.3);">
    <span>Total Amount:</span>
    <span ${chkAmtAttr} style="text-align:right; white-space:nowrap; margin-left:auto; font-size:16px;">₱${finalTotalAmt.toLocaleString()}</span>
  </div></div>`;

  const onClickAttr = (pi !== null && showActionButtons) ? `onclick="selectCartPkg(${pi})"` : '';
  const cursorStyle = (pi !== null && showActionButtons) ? 'cursor:pointer;' : '';

  let actionBtnsHtml = '';
  if (showActionButtons && pi !== null) {
    actionBtnsHtml = `<div style="display:flex; gap:10px; width:100%; margin-top:15px;">
      <button class="btn-modify-cpkg" onclick="event.stopPropagation();modifyCartPkg(${pi})" style="flex:1; background:#c49a3c; color:#ffffff; border:none; padding:8px; border-radius:8px; font-size:12px; font-weight:700; cursor:pointer; transition:0.2s;">Modify</button>
      <button class="btn-remove-cpkg" onclick="event.stopPropagation();removeCartPkg(${pi})" style="flex:1; background:#dc2626; color:#ffffff; border:none; padding:8px; border-radius:8px; font-size:12px; font-weight:700; cursor:pointer; transition:0.2s;">Remove</button>
    </div>`;
  }

  const conflictBadgeHtml = isConflict
    ? `<div style="margin-bottom:10px; padding:6px 10px; border-radius:6px; background:rgba(239,68,68,0.1); border:1px solid #ef4444; color:#ef4444; font-size:11px; font-weight:700;">
        Unavailable: ${isDateFull ? 'Event date is fully booked.' : isDateDisabled ? 'Event date was disabled by admin.' : 'Meeting slot was taken by another customer.'} Click Modify to pick an available slot.
       </div>`
    : (isYellowDemand
        ? `<div style="margin-bottom:10px; padding:5px 8px; border-radius:6px; background:rgba(234,179,8,0.1); border:1px solid #eab308; color:#b45309; font-size:11px; font-weight:700;">
            High Demand: Event date or meeting slot is also in another customer's cart. Checkout soon to secure it!
           </div>`
        : `<div style="margin-bottom:10px; padding:4px 8px; border-radius:6px; background:rgba(34,197,94,0.1); border:1px solid #22c55e; color:#22c55e; font-size:10.5px; font-weight:700;">
            Date &amp; Meeting Slot Available
           </div>`);

  return `<div class="c-item chk-new-summary ${conflictGlowClass}" ${onClickAttr} style="display:flex; flex-direction:column; padding:20px; border-radius:12px; ${cursorStyle} transition:0.2s; margin-bottom:10px; width:100%; box-sizing:border-box; ${selStyle}">
    ${(showSelectionBadge && isSelected) ? '<div style="font-size:10px; font-weight:800; color:#cba153; text-align:right; width:100%; padding-bottom:10px; text-transform:uppercase; letter-spacing:1px;">Selected for Checkout</div>' : ''}
    ${conflictBadgeHtml}
    <div style="display:flex; justify-content:space-between; align-items:flex-start; width:100%; margin-bottom:8px; gap:12px;">
      <div style="flex:1;">
        ${typeBadge}
        <div style="font-family:'Times New Roman', serif; font-size:20px; font-weight:700; color:#3d2b1a; margin-top:4px;">${pkg.name}</div>
        ${(() => {
          const origPremade = pkg.premadePackageName || (pkg.activePkgId && typeof PKGS !== 'undefined' ? PKGS.find(p => p.id === pkg.activePkgId)?.name : null);
          if (origPremade) {
            return `<div style="font-size:12px; color:#8c7653; margin-top:2px;">Premade Package: <span style="font-weight:600; color:#3d2b1a;">${origPremade}</span></div>`;
          }
          return '';
        })()}
        ${cartDetailsRowsHtml}
      </div>
      <div style="font-family:'Times New Roman', serif; font-size:18px; font-weight:700; color:#cba153; text-align:right; white-space:nowrap; margin-left:auto;">₱${pkgTotal.toLocaleString()}</div>
    </div>
    ${extraTimingHtml}
    ${extraMeetingsHtml}
    ${extraSetupHtml}
    <div style="border-top:1px dashed rgba(203,161,83,0.3); margin:10px 0;"></div>
    <div style="font-size:13px; color:#5c4f44; line-height:1.6; margin-bottom:10px;">
      ${itemsHtml}
    </div>
    ${pricingBreakdownHtml}
    ${actionBtnsHtml}
  </div>`;
}
window.renderCartCardHTML = renderCartCardHTML;

function renderCart() {
  const badge = document.getElementById('c-badge');
  if (badge) badge.textContent = cart.length;
  const el = document.getElementById('cart-items');
  const tot = document.getElementById('cart-tot');
  const checkoutBtn = document.getElementById('btn-cart-checkout');
  if (!el) return;

  // Clamp selectedCartIdx if cart shrank
  if (selectedCartIdx !== null && selectedCartIdx >= cart.length) {
    selectedCartIdx = null;
  }

  if (!cart.length) {
    el.innerHTML = `<div class="cart-empty"><div></div><p>No finalized packages yet.<br>Build and finalize a package from the catalog.</p></div>`;
    if (tot) tot.textContent = ':';
    if (checkoutBtn) { checkoutBtn.disabled = true; checkoutBtn.textContent = ' Select a Package to Checkout'; checkoutBtn.style.opacity = '0.45'; checkoutBtn.style.cursor = 'not-allowed'; }
    return;
  }

  // Update footer button state
  if (checkoutBtn) {
    if (selectedCartIdx !== null) {
      checkoutBtn.disabled = false;
      checkoutBtn.textContent = '✓ Checkout Selected Package';
      checkoutBtn.style.opacity = '1';
      checkoutBtn.style.cursor = 'pointer';
      const selPkg = cart[selectedCartIdx];
      if (tot) tot.textContent = selPkg ? '₱' + selPkg.price.toLocaleString() : ':';
    } else {
      checkoutBtn.disabled = true;
      checkoutBtn.textContent = ' Select a Package to Checkout';
      checkoutBtn.style.opacity = '0.45';
      checkoutBtn.style.cursor = 'not-allowed';
      if (tot) tot.textContent = ':';
    }
  }

  el.innerHTML = cart.map((pkg, pi) => {
    const isSelected = selectedCartIdx === pi;
    return renderCartCardHTML(pkg, {
      isSelected: isSelected,
      pi: pi,
      showSelectionBadge: true,
      showActionButtons: true
    });
  }).join('');
}
window.renderCart = renderCart;

function removeCartPkg(idx) {
  if (selectedCartIdx === idx) selectedCartIdx = null;
  else if (selectedCartIdx !== null && selectedCartIdx > idx) selectedCartIdx--;
  cart.splice(idx, 1);
  saveCartToSupabase();
  renderCart();
}
window.removeCartPkg = removeCartPkg;

// ===== CART PERSISTENCE (LocalStorage + Supabase + Realtime Sync) =====
function getCartUserId() {
  if (typeof currentUserId !== 'undefined' && currentUserId) return String(currentUserId);
  if (currentUser) {
    return String(currentUser.id || currentUser.uid || currentUser.email || '');
  }
  return null;
}

function getCartStorageKey() {
  const uid = getCartUserId();
  return uid ? ('halden_cart_' + uid) : 'halden_cart_guest';
}

function saveCartToStorage() {
  try {
    const key = getCartStorageKey();
    localStorage.setItem(key, JSON.stringify(cart));
  } catch (e) {
    console.warn('LocalStorage cart save error:', e);
  }
}

function loadCartFromStorage() {
  try {
    const key = getCartStorageKey();
    const raw = localStorage.getItem(key);
    if (raw) {
      const loaded = JSON.parse(raw);
      if (Array.isArray(loaded)) {
        cart = loaded.slice(0, 3);
        renderCart();
        return;
      }
    }
    // If no cart saved for this specific user, reset memory cart to empty
    cart = [];
    renderCart();
  } catch (e) {
    console.warn('LocalStorage cart load error:', e);
  }
}

async function saveCartToSupabase() {
  saveCartToStorage();
  const sb = window.supabaseClient || window.supabase;
  const uid = getCartUserId();
  if (!uid || !sb) return;
  try {
    const payload = { user_id: uid, cart_data: JSON.stringify(cart), updated_at: new Date().toISOString() };
    const { error } = await sb
      .from('customer_cart')
      .upsert(payload, { onConflict: 'user_id' });
    if (error) {
      // Self-heal on 409 conflict or missing unique constraint: fetch existing row and update
      const { data: existing } = await sb.from('customer_cart').select('id').eq('user_id', uid).maybeSingle();
      if (existing && existing.id) {
        await sb.from('customer_cart').update({ cart_data: payload.cart_data, updated_at: payload.updated_at }).eq('id', existing.id);
      } else {
        await sb.from('customer_cart').insert(payload);
      }
    }
  } catch (err) {
    console.warn('Could not save cart to Supabase:', err);
  }
}

async function loadCartFromSupabase() {
  loadCartFromStorage();
  const sb = window.supabaseClient || window.supabase;
  const uid = getCartUserId();
  if (!uid || !sb) return;
  try {
    const { data, error } = await sb
      .from('customer_cart')
      .select('cart_data')
      .eq('user_id', uid)
      .maybeSingle();
    if (error) {
      console.warn('Could not load cart from Supabase:', error.message);
      return;
    }
    if (data && data.cart_data) {
      const loaded = JSON.parse(data.cart_data || '[]');
      if (Array.isArray(loaded)) {
        cart = loaded.slice(0, 3);
        saveCartToStorage();
        renderCart();
      }
    } else {
      cart = [];
      saveCartToStorage();
      renderCart();
    }
  } catch (err) {
    console.warn('Could not load cart from Supabase:', err);
  }
}

let cartRealtimeChannel = null;
function subscribeToCartRealtime() {
  const sb = window.supabaseClient || window.supabase;
  const uid = getCartUserId();
  if (!uid || !sb) return;

  if (cartRealtimeChannel) {
    try { sb.removeChannel(cartRealtimeChannel); } catch (e) { }
  }

  cartRealtimeChannel = sb
    .channel(`cart_realtime_${uid}`)
    .on(
      'postgres_changes',
      { event: '*', schema: 'public', table: 'customer_cart', filter: `user_id=eq.${uid}` },
      (payload) => {
        console.log('[Cart Realtime] Remote cart updated:', payload);
        if (payload.new && payload.new.cart_data) {
          try {
            const loaded = JSON.parse(payload.new.cart_data || '[]');
            if (Array.isArray(loaded)) {
              cart = loaded.slice(0, 3);
              saveCartToStorage();
              renderCart();
            }
          } catch (e) { }
        }
      }
    )
    .subscribe();
}

window.saveCartToSupabase = saveCartToSupabase;
window.loadCartFromSupabase = loadCartFromSupabase;
window.subscribeToCartRealtime = subscribeToCartRealtime;

function modifyCartPkg(idx) {
  const pkg = cart[idx];
  if (!pkg) return;

  const safeAssign = window.smartAssign;

  if (pkg.activePkgId) {
    activePkg = PKGS.find(p => p.id === pkg.activePkgId);
  } else {
    activePkg = null;
  }
  window.activeTier = pkg.selectedTier || null;

  safeAssign('cpkg-desc', pkg.desc);
  safeAssign('cpkg-theme', pkg.theme);
  safeAssign('cpkg-pax', pkg.pax);
  safeAssign('cpkg-occasion', pkg.occasion);
  safeAssign('cpkg-venue-location', pkg.venueLocation);
  safeAssign('cpkg-venue', pkg.venue);
  safeAssign('cpkg-date', pkg.date);
  safeAssign('cpkg-timeframe', pkg.time);
  safeAssign('cpkg-calltime', formatTime24H(pkg.callTime));
  safeAssign('map-search-input', pkg.venue);

  editingPkgName = pkg.name;
  customPkgItems = [...pkg.items];

  const vipCheck = document.getElementById('cpkg-vip-check');
  if (vipCheck) {
    vipCheck.checked = pkg.isVIP || false;
    toggleVIPFields();
  }
  safeAssign('cpkg-vip-count', pkg.vipCount);
  safeAssign('cpkg-vip-service', pkg.vipService);

  preferredMeetingTimes = pkg.meetingTimes ? [...pkg.meetingTimes] : [];
  renderMeetingTimes();

  // Restore event setup dropdown & lock if premade
  const _esSel = document.getElementById('cpkg-event-setup');
  if (_esSel) {
    if (pkg.eventSetupSlug) _esSel.value = pkg.eventSetupSlug;
    if (pkg.activePkgId) {
      _esSel.disabled = true;
      _esSel.style.cursor = 'not-allowed';
      _esSel.style.opacity = '0.75';
      _esSel.title = 'Event setup is locked for pre-made packages.';
    } else {
      _esSel.disabled = false;
      _esSel.style.cursor = 'pointer';
      _esSel.style.opacity = '1';
      _esSel.removeAttribute('title');
    }
    if (typeof onEventSetupChange === 'function') onEventSetupChange();
  }

  cart.splice(idx, 1);
  renderCart();
  renderCustomPkg();
  renderCat();
  if (typeof updateDawContextBar === 'function') updateDawContextBar();

  document.getElementById('cart-drawer').classList.remove('open');
  const overlay = document.getElementById('cart-overlay');
  if (overlay) overlay.classList.remove('on');
  go('#builder');
  const targetEl = document.getElementById('cpkg-panel') || document.getElementById('catalog');
  if (targetEl) targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  if (typeof openCustomPanel === 'function') {
    const workspace = document.getElementById('custom-workspace-overlay');
    if (workspace && !workspace.classList.contains('open')) {
        openCustomPanel();
    }
  }
}
window.modifyCartPkg = modifyCartPkg;

function toggleCart() {
  const drawer = document.getElementById('cart-drawer');
  const overlay = document.getElementById('cart-overlay');
  if (!drawer) return;
  const isOpen = drawer.classList.contains('open');
  if (isOpen) {
    drawer.classList.remove('open');
    if (overlay) overlay.classList.remove('on');
  } else {
    drawer.classList.add('open');
    if (overlay) overlay.classList.add('on');
    if (typeof loadCartFromSupabase === 'function') loadCartFromSupabase();
  }
}
window.toggleCart = toggleCart;

// ===== DATA INSIGHTS PANEL =====
let insightChart = null;
let dataPanelTimeout = null;

function openDataPanel(type) {
  // Removed events we catered and popular event themes panels per request
  if (type === 'occasion' || type === 'theme') return;
  if (window.innerWidth <= 768) return;
  clearTimeout(dataPanelTimeout);
  const workspace = document.getElementById('custom-workspace-overlay');
  if (workspace) workspace.classList.add('show-data');
  updateInsightChart(type);
}

function closeDataPanelDelay() {
  dataPanelTimeout = setTimeout(() => {
    const workspace = document.getElementById('custom-workspace-overlay');
    if (workspace) workspace.classList.remove('show-data');
  }, 100);
}

function closeDataPanel() {
  clearTimeout(dataPanelTimeout);
  const workspace = document.getElementById('custom-workspace-overlay');
  if (workspace) workspace.classList.remove('show-data');
}

window.openDataPanel = openDataPanel;
window.closeDataPanelDelay = closeDataPanelDelay;
window.closeDataPanel = closeDataPanel;

function updateInsightChart(type) {
  const ctx = document.getElementById('insight-chart').getContext('2d');
  const titleEl = document.getElementById('data-title');
  const txtEl = document.getElementById('data-insight-text');

  if (insightChart) insightChart.destroy();

  let chartConfig = {};
  let text = '';
  let title = 'Past Trends & Insights';

  // Using Halden's premium gold/brown colors
  const primary = 'rgba(196, 154, 60, 0.8)';
  const secondary = 'rgba(103, 73, 44, 0.8)';
  const tertiary = 'rgba(146, 110, 60, 0.8)';

  if (type === 'theme') {
    title = 'Popular Event Themes';
    text = 'Rustic and Modern Minimalist continue to dominate, making up 60% of all events this year.';
    chartConfig = {
      type: 'pie',
      data: {
        labels: ['Rustic', 'Modern Minimalist', 'Filipiniana', 'Classic Elegance', 'Other'],
        datasets: [{ data: [35, 25, 20, 15, 5], backgroundColor: [secondary, primary, tertiary, '#8f7b66', '#d6c6b4'] }]
      },
      options: { responsive: true, maintainAspectRatio: false }
    };
  } else if (type === 'pax') {
    title = 'Average Guest Count';
    text = 'Most events hover between 50 to 100 guests. Pricing scales attractively within this range.';
    chartConfig = {
      type: 'line',
      data: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        datasets: [{
          label: 'Guests (Pax)',
          data: [80, 95, 60, 120, 150, 90],
          backgroundColor: primary,
          borderColor: secondary,
          tension: 0.3,
          fill: true
        }]
      },
      options: { responsive: true, maintainAspectRatio: false }
    };
  } else if (type === 'occasion') {
    title = 'Events We Catered';
    text = 'Weddings are our specialty, followed closely by Corporate Gatherings and milestone Birthdays.';
    chartConfig = {
      type: 'bar',
      data: {
        labels: ['Weddings', 'Birthdays', 'Corporate', 'Anniversaries', 'Other'],
        datasets: [{ label: 'Frequency', data: [42, 28, 15, 10, 5], backgroundColor: secondary, borderRadius: 4, indexAxis: 'y' }]
      },
      options: { responsive: true, maintainAspectRatio: false }
    };
  } else if (type === 'city') {
    title = 'Specific Venue Insights';
    const cityInput = document.getElementById('cpkg-venue-location').value.trim().toLowerCase();

    if (!cityInput) {
      text = 'Please input your chosen city within NCR (e.g. Quezon City, Makati, Malabon). We will display real-time data on the most frequently chosen venues in that area.';
      chartConfig = null;
    } else {
      const ncrVenues = {
        'quezon city': { labels: ['Elements at Centris', 'Fernwood Gardens', 'UP Diliman Halls', 'Veterans Center', 'Blue Gardens'], data: [40, 25, 15, 12, 8] },
        'makati': { labels: ['The Peninsula', 'Makati Shangri-La', 'Whitespace Manila', 'Greenbelt Venues', 'City Club'], data: [35, 30, 20, 10, 5] },
        'manila': { labels: ['Manila Hotel', 'Intramuros Gardens', 'Rizal Park', 'Palacio de Maynila', 'Casa Blanca'], data: [28, 26, 20, 15, 11] },
        'taguig': { labels: ['Blue Leaf Pavilion', 'Marquis Events', 'SMX Aura', 'Enderun Tent', 'Grand Canal Venues'], data: [45, 20, 15, 12, 8] },
        'pasig': { labels: ['Valle Verde Club', 'Glass Garden', 'Kapitolyo Halls', 'Astoria Plaza', 'The Tent'], data: [30, 25, 20, 15, 10] },
        'malabon': { labels: ['A.C. Santos Hall', 'Malabon Grand', 'City Square Events', 'Fishermen\'s Grill', 'Local Covered Court'], data: [50, 25, 15, 5, 5] },
        'caloocan': { labels: ['Grace Park Halls', 'Monument Circle Spaces', 'Luzvimin Resort', 'Caloocan Sports Complex', 'Notre Dame Hall'], data: [35, 25, 20, 10, 10] },
        'marikina': { labels: ['Marikina Convention Center', 'Kapitan Moy', 'Riverbanks Center', 'Loyola Grand Villas', 'Hacienda'], data: [40, 25, 15, 15, 5] }
      };

      const matchKey = Object.keys(ncrVenues).find(k => k === cityInput || cityInput.includes(k) || k.includes(cityInput));

      if (matchKey) {
        const d = ncrVenues[matchKey];
        const prettyCity = matchKey.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
        text = `Here are the top venues favored by clients specifically within ${prettyCity}:`;
        chartConfig = {
          type: 'bar',
          data: {
            labels: d.labels,
            datasets: [{ label: 'Booking Frequency', data: d.data, backgroundColor: [primary, secondary, tertiary, '#8f7b66', '#d6c6b4'], borderRadius: 4 }]
          },
          options: { responsive: true, maintainAspectRatio: false }
        };
      } else {
        text = 'The catering service does not have enough statistical data for this specific city yet, or it is outside NCR. Please try another common NCR city.';
        chartConfig = null;
      }
    }
  } else {
    title = 'General Insights';
    text = 'Our curated catalog is designed based on industry statistics to assure the finest execution for any event element you choose.';
    chartConfig = {
      type: 'doughnut',
      data: {
        labels: ['Food', 'Decor', 'Equipment', 'Entertainment'],
        datasets: [{ data: [50, 20, 15, 15], backgroundColor: [secondary, primary, tertiary, '#d6c6b4'] }]
      },
      options: { responsive: true, maintainAspectRatio: false }
    };
  }

  titleEl.textContent = title;
  txtEl.textContent = text;

  const chartCanvas = document.getElementById('insight-chart');
  if (chartConfig) {
    chartCanvas.style.display = 'block';
    insightChart = new Chart(ctx, chartConfig);
  } else {
    chartCanvas.style.display = 'none';
  }
}

