function toggleMobileNav() {
  const nav = document.getElementById('mobile-nav');
  const ham = document.getElementById('hamburger');
  if (!nav) return;
  const isOpen = nav.classList.toggle('open');
  if (ham) ham.classList.toggle('open', isOpen);
  if (isOpen) {
    document.body.classList.add('mob-nav-open');
    document.documentElement.classList.add('mob-nav-open');
    document.body.style.overflow = 'hidden';
    document.documentElement.style.overflow = 'hidden';
  } else {
    document.body.classList.remove('mob-nav-open');
    document.documentElement.classList.remove('mob-nav-open');
    document.body.style.overflow = '';
    document.documentElement.style.overflow = '';
  }
}
