window.uploadCustomerMtFile = async function (event, agenda) {
  const file = event.target.files[0];
  if (!file || !activeCustomerMeeting) return;
  const mtId = activeCustomerMeeting.id;

  const progEl = document.getElementById('c-' + agenda + '-upload-progress');
  if (progEl) progEl.innerHTML = '<i class="fas fa-circle-notch fa-spin"></i> Uploading...';

  const formData = new FormData();
  formData.append('upload_preset', 'test_default');
  formData.append('folder', 'catering');
  formData.append('file', file);

  try {
    const url = 'https://api.cloudinary.com/v1_1/dg8ytmck5/auto/upload';
    const res = await fetch(url, { method: 'POST', body: formData });
    if (!res.ok) throw new Error('Cloudinary upload failed');
    const data = await res.json();

    // Append to existing shared documents
    let docs = activeCustomerMeeting.sharedDocuments || [];
    docs.push({
      url: data.secure_url,
      name: file.name,
      type: file.type,
      agenda: agenda,
      delete_token: data.delete_token
    });

    // Update Supabase
    const { error } = await window.supabaseClient.from('meetings').update({ shared_documents: docs }).eq('id', mtId);
    if (error) throw error;

    // Update Firebase as fallback
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'meetings', mtId), { sharedDocuments: docs });

    // Update local meeting cache so renderCustomerUploadList works immediately
    activeCustomerMeeting.sharedDocuments = docs;

    // Re-render the upload list so the newly uploaded file appears right away
    if (window.renderCustomerUploadList) {
      window.renderCustomerUploadList('c-' + agenda + '-upload-list', agenda);
    }

    if (progEl) progEl.innerHTML = '<span style="color:#27ae60;">Upload successful!</span>';
    setTimeout(() => { if (progEl) progEl.innerHTML = ''; }, 3000);
  } catch (e) {
    if (progEl) progEl.innerHTML = '<span style="color:var(--red);">Upload failed: ' + e.message + '</span>';
  }

  event.target.value = ''; // reset input
};

window.renderCustomerUploadList = function (containerId, agenda) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const docs = (activeCustomerMeeting && activeCustomerMeeting.sharedDocuments) || [];
  const filtered = docs.filter(d => {
    if (agenda === 'design') {
      // Show design-tagged docs AND legacy untagged docs, but NOT explicitly 'res'-tagged
      return d.agenda === 'design' || (d.agenda !== 'res');
    }
    return (d.agenda || 'res') === agenda;
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div style="color:#aaa; font-size:12px; text-align:center;">No reference pictures uploaded.</div>';
    return;
  }

  container.innerHTML = filtered.map(d => {
    const isPDF = d.type === 'application/pdf' || (d.name && d.name.toLowerCase().endsWith('.pdf'));
    const isImg = d.type && d.type.startsWith('image/');
    let previewHtml = '';

    if (isImg || isPDF) {
      const displayUrl = isPDF ? d.url.replace('/upload/', '/upload/pg_1,f_jpg,w_400,c_limit/') : d.url;
      previewHtml = `<img src="${displayUrl}" style="width:50px; height:50px; object-fit:cover; border-radius:4px; border:1px solid #ddd;" />`;
    } else {
      previewHtml = `<div style="width:50px; height:50px; background:#f0f0f0; display:flex; align-items:center; justify-content:center; font-size:20px; border-radius:4px; color:#aaa;"><i class="fas fa-file"></i></div>`;
    }

    return `
      <div style="display:flex; align-items:center; gap:12px; padding:10px; background:#fff; border:1px solid #eee; border-radius:8px;">
        ${previewHtml}
        <div style="flex:1; overflow:hidden;">
          <div style="font-size:12px; font-weight:600; color:#333; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${d.name}</div>
          <a href="${d.url}" target="_blank" style="font-size:10px; color:#c49a3c; text-decoration:none;">View Full</a>
        </div>
      </div>
    `;
  }).join('');
};

window.uploadGcashProof = async function (event, meetingId) {
  const file = event.target.files[0];
  if (!file) return;

  const btn = event.target.nextElementSibling; // The upload button
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-circle-notch fa-spin"></i> Uploading...'; }

  const formData = new FormData();
  formData.append('file', file);
  formData.append('upload_preset', 'test_default');
  formData.append('folder', 'catering');

  try {
    const url = 'https://api.cloudinary.com/v1_1/dg8ytmck5/auto/upload';
    const res = await fetch(url, { method: 'POST', body: formData });
    if (!res.ok) throw new Error('Cloudinary upload failed');
    const data = await res.json();
    const proofUrl = data.secure_url;

    const effectiveMeetingId = meetingId || (activeCustomerMeeting && activeCustomerMeeting.id) || '';
    const roomCode = activeCustomerMeeting?.meetingRoomId || activeCustomerMeeting?.room_id || activeCustomerMeeting?.roomId;
    const resId = activeCustomerMeeting?.reservationId || activeCustomerMeeting?.reservation_id || (activeCustomerReservation && activeCustomerReservation.id);

    if (activeCustomerMeeting) {
      activeCustomerMeeting.initial_fee_status = 'gcash_proof_uploaded';
      activeCustomerMeeting.initial_fee_received_by = proofUrl;
      activeCustomerMeeting.initial_fee_proof = proofUrl;
      activeCustomerMeeting.initial_fee_proof_url = proofUrl;
    }
    if (activeCustomerReservation) {
      activeCustomerReservation.initial_fee_status = 'gcash_proof_uploaded';
      activeCustomerReservation.initial_fee_received_by = proofUrl;
      activeCustomerReservation.initial_fee_proof = proofUrl;
      activeCustomerReservation.initial_fee_proof_url = proofUrl;
    }

    const sb = window.supabaseClient;
    if (sb) {
      const gcashPayload = {
        initial_fee_status: 'gcash_proof_uploaded',
        initial_fee_received_by: proofUrl,
        initial_fee_proof: proofUrl,
        initial_fee_proof_url: proofUrl
      };
      if (effectiveMeetingId) {
        await sb.from('meetings').update(gcashPayload).eq('id', effectiveMeetingId);
      }
      if (roomCode) {
        await sb.from('meetings').update(gcashPayload).or(`meetingRoomId.eq.${roomCode},room_id.eq.${roomCode}`);
      }
      if (resId) {
        await sb.from('meetings').update(gcashPayload).eq('reservation_id', resId);
      }
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        if (effectiveMeetingId) {
          updateDoc(doc(window.firebaseDB, 'meetings', effectiveMeetingId), {
            initial_fee_status: 'gcash_proof_uploaded',
            initial_fee_received_by: proofUrl,
            initial_fee_proof: proofUrl,
            initial_fee_proof_url: proofUrl
          }).catch(()=>{});
        }
      } catch(e) {}
    }

    renderCustomerInitialFeeModal(activeCustomerMeeting);
  } catch (e) {
    alert('Upload failed: ' + e.message);
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-upload"></i> Upload Screenshot Proof'; }
  }
};

window.postponeInitialFee = async function (meetingId) {
  const modal = document.getElementById('c-mt-initial-fee-modal');
  if (modal) modal.remove();

  const btn = event?.target?.closest('button');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-circle-notch fa-spin"></i> Processing...'; }

  const effectiveMeetingId = meetingId || (activeCustomerMeeting && activeCustomerMeeting.id) || '';
  const roomCode = activeCustomerMeeting?.meetingRoomId || activeCustomerMeeting?.room_id || activeCustomerMeeting?.roomId;
  const resId = activeCustomerMeeting?.reservationId || activeCustomerMeeting?.reservation_id || (activeCustomerReservation && activeCustomerReservation.id);

  try {
    const deadline = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    const sb = window.supabaseClient;
    if (sb) {
      if (effectiveMeetingId) {
        await sb.from('meetings').update({
          initial_fee_status: 'declined_24h',
          initial_fee_deadline: deadline,
          initial_fee_pay_triggered: false
        }).eq('id', effectiveMeetingId);
      }
      if (roomCode) {
        await sb.from('meetings').update({
          initial_fee_status: 'declined_24h',
          initial_fee_deadline: deadline,
          initial_fee_pay_triggered: false
        }).or(`meetingRoomId.eq.${roomCode},room_id.eq.${roomCode}`);
      }
      if (resId) {
        await sb.from('meetings').update({
          initial_fee_status: 'declined_24h',
          initial_fee_deadline: deadline,
          initial_fee_pay_triggered: false
        }).eq('reservation_id', resId);

        await sb.from('reservations').update({
          initial_fee_status: 'declined_24h',
          initial_fee_deadline: deadline
        }).eq('id', resId);
      }
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        if (effectiveMeetingId) {
          updateDoc(doc(window.firebaseDB, 'meetings', effectiveMeetingId), {
            initial_fee_status: 'declined_24h',
            initial_fee_deadline: deadline,
            initial_fee_pay_triggered: false
          }).catch(()=>{});
        }
      } catch(e) {}
    }

    if (activeCustomerMeeting) {
      activeCustomerMeeting.initial_fee_status = 'declined_24h';
      activeCustomerMeeting.initial_fee_pay_triggered = false;
    }
    if (activeCustomerReservation) {
      activeCustomerReservation.initial_fee_status = 'declined_24h';
    }
    const finalModal = document.getElementById('c-mt-initial-fee-modal');
    if (finalModal) finalModal.remove();
  } catch (e) {
    console.error('[postponeInitialFee]', e);
    alert('Failed to postpone payment.');
    if (btn) { btn.disabled = false; btn.innerHTML = "I can't pay right now"; }
  }
};

window.selectCancellationFeeOnline = async function (meetingId) {
  const btn = event?.target?.closest('button');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-circle-notch fa-spin"></i> Processing...'; }

  const meeting = activeCustomerMeeting;
  const res = activeCustomerReservation;
  let resId = meeting?.reservationId || meeting?.reservation_id || res?.id;
  const effectiveMeetingId = meetingId || meeting?.id || '';
  if (!resId && effectiveMeetingId) {
    try {
      const sb = window.supabaseClient;
      if (sb) {
        const { data: mtRow } = await sb.from('meetings').select('reservation_id, reservationId').eq('id', effectiveMeetingId).maybeSingle();
        if (mtRow) resId = mtRow.reservation_id || mtRow.reservationId || '';
      }
    } catch (e) {}
  }
  const amt = parseFloat(meeting?.cancellation_fee_amount || meeting?.cancellationFeeAmount || 0) || (typeof computeCustomerCancellationBalances === 'function' ? (computeCustomerCancellationBalances(res)?.totalDue || 0) : 0);

  // Close modal if open
  const m = document.getElementById('c-mt-initial-fee-modal');
  if (m) m.remove();

  if (typeof openPaymentModal === 'function' && resId) {
    openPaymentModal(resId, amt, 'Cancellation Fee');
  } else {
    try {
      const isFromMeeting = !!effectiveMeetingId;
      const returnUrl = isFromMeeting
        ? `${window.location.origin}/customer.html?from=meeting&meetingId=${encodeURIComponent(effectiveMeetingId)}`
        : `${window.location.origin}/customer.html?from=payments&tab=payments`;
      const apiRes = await fetch('/api/paymongo', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          items: [{ name: 'Cancellation Fee Settlement', price: amt }],
          customerInfo: { name: currentUser?.displayName || 'Customer', email: currentUser?.email, type: 'Cancellation' },
          reservationId: resId,
          meetingId: effectiveMeetingId || undefined,
          paymentType: 'cancellation_fee',
          source: isFromMeeting ? 'meeting' : 'payments',
          tab: isFromMeeting ? undefined : 'payments',
          returnUrl: returnUrl
        })
      });
      const data = await apiRes.json();
      if (data.checkout_url || data.url) {
        window.location.href = data.checkout_url || data.url;
      } else {
        alert('Could not start online payment session: ' + (data.error || 'Unknown error'));
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-credit-card"></i> Pay Online'; }
      }
    } catch (e) {
      alert('Online payment error: ' + e.message);
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-credit-card"></i> Pay Online'; }
    }
  }
};

async function updateCustomerCancellationMeetingState(meetingId, partialState) {
  const sb = window.supabaseClient;
  const mt = activeCustomerMeeting || {};
  const effectiveId = meetingId || mt.id || mt.meetingRoomId || mt.room_id || '';

  let currentPayload = {};
  try {
    if (mt.liveDraft && mt.liveDraft.cancellation_pay) {
      currentPayload = { ...mt.liveDraft.cancellation_pay };
    } else if (mt.cancellationNote && typeof mt.cancellationNote === 'string' && mt.cancellationNote.trim().startsWith('{')) {
      currentPayload = JSON.parse(mt.cancellationNote);
    }
  } catch (e) {}

  const updatedPayload = {
    ...currentPayload,
    cancellation_fee_status: mt.cancellation_fee_status,
    cancellation_fee_choice: mt.cancellation_fee_choice,
    cancellation_fee_amount: mt.cancellation_fee_amount,
    cancellation_dp_amount: mt.cancellation_dp_amount,
    cancellation_final_amount: mt.cancellation_final_amount,
    cancellation_pay_triggered: mt.cancellation_pay_triggered,
    cancellation_fee_proof: mt.cancellation_fee_proof,
    ...partialState
  };

  if (partialState.cancellation_fee_status === 'triggered') {
    updatedPayload.cancellation_pay_triggered = true;
  }

  // 1. Immediately update in-memory state and re-render modal & tabs (Instant zero-latency UI)
  Object.assign(mt, updatedPayload);
  mt.cancellationNote = JSON.stringify(updatedPayload);
  if (!mt.liveDraft) mt.liveDraft = {};
  mt.liveDraft.cancellation_pay = updatedPayload;

  renderCustomerInitialFeeModal(mt);
  const currentActive = document.querySelector('#c-mt-nav .btn-outline.active');
  const currentTabId = currentActive ? currentActive.id.replace('btn-c-mt-nav-', '') : '';
  if (currentTabId === 'cancellation') {
    toggleCustomerMtPanel('cancellation');
  }

  // 2. Persist to Supabase and Firebase in background
  if (sb && effectiveId) {
    const rawJson = JSON.stringify(updatedPayload);
    try {
      await sb.from('meetings').update({
        cancellationNote: rawJson,
        live_draft: { cancellation_pay: updatedPayload }
      }).or(`id.eq.${effectiveId},room_id.eq.${effectiveId}`);
    } catch (err) {
      console.warn('[updateCustomerCancellationMeetingState] Supabase error:', err);
    }
  }

  if (window.firebaseDB && window.firebaseFns && effectiveId) {
    try {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'meetings', effectiveId), {
        cancellationNote: JSON.stringify(updatedPayload),
        ...updatedPayload
      });
    } catch (e) {}
  }
}

