window.downloadICS = function(dateStr, timeStr, agendas) {
  try {
    const d = new Date(dateStr);
    let startStr = dateStr.replace(/-/g, '') + 'T090000';
    let endStr = dateStr.replace(/-/g, '') + 'T100000';
    if (timeStr) {
      const parts = timeStr.split('-');
      const st = window.formatTime24H ? window.formatTime24H(parts[0]) : parts[0].trim();
      if (st) {
        const sP = st.split(':');
        d.setHours(parseInt(sP[0], 10), parseInt(sP[1], 10), 0, 0);
        let iso = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString();
        startStr = iso.replace(/[-:]/g, '').split('.')[0];
        d.setHours(d.getHours() + 1);
        iso = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString();
        endStr = iso.replace(/[-:]/g, '').split('.')[0];
      }
    }
    let icsContent = "BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//SmartServe//Event Meetings//EN\nBEGIN:VEVENT\n";
    icsContent += "DTSTART:" + startStr + "\n";
    icsContent += "DTEND:" + endStr + "\n";
    icsContent += "SUMMARY:Meeting with SmartServe\n";
    icsContent += "DESCRIPTION:Agendas: " + (agendas || 'Discussion') + "\n";
    icsContent += "END:VEVENT\nEND:VCALENDAR";
    
    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = "smartserve_meeting.ics";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch(e) { console.error('Failed to generate ICS', e); }
};

