async function openCustomerExecLivePanel(resId, retryCount = 0) {
  const overlay = document.getElementById('cust-exec-live-overlay');
  if (overlay) {
    overlay.style.setProperty('display', 'flex', 'important');
    overlay.style.setProperty('position', 'fixed', 'important');
    overlay.style.setProperty('inset', '0px', 'important');
    overlay.style.setProperty('top', '0px', 'important');
    overlay.style.setProperty('left', '0px', 'important');
    overlay.style.setProperty('right', '0px', 'important');
    overlay.style.setProperty('bottom', '0px', 'important');
    // Body has CSS zoom (UI scale, 0.8 on mobile) which shrinks vw/dvh units,
    // so size strictly via inset:0 to cover the true viewport.
    overlay.style.setProperty('width', 'auto', 'important');
    overlay.style.setProperty('max-width', 'none', 'important');
    overlay.style.setProperty('height', 'auto', 'important');
    overlay.style.setProperty('min-height', '0px', 'important');
    overlay.style.setProperty('z-index', '9999999', 'important');
    overlay.style.setProperty('margin', '0px', 'important');
    overlay.style.setProperty('padding', '0px', 'important');
    document.body.style.overflow = 'hidden';
  }

  // Update URL hash & storage for refresh persistence
  activeCustExecResId = resId;
  window.activeCustExecResId = resId;
  window._lastCompletedCustResId = resId;
  try {
    sessionStorage.setItem('active_cust_exec_res_id', resId);
    localStorage.setItem('active_cust_exec_res_id', resId);
  } catch(e) {}
  if (window.location.hash !== '#execution-day?id=' + resId) {
    try {
      window.history.replaceState(null, '', '#execution-day?id=' + resId);
    } catch(e) {
      window.location.hash = 'execution-day?id=' + resId;
    }
  }

  // Safely hide the customer portal sidebar tabs so they never overlap or block the map
  const sidebar = document.querySelector('.cp-sidebar');
  if (sidebar) sidebar.style.setProperty('display', 'none', 'important');

  const approved = typeof _getCustApprovedReservations === 'function' ? _getCustApprovedReservations() : [];
  let res = approved.find(r => String(r.id) === String(resId)) || (window._profileResCache && window._profileResCache[resId]);
  if (!res && window.supabaseClient) {
    try {
      const { data } = await window.supabaseClient.from('reservations').select('*').eq('id', resId).maybeSingle();
      if (data) res = data;
    } catch(e) {}
  }
  if (!res) {
    // If not ready yet on page refresh, retry up to 3 times
    if (retryCount < 3) {
      setTimeout(() => openCustomerExecLivePanel(resId, retryCount + 1), 400);
      return;
    }
    if (overlay) {
      overlay.style.display = 'none';
      document.body.style.overflow = '';
    }
    if (sidebar) sidebar.style.display = '';
    return;
  }

  const isLive = isExecutionSessionLive(res);
  if (!isLive && res.status !== 'completed' && !res.exec_finalized_at) {
    if (overlay) {
      overlay.style.display = 'none';
      document.body.style.overflow = '';
    }
    if (sidebar) sidebar.style.display = '';
    alert('Execution Day live session has not started yet.\n\nThe live tracking session will become available once the admin begins execution day, or on the scheduled date of your event.');
    return;
  }

  // Fetch execution_plans from Supabase to load phases, flexibility, active phase & operational tasks
  if (window.supabaseClient) {
    try {
      const { data: planData } = await window.supabaseClient
        .from('execution_plans')
        .select('*')
        .eq('reservation_id', String(resId))
        .maybeSingle();
      if (planData) {
        const parsedPhases = Array.isArray(planData.phases)
          ? planData.phases
          : (typeof planData.phases === 'string' ? JSON.parse(planData.phases) : []);
        res.executionPlan = {
          flexibility: planData.flexibility || 'strict',
          phases: parsedPhases,
          admin_location: planData.admin_location,
          active_phase_idx: planData.active_phase_idx !== undefined ? planData.active_phase_idx : 0
        };
        res.execution_plan = res.executionPlan;
      }
    } catch(e) {
      console.warn('[openCustomerExecLivePanel] plan fetch error:', e);
    }

    // Fetch event_flow from additional_reservation_details for event program flow
    try {
      const { data: ardData } = await window.supabaseClient
        .from('additional_reservation_details')
        .select('event_flow')
        .eq('reservation_id', String(resId))
        .maybeSingle();
      if (ardData && Array.isArray(ardData.event_flow) && ardData.event_flow.length > 0) {
        if (ardData.event_flow[0] && ardData.event_flow[0].id === 'execution') {
          res.event_flow = ardData.event_flow[0].agenda || ardData.event_flow;
        } else {
          res.event_flow = ardData.event_flow;
        }
      }
    } catch(e) {
      console.warn('[openCustomerExecLivePanel] ard fetch error:', e);
    }
  }

  // Default viewing phase to currently active phase
  const curActiveIdx = (res.executionPlan && res.executionPlan.active_phase_idx !== undefined)
    ? res.executionPlan.active_phase_idx
    : 0;
  custExecViewingPhaseIdx = curActiveIdx;

  custExecActiveRes = res;

  const titleEl = document.getElementById('cust-exec-live-title');
  const subtitleEl = document.getElementById('cust-exec-live-subtitle');
  const pkgName = res.packageName || res.package || res.type || (res.client + "'s Event");
  if (titleEl) titleEl.textContent = `${pkgName} — ${res.client || 'Client'}'s Event`;
  if (subtitleEl) subtitleEl.textContent = `View Mode · ${res.date || '—'} · ${res.venue || res.venueAddress || '—'}`;

  // Check if already completed
  if (res.status === 'completed' || res.exec_finalized_at) {
    showCustExecCongratsModal();
  }

  // Real-time listener for reservation completion, location sync, and new activity logs
  if (custExecRealtimeSub && window.supabaseClient) {
    try { window.supabaseClient.removeChannel(custExecRealtimeSub); } catch(e) {}
    custExecRealtimeSub = null;
  }
  if (window.supabaseClient) {
    try {
      custExecRealtimeSub = window.supabaseClient
        .channel('cust-exec-live-' + resId)
        .on('broadcast', { event: 'manager_location_sync' }, payload => {
          if (payload && payload.payload) {
            syncCustExecLiveState(resId, payload.payload);
          }
        })
        .on('broadcast', { event: 'manager_route_sync' }, payload => {
          if (payload && payload.payload) {
            syncCustExecLiveState(resId, payload.payload);
          }
        })
        .on('broadcast', { event: 'admin_location_sync' }, payload => {
          if (payload && payload.payload) {
            syncCustExecLiveState(resId, payload.payload);
          }
        })
        .on('broadcast', { event: 'admin_route_sync' }, payload => {
          if (payload && payload.payload) {
            syncCustExecLiveState(resId, payload.payload);
          }
        })
        .on('broadcast', { event: 'execution_finalized' }, () => {
          showCustExecCongratsModal();
        })
        .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'reservations', filter: `id=eq.${resId}` }, payload => {
          if (payload && payload.new) {
            if (payload.new.status === 'completed' || payload.new.exec_finalized_at) {
              showCustExecCongratsModal();
            }
            // Dynamically update location and route without page reload or re-entering
            syncCustExecLiveState(resId);
          }
        })
        .on('postgres_changes', { event: '*', schema: 'public', table: 'execution_plans', filter: `reservation_id=eq.${resId}` }, () => {
          syncCustExecLiveState(resId);
        })
        .on('postgres_changes', { event: '*', schema: 'public', table: 'execution_day_activity_logs', filter: `reservation_id=eq.${resId}` }, () => {
          const vPhase = CUST_EXEC_PHASES[custExecViewingPhaseIdx !== null ? custExecViewingPhaseIdx : 0];
          renderCustExecLiveLogs(resId, vPhase ? vPhase.id : null);
        })
        .subscribe();
    } catch(e) {}
  }

  // Also attach Firestore real-time listener if active
  if (window.custExecFirestoreUnsub) {
    try { window.custExecFirestoreUnsub(); } catch(e) {}
    window.custExecFirestoreUnsub = null;
  }
  if (window.firebaseDB && window.firebaseFns && typeof window.firebaseFns.onSnapshot === 'function' && typeof window.firebaseFns.doc === 'function') {
    try {
      window.custExecFirestoreUnsub = window.firebaseFns.onSnapshot(
        window.firebaseFns.doc(window.firebaseDB, 'reservations', String(resId)),
        () => {
          syncCustExecLiveState(resId);
        }
      );
    } catch(e) {}
  }

  // Initialize or refresh map
  try {
    initCustExecLiveMap(res);
  } catch(e) {
    console.warn('[openCustomerExecLivePanel] map init error:', e);
  }
  [50, 150, 300, 600].forEach(delay => {
    setTimeout(() => {
      if (custExecLiveMap) custExecLiveMap.invalidateSize();
    }, delay);
  });

  // Render clickable phases
  try { renderCustExecLivePhases(res); } catch(e) {}

  // Render selected phase details and tasks
  try { renderCustExecLiveActivePhaseCard(res); } catch(e) {}

  // Fetch and render logs for initial viewing phase
  try {
    const vPhase = CUST_EXEC_PHASES[custExecViewingPhaseIdx !== null ? custExecViewingPhaseIdx : 0];
    await renderCustExecLiveLogs(res.id, vPhase ? vPhase.id : null);
  } catch(e) {}

  // Start real-time sync polling (every 5 seconds for responsive dynamic updates)
  if (custExecSyncTimer) clearInterval(custExecSyncTimer);
  custExecSyncTimer = setInterval(() => syncCustExecLiveState(res.id), 5000);
}
window.openCustomerExecLivePanel = openCustomerExecLivePanel;

function closeCustomerExecLivePanel() {
  const overlay = document.getElementById('cust-exec-live-overlay');
  if (overlay) overlay.style.display = 'none';
  document.body.style.overflow = '';
  // Restore the customer portal sidebar tabs
  const sidebar = document.querySelector('.cp-sidebar');
  if (sidebar) sidebar.style.display = '';

  // Reset URL hash & clear sessionStorage for execution-day tab
  try { sessionStorage.removeItem('active_cust_exec_res_id'); } catch(e) {}
  try {
    window.history.replaceState(null, '', '#execution-day');
  } catch(e) {
    window.location.hash = 'execution-day';
  }

  if (custExecSyncTimer) {
    clearInterval(custExecSyncTimer);
    custExecSyncTimer = null;
  }
  if (custExecRealtimeSub && window.supabaseClient) {
    try { window.supabaseClient.removeChannel(custExecRealtimeSub); } catch(e) {}
    custExecRealtimeSub = null;
  }
  if (window.custExecFirestoreUnsub) {
    try { window.custExecFirestoreUnsub(); } catch(e) {}
    window.custExecFirestoreUnsub = null;
  }
}
window.closeCustomerExecLivePanel = closeCustomerExecLivePanel;

function selectCustExecPhase(idx) {
  if (idx < 0 || idx >= CUST_EXEC_PHASES.length) return;
  custExecViewingPhaseIdx = idx;
  if (custExecActiveRes) {
    renderCustExecLivePhases(custExecActiveRes);
    renderCustExecLiveActivePhaseCard(custExecActiveRes);
    renderCustExecLiveLogs(custExecActiveRes.id, CUST_EXEC_PHASES[idx].id);
  }
}
window.selectCustExecPhase = selectCustExecPhase;

/**
 * Fetches turn-by-turn driving road route from OSRM to display the actual road geometry
 * between admin team location and event venue, falling back to direct line if offline.
 */
async function updateCustExecDrivingRoute(startLatLng, endLatLng) {
  if (!custExecRouteLine || !startLatLng || !endLatLng) return;

  const startLat = Array.isArray(startLatLng) ? startLatLng[0] : (startLatLng.lat !== undefined ? startLatLng.lat : null);
  const startLng = Array.isArray(startLatLng) ? startLatLng[1] : (startLatLng.lng !== undefined ? startLatLng.lng : null);
  const endLat = Array.isArray(endLatLng) ? endLatLng[0] : (endLatLng.lat !== undefined ? endLatLng.lat : null);
  const endLng = Array.isArray(endLatLng) ? endLatLng[1] : (endLatLng.lng !== undefined ? endLatLng.lng : null);

  if (startLat == null || startLng == null || endLat == null || endLng == null) return;

  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${startLng},${startLat};${endLng},${endLat}?overview=full&geometries=geojson`;
    let response = null;
    try {
      response = await fetch(url);
    } catch(fetchErr) {
      response = await fetch(`http://router.project-osrm.org/route/v1/driving/${startLng},${startLat};${endLng},${endLat}?overview=full&geometries=geojson`);
    }

    if (response && response.ok) {
      const data = await response.json();
      if (data && data.routes && data.routes.length > 0 && data.routes[0].geometry && data.routes[0].geometry.coordinates) {
        // GeoJSON geometry is [longitude, latitude], Leaflet polyline expects [latitude, longitude]
        const roadPoints = data.routes[0].geometry.coordinates.map(pt => [pt[1], pt[0]]);
        if (custExecRouteLine) {
          custExecRouteLine.setLatLngs(roadPoints);
          custExecRouteLine.setStyle({ weight: 5, color: '#3b82f6', opacity: 0.85, dashArray: null });
        }
        return;
      }
    }
  } catch (err) {
    console.warn('[updateCustExecDrivingRoute] Road routing unavailable, falling back to direct line:', err);
  }

  // Graceful fallback: straight line
  if (custExecRouteLine) {
    custExecRouteLine.setLatLngs([
      [startLat, startLng],
      [endLat, endLng]
    ]);
    custExecRouteLine.setStyle({ weight: 4, color: '#5b9bd5', opacity: 0.85, dashArray: '8,8' });
  }
}
window.updateCustExecDrivingRoute = updateCustExecDrivingRoute;

const _custGeocodeCache = {};
async function geocodeCustVenueAddress(query) {
  if (!query || typeof query !== 'string') return null;
  const qClean = query.trim();
  if (!qClean) return null;
  if (_custGeocodeCache[qClean]) return _custGeocodeCache[qClean];
  try {
    const url = 'https://nominatim.openstreetmap.org/search?format=json&q=' + encodeURIComponent(qClean) + '&limit=1&countrycodes=ph';
    const r = await fetch(url);
    if (!r.ok) return null;
    const data = await r.json();
    if (!data || !data.length) return null;
    const resLL = [parseFloat(data[0].lat), parseFloat(data[0].lon)];
    _custGeocodeCache[qClean] = resLL;
    return resLL;
  } catch(e) {
    return null;
  }
}

function initCustExecLiveMap(res) {
  const mapContainer = document.getElementById('cust-exec-live-map');
  if (!mapContainer || typeof L === 'undefined') return;

  if (custExecLiveMap) {
    try { custExecLiveMap.remove(); } catch(e) {}
    custExecLiveMap = null;
  }
  if (mapContainer._leaflet_id) {
    mapContainer._leaflet_id = null;
  }

  // Base HQ coordinates: SmartServe Malabon HQ
  const hqCoords = [14.6575, 120.9575];

  // Venue coordinates - prioritize exact venue coordinates matching admin side
  let venueCoords = [14.6575, 120.9575];
  let hasExactVenue = false;
  if (res.venue_coords && Array.isArray(res.venue_coords) && res.venue_coords.length >= 2) {
    venueCoords = [parseFloat(res.venue_coords[0]), parseFloat(res.venue_coords[1])];
    hasExactVenue = true;
  } else if (res.executionPlan && res.executionPlan.venue_coords && Array.isArray(res.executionPlan.venue_coords) && res.executionPlan.venue_coords.length >= 2) {
    venueCoords = [parseFloat(res.executionPlan.venue_coords[0]), parseFloat(res.executionPlan.venue_coords[1])];
    hasExactVenue = true;
  } else if (res.execution_plan && res.execution_plan.venue_coords && Array.isArray(res.execution_plan.venue_coords) && res.execution_plan.venue_coords.length >= 2) {
    venueCoords = [parseFloat(res.execution_plan.venue_coords[0]), parseFloat(res.execution_plan.venue_coords[1])];
    hasExactVenue = true;
  } else if (res.venueLat && res.venueLng) {
    venueCoords = [parseFloat(res.venueLat), parseFloat(res.venueLng)];
    hasExactVenue = true;
  } else if (res.latitude && res.longitude) {
    venueCoords = [parseFloat(res.latitude), parseFloat(res.longitude)];
    hasExactVenue = true;
  }

  // Manager & Admin coordinates (Manager takes precedence for team location)
  let teamCoords = null;
  let isFromManager = false;
  const rawMgrLoc = res.manager_location || (res.executionPlan && res.executionPlan.manager_location) || (res.execution_plan && res.execution_plan.manager_location);
  const rawAdminLoc = res.admin_location || (res.executionPlan && res.executionPlan.admin_location) || (res.execution_plan && res.execution_plan.admin_location);

  if (rawMgrLoc) {
    if (Array.isArray(rawMgrLoc) && rawMgrLoc.length >= 2) teamCoords = rawMgrLoc;
    else if (rawMgrLoc.lat && rawMgrLoc.lng) teamCoords = [rawMgrLoc.lat, rawMgrLoc.lng];
    if (teamCoords) isFromManager = true;
  }
  if (!teamCoords && rawAdminLoc) {
    if (Array.isArray(rawAdminLoc) && rawAdminLoc.length >= 2) teamCoords = rawAdminLoc;
    else if (rawAdminLoc.lat && rawAdminLoc.lng) teamCoords = [rawAdminLoc.lat, rawAdminLoc.lng];
  }

  // Initialize map centered at team location if synced, otherwise centered at venue
  custExecLiveMap = L.map(mapContainer, {
    center: teamCoords || venueCoords,
    zoom: teamCoords ? 13 : 14,
    zoomControl: true
  });

  // Use ArcGIS World Street Map (avoids OpenStreetMap 403 Access Blocked)
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
    attribution: 'Tiles &copy; Esri &mdash; SmartServe Real-Time Live Tracking'
  }).addTo(custExecLiveMap);

  // Venue Marker
  const venueIcon = L.divIcon({
    html: '<div style="background:#b8860b;color:#000;font-size:10px;font-weight:800;padding:4px 8px;border-radius:6px;border:1px solid #d4af37;white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,0.3);">Venue</div>',
    className: '',
    iconSize: [60, 24],
    iconAnchor: [30, 12]
  });
  custExecVenueMarker = L.marker(venueCoords, { icon: venueIcon }).addTo(custExecLiveMap);

  // Reset markers & route
  custExecAdminMarker = null;
  custExecRouteLine = null;

  // Only plot team marker & route if manager or admin has actually synced location
  if (teamCoords) {
    const teamLabel = isFromManager ? 'Team Location (Manager)' : 'Team Location';
    const teamBg = isFromManager ? '#2563eb' : '#16a34a';
    const teamBorder = isFromManager ? '#1d4ed8' : '#15803d';
    const teamIcon = L.divIcon({
      html: `<div style="background:${teamBg};color:#fff;font-size:10px;font-weight:800;padding:4px 8px;border-radius:6px;border:1px solid ${teamBorder};white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,0.4);display:flex;align-items:center;gap:4px;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;display:inline-block;"></span> ${teamLabel}</div>`,
      className: '',
      iconSize: [isFromManager ? 140 : 110, 24],
      iconAnchor: [isFromManager ? 70 : 55, 12]
    });
    custExecAdminMarker = L.marker(teamCoords, { icon: teamIcon }).addTo(custExecLiveMap);

    const exactRoute = res.admin_route || (res.executionPlan && res.executionPlan.admin_route) || (res.execution_plan && res.execution_plan.admin_route);
    if (exactRoute && Array.isArray(exactRoute) && exactRoute.length > 1) {
      custExecRouteLine = L.polyline(exactRoute, {
        color: '#3b82f6',
        weight: 5,
        opacity: 0.85
      }).addTo(custExecLiveMap);
    } else {
      custExecRouteLine = L.polyline([teamCoords, venueCoords], {
        color: '#3b82f6',
        weight: 5,
        opacity: 0.85
      }).addTo(custExecLiveMap);
      updateCustExecDrivingRoute(teamCoords, venueCoords);
    }

    try {
      const bounds = L.latLngBounds([teamCoords, venueCoords]);
      custExecLiveMap.fitBounds(bounds, { padding: [40, 40] });
    } catch(e) {}
  } else {
    const statusTxt = document.getElementById('cust-exec-live-status-txt');
    if (statusTxt) statusTxt.textContent = 'Awaiting live location sync...';
  }

  // If venue was not previously resolved, geocode asynchronously and refresh marker
  const venueStr = res.venue || res.venueAddress || res.eventVenue;
  if (!hasExactVenue && venueStr) {
    geocodeCustVenueAddress(venueStr).then(coords => {
      if (coords && custExecLiveMap) {
        venueCoords = coords;
        res.venue_coords = coords;
        if (custExecVenueMarker) custExecVenueMarker.setLatLng(coords);
        if (custExecAdminMarker) {
          const curAdmin = custExecAdminMarker.getLatLng();
          const curExactRoute = res.admin_route || (res.executionPlan && res.executionPlan.admin_route) || (res.execution_plan && res.execution_plan.admin_route);
          if (curExactRoute && Array.isArray(curExactRoute) && curExactRoute.length > 1 && custExecRouteLine) {
            custExecRouteLine.setLatLngs(curExactRoute);
          } else if (curAdmin && custExecRouteLine) {
            updateCustExecDrivingRoute(curAdmin, coords);
          }
          try {
            custExecLiveMap.fitBounds(L.latLngBounds([curAdmin, coords]).pad(0.15));
          } catch(e) {}
        }
      }
    });
  }

  setTimeout(() => {
    if (custExecLiveMap) custExecLiveMap.invalidateSize();
  }, 300);
}

async function syncCustExecLiveState(resId, overridePayload = null) {
  if (document.hidden && !overridePayload) return;
  if (!window.supabaseClient || !resId) return;
  try {
    const [resResult, planResult] = await Promise.all([
      window.supabaseClient.from('reservations').select('*').eq('id', resId).maybeSingle(),
      window.supabaseClient.from('execution_plans').select('*').eq('reservation_id', resId).maybeSingle()
    ]);

    if (resResult.data) {
      const data = resResult.data;
      if (typeof data.execution_plan === 'string') {
        try { data.execution_plan = JSON.parse(data.execution_plan); } catch(e) {}
      }
      if (data.execution_plan && !data.executionPlan) {
        data.executionPlan = data.execution_plan;
      }

      if (planResult.data) {
        const parsedPhases = Array.isArray(planResult.data.phases)
          ? planResult.data.phases
          : (typeof planResult.data.phases === 'string' ? JSON.parse(planResult.data.phases) : []);
        data.executionPlan = data.executionPlan || {};
        data.executionPlan.flexibility = planResult.data.flexibility || data.executionPlan.flexibility || 'strict';
        data.executionPlan.phases = parsedPhases;
        if (planResult.data.admin_location) data.executionPlan.admin_location = planResult.data.admin_location;
        if (planResult.data.venue_coords) data.executionPlan.venue_coords = planResult.data.venue_coords;
        if (planResult.data.admin_route) data.executionPlan.admin_route = planResult.data.admin_route;
        data.executionPlan.active_phase_idx = planResult.data.active_phase_idx !== undefined ? planResult.data.active_phase_idx : (data.executionPlan.active_phase_idx || 0);
        data.executionPlan.activity_logs = planResult.data.activity_logs || data.executionPlan.activity_logs || [];
        data.execution_plan = data.executionPlan;
      }

      // Apply real-time broadcast payload if provided
      if (overridePayload) {
        if (overridePayload.manager_location) {
          data.manager_location = overridePayload.manager_location;
          if (data.executionPlan) data.executionPlan.manager_location = overridePayload.manager_location;
        }
        if (overridePayload.manager_route) {
          data.manager_route = overridePayload.manager_route;
          if (data.executionPlan) data.executionPlan.manager_route = overridePayload.manager_route;
        }
        if (overridePayload.admin_location) {
          data.admin_location = overridePayload.admin_location;
          if (data.executionPlan) data.executionPlan.admin_location = overridePayload.admin_location;
        }
        if (overridePayload.admin_route) {
          data.admin_route = overridePayload.admin_route;
          if (data.executionPlan) data.executionPlan.admin_route = overridePayload.admin_route;
        }
      }

      // Firestore fallback if location is not yet present in Supabase
      const hasLoc = data.manager_location || data.admin_location || (data.executionPlan && (data.executionPlan.manager_location || data.executionPlan.admin_location)) || (data.execution_plan && (data.execution_plan.manager_location || data.execution_plan.admin_location));
      if (!hasLoc && window.firebaseDB && window.firebaseFns && window.firebaseFns.getDoc && window.firebaseFns.doc) {
        try {
          const fsSnap = await window.firebaseFns.getDoc(window.firebaseFns.doc(window.firebaseDB, 'reservations', String(resId)));
          if (fsSnap && fsSnap.exists && fsSnap.exists()) {
            const fsD = fsSnap.data();
            if (fsD.manager_location) {
              data.manager_location = fsD.manager_location;
              if (data.executionPlan) data.executionPlan.manager_location = fsD.manager_location;
            }
            if (fsD.manager_route) {
              data.manager_route = fsD.manager_route;
              if (data.executionPlan) data.executionPlan.manager_route = fsD.manager_route;
            }
            if (fsD.admin_location) {
              data.admin_location = fsD.admin_location;
              if (data.executionPlan) data.executionPlan.admin_location = fsD.admin_location;
            }
            if (fsD.admin_route) {
              data.admin_route = fsD.admin_route;
              if (data.executionPlan) data.executionPlan.admin_route = fsD.admin_route;
            }
          }
        } catch(e) {}
      }
      // Preserve event_flow if already attached
      if (custExecActiveRes && custExecActiveRes.event_flow) {
        data.event_flow = custExecActiveRes.event_flow;
      }

      custExecActiveRes = data;

      // Check if completed/finalized -> trigger Congratulations feedback modal
      if (data.status === 'completed' || data.exec_finalized_at) {
        showCustExecCongratsModal();
        return;
      }

      // 1. Dynamically sync venue coordinates if provided by admin
      const rawVenueCoords = data.venue_coords || (data.executionPlan && data.executionPlan.venue_coords) || (data.execution_plan && data.execution_plan.venue_coords);
      if (rawVenueCoords && Array.isArray(rawVenueCoords) && rawVenueCoords.length >= 2 && custExecVenueMarker) {
        custExecVenueMarker.setLatLng(rawVenueCoords);
      }

      // 2. Dynamically sync exact route polyline from manager or admin side
      const rawRoute = data.manager_route || (data.executionPlan && data.executionPlan.manager_route) ||
                       data.admin_route || (data.executionPlan && data.executionPlan.admin_route) ||
                       (data.execution_plan && data.execution_plan.admin_route);
      let routeDrawnFromAdmin = false;
      if (rawRoute && Array.isArray(rawRoute) && rawRoute.length > 1) {
        if (!custExecRouteLine && custExecLiveMap) {
          custExecRouteLine = L.polyline(rawRoute, { weight: 5, color: '#3b82f6', opacity: 0.85 }).addTo(custExecLiveMap);
        } else if (custExecRouteLine) {
          custExecRouteLine.setLatLngs(rawRoute);
          custExecRouteLine.setStyle({ weight: 5, color: '#3b82f6', opacity: 0.85, dashArray: null });
        }
        routeDrawnFromAdmin = true;
      }

      // 3. Dynamically update team location marker on map without page refresh (Manager takes precedence)
      const rawMgrLoc = data.manager_location || (data.executionPlan && data.executionPlan.manager_location) || (data.execution_plan && data.execution_plan.manager_location);
      const rawAdminLoc = data.admin_location || (data.executionPlan && data.executionPlan.admin_location) || (data.execution_plan && data.execution_plan.admin_location);
      const activeLoc = rawMgrLoc || rawAdminLoc;
      const isMgr = !!rawMgrLoc;

      if (activeLoc) {
        let lat = null, lng = null;
        if (Array.isArray(activeLoc) && activeLoc.length >= 2) {
          lat = activeLoc[0]; lng = activeLoc[1];
        } else if (activeLoc.lat && activeLoc.lng) {
          lat = activeLoc.lat; lng = activeLoc.lng;
        }
        if (lat && lng) {
          const newLatLng = [lat, lng];
          const teamLabel = isMgr ? 'Team Location (Manager)' : 'Team Location';
          const teamBg = isMgr ? '#2563eb' : '#16a34a';
          const teamBorder = isMgr ? '#1d4ed8' : '#15803d';
          const teamIcon = L.divIcon({
            html: `<div style="background:${teamBg};color:#fff;font-size:10px;font-weight:800;padding:4px 8px;border-radius:6px;border:1px solid ${teamBorder};white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,0.4);display:flex;align-items:center;gap:4px;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;display:inline-block;"></span> ${teamLabel}</div>`,
            className: '',
            iconSize: [isMgr ? 140 : 110, 24],
            iconAnchor: [isMgr ? 70 : 55, 12]
          });
          if (custExecAdminMarker) {
            custExecAdminMarker.setIcon(teamIcon);
            custExecAdminMarker.setLatLng(newLatLng);
          } else if (custExecLiveMap) {
            custExecAdminMarker = L.marker(newLatLng, { icon: teamIcon }).addTo(custExecLiveMap);
          }

          if (!routeDrawnFromAdmin && custExecVenueMarker) {
            if (!custExecRouteLine && custExecLiveMap) {
              custExecRouteLine = L.polyline([newLatLng, custExecVenueMarker.getLatLng()], {
                color: '#3b82f6',
                weight: 5,
                opacity: 0.85
              }).addTo(custExecLiveMap);
            }
            if (custExecRouteLine) {
              updateCustExecDrivingRoute(newLatLng, custExecVenueMarker.getLatLng());
            }
          }

          if (custExecLiveMap && custExecVenueMarker) {
            try {
              const bounds = L.latLngBounds([newLatLng, custExecVenueMarker.getLatLng()]).pad(0.15);
              custExecLiveMap.fitBounds(bounds);
            } catch(e) {}
          }

          const statusTxt = document.getElementById('cust-exec-live-status-txt');
          if (statusTxt) statusTxt.textContent = `${isMgr ? 'Team (Manager)' : 'Team'} location updated (${lat.toFixed(4)}, ${lng.toFixed(4)})`;
        }
      } else {
        // If neither manager nor admin has synced location yet, remove any residual markers
        if (custExecAdminMarker) {
          try { custExecAdminMarker.remove(); } catch(e) {}
          custExecAdminMarker = null;
        }
        if (custExecRouteLine) {
          try { custExecRouteLine.remove(); } catch(e) {}
          custExecRouteLine = null;
        }
        const statusTxt = document.getElementById('cust-exec-live-status-txt');
        if (statusTxt) statusTxt.textContent = 'Awaiting live location sync...';
      }

      // Re-render phases and tasks preserving user's viewed phase
      renderCustExecLivePhases(data);
      renderCustExecLiveActivePhaseCard(data);

      const vPhase = CUST_EXEC_PHASES[custExecViewingPhaseIdx !== null ? custExecViewingPhaseIdx : 0];
      renderCustExecLiveLogs(resId, vPhase ? vPhase.id : null);
    }
  } catch(e) {}
}

function renderCustExecLivePhases(res) {
  const container = document.getElementById('cust-exec-phases-container');
  if (!container) return;

  const ep = res.execution_plan || res.executionPlan || {};
  const phasesArr = Array.isArray(ep.phases) ? ep.phases : [];
  const activeIdx = ep.active_phase_idx !== undefined ? ep.active_phase_idx : 0;
  const viewingIdx = (custExecViewingPhaseIdx !== null && custExecViewingPhaseIdx !== undefined)
    ? custExecViewingPhaseIdx
    : activeIdx;

  container.innerHTML = CUST_EXEC_PHASES.map((p, idx) => {
    const isViewing = idx === viewingIdx;
    const isActive = idx === activeIdx;
    const isPast = idx < activeIdx;
    const phaseData = phasesArr.find(ph => ph.id === p.id) || phasesArr[idx] || {};
    const timeRange = (phaseData.start && phaseData.end)
      ? `${formatTime12h(phaseData.start)} - ${formatTime12h(phaseData.end)}`
      : '';

    return `
      <div onclick="selectCustExecPhase(${idx})"
        style="cursor:pointer; background:var(--cp-sidebar, #ffffff); border:${isViewing ? '2.5px solid var(--cp-gold, #b8860b)' : (isPast ? '1.5px solid #2d8a4e' : '1px solid var(--cp-border)')}; box-shadow:${isViewing ? '0 0 12px rgba(184,134,11,0.25)' : 'none'}; border-radius:10px; padding:14px 12px; text-align:center; transition:all 0.2s;"
        onmouseenter="this.style.transform='translateY(-2px)'"
        onmouseleave="this.style.transform='none'">
        <div style="display:flex;align-items:center;justify-content:center;gap:4px;margin-bottom:5px;">
          <span style="font-size:11px;font-weight:800;text-transform:uppercase;color:${isViewing ? 'var(--cp-gold, #855800)' : (isPast ? '#2d8a4e' : 'var(--cp-text-dim, #6b7280)')};letter-spacing:0.5px;">
            ${p.label}
          </span>
          ${isViewing ? '<span style="font-size:9px;background:transparent !important;color:var(--cp-gold, #b8860b);padding:0 !important;border:none !important;font-weight:800;">VIEWING</span>' : (isActive ? '<span style="font-size:9px;color:var(--cp-text-dim, #6b7280);padding:0 !important;font-weight:700;">CURRENT</span>' : '')}
        </div>
        ${timeRange ? `<div style="font-size:11px;font-weight:600;color:var(--cp-text-mid, #4b5563);margin-top:6px;">${timeRange}</div>` : ''}
      </div>
    `;
  }).join('');
}

function renderCustExecLiveActivePhaseCard(res) {
  const container = document.getElementById('cust-exec-active-phase-card');
  if (!container || !res) return;

  const ep = res.execution_plan || res.executionPlan || {};
  const phasesArr = Array.isArray(ep.phases) ? ep.phases : [];
  const activeIdx = ep.active_phase_idx !== undefined ? ep.active_phase_idx : 0;
  const viewingIdx = (custExecViewingPhaseIdx !== null && custExecViewingPhaseIdx !== undefined)
    ? custExecViewingPhaseIdx
    : activeIdx;

  const phaseDef = CUST_EXEC_PHASES[viewingIdx] || CUST_EXEC_PHASES[0];
  const p = phasesArr.find(ph => ph.id === phaseDef.id) || phasesArr[viewingIdx] || {
    id: phaseDef.id,
    name: phaseDef.label,
    start: '',
    end: '',
    tasks: DEFAULT_EXEC_TASKS[phaseDef.id] || []
  };

  // Fallback tasks if not populated
  if (!Array.isArray(p.tasks) || !p.tasks.length) {
    p.tasks = DEFAULT_EXEC_TASKS[phaseDef.id] || [];
  }

  // If in execution phase and agenda is not loaded yet, fetch from additional_reservation_details or res.event_flow
  if (p.id === 'execution') {
    if ((!p.agenda || !p.agenda.length) && Array.isArray(res.event_flow) && res.event_flow.length > 0) {
      p.agenda = res.event_flow;
    } else if ((!p.agenda || !p.agenda.length) && Array.isArray(res.eventFlow) && res.eventFlow.length > 0) {
      p.agenda = res.eventFlow;
    } else if ((!p.agenda || !p.agenda.length) && !p._fetchingAgenda && window.supabaseClient && res.id) {
      p._fetchingAgenda = true;
      window.supabaseClient.from('additional_reservation_details')
        .select('event_flow')
        .eq('reservation_id', res.id)
        .maybeSingle()
        .then(({ data: ard }) => {
          p._fetchingAgenda = false;
          if (ard && Array.isArray(ard.event_flow) && ard.event_flow.length > 0) {
            p.agenda = ard.event_flow;
            renderCustExecLiveActivePhaseCard(res);
          }
        })
        .catch(() => { p._fetchingAgenda = false; });
    }
  }

  // Parse event start and end time for Beginning and End of Event milestones
  const resTimeStr = res.time || '';
  const timeParts = resTimeStr.split(/\s*[--to]\s*/i);
  const evStart12 = formatTime12h(p.start || (timeParts[0] || '')) || 'Event Start';
  const evEnd12 = formatTime12h(p.end || (timeParts[1] || '')) || 'Event End';

  const isCurrentActive = viewingIdx === activeIdx;
  const accent = 'var(--cp-gold, #c49a3c)';

  container.style.display = 'block';
  container.style.marginBottom = '20px';

  container.innerHTML = `
    <!-- Active Phase Details Card -->
    <div style="background:var(--cp-sidebar, var(--cp-bg2));border:1px solid var(--cp-border);border-left:4px solid ${accent};border-radius:12px;padding:20px;box-shadow:var(--cp-shadow);">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px;flex-wrap:wrap;gap:10px;">
        <div>
          <div style="font-size:11px;color:${accent};text-transform:uppercase;font-weight:800;letter-spacing:1px;margin-bottom:4px;">
            ${isCurrentActive ? 'Active Phase' : 'Viewing Phase'}
          </div>
          <div style="font-size:20px;font-weight:800;color:var(--cp-text);text-transform:uppercase;">
            ${escHtml(p.name || phaseDef.label)}
          </div>
          ${(p.start && p.end) ? `
            <div style="font-size:13px;color:var(--cp-text-dim);margin-top:3px;">
              ${formatTime12h(p.start)} - ${formatTime12h(p.end)}
            </div>
          ` : ''}
        </div>
        <div style="font-size:12px;font-weight:700;color:var(--cp-text-dim);background:transparent !important;padding:0 !important;border:none !important;">
          ${(p.tasks || []).length} activities
        </div>
      </div>

      <!-- Task Checklist (Read-only for Customer) -->
      <div style="display:flex;flex-direction:column;gap:10px;">
        ${(p.tasks || []).map((t, tIdx) => {
          if (typeof t === 'string') {
            t = { text: t, doneAt: null, status: 'pending' };
            p.tasks[tIdx] = t;
          }
          const isDone = !!(t.doneAt || t.status === 'done' || t.done);
          return `
            <div style="background:${isDone ? 'rgba(45,138,78,0.06)' : 'var(--cp-bg3, rgba(255,255,255,0.03))'};border:1px solid ${isDone ? 'rgba(45,138,78,0.25)' : 'var(--cp-border)'};border-radius:10px;padding:14px 16px;display:flex;align-items:flex-start;gap:14px;transition:all 0.2s;">
              <div style="width:10px;height:10px;border-radius:50%;background:${isDone ? 'var(--cp-green, #2d8a4e)' : 'var(--cp-text-dim)'};margin-top:5px;flex-shrink:0;"></div>
              <div style="flex:1;">
                <div style="font-size:14px;font-weight:600;color:${isDone ? 'var(--cp-text-dim)' : 'var(--cp-text)'};text-decoration:${isDone ? 'line-through' : 'none'};">
                  ${escHtml(t.text || 'Operational activity')}
                </div>
                ${isDone ? `
                  <div style="font-size:11px;color:var(--cp-green, #2d8a4e);margin-top:4px;font-weight:600;">
                    Done${t.doneAt ? ` at ${formatTime12h(t.doneAt)}` : ''}
                  </div>
                ` : ''}
              </div>
              <span style="flex-shrink:0;padding:0 !important;border:none !important;background:transparent !important;color:${isDone ? '#2d8a4e' : 'var(--cp-text-dim)'};font-size:11px;font-weight:700;">
                ${isDone ? 'Done' : 'In Progress'}
              </span>
            </div>
          `;
        }).join('')}
      </div>
    </div>

    <!-- Event Program Flow (Execution Phase only, matching admin side) -->
    ${p.id === 'execution' ? `
      <div style="margin-top:18px; background:var(--cp-sidebar, var(--cp-bg2)); border:1px solid var(--cp-border); border-radius:12px; padding:20px; box-shadow:var(--cp-shadow);">
        <div style="font-size:11px; color:var(--cp-text-dim); text-transform:uppercase; font-weight:800; letter-spacing:1px; margin-bottom:4px;">Execution Agenda</div>
        <div style="font-size:16px; color:var(--cp-text); font-weight:700; margin-bottom:16px;">Event Program Flow</div>
        <div style="display:flex; flex-direction:column; gap:10px;">
          <!-- Beginning of Event Milestone -->
          <div style="background:rgba(212,175,55,0.06); border:1px solid rgba(212,175,55,0.25); border-radius:10px; padding:12px 16px; display:flex; align-items:center; gap:14px;">
            <span style="font-size:13px; color:var(--cp-gold, #c49a3c); font-weight:800; min-width:80px; letter-spacing:0.5px;">${evStart12}</span>
            <span style="font-size:13px; color:var(--cp-text); font-style:italic; font-weight:600;">Beginning of Event</span>
          </div>

          <!-- Agenda items -->
          ${(p.agenda && p.agenda.length > 0) ? p.agenda.map(a => {
            const typeColors = {
              'Arrival': { text: '#2d8a4e' },
              'Program': { text: '#8b5cf6' },
              'Catering': { text: '#3b82f6' },
              'Buffer': { text: '#d97706' },
              'Custom': { text: 'var(--cp-text-dim)' }
            };
            const tc = typeColors[a.type || 'Custom'] || typeColors['Custom'];
            return `
              <div style="background:var(--cp-bg3, rgba(255,255,255,0.03)); border:1px solid var(--cp-border); border-radius:10px; padding:12px 16px; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px;">
                <div style="display:flex; align-items:center; gap:14px;">
                  <div style="font-size:13px; font-weight:800; color:var(--cp-gold, #c49a3c); min-width:80px;">${formatTime12h(a.time)}</div>
                  <div style="font-size:14px; font-weight:600; color:var(--cp-text);">${escHtml(a.text || 'Agenda Item')}</div>
                </div>
                <div style="font-size:11px; font-weight:700; color:${tc.text}; border:none !important; background:transparent !important; padding:0 !important; text-transform:uppercase;">${escHtml(a.type || 'Program')}</div>
              </div>
            `;
          }).join('') : '<div style="color:var(--cp-text-dim);font-size:13px;text-align:center;padding:14px;">No program flow agenda items added yet.</div>'}

          <!-- End of Event Milestone -->
          <div style="background:rgba(212,175,55,0.06); border:1px solid rgba(212,175,55,0.25); border-radius:10px; padding:12px 16px; display:flex; align-items:center; gap:14px;">
            <span style="font-size:13px; color:var(--cp-gold, #c49a3c); font-weight:800; min-width:80px; letter-spacing:0.5px;">${evEnd12}</span>
            <span style="font-size:13px; color:var(--cp-text); font-style:italic; font-weight:600;">End of Event</span>
          </div>
        </div>
      </div>
    ` : ''}
  `;
}

async function renderCustExecLiveLogs(resId, phaseId) {
  const container = document.getElementById('cust-exec-logs-container');
  if (!container || !resId) return;

  const res = (typeof custExecActiveRes !== 'undefined' && custExecActiveRes && String(custExecActiveRes.id) === String(resId))
    ? custExecActiveRes
    : (Array.isArray(window.RESERVATIONS) ? window.RESERVATIONS.find(r => String(r.id) === String(resId)) : null);

  let rawLogs = [];

  // 1. Fetch from Supabase execution_day_activity_logs
  if (window.supabaseClient) {
    try {
      const { data } = await window.supabaseClient
        .from('execution_day_activity_logs')
        .select('*')
        .eq('reservation_id', String(resId))
        .order('logged_at', { ascending: false });
      if (data && data.length) rawLogs.push(...data);
    } catch(e) {
      console.warn('[renderCustExecLiveLogs] fetch error:', e);
    }
  }

  // 2. Fetch from reservation executionPlan activity_logs
  const ep = (res && (res.execution_plan || res.executionPlan)) || {};
  if (Array.isArray(ep.activity_logs) && ep.activity_logs.length) {
    ep.activity_logs.forEach(al => {
      rawLogs.push({
        text: al.text || al.message || '',
        phase_id: al.phaseId || al.phase_id || 'general',
        phase_name: al.phaseName || al.phase_name || '',
        logged_at: al.logged_at || al.time || '',
        time: al.time || '',
        logged_by_name: al.logged_by_name || 'Admin'
      });
    });
  }

  // 3. Fetch from localStorage cache
  try {
    const cached = JSON.parse(localStorage.getItem('exec_activities_' + resId) || '[]');
    if (Array.isArray(cached) && cached.length) {
      cached.forEach(al => {
        rawLogs.push({
          text: al.text || al.message || '',
          phase_id: al.phaseId || al.phase_id || 'general',
          phase_name: al.phaseName || al.phase_name || '',
          logged_at: al.logged_at || al.time || '',
          time: al.time || '',
          logged_by_name: al.logged_by_name || 'Admin'
        });
      });
    }
  } catch(e) {}

  // 4. Synthesize logs from completed tasks in execution plan phases
  const phasesArr = Array.isArray(ep.phases) ? ep.phases : [];
  phasesArr.forEach(ph => {
    const tasks = Array.isArray(ph.tasks) ? ph.tasks : [];
    tasks.forEach(t => {
      const isDone = typeof t === 'object' && (t.doneAt || t.status === 'done' || t.status === 'completed');
      if (isDone) {
        const tText = typeof t === 'string' ? t : (t.text || '');
        const timeVal = t.doneAt || '';
        rawLogs.push({
          text: 'Task completed: ' + tText,
          phase_id: ph.id,
          phase_name: ph.name,
          logged_at: timeVal,
          time: timeVal,
          logged_by_name: 'Admin'
        });
      }
    });
  });

  // Deduplicate entries by normalized text + phase_id
  const seenKeys = new Set();
  const allLogs = [];
  rawLogs.forEach(item => {
    const normText = (item.text || item.message || '').trim();
    if (!normText) return;
    const pId = String(item.phase_id || item.phaseId || '').toLowerCase();
    const key = normText.toLowerCase() + '|' + pId;
    if (!seenKeys.has(key)) {
      seenKeys.add(key);
      allLogs.push(item);
    }
  });

  // Show all operational and command logs, exactly like admin execution day area
  const displayLogs = allLogs;

  if (!displayLogs.length) {
    container.innerHTML = `
      <div style="font-size:13px;color:var(--cp-text, #111827);text-align:center;padding:24px;font-weight:500;">
        No operational logs submitted yet. Real-time updates from the team will appear here.
      </div>`;
    return;
  }

  container.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:4px 2px;margin-bottom:8px;">
      <span style="font-size:11px;font-weight:700;color:var(--cp-gold, #855800);text-transform:uppercase;">Live Execution &amp; Activity Logs (${displayLogs.length})</span>
      <span style="font-size:11px;color:var(--cp-text-dim, #6b7280);">Real-time synchronized with admin operations</span>
    </div>
    <div style="display:flex;flex-direction:column;gap:6px;">
      ${displayLogs.map(l => {
        let timeStr = l.time || '';
        if (!timeStr && l.logged_at) {
          try {
            timeStr = new Date(l.logged_at).toLocaleTimeString([], { hour:'numeric', minute:'2-digit', hour12:true });
          } catch(e) {
            timeStr = String(l.logged_at);
          }
        }
        const phaseLabel = l.phase_name || l.phase_id || 'General';
        return `
          <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:var(--cp-bg, #faf8f4);border:1px solid var(--cp-border);border-radius:8px;gap:14px;">
            <div style="display:flex;align-items:center;gap:12px;flex:1;">
              <div style="width:7px;height:7px;border-radius:50%;background:#16a34a;flex-shrink:0;"></div>
              <div>
                <div style="font-size:13.5px;font-weight:600;color:var(--cp-text, #111827);line-height:1.4;">${escHtml(l.text || l.message || '')}</div>
                <div style="font-size:11px;color:var(--cp-text-dim, #6b7280);margin-top:2px;">Phase: ${escHtml(phaseLabel)}</div>
              </div>
            </div>
            <div style="font-size:12px;font-weight:700;color:var(--cp-text-dim, #6b7280);white-space:nowrap;">${timeStr || 'Recent'}</div>
          </div>
        `;
      }).join('')}
    </div>
  `;
}

