window.exportCustomerExecutionSummaryPdf = async function(targetResId) {
  // Comprehensive lookup for active or recently completed reservation
  let resId = targetResId || activeCustExecResId || window.activeCustExecResId || window._lastCompletedCustResId;
  if (!resId) {
    try {
      resId = sessionStorage.getItem('active_cust_exec_res_id') || localStorage.getItem('active_cust_exec_res_id');
    } catch(e) {}
  }
  if (!resId && window.location.hash.includes('id=')) {
    try { resId = window.location.hash.split('id=')[1].split('&')[0]; } catch(e) {}
  }

  let res = null;
  if (resId && window._profileResCache && window._profileResCache[resId]) {
    res = window._profileResCache[resId];
  }
  if (!res && resId && window.supabaseClient) {
    try {
      const { data } = await window.supabaseClient.from('reservations').select('*').eq('id', resId).maybeSingle();
      if (data) res = data;
    } catch(e) {}
  }
  if (!res) {
    const list = (typeof _getCustApprovedReservations === 'function' ? _getCustApprovedReservations() : []) || (window.RESERVATIONS || []);
    if (resId && list.length) res = list.find(r => String(r.id) === String(resId));
    if (!res && list.length) res = list[0];
  }
  if (!res && window.supabaseClient) {
    try {
      const user = currentUser || JSON.parse(localStorage.getItem('currentUser') || sessionStorage.getItem('currentUser') || '{}');
      const email = (user.email || '').toLowerCase().trim();
      if (email) {
        const { data } = await window.supabaseClient.from('reservations').select('*').ilike('client_email', email).order('created_at', { ascending: false }).limit(1);
        if (data && data[0]) res = data[0];
      }
    } catch(e) {}
  }
  if (!res) {
    alert('No reservation details found to export.');
    return;
  }

  const client = res.client || res.name || res.client_name || 'Valued Client';
  const pkg = res.packageName || res.package_name || res.premadePackageName || 'Catering Package';
  const dateStr = res.date || res.eventDate || res.event_date || 'N/A';
  const venue = res.venue || res.venueAddress || res.venue_location || 'N/A';
  const pax = res.pax || res.guests || res.guest_count || 'N/A';

  const sumObj = res.exec_summary || (res.executionPlan && res.executionPlan.exec_summary) || null;
  const _pricing = (typeof computePricingDetails === 'function') ? computePricingDetails(res) : null;
  const initFee = parseFloat(res.initial_fee_received || res.initialBookingFee || res.initial_booking_fee || 5000) || 5000;
  let dpAmt = parseFloat(res.downpayment_received || res.downpayment_amount || res.downpaymentAmount || res.downpayment || 0) || 0;
  if (dpAmt === 0 && res.amount) {
    dpAmt = Math.round(parseFloat(res.amount) * 0.5);
  }
  let finalAmt = parseFloat(res.final_received || res.final_payment_amount || res.final_amount || res.finalPaymentAmount || res.finalPayment || res.final_payment || 0) || 0;
  if (finalAmt === 0) {
    if (_pricing && _pricing.basePrice) {
      finalAmt = Math.max(0, _pricing.basePrice - dpAmt);
    } else if (res.amount) {
      finalAmt = Math.max(0, parseFloat(res.amount) - dpAmt);
    } else {
      finalAmt = dpAmt;
    }
  }

  const extraItemsTotal = parseFloat(sumObj?.extraItemsTotal ?? _pricing?.extraItemsTotal ?? res.additional_items_charge ?? res.additionalItemsCharge ?? 0) || 0;
  const extraItemsBreakdown = (sumObj && Array.isArray(sumObj.extraItemsBreakdown)) ? sumObj.extraItemsBreakdown : ((_pricing && Array.isArray(_pricing.extraItemsBreakdown)) ? _pricing.extraItemsBreakdown : []);
  const otcAmt = parseFloat(res.outOfTownCharge || res.out_of_town_charge || res.logisticsSurcharge || sumObj?.otcAmt || 0) || 0;
  const svcAmt = parseFloat(res.serviceCharge || res.service_charge || sumObj?.svcAmt || 0) || 0;

  const overheadUnits = parseInt(res.exec_extra_overhead_units || sumObj?.overheadUnits || 0, 10) || 0;
  const overheadAmt = parseFloat(res.exec_extra_overhead_amount || sumObj?.overheadAmt || (overheadUnits * 450)) || 0;
  const overtimeUnits = parseInt(res.exec_overtime_units || sumObj?.overtimeUnits || 0, 10) || 0;
  const overtimeAmt = parseFloat(res.exec_overtime_amount || sumObj?.overtimeAmt || (overtimeUnits * 1000)) || 0;
  const floorUnits = parseInt(res.exec_floor_access_units || sumObj?.floorUnits || 0, 10) || 0;
  const floorAmt = parseFloat(res.exec_floor_access_amount || sumObj?.floorAmt || (floorUnits * 100)) || 0;
  const incCharge = parseFloat(res.exec_incident_charges || sumObj?.incCharge || 0) || 0;
  const execCharges = (overheadAmt + overtimeAmt + floorAmt + incCharge);
  const subtotalAdditional = execCharges + otcAmt + svcAmt + extraItemsTotal;
  const chargesAmt = parseFloat(res.exec_charges_amount_paid || res.additional_charges_received || res.exec_total_charges || res.additional_charges || sumObj?.totalCharges || subtotalAdditional || 0) || 0;

  const totalSettlement = initFee + dpAmt + finalAmt + chargesAmt;

  const printWin = window.open('', '_blank', 'width=800,height=900');
  if (!printWin) {
    alert('Please allow popups to export the PDF statement.');
    return;
  }
  printWin.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Official Event Settlement & Payment Statement - ${client} - Halden's Catering</title>
      <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background: #fff; color: #111; margin: 24px; padding: 0; line-height: 1.5; font-size: 13px; }
        .header { text-align: center; border-bottom: 2px solid #855800; padding-bottom: 14px; margin-bottom: 20px; }
        .header h1 { margin: 0; font-size: 22px; color: #855800; font-weight: 800; letter-spacing: 0.5px; }
        .header p { margin: 4px 0 0; font-size: 13px; color: #555; }
        .card { border: 1px solid #ddd; border-radius: 8px; padding: 14px 16px; margin-bottom: 16px; page-break-inside: avoid; }
        .card-title { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 10px; color: #855800; border-bottom: 1px solid #eee; padding-bottom: 6px; }
        .row { display: flex; justify-content: space-between; padding: 7px 0; border-bottom: 1px solid #f2f2f2; font-size: 12px; }
        .row:last-child { border-bottom: none; }
        .total-row { display: flex; justify-content: space-between; padding: 10px 0; font-size: 14px; font-weight: 800; border-top: 2px solid #855800; margin-top: 8px; color: #855800; }
        .status-badge { font-size: 11px; font-weight: 700; color: #2ea043; text-transform: uppercase; }
        @media print {
          body { margin: 0; padding: 12px; }
          button { display: none !important; }
        }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>Halden's Catering Services</h1>
        <p>Official Event Settlement Statement & Complete Payment Summary</p>
        <p style="font-size:11px;color:#888;">Issued on: ${new Date().toLocaleDateString('en-PH', { month: 'long', day: 'numeric', year: 'numeric' })}</p>
      </div>

      <div class="card">
        <div class="card-title">Reservation & Event Details</div>
        <div class="row"><span>Client Name:</span><strong>${client}</strong></div>
        <div class="row"><span>Catering Package:</span><strong>${pkg}</strong></div>
        <div class="row"><span>Event Date:</span><strong>${dateStr}</strong></div>
        <div class="row"><span>Venue:</span><strong>${venue}</strong></div>
        <div class="row"><span>Guest Count:</span><strong>${pax} pax</strong></div>
        <div class="row"><span>Reservation ID:</span><strong>${res.id || 'N/A'}</strong></div>
        <div class="row"><span>Operational Status:</span><span class="status-badge">Completed</span></div>
      </div>

      <div class="card">
        <div class="card-title">All Payments Record (Initial Fee to Final Settlement)</div>
        <div class="row">
          <span>Initial Reservation Fee</span>
          <span><strong>PHP ${initFee.toLocaleString()}</strong> <span class="status-badge">&nbsp;(PAID)</span></span>
        </div>
        <div class="row">
          <span>Downpayment</span>
          <span><strong>PHP ${dpAmt.toLocaleString()}</strong> <span class="status-badge">&nbsp;(PAID)</span></span>
        </div>
        <div class="row">
          <span>Final Payment</span>
          <span><strong>PHP ${finalAmt.toLocaleString()}</strong> <span class="status-badge">&nbsp;(PAID)</span></span>
        </div>
        <div class="row">
          <span>Additional Execution Charges</span>
          <span><strong>PHP ${chargesAmt.toLocaleString()}</strong> <span class="status-badge">&nbsp;(PAID)</span></span>
        </div>
        <div class="total-row">
          <span>Total Payments Received</span>
          <span>PHP ${totalSettlement.toLocaleString()}</span>
        </div>
      </div>

      ${subtotalAdditional > 0 ? `
      <div class="card">
        <div class="card-title">Itemized Additional Execution Charges</div>
        ${extraItemsBreakdown.length > 0
          ? extraItemsBreakdown.map(it => `<div class="row"><span>+ ${it.name || 'Additional Item'}</span><span>PHP ${(it.price || 0).toLocaleString()}</span></div>`).join('')
          : (extraItemsTotal > 0 ? `<div class="row"><span>Additional Package Items</span><span>PHP ${extraItemsTotal.toLocaleString()}</span></div>` : '')}
        ${otcAmt > 0 ? `<div class="row"><span>Out of Town Surcharge</span><span>PHP ${otcAmt.toLocaleString()}</span></div>` : ''}
        ${svcAmt > 0 ? `<div class="row"><span>Service Charge</span><span>PHP ${svcAmt.toLocaleString()}</span></div>` : ''}
        ${overheadUnits > 0 ? `<div class="row"><span>Extra Overhead (${overheadUnits} units @ PHP 450)</span><span>PHP ${overheadAmt.toLocaleString()}</span></div>` : ''}
        ${overtimeUnits > 0 ? `<div class="row"><span>Overtime Charge (${overtimeUnits} hrs @ PHP 1,000)</span><span>PHP ${overtimeAmt.toLocaleString()}</span></div>` : ''}
        ${floorUnits > 0 ? `<div class="row"><span>Venue Floor Accessibility (${floorUnits} floors @ PHP 100)</span><span>PHP ${floorAmt.toLocaleString()}</span></div>` : ''}
        ${incCharge > 0 ? `<div class="row"><span>Incident Charges</span><span>PHP ${incCharge.toLocaleString()}</span></div>` : ''}
        <div class="row" style="font-weight:700;"><span>Subtotal Additional Charges</span><span>PHP ${chargesAmt.toLocaleString()}</span></div>
      </div>
      ` : ''}

      <div style="text-align:center;margin-top:28px;font-size:12px;color:#555;">
        <p>Congratulations on a successful event! Thank you for choosing Halden's Catering Services.</p>
        <p style="font-size:11px;color:#888;">For any inquiries regarding this settlement, please contact us at jmlenncatering@gmail.com</p>
      </div>

      <script>
        setTimeout(() => { window.print(); }, 400);
      <\/script>
    </body>
    </html>
  `);
  printWin.document.close();
};

// Global URL hash navigation router for Customer Execution Day & tabs
function handleCustomerHashNavigation() {
  const hash = window.location.hash || '';
  const searchParams = new URLSearchParams(window.location.search);
  const tabFromQuery = searchParams.get('tab') || searchParams.get('from');

  if (tabFromQuery && typeof switchDashTab === 'function') {
    const navBtn = document.getElementById('nav-' + tabFromQuery);
    switchDashTab(tabFromQuery, navBtn);
  } else if (hash.startsWith('#') && !hash.startsWith('#execution-day')) {
    const tabFromHash = hash.slice(1).split('?')[0];
    const navBtn = document.getElementById('nav-' + tabFromHash);
    if (navBtn && typeof switchDashTab === 'function') {
      switchDashTab(tabFromHash, navBtn);
    }
  }

  let resId = null;
  if (hash.startsWith('#execution-day')) {
    const query = hash.split('?')[1] || '';
    const params = new URLSearchParams(query);
    resId = params.get('id');
    if (typeof switchDashTab === 'function') {
      const navBtn = document.getElementById('nav-execution-day');
      switchDashTab('execution-day', navBtn);
    }
  }
  if (!resId) {
    try {
      const saved = sessionStorage.getItem('active_cust_exec_res_id');
      if (saved) {
        resId = saved;
        if (typeof switchDashTab === 'function') {
          const navBtn = document.getElementById('nav-execution-day');
          switchDashTab('execution-day', navBtn);
        }
      }
    } catch(e) {}
  }
  if (resId) {
    setTimeout(() => {
      openCustomerExecLivePanel(resId);
    }, 350);
  }
}
window.handleCustomerHashNavigation = handleCustomerHashNavigation;
window.addEventListener('hashchange', handleCustomerHashNavigation);
document.addEventListener('DOMContentLoaded', () => {
  setTimeout(handleCustomerHashNavigation, 250);
});
window.addEventListener('load', () => {
  setTimeout(handleCustomerHashNavigation, 500);
});

function goToCustomerLogisticsTimeline(resId) {
  if (typeof openCustomerResDetailModal === 'function') {
    openCustomerResDetailModal(resId);
  } else if (typeof switchDashTab === 'function') {
    switchDashTab('resdetails');
  }
}
window.goToCustomerLogisticsTimeline = goToCustomerLogisticsTimeline;

function openProfile() {
  if (!currentUser) return;
  window.location.href = 'customer.html';
}
window.openProfile = openProfile;

function renderCustomerProfileUI() {
  if (!currentUser) return;
  const fnameEl = document.getElementById('prof-fname');
  const mnameEl = document.getElementById('prof-mname');
  const lnameEl = document.getElementById('prof-lname');
  const emailEl = document.getElementById('prof-email');
  const phoneEl = document.getElementById('prof-phone');

  let fname = currentUser.fname || currentUser.first_name || '';
  let mname = currentUser.mname || currentUser.middle_name || '';
  let lname = currentUser.lname || currentUser.last_name || '';
  let email = currentUser.email || '';
  let phone = currentUser.phone || currentUser.phone_number || '';

  if (!fname && currentUser.name) {
    const parts = currentUser.name.trim().split(/\s+/);
    if (parts.length === 1) fname = parts[0];
    else if (parts.length === 2) { fname = parts[0]; lname = parts[1]; }
    else if (parts.length >= 3) { fname = parts[0]; mname = parts[1]; lname = parts.slice(2).join(' '); }
  }

  if (fnameEl) fnameEl.textContent = fname || ':';
  if (mnameEl) mnameEl.textContent = mname || ':';
  if (lnameEl) lnameEl.textContent = lname || ':';
  if (emailEl) emailEl.textContent = email || ':';
  if (phoneEl) phoneEl.textContent = phone || ':';

  const uid = currentUser.id || currentUser.uid;
  if (window.supabaseClient && uid) {
    window.supabaseClient
      .from('users')
      .select('fname, lname, mname, email, phone, name')
      .eq('id', uid)
      .maybeSingle()
      .then(({ data, error }) => {
        if (!error && data) {
          if (data.fname) fname = data.fname;
          if (data.lname) lname = data.lname;
          if (data.mname) mname = data.mname;
          if (data.email) email = data.email;
          if (data.phone) phone = data.phone;

          if (!fname && data.name) {
            const parts = data.name.trim().split(/\s+/);
            if (parts.length === 1) fname = parts[0];
            else if (parts.length === 2) { fname = parts[0]; lname = parts[1]; }
            else if (parts.length >= 3) { fname = parts[0]; mname = parts[1]; lname = parts.slice(2).join(' '); }
          }

          if (fnameEl) fnameEl.textContent = fname || ':';
          if (mnameEl) mnameEl.textContent = mname || ':';
          if (lnameEl) lnameEl.textContent = lname || ':';
          if (emailEl) emailEl.textContent = email || ':';
          if (phoneEl) phoneEl.textContent = phone || ':';
        }
      })
      .catch(e => console.warn('Could not fetch user profile from Supabase:', e));
  }
}
window.renderCustomerProfileUI = renderCustomerProfileUI;

function validateEditProfileFieldLive(el) {
  if (!el) return;
  const id = el.id;
  const val = (el.value || '');
  // Strict Name Rule: Purely letters and spaces, first character must be a letter, no space or dash at start, no numbers or special characters, max 20 chars
  const nameRegex = /^[a-zA-Z\u00C0-\u024F][a-zA-Z\u00C0-\u024F\s]{0,19}$/;
  let valid = true;

  if (id === 'edit-prof-fname' || id === 'edit-prof-lname') {
    valid = val.length > 0 && val.length <= 20 && nameRegex.test(val);
    el.style.outline = valid ? '2px solid rgba(34,197,94,0.7)' : '2px solid rgba(220,38,38,0.7)';
    el.style.boxShadow = valid ? '0 0 8px rgba(34,197,94,0.3)' : '0 0 8px rgba(220,38,38,0.35)';
  } else if (id === 'edit-prof-mname') {
    valid = val.length === 0 || (val.length <= 20 && nameRegex.test(val));
    if (val.length === 0) {
      el.style.outline = 'none';
      el.style.boxShadow = 'none';
    } else {
      el.style.outline = valid ? '2px solid rgba(34,197,94,0.7)' : '2px solid rgba(220,38,38,0.7)';
      el.style.boxShadow = valid ? '0 0 8px rgba(34,197,94,0.3)' : '0 0 8px rgba(220,38,38,0.35)';
    }
  } else if (id === 'edit-phone-input') {
    const wrap = document.getElementById('edit-prof-phone-wrap') || el.parentElement || el;
    const clean = val.replace(/[^0-9]/g, '');
    valid = clean.length === 10 && clean.startsWith('9');
    wrap.style.outline = valid ? '2px solid rgba(34,197,94,0.7)' : '2px solid rgba(220,38,38,0.7)';
    wrap.style.boxShadow = valid ? '0 0 8px rgba(34,197,94,0.3)' : '0 0 8px rgba(220,38,38,0.35)';
  }
}
window.validateEditProfileFieldLive = validateEditProfileFieldLive;

function openEditProfileModal() {
  const modal = document.getElementById('edit-phone-overlay');
  const fnameInp = document.getElementById('edit-prof-fname');
  const mnameInp = document.getElementById('edit-prof-mname');
  const lnameInp = document.getElementById('edit-prof-lname');
  const phoneInp = document.getElementById('edit-phone-input');
  const msg = document.getElementById('edit-phone-msg');
  if (msg) { msg.style.display = 'none'; msg.textContent = ''; }

  const u = currentUser || JSON.parse(localStorage.getItem('currentUser') || '{}');
  let fname = u.fname || u.first_name || '';
  let mname = u.mname || u.middle_name || '';
  let lname = u.lname || u.last_name || '';
  if (!fname && u.name) {
    const parts = u.name.trim().split(/\s+/);
    if (parts.length === 1) fname = parts[0];
    else if (parts.length === 2) { fname = parts[0]; lname = parts[1]; }
    else if (parts.length >= 3) { fname = parts[0]; mname = parts[1]; lname = parts.slice(2).join(' '); }
  }

  let rawPhone = u.phone || u.phone_number || '';
  let cleanPhone = String(rawPhone).replace(/[^0-9]/g, '');
  if (cleanPhone.startsWith('639') && cleanPhone.length === 12) cleanPhone = cleanPhone.slice(2);
  else if (cleanPhone.startsWith('09') && cleanPhone.length === 11) cleanPhone = cleanPhone.slice(1);

  if (fnameInp) { fnameInp.value = fname; validateEditProfileFieldLive(fnameInp); }
  if (mnameInp) { mnameInp.value = mname; validateEditProfileFieldLive(mnameInp); }
  if (lnameInp) { lnameInp.value = lname; validateEditProfileFieldLive(lnameInp); }
  if (phoneInp) { phoneInp.value = cleanPhone; validateEditProfileFieldLive(phoneInp); }

  if (modal) modal.classList.add('on');
}
window.openEditProfileModal = openEditProfileModal;
window.openEditPhoneModal = openEditProfileModal;

function closeEditProfileModal() {
  const modal = document.getElementById('edit-phone-overlay');
  if (modal) modal.classList.remove('on');
}
window.closeEditProfileModal = closeEditProfileModal;
window.closeEditPhoneModal = closeEditProfileModal;

async function saveUpdatedProfile() {
  const fnameInp = document.getElementById('edit-prof-fname');
  const mnameInp = document.getElementById('edit-prof-mname');
  const lnameInp = document.getElementById('edit-prof-lname');
  const phoneInp = document.getElementById('edit-phone-input');
  const msg = document.getElementById('edit-phone-msg');
  const btn = document.getElementById('btn-save-phone');

  const fname = (fnameInp?.value || '').trim();
  const mname = (mnameInp?.value || '').trim();
  const lname = (lnameInp?.value || '').trim();
  const rawPhone = (phoneInp?.value || '').trim().replace(/[^0-9]/g, '');

  const nameRegex = /^[a-zA-Z\u00C0-\u024F][a-zA-Z\u00C0-\u024F\s]{0,19}$/;

  const showError = (text) => {
    if (msg) {
      msg.style.display = 'block';
      msg.style.color = '#e74c3c';
      msg.textContent = text;
    }
  };

  if (!fname || fname.length > 20 || !nameRegex.test(fname)) {
    showError('First name must contain only letters and spaces, start with a letter, and be at most 20 characters (no numbers, dashes, or special characters).');
    return;
  }
  if (!lname || lname.length > 20 || !nameRegex.test(lname)) {
    showError('Last name must contain only letters and spaces, start with a letter, and be at most 20 characters (no numbers, dashes, or special characters).');
    return;
  }
  if (mname && (mname.length > 20 || !nameRegex.test(mname))) {
    showError('Middle name must contain only letters and spaces, start with a letter, and be at most 20 characters (no numbers, dashes, or special characters).');
    return;
  }
  if (rawPhone.length !== 10 || !rawPhone.startsWith('9')) {
    showError('Please enter a valid 10-digit Philippine phone number starting with 9 (e.g. 9561545551).');
    return;
  }

  const officialPhone = '0' + rawPhone;
  const fullName = [fname, mname, lname].filter(Boolean).join(' ');

  if (btn) { btn.disabled = true; btn.textContent = 'Saving...'; }
  if (msg) { msg.style.display = 'none'; }

  try {
    const uid = currentUser?.id || currentUser?.uid;
    if (window.supabaseClient && uid) {
      const { error } = await window.supabaseClient
        .from('users')
        .update({
          fname: fname,
          mname: mname || null,
          lname: lname,
          name: fullName,
          phone: officialPhone
        })
        .eq('id', uid);
      if (error) throw error;
    }

    if (currentUser) {
      currentUser.fname = fname;
      currentUser.mname = mname;
      currentUser.lname = lname;
      currentUser.name = fullName;
      currentUser.phone = officialPhone;
      localStorage.setItem('currentUser', JSON.stringify(currentUser));
      localStorage.setItem('halden_customer', JSON.stringify(currentUser));
    }

    renderCustomerProfileUI();
    const navName = document.getElementById('user-name-display') || document.getElementById('customer-nav-name');
    if (navName) navName.textContent = fname || fullName;

    if (msg) {
      msg.style.display = 'block';
      msg.style.color = '#2ecc71';
      msg.textContent = 'Profile updated successfully!';
    }

    setTimeout(() => {
      closeEditProfileModal();
      if (btn) { btn.disabled = false; btn.textContent = 'Save Changes'; }
    }, 800);
  } catch (err) {
    console.error('Profile update error:', err);
    showError('Failed to update profile: ' + (err.message || 'Server error'));
    if (btn) { btn.disabled = false; btn.textContent = 'Save Changes'; }
  }
}
window.saveUpdatedProfile = saveUpdatedProfile;
window.saveUpdatedPhoneNumber = saveUpdatedProfile;

function closeProfile() {
  window.location.href = 'index.html';
}
window.closeProfile = closeProfile;

let profileResUnsub = null;

async function renderProfileReservations() {
  const lists = {
    processing: document.getElementById('list-processing'),
    approved: document.getElementById('list-approved'),
    rejected: document.getElementById('list-rejected')
  };
  const counts = {
    processing: document.getElementById('count-processing'),
    approved: document.getElementById('count-approved'),
    rejected: document.getElementById('count-rejected')
  };

  if (!lists.processing) return;

  if (profileResUnsub) profileResUnsub();

  // Also grab the section-header badges (if present)
  const badges = {
    processing: document.getElementById('badge-processing'),
    approved:   document.getElementById('badge-approved'),
    rejected:   document.getElementById('badge-rejected')
  };

  const userEmail = currentUser && currentUser.email ? currentUser.email : '';
  const userId    = (currentUser && (currentUser.id || currentUser.uid)) || '';

  // ── Core render function called on every data refresh ─────────────────
  const processAndRender = function(rows) {
    const groups = { processing: [], approved: [], rejected: [] };
    let pendingRes = null;
    let paymentRes = null;

    rows.forEach(function(res) {
      const status = (res.status || 'pending').toLowerCase();

      if (status === 'pending' || status === 'processing' || status === 'confirmed') {
        pendingRes = res;
      }

      if (res.customerHidden) return;

      if (res.paymentRequested && res.paymentStatus !== 'paid') {
        paymentRes = res;
      }

      if (['pending', 'processing', 'preparing'].includes(status)) groups.processing.push(res);
      else if (['confirmed', 'approved', 'completed', 'on-going', 'ongoing', 'in-progress', 'in_progress'].includes(status)) groups.approved.push(res);
      else if (['cancelled', 'rejected'].includes(status)) groups.rejected.push(res);
    });

    window._profileResCache = {};
    [...groups.processing, ...groups.approved, ...groups.rejected].forEach(function(r) {
      window._profileResCache[r.id] = r;
    });

    const flagContainer = document.getElementById('dash-res-flags');
    if (flagContainer) {
      if (paymentRes) {
        flagContainer.innerHTML = `
          <div style="background: #eef2ff; border: 2px solid #4f46e5; border-radius: 16px; padding: 24px; display: flex; align-items: flex-start; gap: 20px; margin-bottom: 30px; box-shadow: 0 10px 30px rgba(79, 70, 229, 0.1); animation: slideDown 0.5s ease-out;">
            <div style="font-size: 32px; background: #4f46e5; color: #fff; width: 60px; height: 60px; border-radius: 14px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;"></div>
            <div style="flex: 1;">
              <div style="font-weight: 800; color: #3730a3; margin-bottom: 6px; font-size: 17px; text-transform: uppercase; letter-spacing: 0.5px;">Payment Required</div>
              <p style="font-size: 14px; color: #312e81; line-height: 1.6; margin: 0; font-weight: 500;">
                A payment of &#8369;${Number(paymentRes.paymentAmount).toLocaleString()} is required to finalize your contract.
              </p>
              <button class="btn-primary" style="margin-top:15px; background:#4f46e5; color:#fff;" onclick="openPaymentModal('${paymentRes.id}', '${paymentRes.paymentAmount}')">Make Payment Now</button>
            </div>
          </div>
        `;
        if (!activePaymentResId && !window.hasAutoOpenedPaymentModal) {
          openPaymentModal(paymentRes.id, paymentRes.paymentAmount);
          window.hasAutoOpenedPaymentModal = true;
        }
        if (activePaymentResId === paymentRes.id && paymentRes.cashPaymentStatus === 'waiting_for_admin') {
          document.getElementById('pay-selection-area').style.display = 'none';
          document.getElementById('pay-btn-submit').style.display = 'none';
          document.getElementById('pay-waiting-area').style.display = 'block';
        }
      } else if (pendingRes) {
        if (activePaymentResId) closePaymentModal();
        flagContainer.innerHTML = `
          <div style="background: #fffdf0; border: 2px solid #c49a3c; border-radius: 16px; padding: 24px; display: flex; align-items: flex-start; gap: 20px; margin-bottom: 30px; box-shadow: 0 10px 30px rgba(196, 154, 60, 0.1); animation: slideDown 0.5s ease-out;">
            <div style="font-size: 32px; background: #c49a3c; color: #fff; width: 60px; height: 60px; border-radius: 14px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;"></div>
            <div style="flex: 1;">
              <div style="font-weight: 800; color: #8a6820; margin-bottom: 6px; font-size: 17px; text-transform: uppercase; letter-spacing: 0.5px;">Action Required: Awaiting Review</div>
              <p style="font-size: 14px; color: #4a3728; line-height: 1.6; margin: 0; font-weight: 500;">
                Please wait for the admin to review your reservation. Once it is approved or rejected, you will receive a notification within the system and an email will be sent to your provided Gmail.
              </p>
            </div>
          </div>
        `;
      } else {
        if (activePaymentResId) closePaymentModal();
        flagContainer.innerHTML = '';
      }
    }

    // Update Upcoming Reservation banner text & CTA button
    const upcomingBannerText = document.getElementById('upcoming-res-text');
    const upcomingBannerReady = document.getElementById('upcoming-res-ready');
    const upcomingBannerBtn = document.getElementById('upcoming-res-btn');
    const hasActiveUpcomingRes = (groups.processing.length > 0 || groups.approved.length > 0);

    if (upcomingBannerText) {
      if (hasActiveUpcomingRes) {
        upcomingBannerText.innerHTML = `Please check the email that you selected for your account as we will send notifications in there for your reservation. For now you may tap the reservation itself to see its details and please look into the meetings tab for the proper scheduling of your meeting with Alden to finalize your reservation.`;
        if (upcomingBannerReady) upcomingBannerReady.style.display = 'none';
        if (upcomingBannerBtn) {
          upcomingBannerBtn.textContent = 'Go to Meetings';
          upcomingBannerBtn.removeAttribute('href');
          upcomingBannerBtn.onclick = function (e) {
            e.preventDefault();
            if (typeof switchDashTab === 'function') switchDashTab('meetings');
          };
        }
      } else {
        upcomingBannerText.innerHTML = `You have no upcoming events yet.<br/>Let's create something memorable together!`;
        if (upcomingBannerReady) {
          upcomingBannerReady.style.display = 'block';
          upcomingBannerReady.textContent = 'Ready to plan your next event?';
        }
        if (upcomingBannerBtn) {
          upcomingBannerBtn.textContent = 'Create New Reservation';
          upcomingBannerBtn.setAttribute('href', 'index.html#catalog');
          upcomingBannerBtn.onclick = null;
        }
      }
    }

    Object.keys(groups).forEach(function(key) {
      const g = groups[key];
      if (counts[key]) counts[key].textContent = g.length;
      if (badges[key]) badges[key].textContent = g.length;

      g.sort(function(a, b) { return new Date(b.date) - new Date(a.date); });

      lists[key].innerHTML = g.map(function(res) {
        const isApproved = key === 'approved';
        const isContractFinalized = !!(res.contractFinalizedAt || res.contract_finalized_at || res.contractUrl || res.contract_url || (res.contractUrls && res.contractUrls.length > 0));
        const hasCancellationRequested = !!(res.cancellation_requested || res.cancellationRequested);
        const cardStatus = (res.status || (isApproved ? 'approved' : 'pending')).toLowerCase();
        const isCompleted = (cardStatus === 'completed') || !!res.exec_finalized_at || !!(res.executionPlan && res.executionPlan.completedAt);
        const initFeeStatus = (res.initial_fee_status || res.initialFeeStatus || res.payment_status || res.paymentStatus || '').toLowerCase();
        const initFeePaid = initFeeStatus === 'paid' || initFeeStatus === 'initial_paid';
        const rawInitDue = res.initial_fee_due_date || res.initialFeeDueDate || (res.initial_fee_deadline ? res.initial_fee_deadline.slice(0, 10) : null) || null;
        let niceInitDue = rawInitDue;
        if (rawInitDue) {
          try {
            const d = new Date(rawInitDue + (rawInitDue.includes('T') ? '' : 'T00:00:00'));
            niceInitDue = isNaN(d.getTime()) ? rawInitDue : d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
          } catch (e) { niceInitDue = rawInitDue; }
        }
        const initDueTag = (!initFeePaid && niceInitDue) ? `<span style="display:inline-block; font-size:10px; font-weight:700; color:#d97706; margin-left:6px;">Initial Fee Due: ${niceInitDue}</span>` : '';

        if (isApproved) {
          const lat = (res.coords && res.coords.lat) ? res.coords.lat : 14.5995;
          const lon = (res.coords && res.coords.lon) ? res.coords.lon : 120.9842;
          const mapUrl = 'https://static-maps.yandex.ru/1.x/?ll=' + lon + ',' + lat + '&z=14&l=map&pt=' + lon + ',' + lat + ',pm2rdl&size=400,300';

          return `
            <div class="dash-res-card approved" data-res-status="${cardStatus}" style="cursor:pointer; background:var(--cp-card, var(--cp-sidebar, #ffffff)); border:1px solid var(--cp-border, #e2e8f0); color:var(--cp-text); border-radius:14px; padding:20px; box-shadow:0 2px 8px rgba(0,0,0,0.03); margin-bottom:14px; position:relative; overflow:hidden;" onclick="openCustomerResModal('${res.id}')">
              <div class="drc-content" style="margin-right:0; margin-top:0;">
                <div style="font-size:16px; font-weight:700; color:var(--cp-text, #1a202c); margin-bottom:2px;">${res.packageName || 'Custom Package'}</div>
                <div style="font-size:12px; color:var(--cp-text-dim, #718096); margin-bottom:12px;">${res.type || 'Event'}${initDueTag}</div>
                <div style="font-size:12px; color:var(--cp-text-mid, #2d3748); display:flex; gap:12px; align-items:center; margin-bottom:10px;">
                  <span>${res.date || ''}</span>
                  <span style="color:var(--cp-border, #cbd5e0);">|</span>
                  <span>${res.pax || 0} pax</span>
                  <span style="color:var(--cp-border, #cbd5e0);">|</span>
                  <span style="font-weight:600;">&#8369;${safeNum(res.amount || res.total || res.price).toLocaleString()}</span>
                </div>
                <div style="font-size:12px; color:var(--cp-text-dim, #718096); line-height:1.4; margin-bottom:10px;">${res.venue || res.venueAddress || "Halden's Private Venue"}</div>
                <div style="display:flex; align-items:center; gap:8px;">
                  <button onclick="event.stopPropagation(); saveReservationTemplate('${res.id}')" style="background:var(--cp-gold); color:#ffffff; border:none; border-radius:6px; padding:6px 12px; font-size:11px; font-weight:700; cursor:pointer;">Save</button>
                  ${isCompleted ? '' : (() => {
                    const cw = res.cancellation_window || res.cancellationWindow;
                    const todayStr = new Date().toISOString().slice(0, 10);
                    const isWithinWindow = cw ? (todayStr <= String(cw).slice(0, 10)) : !isContractFinalized;
                    if (isWithinWindow) {
                      return `<button onclick="event.stopPropagation(); openCustomerCancelDirectModal('${res.id}')" style="background:#dc2626; color:#ffffff; border:none; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:700; cursor:pointer;">Cancel</button>`;
                    } else if (hasCancellationRequested) {
                      return `<span style="font-size:11px; font-weight:700; color:#dc2626; background:transparent !important; border:none !important; padding:0 !important;">Cancellation Requested</span>`;
                    } else {
                      return `<button onclick="event.stopPropagation(); openCustomerCancelRequestModal('${res.id}')" style="background:#dc2626; color:#ffffff; border:none; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:700; cursor:pointer;">Request Cancellation</button>`;
                    }
                  })()}
                </div>
              </div>
            </div>
          `;
        }

        const isPending   = ['pending', 'processing', 'preparing'].includes((res.status || '').toLowerCase());
        const isCancelled = ['cancelled', 'rejected'].includes((res.status || '').toLowerCase());
        const statusColor = isPending ? '#f39c12' : isCancelled ? '#e74c3c' : '#27ae60';
        const statusText  = isPending ? 'PROCESSING' : isCancelled ? 'CANCELLED' : (res.status || 'STATUS').toUpperCase();

        return `
          <div class="dash-res-card" data-res-status="${cardStatus}" style="cursor:pointer; background:var(--cp-card, var(--cp-sidebar, #ffffff)); border:1px solid var(--cp-border, #e2e8f0); color:var(--cp-text); border-radius:14px; padding:20px; box-shadow:0 2px 8px rgba(0,0,0,0.03); margin-bottom:14px;" onclick="openCustomerResModal('${res.id}')">
            <div style="font-size:11px; font-weight:700; color:${statusColor}; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:4px;">${statusText}</div>
            <div style="font-size:16px; font-weight:700; color:var(--cp-text, #1a202c); margin-bottom:2px;">${res.packageName || 'Custom Package'}</div>
            <div style="font-size:12px; color:var(--cp-text-dim, #718096); margin-bottom:12px;">${res.type || 'Event'} ${statusText}${initDueTag}</div>
            <div style="font-size:12px; color:var(--cp-text-mid, #2d3748); display:flex; gap:12px; align-items:center; margin-bottom:6px;">
              <span>${res.date || ''}</span>
              <span style="color:var(--cp-border, #cbd5e0);">|</span>
              <span>${res.pax || 0} pax</span>
              <span style="color:var(--cp-border, #cbd5e0);">|</span>
              <span style="font-weight:600;">&#8369;${safeNum(res.amount || res.total || res.price).toLocaleString()}</span>
            </div>
            ${(isPending && !isCompleted) ? `
              <div style="display:flex; align-items:center; gap:8px; margin-top:10px;">
                <button onclick="event.stopPropagation(); saveReservationTemplate('${res.id}')" style="background:var(--cp-gold); color:#ffffff; border:none; border-radius:6px; padding:6px 12px; font-size:11px; font-weight:700; cursor:pointer;">Save</button>
                ${(() => {
                  const cw = res.cancellation_window || res.cancellationWindow;
                  const todayStr = new Date().toISOString().slice(0, 10);
                  const isWithinWindow = cw ? (todayStr <= String(cw).slice(0, 10)) : !isContractFinalized;
                  if (isWithinWindow) {
                    return `<button onclick="event.stopPropagation(); openCustomerCancelDirectModal('${res.id}')" style="background:#dc2626; color:#ffffff; border:none; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:700; cursor:pointer;">Cancel</button>`;
                  } else if (hasCancellationRequested) {
                    return `<span style="font-size:11px; font-weight:700; color:#dc2626; background:transparent !important; border:none !important; padding:0 !important;">Cancellation Requested</span>`;
                  } else {
                    return `<button onclick="event.stopPropagation(); openCustomerCancelRequestModal('${res.id}')" style="background:#dc2626; color:#ffffff; border:none; border-radius:6px; padding:5px 12px; font-size:11px; font-weight:700; cursor:pointer;">Request Cancellation</button>`;
                  }
                })()}
              </div>
            ` : ''}
            ${isCancelled ? `
              <button class="btn-modify-res" data-res-id="${res.id}" style="margin-top:10px; width:100%; padding:9px; font-size:12px; font-weight:600; background:linear-gradient(135deg,#c49a3c,#e8c66a); color:#ffffff; border:none; border-radius:8px; cursor:pointer; font-family:'DM Sans',sans-serif; letter-spacing:0.3px; transition:opacity 0.18s;">Modify Reservation</button>
              <button onclick="event.stopPropagation(); window.deleteRejectedReservation('${res.id}')" style="margin-top:8px; width:100%; padding:9px; font-size:12px; font-weight:600; background:#dc2626; color:#ffffff; border:none; border-radius:8px; cursor:pointer; font-family:'DM Sans',sans-serif; letter-spacing:0.3px; transition:opacity 0.18s;">Remove Record</button>
            ` : ''}
          </div>
        `;
      }).join('') || '<div style="padding:10px; font-size:12px; color:var(--text-dim);">No ' + key + ' reservations.</div>';
    });

    if (typeof applyCustomerResFilter === 'function') {
      applyCustomerResFilter(window._activeCustomerResFilter || 'all');
    }

    if (typeof initPublicCalendar === 'function') {
      initPublicCalendar(true);
    }
  };

  // ── Dual-query fetch: by client_email AND by user_id ──────────────────
  // This catches both: reservations the customer submitted themselves
  // (stored with client_email) AND reservations admin created on their
  // behalf (stored with user_id but possibly missing client_email).
  const fetchAndRender = async function() {
    try {
      const sb = window.supabaseClient;
      const allDocs = new Map();

      let uEmail = userEmail || (window.supabaseUser && window.supabaseUser.email) || '';
      let uId = userId || (window.supabaseUser && window.supabaseUser.id) || '';

      if ((!uEmail || !uId) && sb) {
        try {
          const authUser = (await sb.auth.getUser())?.data?.user;
          if (authUser) {
            if (!uId) uId = authUser.id;
            if (!uEmail) uEmail = authUser.email;
          }
        } catch (e) {}
      }

      // Query 1: by client_email
      if (uEmail) {
        const resp1 = await sb.from('reservations').select('*').ilike('client_email', uEmail);
        (resp1.data || []).forEach(function(row) { allDocs.set(row.id, row); });
      }

      // Query 2: by user_id
      if (uId) {
        const resp2 = await sb.from('reservations').select('*').eq('user_id', uId);
        (resp2.data || []).forEach(function(row) {
          if (!allDocs.has(row.id)) allDocs.set(row.id, row);
        });
      }

      // Map Supabase snake_case columns to the JS camelCase names the rest
      // of the code expects (mirrors what supabase_adapter mapFromDB does).
      const mapRow = function(row) {
        const d = Object.assign({}, row);
        if (d.client_email  !== undefined) { d.email            = d.client_email;        delete d.client_email; }
        if (d.client_name   !== undefined) { d.client           = d.client_name;         delete d.client_name; }
        if (d.package_name  !== undefined) { d.packageName      = d.package_name;        delete d.package_name; }
        if (d.timeframe     !== undefined) { d.time             = d.timeframe;           delete d.timeframe; }
        if (d.venue_coords  !== undefined) { d.coords           = d.venue_coords;        delete d.venue_coords; }
        if (d.payment_method !== undefined){ d.paymentMethod    = d.payment_method;      delete d.payment_method; }
        if (d.pricing_mode  !== undefined) { d.pricingMode      = d.pricing_mode;        delete d.pricing_mode; }
        if (d.selected_tier !== undefined) { d.selectedTier     = d.selected_tier;       delete d.selected_tier; }
        if (d.package_origin !== undefined){ d.packageOrigin    = d.package_origin;      delete d.package_origin; }
        if (d.price_per_head !== undefined){ d.pricePerHead     = parseFloat(d.price_per_head) || 0; delete d.price_per_head; }
        if (d.price_tiers   !== undefined) { d.priceTiers       = d.price_tiers;         delete d.price_tiers; }
        if (d.payment_status !== undefined){ d.paymentStatus    = d.payment_status;      delete d.payment_status; }
        if (d.venue_location !== undefined){ d.venueLocation    = d.venue_location;      delete d.venue_location; }
        if (d.rejection_reason !== undefined){ d.rejectionReason= d.rejection_reason;    delete d.rejection_reason; }
        if (d.active_pkg_id !== undefined) { d.activePkgId      = d.active_pkg_id;       delete d.active_pkg_id; }
        if (d.downpayment_amount !== undefined){ d.downpaymentAmount = d.downpayment_amount; delete d.downpayment_amount; }
        if (d.downpayment_due_date !== undefined){ d.downpaymentDueDate = d.downpayment_due_date; delete d.downpayment_due_date; }
        if (d.final_payment_due_date !== undefined){ d.finalPaymentDueDate = d.final_payment_due_date; delete d.final_payment_due_date; }
        if (d.final_payment_amount !== undefined){ d.finalPaymentAmount = d.final_payment_amount; delete d.final_payment_amount; }
        if (d.meeting_times !== undefined) { d.proposedMeetingTimes = d.meeting_times;   delete d.meeting_times; }
        if (d.package_items !== undefined) {
          d.packageItems = Array.isArray(d.package_items) ? d.package_items : [];
          delete d.package_items;
        }
        if (d.vip) {
          d.isVIP = d.vip.enabled; d.vipCount = d.vip.count; d.vipService = d.vip.service;
          delete d.vip;
        }
        if (d.execution_plan && d.execution_plan._firebase_extras) {
          Object.assign(d, d.execution_plan._firebase_extras);
          delete d.execution_plan._firebase_extras;
        }
        return d;
      };

      const rows = Array.from(allDocs.values()).map(mapRow);
      processAndRender(rows);
    } catch (err) {
      console.error('renderProfileReservations fetch error:', err);
    }
  };

  // Initial load
  await fetchAndRender();

  // ── Realtime: re-fetch whenever the reservations table changes ────────
  const channel = window.supabaseClient
    .channel('profile-reservations-' + Date.now())
    .on('postgres_changes', { event: '*', schema: 'public', table: 'reservations' }, function() {
      fetchAndRender();
    })
    .subscribe();

  profileResUnsub = function() { window.supabaseClient.removeChannel(channel); };
}

// ====================================================================
// CUSTOMER PORTAL RESERVATION SORTING / FILTERING
// ====================================================================
window._activeCustomerResFilter = 'all';

function filterCustomerReservations(filter, btn) {
  window._activeCustomerResFilter = filter || 'all';

  // Update active state on filter buttons
  document.querySelectorAll('.cp-filter-btn').forEach(b => {
    if (b === btn || b.getAttribute('data-filter') === filter) {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });

  applyCustomerResFilter(filter);
}
window.filterCustomerReservations = filterCustomerReservations;

function applyCustomerResFilter(filter) {
  const normFilter = (filter || 'all').toLowerCase();
  const listApproved = document.getElementById('list-approved');
  const listProcessing = document.getElementById('list-processing');
  const listRejected = document.getElementById('list-rejected');

  const secApproved = listApproved ? listApproved.closest('.cp-res-sec') : null;
  const secTwoCol = listProcessing ? listProcessing.closest('.cp-two-col') : null;
  const secProcessing = listProcessing ? listProcessing.closest('.cp-res-sec') : null;
  const secRejected = listRejected ? listRejected.closest('.cp-res-sec') : null;

  // Filter cards inside lists
  const allCards = document.querySelectorAll('#list-approved .dash-res-card, #list-processing .dash-res-card, #list-rejected .dash-res-card');
  allCards.forEach(card => {
    const status = (card.getAttribute('data-res-status') || '').toLowerCase();
    let show = false;

    if (normFilter === 'all') {
      show = true;
    } else if (normFilter === 'approved') {
      show = ['confirmed', 'approved', 'on-going', 'ongoing', 'in-progress', 'in_progress'].includes(status);
    } else if (normFilter === 'processing') {
      show = ['pending', 'processing', 'preparing'].includes(status);
    } else if (normFilter === 'completed') {
      show = (status === 'completed');
    } else if (normFilter === 'cancelled') {
      show = ['cancelled', 'rejected'].includes(status);
    }

    card.style.display = show ? '' : 'none';
  });

  // Toggle container sections based on filter selection
  if (normFilter === 'all') {
    if (secApproved) secApproved.style.display = '';
    if (secTwoCol) secTwoCol.style.display = '';
    if (secProcessing) secProcessing.style.display = '';
    if (secRejected) secRejected.style.display = '';
  } else if (normFilter === 'approved' || normFilter === 'completed') {
    if (secApproved) secApproved.style.display = '';
    if (secTwoCol) secTwoCol.style.display = 'none';
  } else if (normFilter === 'processing') {
    if (secApproved) secApproved.style.display = 'none';
    if (secTwoCol) secTwoCol.style.display = '';
    if (secProcessing) secProcessing.style.display = '';
    if (secRejected) secRejected.style.display = 'none';
  } else if (normFilter === 'cancelled') {
    if (secApproved) secApproved.style.display = 'none';
    if (secTwoCol) secTwoCol.style.display = '';
    if (secProcessing) secProcessing.style.display = 'none';
    if (secRejected) secRejected.style.display = '';
  }
}
window.applyCustomerResFilter = applyCustomerResFilter;



