window.executeCustomerCancelDirect = async function(resId) {
  const modal = document.getElementById("cust-cancel-direct-modal");
  if (modal) modal.remove();

  try {
    const cancelTime = new Date().toISOString();
    if (window.firebaseDB && window.firebaseFns) {
      try {
        const { updateDoc, doc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, "reservations", resId), {
          status: "cancelled",
          cancelledAt: cancelTime,
          cancelled_at: cancelTime,
          cancellation_reason: "Cancelled by customer within cancellation window"
        });
      } catch(e) {}
    }
    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from("reservations").update({
          status: "cancelled",
          cancelled_at: cancelTime,
          cancellation_reason: "Cancelled by customer within cancellation window"
        }).eq("id", resId);
      } catch(e) {}
    }

    // Update in-memory objects
    const res = (window.RESERVATIONS || []).find(r => r.id === resId);
    if (res) {
      res.status = "cancelled";
      res.cancelled_at = cancelTime;
    }
    if (window._profileResCache && window._profileResCache[resId]) {
      window._profileResCache[resId].status = "cancelled";
      window._profileResCache[resId].cancelled_at = cancelTime;
    }

    // Re-render UI components
    if (typeof activeResDetailId !== "undefined" && activeResDetailId === resId) {
      if (res && typeof window.updateCustomerResDetailCancelButtons === "function") {
        window.updateCustomerResDetailCancelButtons(res);
      }
      if (typeof window.initCustomerResDetails === "function") {
        window.initCustomerResDetails();
      }
    }
    if (typeof renderProfileReservations === "function") {
      renderProfileReservations();
    }
    if (typeof renderCustomerReservationsList === "function") {
      renderCustomerReservationsList();
    }
    alert("Your reservation has been cancelled.");
  } catch(e) {
    console.error("[executeCustomerCancelDirect] error:", e);
    alert("Failed to cancel reservation. Please try again.");
  }
};

