// ── Helpers ──────────────────────────────────────────────────────────
function _fmtTimeAmPm(t) {
  if (!t) return 'TBD';
  const parts = t.split(':');
  if (parts.length < 2) return t;
  let h = parseInt(parts[0]);
  const m = parts[1];
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${h}:${m} ${ampm}`;
}

function formatMeetingTimeString(val) {
  if (!val) return ':';
  if (typeof val === 'string') {
    const trimmed = val.trim();
    if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
      try { val = JSON.parse(trimmed); } catch (e) { }
    }
  }
  if (Array.isArray(val)) {
    if (val.length === 0) return ':';
    return val.map(v => formatMeetingTimeString(v)).filter(x => x && x !== ':').join(', ');
  }
  if (typeof val === 'object' && val !== null) {
    const d = val.date || val.day || '';
    const s = formatMeetingTimeString(val.start || val.startTime || val.from || '');
    const e = formatMeetingTimeString(val.end || val.endTime || val.to || '');
    const startFormatted = (s && s !== ':') ? s : '';
    const endFormatted = (e && e !== ':') ? e : '';
    const timeRange = (startFormatted && endFormatted) ? `${startFormatted} - ${endFormatted}` : (startFormatted || endFormatted);
    if (!d && !timeRange) return ':';
    return [d, timeRange].filter(Boolean).join('  ');
  }
  let str = String(val).trim();
  if (!str) return '';
  if (/\b(AM|PM)\b/i.test(str)) return str;
  return str.replace(/\b([01]?\d|2[0-3]):([0-5]\d)\b/g, (match, h, m) => {
    let hour = parseInt(h, 10);
    const ap = hour >= 12 ? 'PM' : 'AM';
    hour = hour % 12 || 12;
    return `${hour}:${m} ${ap}`;
  });
}
window.formatMeetingTimeString = formatMeetingTimeString;

function _fmtTimeRange(t, tEnd = null) {
  if (!t || t === 'TBD') return 'TBD';
  const formatHour = (hour, min) => {
    const normH = ((hour % 24) + 24) % 24;
    const ampm = normH >= 12 ? 'PM' : 'AM';
    let hr12 = normH % 12 || 12;
    return `${hr12}:${String(min || '00').padStart(2, '0')} ${ampm}`;
  };
  const parseTimePart = (str) => {
    if (!str) return null;
    const m = String(str).trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM|am|pm)?$/);
    if (!m) return null;
    let hh = parseInt(m[1], 10);
    const mm = parseInt(m[2], 10) || 0;
    const ap = (m[3] || '').toUpperCase();
    if (ap === 'PM' && hh < 12) hh += 12;
    if (ap === 'AM' && hh === 12) hh = 0;
    return { h: hh, m: mm };
  };
  if (!tEnd && (String(t).includes(' - ') || String(t).includes(' - ') || String(t).toLowerCase().includes(' to '))) {
    const sep = String(t).includes(' - ') ? ' - ' : (String(t).toLowerCase().includes(' to ') ? / to /i : ' - ');
    const splitParts = String(t).split(sep);
    if (splitParts.length >= 2) {
      t = splitParts[0].trim();
      tEnd = splitParts[splitParts.length - 1].trim();
    }
  }
  const startP = parseTimePart(t);
  const endP = parseTimePart(tEnd);
  if (startP && endP) {
    return `${formatHour(startP.h, startP.m)} - ${formatHour(endP.h, endP.m)}`;
  }
  if (startP) {
    return `${formatHour(startP.h, startP.m)} - ${formatHour(startP.h + 1, startP.m)}`;
  }
  return String(t);
}

function _fmtTimeframe(tf) {
  if (!tf) return 'TBD';
  const sep = tf.includes(' - ') ? ' - ' : (tf.includes('-') ? '-' : null);
  if (sep) {
    const [s, e] = tf.split(sep).map(x => x.trim());
    return `${_fmtTimeAmPm(s)} - ${_fmtTimeAmPm(e)}`;
  }
  return _fmtTimeAmPm(tf);
}


function _statusStyle(status) {
  const s = (status || '').toLowerCase();
  if (['confirmed', 'approved', 'completed'].includes(s)) return 'background:transparent;color:#2ecc71;border:none;';
  if (['pending', 'processing', 'preparing', 'on-going'].includes(s)) return 'background:transparent;color:#e6991a;border:none;';
  if (['cancelled', 'rejected'].includes(s)) return 'background:transparent;color:#e74c3c;border:none;';
  return 'background:transparent;color:var(--cp-text);border:none;';
}

function _catLabel(cat) {
  const map = {
    food: 'Food', dessert: 'Desserts', drink: 'Drinks',
    decoration: 'Decorations', equipment: 'Equipment', entertainment: 'Add-ons'
  };
  return map[cat] || (cat ? cat.charAt(0).toUpperCase() + cat.slice(1) : 'Other');
}

function _renderCrmItemGroup(label, items, isFree, isCustomPackage = false, pCount = 50) {
  if (!items.length) return '';
  const freeTag = isFree ? ' <span style="font-size:9px;color:var(--cp-gold);font-weight:700;">FREE</span>' : '';
  const boxes = items.map(i => {
    const itemName = typeof i === 'string' ? i : (i.name || '');
    const priceVal = (typeof i === 'object' && (i.snapshotPrice || i.price || i.dynamic_price)) ? (i.snapshotPrice || i.price || i.dynamic_price) : null;
    const isEquip = typeof i === 'object' && ((i.cat || '').toLowerCase() === 'equipment' || (label || '').toLowerCase().includes('equipment'));
    const hasPrice = (isCustomPackage || isEquip) && priceVal && (!isFree || isEquip);
    const priceDisplay = hasPrice ? `<div style="font-size:11px; font-weight:700; color:var(--cp-gold, #c49a3c); margin-top:4px;">₱${Number(priceVal).toLocaleString()}</div>` : '';
    
    let customDetailsHtml = '';
    let isCustomized = false;

    if (isEquip) {
      let eqCount = null;
      if (typeof i === 'object') {
        const cQ = (i.customQty != null) ? i.customQty : (i.custom_qty != null ? i.custom_qty : null);
        if (cQ !== null && parseInt(cQ) > 0) {
          eqCount = parseInt(cQ);
        } else if ((i.isCustomized || i.is_customized) && (i.quantity || i.qty || i.count)) {
          eqCount = parseInt(i.quantity || i.qty || i.count);
        }
      }
      if (!eqCount) {
        const catEntry = typeof CAT !== 'undefined' ? CAT.find(c => c.name.toLowerCase() === itemName.toLowerCase()) : null;
        const resolvedItem = Object.assign({}, catEntry || {}, typeof i === 'object' ? i : { name: itemName });
        if (typeof getEquipmentAllocatedQty === 'function') {
          eqCount = getEquipmentAllocatedQty(resolvedItem, pCount, items);
        } else {
          eqCount = 1;
        }
      }
      const pPax = typeof i === 'object' ? (i.customPax || i.portion_pax || null) : null;
      const specs = typeof i === 'object' ? (i.specifications || i.specs || '') : '';
      isCustomized = typeof i === 'object' && (
        (i.customQty !== undefined && i.customQty !== null) ||
        i.isLocked ||
        i.isCustomized ||
        (i.specifications && String(i.specifications).trim().length > 0)
      );

      customDetailsHtml = `
        <div style="margin-top:6px; padding-top:4px; border-top:1px dashed rgba(196,154,60,0.3); font-size:11px;">
          ${pPax ? `<div style="font-weight:700; color:var(--cp-gold, #c49a3c);">Custom: ${pPax} pax</div>` : ''}
          <div style="font-weight:700; color:var(--cp-gold, #c49a3c);">Count: ${eqCount} pcs</div>
          ${specs ? `<div style="color:var(--cp-text-mid); font-style:italic; margin-top:2px; word-break:break-word;">"${escHtml(specs)}"</div>` : ''}
        </div>
      `;
    } else if (typeof i === 'object') {
      const pPax = i.customPax || i.portion_pax || null;
      const qQty = i.customQty || i.quantity || null;
      const specs = i.specifications || i.specs || '';
      if (pPax || qQty || specs) {
        customDetailsHtml = `
          <div style="margin-top:6px; padding-top:4px; border-top:1px dashed rgba(196,154,60,0.3); font-size:11px;">
            ${pPax ? `<div style="font-weight:700; color:var(--cp-gold, #c49a3c);">Custom: ${pPax} pax</div>` : ''}
            ${qQty ? `<div style="font-weight:700; color:var(--cp-gold, #c49a3c);">Count: ${qQty} pcs</div>` : ''}
            ${specs ? `<div style="color:var(--cp-text-mid); font-style:italic; margin-top:2px; word-break:break-word;">"${escHtml(specs)}"</div>` : ''}
          </div>
        `;
      }
    }
    
    return `
      <div class="crm-item-mini-box" style="background:var(--cp-bg2); border:1px solid var(--cp-border); border-radius:8px; padding:10px 12px; display:flex; flex-direction:column; justify-content:space-between; min-width:135px; flex:1 1 calc(25% - 10px); box-sizing:border-box;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:4px; margin-bottom:2px;">
          <div style="font-size:12px; font-weight:700; color:var(--cp-text); line-height:1.3;">${itemName}</div>
          ${isCustomized ? `<span style="font-size:9.5px; font-weight:700; color:var(--cp-gold, #c49a3c); border:1px solid rgba(196,154,60,0.5); border-radius:3px; padding:1px 5px; text-transform:uppercase; letter-spacing:0.5px; white-space:nowrap;">Customized</span>` : ''}
        </div>
        ${priceDisplay}
        ${customDetailsHtml}
      </div>
    `;
  }).join('');

  return `
    <div style="margin-bottom:14px;">
      <div style="color:var(--cp-gold); font-size:10px; font-weight:800; letter-spacing:1.5px; text-transform:uppercase; margin-bottom:8px;">${label}${freeTag}</div>
      <div style="display:flex; flex-wrap:wrap; gap:8px;">${boxes}</div>
    </div>`;
}

// ── Main modal open ──────────────────────────────────────────────────
window.openCustomerResModal = async function (resId) {
  const res = window._profileResCache && window._profileResCache[resId];
  if (!res) return;
  window._currentCrmResId = resId;

  // Show overlay immediately while we load
  document.getElementById('customer-res-detail-overlay').classList.add('on');

  // ── Origin badge ──
  const originMap = {
    'majorly set': 'Majority Set', 'majorly_set': 'Majority Set',
    'dynamically set': 'Dynamically Set', 'per_head': 'Dynamically Set',
    'custom': 'Custom Build', 'item-based': 'Custom Build'
  };
  const originLabel = originMap[res.packageOrigin || res.pricingMode] || 'Custom Build';
  const el = n => document.getElementById(n);

  el('crm-origin-badge').textContent = originLabel;
  el('crm-status-badge').setAttribute('style',
    `color:var(--cp-gold); font-size:10px; font-weight:800; letter-spacing:1.5px; text-transform:uppercase;`);
  el('crm-status-badge').textContent = res.status;

  // Cancellation Details Banner (if cancelled)
  const crmBanner = el('crm-cancellation-banner');
  const isCancelled = String(res.status || '').toLowerCase() === 'cancelled';
  if (crmBanner) {
    if (isCancelled) {
      const b = computeCustomerCancellationBalances(res);
      const isLateCancel = !!(res.cancellation_requested || res.cancellationRequested || res.cancellation_type === 'late' || res.cancellationType === 'late');
      const isEarlyCancel = !isLateCancel;
      const isRejection = !!(res.rejectionReason || res.rejection_reason || res.reject_reason || String(res.status_note || '').toLowerCase().includes('reject'));
      const origin = (typeof getCancellationOrigin === 'function') ? getCancellationOrigin(res) : (res.cancellation_by || 'customer');
      const isBusiness = origin === 'business' || isRejection || res.cancellation_by === 'business' || res.cancelled_by === 'business';
      const rejectionMsg = res.rejectionReason || res.rejection_reason || res.reject_reason || res.status_note || 'Booking request rejected by administration.';
      const fmt = (n) => (parseFloat(n) || 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

      crmBanner.style.display = 'block';

      if (isEarlyCancel && isBusiness) {
        crmBanner.innerHTML = `
          <div style="background:rgba(239,68,68,0.06); border:1px solid rgba(239,68,68,0.3); border-radius:12px; padding:16px 20px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-wrap:wrap; gap:8px;">
              <div style="font-size:12px; font-weight:800; color:var(--red,#ef4444); text-transform:uppercase; letter-spacing:1px;">Cancellation Details</div>
              <span style="font-size:11px; font-weight:700; color:#c49a3c; text-transform:uppercase;">Early Cancellation &bull; Cancelled By Business</span>
            </div>
            <div style="background:var(--cp-bg2); border:1px solid var(--cp-border); border-radius:8px; padding:14px;">
              <div style="font-size:11px; color:#ef4444; font-weight:800; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:4px;">Rejection Message from Admin</div>
              <div style="font-size:13px; color:var(--cp-text); line-height:1.6;">${rejectionMsg}</div>
            </div>
          </div>
        `;
      } else if (isEarlyCancel && !isBusiness) {
        crmBanner.innerHTML = `
          <div style="background:rgba(0,0,0,0.02); border:1px solid var(--cp-border); border-radius:12px; padding:16px 20px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px;">
              <div style="font-size:12px; font-weight:800; color:var(--cp-text); text-transform:uppercase; letter-spacing:1px;">Cancellation Details</div>
              <span style="font-size:11px; font-weight:700; color:var(--cp-text-dim); text-transform:uppercase;">Early Cancellation</span>
            </div>
            <div style="font-size:13px; color:var(--cp-text-dim); line-height:1.5;">
              Cancelled by the customer. This reservation was cancelled before contract finalization. No cancellation balances are due.
            </div>
          </div>
        `;
      } else if (isLateCancel && isBusiness) {
        const owed = parseFloat(res.cancellation_business_owed) || b.businessLiability;
        const pkg = parseFloat(res.cancellation_package_total) || b.packageTotal;
        crmBanner.innerHTML = `
          <div style="background:rgba(196,154,60,0.08); border:1px solid #c49a3c; border-radius:12px; padding:18px 20px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
              <div style="font-size:12px; font-weight:800; color:#c49a3c; text-transform:uppercase; letter-spacing:1px;">Cancellation Compensation</div>
              <span style="font-size:11px; color:var(--red,#ef4444); font-weight:700; text-transform:uppercase;">Late Cancellation &bull; Cancelled By Business</span>
            </div>
            <div style="background:var(--cp-bg2); border:1px solid var(--cp-border); border-radius:8px; padding:14px; margin-bottom:10px;">
              <div style="font-size:11px; color:var(--cp-text-mid); text-transform:uppercase; font-weight:700;">Amount Owed to You (200% Package Compensation)</div>
              <div style="font-size:24px; font-weight:900; color:#27ae60; margin-top:4px;">&#8369;${fmt(owed)}</div>
              <div style="font-size:12px; color:var(--cp-text-dim); margin-top:4px;">
                Package Total: &#8369;${fmt(pkg)} &bull; Multiplier: 200% (Excluding the &#8369;5,000 initial reservation fee)
              </div>
            </div>
            <div style="font-size:12px; color:var(--cp-text-dim); line-height:1.5;">
              This reservation was cancelled by the business. You do not owe any cancellation fees. The business administration will disburse this compensation amount to you directly.
            </div>
          </div>
        `;
      } else {
        // Late Cancel by Customer
        let rows = `
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; font-size:12px;">
            <span style="color:var(--cp-text-mid);">Downpayment (50% Base)</span>
            <span style="font-weight:700; color:${b.dpPaid ? 'var(--green,#27ae60)' : 'var(--cp-gold)'};">&#8369;${fmt(b.dpAmount)} (${b.dpPaid ? 'Paid' : 'Unpaid'})</span>
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; font-size:12px;">
            <span style="color:var(--cp-text-mid);">Final Payment (50% + Additional Charges)</span>
            <span style="font-weight:700; color:${b.finalPaid ? 'var(--green,#27ae60)' : 'var(--cp-gold)'};">&#8369;${fmt(b.finalAmount)} (${b.finalPaid ? 'Paid' : 'Unpaid'})</span>
          </div>
        `;

        crmBanner.innerHTML = `
          <div style="background:rgba(239,68,68,0.06); border:1px solid rgba(239,68,68,0.3); border-radius:12px; padding:16px 20px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
              <div style="font-size:12px; font-weight:800; color:var(--red,#ef4444); text-transform:uppercase; letter-spacing:1px;">Cancellation Details</div>
              <span style="font-size:11px; font-weight:700; color:#ef4444; text-transform:uppercase;">Late Cancellation &bull; Cancelled By Customer</span>
            </div>
            ${res.cancellation_due_date ? `<div style="font-size:12px; color:var(--cp-text); font-weight:600; margin-bottom:10px;">Payment Due Date: <span style="color:var(--cp-gold); font-weight:700;">${res.cancellation_due_date}</span></div>` : ''}
            <div style="background:var(--cp-bg2); border:1px solid var(--cp-border); border-radius:8px; padding:12px; margin-bottom:12px;">
              ${rows}
              <div style="display:flex; justify-content:space-between; align-items:center; border-top:1px solid var(--cp-border); margin-top:6px; padding-top:6px; font-size:13px; font-weight:700;">
                <span style="color:var(--cp-text);">Total Remaining Balance Due:</span>
                <span style="color:var(--cp-gold); font-size:15px; font-weight:800;">&#8369;${fmt(b.totalDue)}</span>
              </div>
            </div>
            <div style="font-size:12px; color:${b.totalDue === 0 ? '#27ae60' : 'var(--cp-text-dim)'}; font-weight:${b.totalDue === 0 ? '700' : '500'};">
              ${b.totalDue === 0 ? 'All cancellation payments settled.' : 'Outstanding cancellation balances must be coordinated directly with administration.'}
            </div>
          </div>
        `;
      }
    } else {
      crmBanner.style.display = 'none';
      crmBanner.innerHTML = '';
    }
  }

  el('crm-title').textContent = res.packageName || res.type || 'Reservation';
  const pPkgName = res.premadePackageName || res.premade_package_name || null;
  const pWrap = el('crm-premade-name-wrap');
  const pVal = el('crm-premade-name-val');
  if (pWrap && pVal) {
    if (pPkgName) {
      pVal.textContent = pPkgName;
      pWrap.style.display = 'block';
    } else {
      pWrap.style.display = 'none';
    }
  }
  el('crm-desc').textContent = res.description || res.desc || 'No description provided.';

  // Customer Contact Phone Number in expanded reservation view
  const phoneEl = el('crm-phone');
  if (phoneEl) {
    phoneEl.textContent = res.client_phone || res.clientPhone || res.customer_phone || res.phone || res.contactNumber || res.contact_number || (currentUser && currentUser.phone) || 'N/A';
  }

  // ── Price / pax ──
  const amtNum = parseFloat(String(res.amount || '0').replace(/[^0-9.]/g, ''));
  el('crm-price').textContent = '₱' + amtNum.toLocaleString();
  el('crm-pax').textContent = (res.pax || ':') + ' Pax';

  // ── Info grid ──
  el('crm-theme').textContent = res.theme || 'N/A';
  el('crm-occasion').textContent = res.type || 'N/A';

  // Format date nicely
  const rawDate = res.date || '';
  let niceDate = rawDate;
  if (rawDate) {
    const d = new Date(rawDate + 'T00:00:00');
    if (!isNaN(d)) niceDate = d.toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
  }
  el('crm-date').textContent = niceDate || ':';
  el('crm-time').textContent = _fmtTimeframe(res.time || res.timeframe);

  // ── Call Time ──
  const ctEl = el('crm-call-time');
  if (ctEl) {
    let ctDisplay = ':';
    if (res.callTime) {
      ctDisplay = _fmtTimeAmPm(res.callTime);
    } else {
      // Legacy: derive from event start time
      const tf = res.time || res.timeframe || '';
      const sep = tf.toLowerCase().includes(' to ') ? / to /i : (tf.includes('-') ? /-/ : null);
      if (sep) {
        const startPart = tf.split(sep)[0].trim();
        if (startPart) ctDisplay = _fmtTimeAmPm(startPart) + ' (same as event start)';
      }
    }
    ctEl.textContent = ctDisplay;
  }

  // ── Event Setup ──
  const setupName = res.eventSetup || (res.eventSetupSlug ? ((window.EVENT_SETUPS || []).find(s => s.slug === res.eventSetupSlug)?.name || res.eventSetupSlug.replace(/_/g, ' ').toUpperCase()) : 'Complete Setup');
  const esEl = el('crm-event-setup');
  if (esEl) esEl.textContent = setupName;

  // ── Venue ──
  el('crm-venue-loc').textContent = res.venueLocation || res.venue_location || ':';
  el('crm-venue-addr').textContent = res.venue || 'No specific address';
  const vInfoEl = el('crm-venue-info');
  const vInfo = res.venueInfo || res.venue_info || '';
  if (vInfoEl) {
    if (vInfo) {
      vInfoEl.innerHTML = `<span style="color:var(--cp-gold); font-size:10px; font-weight:800; letter-spacing:1px; text-transform:uppercase; display:block; margin-bottom:2px;">Venue Info</span>${escHtml(vInfo)}`;
      vInfoEl.style.display = 'block';
    } else {
      vInfoEl.style.display = 'none';
      vInfoEl.textContent = '';
    }
  }

  // ── VIP ──
  if (res.isVIP && res.vipCount > 0) {
    el('crm-vip').textContent = `${res.vipCount} VIP${res.vipCount > 1 ? 's' : ''} : ${res.vipService || 'Standard'}`;
  } else {
    el('crm-vip').textContent = 'None';
  }

  // ── Additional Charges (including added items on premade packages) ──
  const acEl = el('crm-additional-charges');
  if (acEl) {
    const _isMal = (typeof window.isReservationMalabon === 'function') ? window.isReservationMalabon(res) : false;
    let otc = _isMal ? 0 : parseFloat(res.outOfTownCharge || 0);
    if (!_isMal && otc <= 0) {
      const baseAmt = parseFloat(String(res.amount || 0).replace(/[^0-9.]/g, '')) || 0;
      if (baseAmt > 0) otc = Math.round(baseAmt * 0.05);
    }
    const acParts = [];
    const _crmExInfo = (typeof window.computeCustomerExtraItemsBreakdown === 'function') ? window.computeCustomerExtraItemsBreakdown(res) : { extraItemsBreakdown: [], extraItemsTotal: 0 };
    if (_crmExInfo.extraItemsBreakdown.length > 0) {
      _crmExInfo.extraItemsBreakdown.forEach(ei => {
        acParts.push(`<span style="color:var(--cp-gold);">${ei.name} (Added Item): +₱${ei.price.toLocaleString()}</span>`);
      });
    }
    if (otc > 0) acParts.push(`<span style="color:var(--cp-gold);">Out of town charges: +₱${otc.toLocaleString()}</span>`);
    const _svcp = parseFloat(res.service_charge_pct || res.serviceChargePct || 0);
    const _baseAmtForSvc = (otc > 0 && res.amount >= otc) ? (res.amount - otc) : (parseFloat(res.amount) || 0);
    const _svcAmt = _svcp > 0 ? Math.round(_baseAmtForSvc * (_svcp / 100)) : 0;
    if (_svcAmt > 0) acParts.push(`<span style="color:var(--cp-gold);">Service charges (+${_svcp}%): +₱${_svcAmt.toLocaleString()}</span>`);
    if (acParts.length > 0) {
      acEl.innerHTML = acParts.join('<br/>');
    } else {
      acEl.textContent = 'None';
    }
  }

  // ── Initial Fee Due Date & Cancellation Window ──
  const initFeeDueEl = el('crm-initial-fee-due');
  if (initFeeDueEl) {
    const rawDue = res.initial_fee_due_date || res.initialFeeDueDate || (res.initial_fee_deadline ? res.initial_fee_deadline.slice(0, 10) : null) || null;
    let dueStr = '—';
    if (rawDue) {
      try {
        const d = new Date(rawDue + (rawDue.includes('T') ? '' : 'T00:00:00'));
        dueStr = isNaN(d.getTime()) ? rawDue : d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
      } catch (e) {
        dueStr = rawDue;
      }
    }
    initFeeDueEl.textContent = dueStr;
  }

  const cancWinEl = el('crm-cancellation-window');
  if (cancWinEl) {
    cancWinEl.textContent = res.cancellation_window || res.cancellationWindow || '14 Days';
  }

  // ── Proposed Meeting Times ──
  const meetings = res.proposedMeetingTimes || res.proposed_meeting_times || res.meeting_times || [];
  if (meetings.length > 0) {
    el('crm-meetings-wrap').style.display = 'block';
    el('crm-meetings').innerHTML = meetings.map(mt => {
      const formattedText = formatMeetingTimeString(mt);
      return `<div style="display:flex; align-items:center; gap:10px; padding:8px 12px; background:var(--cp-bg2); border-radius:8px; border:1px solid var(--cp-border); font-size:13px;">
        <span style="color:var(--cp-text); font-weight:600;">${formattedText}</span>
      </div>`;
    }).join('');
  } else {
    el('crm-meetings-wrap').style.display = 'none';
  }

  // ── Items: fetch from reservation_items table ──
  const itemsContainer = el('crm-items');
  itemsContainer.innerHTML = '<div style="text-align:center;color:var(--cp-text-mid);padding:20px;">Loading items...</div>';

  try {
    const { data: riRows, error } = await window.supabaseClient
      .from('reservation_items')
      .select('name, cat, is_free, price, dynamic_price')
      .eq('reservation_id', resId);

    if (error) throw error;

    if (riRows && riRows.length > 0) {
      // Separate freebies from paid items, then group by category
      const paidItems = riRows.filter(i => !i.is_free);
      const freeItems = riRows.filter(i => i.is_free);

      // Group paid by category
      const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment'];
      const grouped = {};
      paidItems.forEach(i => {
        const c = (i.cat || 'other').toLowerCase();
        if (!grouped[c]) grouped[c] = [];
        grouped[c].push(i);
      });

      const isCustomPackage = !res.activePkgId && !res.active_pkg_id && (!res.packageOrigin || res.packageOrigin.toLowerCase().includes('custom') || String(res.pricingMode).toLowerCase().includes('item-based'));
      const savedPool = (Array.isArray(res.items) && res.items.length > 0)
        ? res.items
        : ((Array.isArray(res.custom_items) && res.custom_items.length > 0)
          ? res.custom_items
          : (Array.isArray(res.packageItems) ? res.packageItems : []));

      const hydrateItem = (it) => {
        const n = (it.name || '').toLowerCase().trim();
        const matched = savedPool.find(s => typeof s === 'object' && s && ((s.id && it.id && String(s.id) === String(it.id)) || (s.name || '').toLowerCase().trim() === n));
        if (matched && typeof matched === 'object') {
          if (matched.customPax) it.customPax = matched.customPax;
          if (matched.customQty) it.customQty = matched.customQty;
          if (matched.specifications) it.specifications = matched.specifications;
          if (matched.snapshotPrice) it.snapshotPrice = matched.snapshotPrice;
          if (matched.price && !it.price) it.price = matched.price;
        }
        return it;
      };

      paidItems.forEach(hydrateItem);
      freeItems.forEach(hydrateItem);

      let html = '';
      const crmPaxCount = parseInt(res.pax) || 50;
      catOrder.forEach(c => {
        if (grouped[c]) {
          html += _renderCrmItemGroup(_catLabel(c), grouped[c], false, isCustomPackage, crmPaxCount);
          delete grouped[c];
        }
      });
      Object.keys(grouped).forEach(c => {
        html += _renderCrmItemGroup(_catLabel(c), grouped[c], false, isCustomPackage, crmPaxCount);
      });

      if (freeItems.length > 0) {
        html += `<div style="position:relative;text-align:center;margin:8px 0;">
          <div style="position:absolute;top:50%;left:0;right:0;height:1px;background:rgba(196,154,60,0.3);"></div>
          <span style="position:relative;background:var(--cp-sidebar);padding:0 12px;color:var(--cp-gold);font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;">Freebies Included</span>
        </div>`;
        const freeGrouped = {};
        freeItems.forEach(i => {
          const c = (i.cat || 'other').toLowerCase();
          if (!freeGrouped[c]) freeGrouped[c] = [];
          freeGrouped[c].push(i);
        });
        catOrder.forEach(c => {
          if (freeGrouped[c]) { html += _renderCrmItemGroup(_catLabel(c), freeGrouped[c], true, isCustomPackage, crmPaxCount); delete freeGrouped[c]; }
        });
        Object.keys(freeGrouped).forEach(c => {
          html += _renderCrmItemGroup(_catLabel(c), freeGrouped[c], true, isCustomPackage, crmPaxCount);
        });
      }

      itemsContainer.innerHTML = html || '<div style="color:var(--cp-text-mid);font-size:13px;font-style:italic;">No categorized items found.</div>';

    } else {
      // Fallback to custom_items / items / packageItems array from the reservation doc itself
      const fallback = (Array.isArray(res.custom_items) && res.custom_items.length > 0)
        ? res.custom_items
        : ((Array.isArray(res.items) && res.items.length > 0)
          ? res.items
          : (res.packageItems || []));
      const isCustomPackage = !res.activePkgId && !res.active_pkg_id && (!res.packageOrigin || res.packageOrigin.toLowerCase().includes('custom') || String(res.pricingMode).toLowerCase().includes('item-based'));
      const pCount = parseInt(res.pax) || 50;

      if (fallback.length > 0) {
        const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment'];
        const grouped = {};
        const uncategorized = [];

        fallback.forEach(i => {
          const n = typeof i === 'string' ? i : (i.name || '');
          if (!n) return;
          const found = (typeof CAT !== 'undefined' ? CAT : []).find(c => c.name.toLowerCase() === n.toLowerCase());
          const c = (typeof i === 'object' && i.cat) ? i.cat.toLowerCase() : (found ? (found.cat || 'other').toLowerCase() : 'other');

          let itemObj = typeof i === 'object' ? { ...i } : { name: n };
          itemObj.name = n;
          itemObj.cat = c;
          if (found && !itemObj.price) itemObj.price = found.price;
          if (isCustomPackage) {
            itemObj.price = itemObj.snapshotPrice || itemObj.price || (found ? getDynamicPrice(itemObj, pCount) : 0);
          }

          if (c === 'other') {
            uncategorized.push(itemObj);
          } else {
            if (!grouped[c]) grouped[c] = [];
            grouped[c].push(itemObj);
          }
        });

        let html = '';
        catOrder.forEach(c => {
          if (grouped[c]) html += _renderCrmItemGroup(_catLabel(c), grouped[c], false, isCustomPackage, pCount);
        });
        if (uncategorized.length > 0) {
          html += _renderCrmItemGroup('Other Items', uncategorized, false, isCustomPackage, pCount);
        }
        itemsContainer.innerHTML = html;
      } else {
        itemsContainer.innerHTML = '<div style="color:var(--cp-text-mid);font-size:13px;font-style:italic;text-align:center;padding:20px;">No items found for this reservation.</div>';
      }
    }
  } catch (err) {
    console.error('Error fetching reservation_items:', err);
    itemsContainer.innerHTML = '<div style="color:#e74c3c;font-size:13px;text-align:center;padding:20px;">Could not load items. Please try again.</div>';
  }

  // ── Pricing summary panel ──
  const _pricingSection = document.getElementById('crm-pricing-section');
  const _pricingRows = document.getElementById('crm-pricing-rows');
  const _pricingTotal = document.getElementById('crm-pricing-total');
  if (_pricingSection && _pricingRows && _pricingTotal) {
    const _amt = parseFloat(String(res.amount || '0').replace(/[^0-9.]/g, '')) || 0;
    const _isMal = (typeof window.isReservationMalabon === 'function') ? window.isReservationMalabon(res) : false;
    let _otc = _isMal ? 0 : parseFloat(res.outOfTownCharge || 0);
    if (!_isMal && _otc <= 0 && _amt > 0) {
      _otc = Math.round(_amt * 0.05);
    }
    const _baseAmt = _otc > 0 && _amt >= _otc ? _amt - _otc : _amt;
    // Determine package type for label
    const _pkgOriginRaw = String(res.package_origin || res.packageOrigin || res.package_type || res.pricingMode || res.pricing_mode || '').toLowerCase();
    const _isMajorlySet = _pkgOriginRaw.includes('majorly') || _pkgOriginRaw.includes('tiered');
    const _isDynamic = _pkgOriginRaw.includes('dynamic') || _pkgOriginRaw.includes('per_head');
    let _rowsHtml = '';
    const _paxNum = parseInt(res.pax) || 0;
    if (_isMajorlySet) {
      const _paxLabel = _paxNum > 0 ? ` (${_paxNum} pax)` : '';
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--cp-text-mid);">Pricing Rule${_paxLabel}</span><span style="color:var(--cp-text);font-weight:600;">&#8369;${_baseAmt.toLocaleString()}</span></div>`;
    } else if (_isDynamic) {
      const _pph = parseFloat(res.price_per_head || res.pricePerHead) || (_paxNum > 0 ? Math.round(_baseAmt / _paxNum) : 0);
      const _dynLabel = _paxNum > 0 && _pph > 0
        ? `Pricing Rule (${_paxNum} pax &#8369;${_pph.toLocaleString()}/head)`
        : `Pricing Rule${_paxNum > 0 ? ` (${_paxNum} pax)` : ''}`;
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--cp-text-mid);">${_dynLabel}</span><span style="color:var(--cp-text);font-weight:600;">&#8369;${_baseAmt.toLocaleString()}</span></div>`;
    } else {
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--cp-text-mid);">Items Subtotal</span><span style="color:var(--cp-text);font-weight:600;">&#8369;${_baseAmt.toLocaleString()}</span></div>`;
    }
    // Out of town charge
    if (_otc > 0) {
      const _otcPct = _baseAmt > 0 ? Math.round((_otc / _baseAmt) * 100) : 0;
      const _otcLabel = _otcPct > 0 ? `Out of Town Charge (+${_otcPct}%)` : 'Out of Town Charge';
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--cp-gold);">${_otcLabel}</span><span style="color:var(--cp-gold);font-weight:600;">+&#8369;${_otc.toLocaleString()}</span></div>`;
    }
    // Service charge
    const _svcpRow = parseFloat(res.service_charge_pct || res.serviceChargePct || 0);
    const _svcAmtRow = _svcpRow > 0 ? Math.round(_baseAmt * (_svcpRow / 100)) : 0;
    if (_svcAmtRow > 0) {
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--cp-gold);">Service Charge (+${_svcpRow}%)</span><span style="color:var(--cp-gold);font-weight:600;">+&#8369;${_svcAmtRow.toLocaleString()}</span></div>`;
    }

    _pricingRows.innerHTML = _rowsHtml;
    _pricingTotal.textContent = '\u20B1' + _amt.toLocaleString();
    _pricingSection.style.display = 'block';

    // Store res on window so exportReservationQuotation can access it
    window._crmCurrentRes = res;
  }
};

window.closeCustomerResModal = function () {
  document.getElementById('customer-res-detail-overlay').classList.remove('on');
};

window.exportReservationQuotation = async function (targetRes) {
  const res = targetRes || window._crmCurrentRes;
  if (!res) return;

  const _totalAmt = parseFloat(String(res.amount || '0').replace(/[^0-9.]/g, '')) || 0;
  const _details = (typeof computePricingDetails === 'function')
    ? computePricingDetails(res, res.pax, _totalAmt)
    : null;

  const _isMal = (typeof window.isReservationMalabon === 'function') ? window.isReservationMalabon(res) : false;
  let _otc = _isMal ? 0 : parseFloat(res.outOfTownCharge || 0);
  if (_details && _details.otc !== undefined) {
    _otc = _details.otc;
  } else if (!_isMal && _otc <= 0 && _totalAmt > 0) {
    _otc = Math.round(_totalAmt * 0.05);
  }

  const _extraItemsAmt = _details ? (_details.extraItemsTotal || 0) : (parseFloat(res.additional_items_charge || res.additionalItemsCharge || 0) || 0);
  const _extraBreakdown = (_details && Array.isArray(_details.extraItemsBreakdown)) ? _details.extraItemsBreakdown : [];

  const _baseAmt = (_details && _details.basePrice > 0)
    ? _details.basePrice
    : ((_otc > 0 && _totalAmt >= _otc) ? (_totalAmt - _otc) : _totalAmt);
  const _pkgOriginRaw2 = String(res.package_origin || res.packageOrigin || res.package_type || res.pricingMode || res.pricing_mode || '').toLowerCase();
  const _isMajorlySet2 = _pkgOriginRaw2.includes('majorly') || _pkgOriginRaw2.includes('tiered');
  const _isDynamic2 = _pkgOriginRaw2.includes('dynamic') || _pkgOriginRaw2.includes('per_head');
  const _paxNum2 = parseInt(res.pax) || 0;

  // Build base row label
  let _baseRowLabel;
  if (_isMajorlySet2) {
    _baseRowLabel = _paxNum2 > 0 ? `Pricing Rule (${_paxNum2} pax)` : 'Pricing Rule';
  } else if (_isDynamic2) {
    const _pph2 = parseFloat(res.price_per_head || res.pricePerHead) || (_paxNum2 > 0 ? Math.round(_baseAmt / _paxNum2) : 0);
    _baseRowLabel = _paxNum2 > 0 && _pph2 > 0
      ? `Pricing Rule (${_paxNum2} pax &#8369;${_pph2.toLocaleString()}/head)`
      : `Pricing Rule${_paxNum2 > 0 ? ` (${_paxNum2} pax)` : ''}`;
  } else {
    _baseRowLabel = 'Items Subtotal';
  }

  const _svcpQuo = _details ? _details.serviceChargePct : parseFloat(res.service_charge_pct || res.serviceChargePct || 0);
  const _svcAmtQuo = _details ? _details.serviceChargeAmt : ((_svcpQuo > 0 && (_baseAmt + _extraItemsAmt) > 0) ? Math.round((_baseAmt + _extraItemsAmt) * (_svcpQuo / 100)) : 0);
  const _finalQuoTotal = (_details && _details.finalTotal > 0) ? _details.finalTotal : (_baseAmt + _extraItemsAmt + _otc + _svcAmtQuo);

  let pricingRowsHtml = `<tr><td style="padding:7px 0;color:#555;">${_baseRowLabel}</td><td style="padding:7px 0;text-align:right;color:#222;font-weight:600;">&#8369;${_baseAmt.toLocaleString()}</td></tr>`;
  if (_extraBreakdown.length > 0) {
    _extraBreakdown.forEach(ei => {
      pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Additional Item: ${ei.name}</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+&#8369;${ei.price.toLocaleString()}</td></tr>`;
    });
  } else if (_extraItemsAmt > 0) {
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Additional Package Items</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+&#8369;${_extraItemsAmt.toLocaleString()}</td></tr>`;
  }
  if (_otc > 0) {
    const _otcPct = _baseAmt > 0 ? Math.round((_otc / _baseAmt) * 100) : 0;
    const _otcLabel = _otcPct > 0 ? `Out of Town Charge (+${_otcPct}%)` : 'Out of Town Charge';
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">${_otcLabel}</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+&#8369;${_otc.toLocaleString()}</td></tr>`;
  }
  if (_svcAmtQuo > 0) {
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Service Charge (+${_svcpQuo}%)</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+&#8369;${_svcAmtQuo.toLocaleString()}</td></tr>`;
  }

  const rawDate = res.date || '';
  let niceDate = rawDate;
  if (rawDate) {
    const d = new Date(rawDate + 'T00:00:00');
    if (!isNaN(d)) niceDate = d.toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
  }

  const originMap = {
    'majorly set': 'Majority Set', 'majorly_set': 'Majority Set',
    'dynamically set': 'Dynamically Set', 'per_head': 'Dynamically Set',
    'custom': 'Custom Build', 'item-based': 'Custom Build'
  };
  const originLabel = originMap[res.packageOrigin || res.pricingMode] || 'Custom Build';

  // Event setup name
  const setupName = res.eventSetup || (res.eventSetupSlug ? ((window.EVENT_SETUPS || []).find(s => s.slug === res.eventSetupSlug)?.name || res.eventSetupSlug.replace(/_/g, ' ').toUpperCase()) : 'Complete Setup');

  // Build VIP string
  let vipStr = 'None';
  if (res.isVIP && res.vipCount > 0) vipStr = `${res.vipCount} VIP${res.vipCount > 1 ? 's' : ''} : ${res.vipService || 'Standard'}`;

  // Additional charges string
  const _addlQuoParts = [];
  if (_extraBreakdown.length > 0) {
    _extraBreakdown.forEach(ei => {
      _addlQuoParts.push(`${ei.name}: +\u20B1${ei.price.toLocaleString()}`);
    });
  } else if (_extraItemsAmt > 0) {
    _addlQuoParts.push(`Additional items: +\u20B1${_extraItemsAmt.toLocaleString()}`);
  }
  if (_otc > 0) _addlQuoParts.push(`Out of town charges: +\u20B1${_otc.toLocaleString()}`);
  if (_svcAmtQuo > 0) _addlQuoParts.push(`Service Charge (+${_svcpQuo}%): +\u20B1${_svcAmtQuo.toLocaleString()}`);
  let addlStr = _addlQuoParts.length > 0 ? _addlQuoParts.join(', ') : 'None';

  // Call time logic
  let callTimeStr = res.callTime || '';
  if (!callTimeStr) {
    const tf = res.time || res.timeframe || '';
    const sep = tf.toLowerCase().includes(' to ') ? / to /i : (tf.includes('-') ? /-/ : null);
    if (sep) { 
      const sp = tf.split(sep)[0].trim(); 
      if (sp) {
        // Quick 12-hour format helper
        const m = sp.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
        if (m) {
          let h = parseInt(m[1]), min = m[2], ap = m[3];
          if (!ap) { ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; }
          callTimeStr = `${h}:${min} ${ap.toUpperCase()} (same as start)`;
        } else {
          callTimeStr = sp + ' (same as start)'; 
        }
      }
    }
  }
  callTimeStr = callTimeStr || ':';

  // Venue
  const venueName = res.venueLocation || res.venue_location || ':';
  const venueAddr = res.venue || '';

  // Build items HTML : fetch from Supabase if targetRes was passed (Meeting tab)
  // or fall back to the already-rendered #crm-items DOM element.
  let itemsHtml = '';
  const resId = res.id || res.reservation_id || res.reservationId;

  const _crmEl = document.getElementById('crm-items');
  const _crmContent = _crmEl ? _crmEl.innerHTML : '';
  const _crmIsReady = _crmContent && !_crmContent.includes('Loading items') && !_crmContent.includes('text-align:center');

  const _richSource = (Array.isArray(res.items) && res.items.length > 0)
    ? res.items
    : ((Array.isArray(res.custom_items) && res.custom_items.length > 0) ? res.custom_items : null);

  if (_richSource && _richSource.length > 0) {
    const paidItems = _richSource.filter(i => !i.isFree && !i.is_free);
    const freeItems = _richSource.filter(i => i.isFree || i.is_free);
    const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment'];
    const _fmtGroup = (title, items) => {
      if (!items || !items.length) return '';
      const boxes = items.map(i => {
        const iName = typeof i === 'object' ? (i.name || '') : String(i);
        const iPrice = typeof i === 'object' ? (parseFloat(i.snapshotPrice || i.dynamic_price || i.price || 0) || 0) : 0;
        const iCustomPax = typeof i === 'object' ? (i.customPax || i.custom_pax || i.portion_pax || null) : null;
        const iSpecs = typeof i === 'object' ? (i.specifications || i.portion_specs || i.specs || '') : '';
        const isEquipment = (typeof i === 'object' && String(i.cat || '').toLowerCase() === 'equipment') || (title.toLowerCase() === 'equipment');
        const iEqQty = isEquipment && typeof i === 'object' ? (i.customQty != null ? i.customQty : (i.quantity != null ? i.quantity : (i.autoQty != null ? i.autoQty : 1))) : null;

        let priceHtml = '';
        if (iPrice > 0 && !i.is_free && !i.isFree) {
          priceHtml = `<div class="item-box-price">&#8369;${iPrice.toLocaleString()}</div>`;
        } else if (i.is_free || i.isFree) {
          priceHtml = `<div class="item-box-price" style="color:#10b981;">FREE</div>`;
        }

        let customHtml = '';
        const detailsList = [];
        if (iEqQty) detailsList.push(`<div style="font-weight:700; color:#444;">Quantity: ${iEqQty} pcs</div>`);
        if (iCustomPax) detailsList.push(`<div style="font-weight:700; color:#b8860b;">Custom: ${iCustomPax} pax</div>`);
        if (iSpecs) detailsList.push(`<div style="color:#666; font-style:italic;">Notes: "${esc(iSpecs)}"</div>`);
        if (detailsList.length > 0) {
          customHtml = `<div class="item-box-custom" style="margin-top:4px; padding-top:4px; border-top:1px dashed #e8e0d0; font-size:10px;">${detailsList.join('')}</div>`;
        }

        return `<div class="item-box"><div class="item-box-name">${esc(iName)}</div>${priceHtml}${customHtml}</div>`;
      }).join('');
      return `<div class="item-group"><div class="item-group-label">${title}</div><div class="item-boxes">${boxes}</div></div>`;
    };
    const grouped = {};
    paidItems.forEach(i => { const c = (i.cat || 'other').toLowerCase(); if (!grouped[c]) grouped[c] = []; grouped[c].push(i); });
    catOrder.forEach(c => { if (grouped[c]) { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), grouped[c]); delete grouped[c]; } });
    Object.keys(grouped).forEach(c => { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), grouped[c]); });
    if (freeItems.length > 0) {
      itemsHtml += `<div style="font-size:9px;font-weight:800;color:#b8860b;text-transform:uppercase;letter-spacing:1.2px;margin:12px 0 6px;">Freebies Included</div>`;
      const fg = {};
      freeItems.forEach(i => { const c = (i.cat || 'other').toLowerCase(); if (!fg[c]) fg[c] = []; fg[c].push(i); });
      catOrder.forEach(c => { if (fg[c]) { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), fg[c]); delete fg[c]; } });
      Object.keys(fg).forEach(c => { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), fg[c]); });
    }
  } else if (!targetRes && _crmIsReady) {
    // Normal flow: modal was open and items are already rendered
    itemsHtml = _crmContent;
  } else if (resId && window.supabaseClient) {
    // Meeting tab (or fallback): fetch reservation_items directly from Supabase
    try {
      const { data: riRows } = await window.supabaseClient
        .from('reservation_items')
        .select('name, cat, is_free, price, dynamic_price')
        .eq('reservation_id', resId);

      if (riRows && riRows.length > 0) {
        const paidItems = riRows.filter(i => !i.is_free);
        const freeItems = riRows.filter(i => i.is_free);
        const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment'];
        const _fmtGroup = (title, items) => {
          if (!items || !items.length) return '';
          const boxes = items.map(i => {
            const iName = typeof i === 'object' ? (i.name || '') : String(i);
            const iPrice = typeof i === 'object' ? (parseFloat(i.dynamic_price || i.price || 0) || 0) : 0;
            const iCustomPax = typeof i === 'object' ? (i.customPax || i.custom_pax || i.portion_pax || null) : null;
            const iSpecs = typeof i === 'object' ? (i.specifications || i.portion_specs || '') : '';
            
            let priceHtml = '';
            if (iPrice > 0 && !i.is_free && !i.isFree) {
              priceHtml = `<div class="item-box-price">&#8369;${iPrice.toLocaleString()}</div>`;
            } else if (i.is_free || i.isFree) {
              priceHtml = `<div class="item-box-price" style="color:#10b981;">FREE</div>`;
            }

            let customHtml = '';
            if (iCustomPax || iSpecs) {
              customHtml = `<div class="item-box-custom">${iCustomPax ? `Custom: ${iCustomPax} pax` : ''}${iCustomPax && iSpecs ? ' &bull; ' : ''}${iSpecs ? `<em>${iSpecs}</em>` : ''}</div>`;
            }

            return `<div class="item-box"><div class="item-box-name">${iName}</div>${priceHtml}${customHtml}</div>`;
          }).join('');
          return `<div class="item-group"><div class="item-group-label">${title}</div><div class="item-boxes">${boxes}</div></div>`;
        };
        const grouped = {};
        paidItems.forEach(i => { const c = (i.cat || 'other').toLowerCase(); if (!grouped[c]) grouped[c] = []; grouped[c].push(i); });
        catOrder.forEach(c => { if (grouped[c]) { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), grouped[c]); delete grouped[c]; } });
        Object.keys(grouped).forEach(c => { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), grouped[c]); });
        if (freeItems.length > 0) {
          itemsHtml += `<div style="font-size:9px;font-weight:800;color:#b8860b;text-transform:uppercase;letter-spacing:1.2px;margin:12px 0 6px;">Freebies Included</div>`;
          const fg = {};
          freeItems.forEach(i => { const c = (i.cat || 'other').toLowerCase(); if (!fg[c]) fg[c] = []; fg[c].push(i); });
          catOrder.forEach(c => { if (fg[c]) { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), fg[c]); delete fg[c]; } });
          Object.keys(fg).forEach(c => { itemsHtml += _fmtGroup(c.charAt(0).toUpperCase() + c.slice(1), fg[c]); });
        }
      }
    } catch (e) {
      console.error('exportReservationQuotation: failed to fetch reservation_items', e);
    }
  }

  // Final fallback: use res.packageItems array if available
  if (!itemsHtml) {
    if (res.packageItems && res.packageItems.length) {
      const boxes = res.packageItems.map(i => {
        const iName = typeof i === 'string' ? i : (i.name || '');
        const iPrice = typeof i === 'object' ? (parseFloat(i.price || 0) || 0) : 0;
        const iCustomPax = typeof i === 'object' ? (i.customPax || i.custom_pax || null) : null;
        const iSpecs = typeof i === 'object' ? (i.specifications || '') : '';
        const priceHtml = iPrice > 0 ? `<div class="item-box-price">&#8369;${iPrice.toLocaleString()}</div>` : '';
        const customHtml = (iCustomPax || iSpecs) ? `<div class="item-box-custom">${iCustomPax ? `Custom: ${iCustomPax} pax` : ''}${iCustomPax && iSpecs ? ' &bull; ' : ''}${iSpecs ? `<em>${iSpecs}</em>` : ''}</div>` : '';
        return `<div class="item-box"><div class="item-box-name">${iName}</div>${priceHtml}${customHtml}</div>`;
      }).join('');
      itemsHtml = `<div class="item-group"><div class="item-group-label">Included Items</div><div class="item-boxes">${boxes}</div></div>`;
    } else {
      itemsHtml = '<p style="color:#888;font-size:12px;font-style:italic;">No specific items listed.</p>';
    }
  }

  const generatedAt = new Date().toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  const w = window.open('', '_blank');
  if (!w) { alert('Please allow pop-ups to export the quotation.'); return; }
  w.document.write(`<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Quotation - ${res.packageName || 'Reservation'}</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap');
  body { font-family: 'Inter', Arial, sans-serif; background:#fff; color:#222; padding:0; }
  @page { margin:18mm 15mm; size:A4; }
  @media print { .no-print { display:none; } body { print-color-adjust:exact; -webkit-print-color-adjust:exact; } }
  .page { max-width:740px; margin:0 auto; padding:36px 40px; }
  .header { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:30px; padding-bottom:20px; border-bottom:2px solid #b8860b; }
  .header-brand { display:flex; flex-direction:column; gap:2px; }
  .brand-name { font-size:22px; font-weight:800; color:#b8860b; letter-spacing:1px; }
  .brand-sub  { font-size:11px; color:#888; font-weight:500; text-transform:uppercase; letter-spacing:1.5px; }
  .doc-title  { text-align:right; }
  .doc-title h1 { font-size:18px; font-weight:800; color:#222; text-transform:uppercase; letter-spacing:1.5px; }
  .doc-title .gen-date { font-size:10px; color:#999; margin-top:4px; }
  .pkg-header { margin-bottom:22px; }
  .pkg-origin { font-size:10px; font-weight:800; color:#b8860b; letter-spacing:1.5px; text-transform:uppercase; margin-bottom:5px; }
  .pkg-name   { font-size:24px; font-weight:800; color:#111; margin-bottom:4px; }
  .pkg-desc   { font-size:12px; color:#666; line-height:1.6; }
  .price-bar  { display:flex; justify-content:space-between; align-items:center; background:#fffbf0; border:1px solid #e8c96a; border-radius:10px; padding:14px 20px; margin-bottom:22px; }
  .price-amount { font-size:28px; font-weight:800; color:#b8860b; }
  .price-pax    { font-size:13px; color:#888; }
  .price-status { font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:1px; color:#b8860b; border:1px solid #b8860b; border-radius:5px; padding:4px 10px; }
  .section-title { font-size:10px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.5px; margin-bottom:10px; }
  .info-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px 20px; margin-bottom:22px; }
  .info-cell { border:1px solid #eee; border-radius:8px; padding:10px 14px; }
  .info-cell .lbl { font-size:9px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.2px; margin-bottom:3px; }
  .info-cell .val { font-size:13px; font-weight:600; color:#222; }
  .info-cell.full { grid-column:1/-1; }
  .divider { border:none; border-top:1px solid #eee; margin:18px 0; }
  .items-section { margin-bottom:22px; }
  .item-group { margin-bottom:14px; }
  .item-group-label { font-size:9px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.2px; margin-bottom:6px; }
  .item-boxes { display:grid; grid-template-columns:repeat(auto-fill, minmax(170px, 1fr)); gap:8px; }
  .item-box { border:1px solid #d4af37; background:#fffdfa; border-radius:6px; padding:8px 10px; font-size:11px; color:#222; display:flex; flex-direction:column; justify-content:space-between; }
  .item-box-name { font-weight:700; color:#111; line-height:1.3; margin-bottom:4px; }
  .item-box-price { font-size:11px; font-weight:800; color:#b8860b; }
  .item-box-custom { font-size:9.5px; color:#666; margin-top:3px; line-height:1.3; }
  .pricing-table { width:100%; border-collapse:collapse; margin-bottom:6px; font-size:13px; }
  .pricing-table td { padding:7px 4px; border-bottom:1px solid #f0f0f0; }
  .pricing-table tr:last-child td { border-bottom:none; }
  .total-row { display:flex; justify-content:space-between; align-items:center; background:#fffbf0; border:1px solid #e8c96a; border-radius:8px; padding:12px 16px; margin-top:10px; }
  .total-label { font-size:14px; font-weight:700; color:#222; }
  .total-value { font-size:22px; font-weight:800; color:#b8860b; }
  .footer { margin-top:36px; padding-top:16px; border-top:1px solid #eee; display:flex; justify-content:space-between; align-items:flex-end; }
  .footer-note { font-size:10px; color:#aaa; line-height:1.6; }
  .footer-sig { text-align:right; font-size:10px; color:#bbb; }
  .print-btn { display:inline-block; margin:20px auto; padding:11px 30px; background:#b8860b; color:#fff; border:none; border-radius:8px; font-size:14px; font-weight:700; cursor:pointer; letter-spacing:0.5px; }
</style>
</head>
<body>
<div class="page">
  <div class="header">
    <div class="header-brand">
      <div class="brand-name">Halden's</div>
      <div class="brand-sub">Catering Services</div>
    </div>
    <div class="doc-title">
      <h1>Quotation</h1>
      <div class="gen-date">Generated: ${generatedAt}</div>
    </div>
  </div>

  <div class="pkg-header">
    <div class="pkg-origin">${originLabel}</div>
    <div class="pkg-name">${res.packageName || 'Reservation'}</div>
    ${(res.premadePackageName || res.premade_package_name) ? `<div style="font-size:12px; color:#666; margin-bottom:4px;">Premade Package: <strong style="color:#b8860b;">${res.premadePackageName || res.premade_package_name}</strong></div>` : ''}
    <div class="pkg-desc">${res.description || res.desc || 'No description provided.'}</div>
  </div>

  <div class="price-bar">
    <div>
      <div class="price-amount">&#8369;${_finalQuoTotal.toLocaleString()}</div>
      <div class="price-pax">${res.pax ? res.pax + ' Pax' : ''}</div>
    </div>
    <div class="price-status">${(res.status || 'Pending').toUpperCase()}</div>
  </div>

  <div class="section-title">Event Details</div>
  <div class="info-grid">
    <div class="info-cell"><div class="lbl">Theme</div><div class="val">${res.theme || 'N/A'}</div></div>
    <div class="info-cell"><div class="lbl">Occasion</div><div class="val">${res.type || 'N/A'}</div></div>
    <div class="info-cell"><div class="lbl">Event Date</div><div class="val">${niceDate || ':'}</div></div>
    <div class="info-cell"><div class="lbl">Time Frame</div><div class="val">${res.time || res.timeframe || ':'}</div></div>
    <div class="info-cell"><div class="lbl">Call Time</div><div class="val">${callTimeStr}</div></div>
    <div class="info-cell"><div class="lbl">Guest Count</div><div class="val">${res.pax ? res.pax + ' Pax' : ':'}</div></div>
    <div class="info-cell"><div class="lbl">VIP Guests</div><div class="val">${vipStr}</div></div>
    <div class="info-cell"><div class="lbl">Additional Charges</div><div class="val">${addlStr}</div></div>
    <div class="info-cell full"><div class="lbl">Event Setup</div><div class="val" style="color:#b8860b; font-weight:700;">${setupName}</div></div>
    <div class="info-cell full"><div class="lbl">Venue</div><div class="val">${venueName}${venueAddr ? ' &mdash; ' + venueAddr : ''}</div></div>
  </div>

  <hr class="divider">
  <div class="section-title">Included in this Package</div>
  <div class="items-section">${itemsHtml}</div>

  <hr class="divider">
  <div class="section-title">Pricing Details</div>
  <table class="pricing-table">
    <tbody>${pricingRowsHtml}</tbody>
  </table>
  <div class="total-row">
    <span class="total-label">Total Amount</span>
    <span class="total-value">&#8369;${_finalQuoTotal.toLocaleString()}</span>
  </div>

  <div class="footer">
    <div class="footer-note">This quotation is generated by Halden's Catering Services.<br>For inquiries, please contact our team directly.</div>
    <div class="footer-sig">Halden's Catering Services<br>Authorized Quotation</div>
  </div>
</div>
<div class="no-print" style="text-align:center; padding:16px;">
  <button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
</div>
<script>window.onload=function(){ setTimeout(function(){ window.print(); }, 600); };<\/script>
</body>
</html>`);
  w.document.close();
};

window.exportMeetingReservationQuotation = async function (reservationId) {
  let targetId = (reservationId || '').trim();

  // If not explicitly provided, attempt to fallback to customer's active reservation in cache
  if (!targetId && window._profileResCache) {
    const cachedKeys = Object.keys(window._profileResCache);
    if (cachedKeys.length > 0) {
      targetId = cachedKeys[0];
    }
  }

  if (!targetId) {
    alert('No reservation attached to this meeting.');
    return;
  }

  // 1. Check local profile reservations cache first
  if (window._profileResCache && window._profileResCache[targetId]) {
    exportReservationQuotation(window._profileResCache[targetId]);
    return;
  }

  // 2. Check Supabase reservations table
  if (window.supabaseClient) {
    try {
      const { data, error } = await window.supabaseClient
        .from('reservations')
        .select('*')
        .eq('id', targetId)
        .maybeSingle();
      if (data) {
        exportReservationQuotation(data);
        return;
      }
    } catch (e) {
      console.warn('Supabase quotation fetch fallback:', e);
    }
  }

  // 3. Check Firebase reservations collection
  try {
    if (window.firebaseFns && window.firebaseDB) {
      const { doc, getDoc } = window.firebaseFns;
      const db = window.firebaseDB;
      const snap = await getDoc(doc(db, 'reservations', targetId));
      if (snap && snap.exists()) {
        const resData = { id: snap.id, ...snap.data() };
        exportReservationQuotation(resData);
        return;
      }
    }
  } catch (e) {
    console.error('Error exporting quotation for meeting reservation from Firebase:', e);
  }

  alert('Reservation record not found.');
};

// Delegated click handler for "Modify Reservation" buttons rendered inside reservations
document.addEventListener('click', function (e) {
  const btn = e.target.closest('.btn-modify-res');
  if (!btn) return;
  e.stopPropagation();
  const resId = btn.getAttribute('data-res-id');
  if (!resId || !window._profileResCache) return;
  const res = window._profileResCache[resId];
  if (!res) return;
  try {
    sessionStorage.setItem('halden_modify_res', JSON.stringify(res));
    window.location.href = 'index.html';
  } catch (err) {
    console.error('Modify reservation redirect error:', err);
  }
});

// ===== PAYMONGO: PAY AN EXISTING CONFIRMED RESERVATION =====
async function payReservation(resId, amountStr, type, date) {
  const btn = window.event?.target || null;
  if (btn) { btn.disabled = true; btn.textContent = ' Processing...'; }
  try {
    const amount = parseFloat((amountStr || '').replace(/[^0-9.]/g, '')) || 1;
    const returnUrl = `${window.location.origin}/customer.html`;
    const apiRes = await fetch('/api/paymongo', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        items: [{ name: `${type} - ${date}`, price: amount }],
        customerInfo: { name: currentUser?.displayName || 'Customer', email: currentUser?.email, type },
        reservationId: resId,
        returnUrl: returnUrl
      })
    });
    const data = await apiRes.json();
    if (data.checkout_url || data.url) {
      window.location.href = data.checkout_url || data.url;
    } else {
      throw new Error(data.error || 'Could not create payment session. Try again.');
    }
  } catch (e) {
    alert('Payment error: ' + e.message);
    if (btn) { btn.disabled = false; btn.textContent = 'Pay Now'; }
  }
}
window.payReservation = payReservation;

// Handle PayMongo redirect-back: ?payment=success&resId=xxx or ?payment=cancel
(async function handlePaymentReturn() {
  const params = new URLSearchParams(window.location.search);
  const payment = params.get('payment');
  let resId = params.get('resId');
  const type = params.get('type');
  let meetingId = params.get('meetingId');
  if (!payment) return;

  if (resId === 'undefined' || resId === 'null') resId = '';
  if (meetingId === 'undefined' || meetingId === 'null') meetingId = '';

  // 1. If on index.html (or root) and this is a meeting / portal payment, forward to customer.html immediately
  const isCustomerPage = window.location.pathname.endsWith('customer.html') || window.location.pathname.includes('customer');
  if (!isCustomerPage && (type === 'initial_fee' || type === 'cancellation_fee' || meetingId || resId)) {
    window.location.replace('customer.html' + window.location.search);
    return;
  }

  // 2. Clean URL without reload (preserving browser history cleanliness)
  try {
    window.history.replaceState({}, '', window.location.pathname);
  } catch (e) {}

  if (payment === 'success') {
    try {
      await new Promise(r => setTimeout(r, 600));  // wait for Supabase and Firebase clients to initialize
      const sb = window.supabaseClient;

      // Safe ID fallback: if resId or meetingId is missing, resolve from Supabase
      if (!resId && meetingId && sb) {
        try {
          const { data: mtRow } = await sb.from('meetings').select('reservation_id, reservationId').eq('id', meetingId).maybeSingle();
          if (mtRow) resId = mtRow.reservation_id || mtRow.reservationId || '';
        } catch (e) {}
      }
      if (resId && !meetingId && sb) {
        try {
          const { data: mtRow } = await sb.from('meetings').select('id').or(`reservation_id.eq.${resId},reservationId.eq.${resId}`).order('created_at', { ascending: false }).limit(1).maybeSingle();
          if (mtRow) meetingId = mtRow.id;
        } catch (e) {}
      }

      const now = new Date().toISOString();
      const refId = 'PAY-INIT-' + String(resId || meetingId || '000000').slice(-6).toUpperCase();

      let paymongoPaymentId = params.get('paymentId') || params.get('payment_id') || '';
      let sessionId = params.get('sessionId') || params.get('session_id') || '';
      if (!sessionId && resId) {
        try {
          sessionId = sessionStorage.getItem('paymongo_session_' + resId) || localStorage.getItem('paymongo_session_' + resId) || '';
        } catch (e) {}
      }

      let pmCheckResult = null;
      // Proactively verify with PayMongo API to retrieve actual payment ID and trigger server-side sync
      try {
        const checkUrl = `/api/paymongo?action=check&sessionId=${encodeURIComponent(sessionId || '')}&paymentId=${encodeURIComponent(paymongoPaymentId || '')}&resId=${encodeURIComponent(resId || '')}&type=${encodeURIComponent(type || '')}&amount=${encodeURIComponent(params.get('amount') || '')}`;
        const pmResp = await fetch(checkUrl);
        if (pmResp.ok) {
          pmCheckResult = await pmResp.json();
          if (pmCheckResult && pmCheckResult.paid) {
            if (pmCheckResult.paymentId) paymongoPaymentId = pmCheckResult.paymentId;
          }
        }
      } catch (checkErr) {
        console.warn('[handlePaymentReturn] /api/paymongo check error:', checkErr);
      }

      const mergeHist = (a, b) => {
        const combined = [...(Array.isArray(a) ? a : []), ...(Array.isArray(b) ? b : [])];
        const seen = new Set();
        return combined.filter(r => {
          if (!r || typeof r !== 'object') return false;
          if (String(r.id || '').includes('LEGACY') || r.ref_id === 'LEGACY' || r.notes === 'Prior payment') return false;
          const key = r.paymongo_payment_id || r.payment_id || r.id || r.ref_id || `${r.paid_at}_${r.amount_paid}`;
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      };

      // Case A: Initial Fee (Supports Full & Partial Payments with Stacking Receipts)
      if (type === 'initial_fee' || type === 'initial') {
        const amtParam = params.get('amount');
        const paidAmt = amtParam ? parseFloat(amtParam) : 5000;
        let curPm = {};
        let curRes = {};
        if (sb && resId) {
          try {
            const [pmSnap, resSnap] = await Promise.all([
              sb.from('reservation_payments').select('*').eq('reservation_id', resId).maybeSingle(),
              sb.from('reservations').select('*').eq('id', resId).maybeSingle()
            ]);
            if (pmSnap.data) curPm = pmSnap.data;
            if (resSnap.data) curRes = resSnap.data;
          } catch(e) {}
        }
        const prevReceived = parseFloat(curPm.initial_fee_received || curRes.initial_fee_received || 0);

        let initHistory = mergeHist(curPm.initial_fee_history, curRes.initial_fee_history);
        initHistory = initHistory.filter(r => !r.fee_type || r.fee_type === 'initial' || r.fee_type === 'initial_fee');

        const isAlreadyRecorded = (pmCheckResult && pmCheckResult.alreadyRecorded) ||
          (paymongoPaymentId && (
            initHistory.some(r => r.paymongo_payment_id === paymongoPaymentId || r.payment_id === paymongoPaymentId) ||
            curPm.paymongo_payment_id === paymongoPaymentId ||
            curRes.paymongo_payment_id === paymongoPaymentId
          ));

        const totalDue = 5000;
        let finalInitStatus = curPm.initial_fee_status || curRes.initial_fee_status || 'paid';
        let finalInitReceived = prevReceived || totalDue;
        let finalInitRemaining = Math.max(0, totalDue - finalInitReceived);

        if (!isAlreadyRecorded) {
          const newCumulative = prevReceived + paidAmt;
          const isPartial = newCumulative < totalDue;
          const remaining = Math.max(0, totalDue - newCumulative);
          const status = isPartial ? 'partial' : 'paid';
          finalInitStatus = status;
          finalInitReceived = newCumulative;
          finalInitRemaining = remaining;

          if (initHistory.length === 0 && prevReceived > 0 && prevReceived < totalDue) {
            initHistory.push({
              id: 'RCPT-INIT-LEGACY',
              fee_type: 'initial',
              amount_paid: prevReceived,
              amount_due: totalDue,
              balance_remaining: totalDue - prevReceived,
              change: 0,
              method: curPm.initial_fee_method || curRes.initial_fee_method || 'cash',
              ref_id: curRes.initial_fee_ref_id || 'LEGACY',
              paid_at: curPm.initial_fee_paid_at || now,
              received_by: curPm.initial_fee_received_by || 'Admin',
              status: 'partial',
              notes: 'Prior payment'
            });
          }
          const receiptItem = {
            id: 'RCPT-INIT-' + Date.now(),
            fee_type: 'initial',
            amount_paid: paidAmt,
            amount_due: totalDue - prevReceived,
            balance_remaining: remaining,
            change: 0,
            method: 'online',
            gateway: 'PayMongo',
            ref_id: refId,
            paymongo_payment_id: paymongoPaymentId || undefined,
            paid_at: now,
            received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ''}`,
            status: status,
            notes: isPartial ? 'Partial Initial Reservation Fee paid via PayMongo' : 'Initial Reservation Fee paid via PayMongo'
          };
          initHistory.push(receiptItem);
          let allHistory = mergeHist(curPm.payment_history, curRes.payment_history);
          allHistory.push(receiptItem);

          if (sb) {
            // 1. Update Supabase meetings table
            const mtUpdate = {
              initial_fee_status: status,
              initial_fee_method: 'online',
              initial_fee_received: newCumulative,
              initial_fee_change: 0,
              initial_fee_paid_at: now,
              initial_fee_received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ''}`,
              initial_fee_ref_id: paymongoPaymentId || refId,
              initial_fee_paymongo_id: paymongoPaymentId || null,
              paymongo_payment_id: paymongoPaymentId || null
            };
            if (meetingId) {
              const { error: mtErr } = await sb.from('meetings').update(mtUpdate).eq('id', meetingId);
              if (mtErr) console.error('[handlePaymentReturn] meetings update error:', mtErr);
            } else if (resId) {
              const { error: mtErr } = await sb.from('meetings').update(mtUpdate).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);
              if (mtErr) console.error('[handlePaymentReturn] meetings update error:', mtErr);
            }

            // 2. Update Supabase reservations table
            if (resId) {
              const { error: resErr } = await sb.from('reservations').update({
                initial_fee_status: status,
                initial_fee_paid: !isPartial,
                payment_status: status === 'paid' ? 'initial_paid' : 'partial',
                initial_fee_received: newCumulative,
                initial_fee_remaining: remaining,
                initial_fee_ref_id: paymongoPaymentId || refId,
                initial_fee_paymongo_id: paymongoPaymentId || null,
                initial_fee_history: initHistory,
                payment_history: allHistory,
                paymongo_payment_id: paymongoPaymentId || undefined,
                paymongo_payment_type: 'initial_fee',
                updated_at: now
              }).eq('id', resId);
              if (resErr) console.error('[handlePaymentReturn] reservations update error:', resErr);
            }

            // 3. Upsert into Supabase reservation_payments table
            if (resId) {
              const { error: pmErr } = await sb.from('reservation_payments').upsert({
                reservation_id: resId,
                initial_fee_amount: totalDue,
                initial_fee_status: status,
                initial_fee_method: 'online',
                initial_fee_received: newCumulative,
                initial_fee_remaining: remaining,
                initial_fee_change: 0,
                initial_fee_paid_at: now,
                initial_fee_received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ''}`,
                initial_fee_ref_id: paymongoPaymentId || refId,
                initial_fee_paymongo_id: paymongoPaymentId || null,
                initial_fee_history: initHistory,
                payment_history: allHistory,
                paymongo_payment_id: paymongoPaymentId || undefined,
                paymongo_payment_type: 'initial_fee',
                updated_at: now
              }, { onConflict: 'reservation_id' });
              if (pmErr) console.error('[handlePaymentReturn] reservation_payments upsert error:', pmErr);
            }
          }
        }

        // 4. Update Firestore documents if Firebase is active
        const { doc, updateDoc } = window.firebaseFns || {};
        if (doc && updateDoc && window.firebaseDB) {
          if (resId) {
            try {
              await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
                paymentStatus: finalInitStatus,
                paymentAmount: String(finalInitReceived),
                initial_fee_status: finalInitStatus,
                initialFeeStatus: finalInitStatus,
                initial_fee_method: 'online',
                initialFeeMethod: 'online',
                initial_fee_ref_id: curRes.initial_fee_ref_id || refId,
                initialFeeRefId: curRes.initial_fee_ref_id || refId,
                initial_fee_received: finalInitReceived,
                initial_fee_remaining: finalInitRemaining,
                initial_fee_history: initHistory,
                initial_fee_change: 0,
                initial_fee_paid_at: now,
                paidAt: now
              });
            } catch (fErr) {
              console.warn('[handlePaymentReturn] Firestore reservation update warning:', fErr);
            }
          }
          if (meetingId) {
            try {
              await updateDoc(doc(window.firebaseDB, 'meetings', meetingId), {
                initial_fee_status: finalInitStatus,
                initialFeeStatus: finalInitStatus,
                initial_fee_method: 'online',
                initialFeeMethod: 'online',
                initial_fee_received: finalInitReceived,
                initial_fee_change: 0,
                initial_fee_paid_at: now,
                initial_fee_ref_id: curRes.initial_fee_ref_id || refId,
                initialFeeRefId: curRes.initial_fee_ref_id || refId
              });
            } catch (fErr) {}
          }
        }

        // 5. Automatically reopen and synchronize the customer meeting room
        try {
          let targetMeeting = null;
          if (sb) {
            if (meetingId) {
              const { data: mtRow } = await sb.from('meetings').select('*').eq('id', meetingId).maybeSingle();
              targetMeeting = mtRow;
            }
            if (!targetMeeting && resId) {
              const { data: mtRow } = await sb.from('meetings').select('*').or(`reservation_id.eq.${resId},reservationId.eq.${resId}`).order('created_at', { ascending: false }).limit(1).maybeSingle();
              targetMeeting = mtRow;
            }
          }
          if (targetMeeting) {
            // Clear stale local fee paid cache so celebration modal can render
            if (targetMeeting.id) {
              localStorage.removeItem('fee_paid_' + targetMeeting.id);
            }
            const normMeeting = {
              ...targetMeeting,
              id: targetMeeting.id,
              reservationId: targetMeeting.reservation_id || targetMeeting.reservationId || resId,
              roomId: targetMeeting.room_id || targetMeeting.roomId,
              agenda: targetMeeting.agenda || targetMeeting.topic || 'Meeting',
              activeTab: targetMeeting.active_tab || targetMeeting.activeTab || 'res',
              notes: targetMeeting.meeting_notes || targetMeeting.notes || '',
              initialFeeStatus: finalInitStatus,
              initialFeeMethod: 'online',
              initial_fee_status: finalInitStatus,
              initial_fee_method: 'online',
              initial_fee_received: finalInitReceived,
              initial_fee_change: 0,
              initial_fee_paid_at: now,
              initial_fee_received_by: 'PayMongo Gateway',
              initial_fee_ref_id: curRes.initial_fee_ref_id || refId
            };
            if (typeof openCustomerMeetingHub === 'function') {
              await openCustomerMeetingHub(normMeeting);
            }
            if (typeof startMeetingRoomListener === 'function') {
              startMeetingRoomListener(targetMeeting.id);
            }
            if (typeof checkInitialFeeModal === 'function') {
              checkInitialFeeModal(normMeeting);
            }
          }
        } catch (mErr) {
          console.warn('[handlePaymentReturn] Could not restore meeting room:', mErr);
        }

      // Case B: Cancellation Fee Settlement
      } else if (type === 'cancellation_fee') {
        if (sb) {
          if (meetingId) {
            await sb.from('meetings').update({
              cancellation_fee_status: 'paid',
              cancellation_pay_triggered: false,
              cancellation_fee_paid_at: now,
              updated_at: now
            }).eq('id', meetingId);
          }
          if (resId) {
            await sb.from('reservations').update({
              cancellation_request_status: 'paid',
              cancellation_status: 'paid',
              updated_at: now
            }).eq('id', resId);
          }
        }

        // Reopen meeting if returning to meeting room
        try {
          if (sb && (meetingId || resId)) {
            let targetMeeting = null;
            if (meetingId) {
              const { data: mtRow } = await sb.from('meetings').select('*').eq('id', meetingId).maybeSingle();
              targetMeeting = mtRow;
            }
            if (!targetMeeting && resId) {
              const { data: mtRow } = await sb.from('meetings').select('*').or(`reservation_id.eq.${resId},reservationId.eq.${resId}`).order('created_at', { ascending: false }).limit(1).maybeSingle();
              targetMeeting = mtRow;
            }
            if (targetMeeting && typeof openCustomerMeetingHub === 'function') {
              await openCustomerMeetingHub(targetMeeting);
              if (typeof startMeetingRoomListener === 'function') {
                startMeetingRoomListener(targetMeeting.id);
              }
            }
          }
        } catch (cErr) {
          console.warn('[handlePaymentReturn] Could not restore cancellation meeting room:', cErr);
        }

      // Case C: Downpayment Online Payment via PayMongo (Supports Partial & Stacking)
      } else if (type === 'downpayment') {
        const amtPaid = parseFloat(params.get('amount')) || 0;
        const receiptRefId = 'PAY-DP-' + String(resId || '000000').slice(-6).toUpperCase() + '-' + Date.now().toString().slice(-4);

        if (sb && resId) {
          // Fetch existing payment data and reservation to calculate remaining balance & stack history
          const [resSnap, pmSnap] = await Promise.all([
            sb.from('reservations').select('*').eq('id', resId).maybeSingle(),
            sb.from('reservation_payments').select('*').eq('reservation_id', resId).maybeSingle()
          ]);
          const curRes = resSnap.data || {};
          const curPm = pmSnap.data || {};

          // Calculate downpayment total due (50% of base price)
          const totalAmt = parseFloat(curRes.amount || 0);
          const basePrice = parseFloat(curRes.basePrice || curRes.base_price || (totalAmt > 0 ? totalAmt * 0.95 : totalAmt));
          const dpTotalDue = Math.round(basePrice * 0.5) || parseFloat(curPm.downpayment_amount || curRes.downpaymentAmount || 0) || (amtPaid > 0 ? amtPaid : 0);

          const prevReceived = parseFloat(curPm.downpayment_received || curRes.downpayment_received || 0);

          // Retrieve and stack receipts in downpayment_history
          let dpHistory = mergeHist(curPm.downpayment_history, curRes.downpayment_history);
          dpHistory = dpHistory.filter(r => !r.fee_type || r.fee_type === 'downpayment' || r.fee_type === 'dp' || r.fee_type === 'down_payment');

          const isAlreadyRecorded = (pmCheckResult && pmCheckResult.alreadyRecorded) ||
            (paymongoPaymentId && (
              dpHistory.some(r => r.paymongo_payment_id === paymongoPaymentId || r.payment_id === paymongoPaymentId) ||
              curPm.paymongo_payment_id === paymongoPaymentId ||
              curRes.paymongo_payment_id === paymongoPaymentId
            ));

          let finalDpStatus = curPm.downpayment_status || curRes.downpayment_status || 'paid';
          let finalDpReceived = prevReceived || dpTotalDue;
          let finalDpRemaining = Math.max(0, dpTotalDue - finalDpReceived);

          if (!isAlreadyRecorded) {
            const newReceived = prevReceived + (amtPaid > 0 ? amtPaid : dpTotalDue);
            const remaining = Math.max(0, dpTotalDue - newReceived);
            const isSettled = remaining <= 0;

            if (dpHistory.length === 0 && prevReceived > 0 && prevReceived < dpTotalDue) {
              dpHistory.push({
                id: 'RCPT-DP-LEGACY',
                fee_type: 'downpayment',
                amount_paid: prevReceived,
                amount_due: dpTotalDue,
                balance_remaining: Math.max(0, dpTotalDue - prevReceived),
                change: 0,
                method: curPm.downpayment_method || curRes.downpayment_method || 'cash',
                ref_id: curRes.downpayment_ref_id || 'LEGACY',
                paid_at: curPm.downpayment_paid_at || now,
                received_by: curPm.downpayment_received_by || 'Admin',
                status: 'partial',
                notes: 'Prior payment'
              });
            }

            const newReceipt = {
              id: 'RCPT-DP-' + Date.now(),
              fee_type: 'downpayment',
              amount_paid: amtPaid > 0 ? amtPaid : dpTotalDue,
              amount_due: dpTotalDue,
              balance_remaining: remaining,
              change: 0,
              method: 'online',
              gateway: 'PayMongo',
              ref_id: receiptRefId,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paid_at: now,
              received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ' (Online)'}`,
              proof_url: null,
              status: isSettled ? 'paid' : 'partial',
              notes: isSettled ? 'Downpayment paid in full online via PayMongo' : 'Partial downpayment paid online via PayMongo'
            };
            dpHistory.push(newReceipt);

            let allHistory = mergeHist(curPm.payment_history, curRes.payment_history);
            allHistory.push(newReceipt);

            const dpStatus = isSettled ? 'paid' : 'partial';
            finalDpStatus = dpStatus;
            finalDpReceived = newReceived;
            finalDpRemaining = remaining;

            // Update Supabase reservations (clean columns without schema mismatch)
            await sb.from('reservations').update({
              downpayment_status: dpStatus,
              downpayment_method: 'online',
              downpayment_received: newReceived,
              downpayment_remaining: remaining,
              downpayment_paid_at: now,
              downpayment_ref_id: paymongoPaymentId || receiptRefId,
              downpayment_paymongo_id: paymongoPaymentId || null,
              downpayment_history: dpHistory,
              payment_history: allHistory,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paymongo_payment_type: 'downpayment',
              updated_at: now
            }).eq('id', resId);

            // Update Supabase reservation_payments
            const dpPayload = {
              reservation_id: resId,
              downpayment_amount: dpTotalDue,
              downpayment_status: dpStatus,
              downpayment_method: 'online',
              downpayment_received: newReceived,
              downpayment_remaining: remaining,
              downpayment_change: 0,
              downpayment_paid_at: now,
              downpayment_received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ' (Online)'}`,
              downpayment_ref_id: paymongoPaymentId || receiptRefId,
              downpayment_paymongo_id: paymongoPaymentId || null,
              downpayment_history: dpHistory,
              payment_history: allHistory,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paymongo_payment_type: 'downpayment',
              updated_at: now
            };
            const { error: pmUpdErr } = await sb.from('reservation_payments').update(dpPayload).eq('reservation_id', resId);
            if (pmUpdErr) {
              await sb.from('reservation_payments').upsert(dpPayload, { onConflict: 'reservation_id' });
            }

            // Update meetings
            await sb.from('meetings').update({
              downpayment_status: dpStatus,
              downpayment_method: 'online',
              downpayment_received: newReceived,
              downpayment_paid_at: now
            }).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);

            // Automated Email Notification for online downpayment
            const notifService = window.HalServeNotifications || window.SmartServeNotifications;
            if (notifService && typeof notifService.notifyPaymentMade === 'function') {
              const custEmail = (window.currentUser && window.currentUser.email) || curRes.email || curRes.client_email;
              const clientName = (window.currentUser && (window.currentUser.name || window.currentUser.full_name)) || curRes.client || curRes.client_name || 'Customer';
              notifService.notifyPaymentMade({
                customerEmail: custEmail,
                customerName: clientName,
                reservationId: resId,
                paymentType: `Downpayment${isSettled ? '' : ' (Partial Payment)'}`,
                amount: amtPaid > 0 ? amtPaid : dpTotalDue,
                paymentMethod: `PayMongo Online Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ''}`,
                referenceId: receiptRefId,
                transactionDate: new Date().toLocaleString('en-PH')
              });
            }
          }

          // Sync Firestore reservations for downpayment
          const { doc, updateDoc } = window.firebaseFns || {};
          if (doc && updateDoc && window.firebaseDB) {
            try {
              await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
                downpayment_status: finalDpStatus,
                downpaymentStatus: finalDpStatus,
                downpayment_method: 'online',
                downpaymentMethod: 'online',
                downpayment_received: finalDpReceived,
                downpayment_remaining: finalDpRemaining,
                downpayment_history: dpHistory,
                downpayment_paid_at: now
              });
            } catch (fErr) {}
          }

          try {
            sessionStorage.removeItem('paymongo_session_' + resId);
            localStorage.removeItem('paymongo_session_' + resId);
            sessionStorage.removeItem('paymongo_fee_type_' + resId);
            localStorage.removeItem('paymongo_fee_type_' + resId);
          } catch (e) {}
        }

      // Case D: Final Payment Online Payment via PayMongo (Supports Partial & Stacking)
      } else if (type === 'final_payment' || type === 'final') {
        const amtPaid = parseFloat(params.get('amount')) || 0;
        const receiptRefId = 'PAY-FINAL-' + String(resId || '000000').slice(-6).toUpperCase() + '-' + Date.now().toString().slice(-4);

        if (sb && resId) {
          const [resSnap, pmSnap] = await Promise.all([
            sb.from('reservations').select('*').eq('id', resId).maybeSingle(),
            sb.from('reservation_payments').select('*').eq('reservation_id', resId).maybeSingle()
          ]);
          const curRes = resSnap.data || {};
          const curPm = pmSnap.data || {};

          // Calculate final payment total due
          const totalAmt = parseFloat(curRes.amount || 0);
          const basePrice = parseFloat(curRes.basePrice || curRes.base_price || (totalAmt > 0 ? totalAmt * 0.95 : totalAmt));
          const dpPart = Math.round(basePrice * 0.5);
          const finalTotalDue = Math.max(0, totalAmt - dpPart) || parseFloat(curPm.final_payment_amount || curRes.finalPaymentAmount || 0) || (amtPaid > 0 ? amtPaid : 0);

          const prevReceived = parseFloat(curPm.final_received || curRes.final_received || 0);

          // Retrieve and stack receipts in final_history
          let finalHistory = mergeHist(curPm.final_history, curRes.final_history);
          finalHistory = finalHistory.filter(r => !r.fee_type || r.fee_type === 'final_payment' || r.fee_type === 'final' || r.fee_type === 'final_settlement');

          const isAlreadyRecorded = (pmCheckResult && pmCheckResult.alreadyRecorded) ||
            (paymongoPaymentId && (
              finalHistory.some(r => r.paymongo_payment_id === paymongoPaymentId || r.payment_id === paymongoPaymentId) ||
              curPm.paymongo_payment_id === paymongoPaymentId ||
              curRes.paymongo_payment_id === paymongoPaymentId
            ));

          let finalSt = curPm.final_payment_status || curRes.final_payment_status || 'paid';
          let finalRec = prevReceived || finalTotalDue;
          let finalRem = Math.max(0, finalTotalDue - finalRec);

          if (!isAlreadyRecorded) {
            const newReceived = prevReceived + (amtPaid > 0 ? amtPaid : finalTotalDue);
            const remaining = Math.max(0, finalTotalDue - newReceived);
            const isSettled = remaining <= 0;

            if (finalHistory.length === 0 && prevReceived > 0 && prevReceived < finalTotalDue) {
              finalHistory.push({
                id: 'RCPT-FINAL-LEGACY',
                fee_type: 'final_payment',
                amount_paid: prevReceived,
                amount_due: finalTotalDue,
                balance_remaining: Math.max(0, finalTotalDue - prevReceived),
                change: 0,
                method: curPm.final_method || curRes.final_method || 'cash',
                ref_id: curRes.final_ref_id || 'LEGACY',
                paid_at: curPm.final_paid_at || now,
                received_by: curPm.final_received_by || 'Admin',
                status: 'partial',
                notes: 'Prior payment'
              });
            }

            const newReceipt = {
              id: 'RCPT-FINAL-' + Date.now(),
              fee_type: 'final_payment',
              amount_paid: amtPaid > 0 ? amtPaid : finalTotalDue,
              amount_due: finalTotalDue,
              balance_remaining: remaining,
              change: 0,
              method: 'online',
              gateway: 'PayMongo',
              ref_id: receiptRefId,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paid_at: now,
              received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ' (Online)'}`,
              proof_url: null,
              status: isSettled ? 'paid' : 'partial',
              notes: isSettled ? 'Final payment settled in full online via PayMongo' : 'Partial final payment paid online via PayMongo'
            };
            finalHistory.push(newReceipt);

            let allHistory = mergeHist(curPm.payment_history, curRes.payment_history);
            allHistory.push(newReceipt);

            const finalStatus = isSettled ? 'paid' : 'partial';
            finalSt = finalStatus;
            finalRec = newReceived;
            finalRem = remaining;

            // Update Supabase reservations
            await sb.from('reservations').update({
              final_payment_status: finalStatus,
              settled: isSettled,
              final_received: newReceived,
              final_remaining: remaining,
              final_ref_id: paymongoPaymentId || receiptRefId,
              final_paymongo_id: paymongoPaymentId || null,
              final_history: finalHistory,
              payment_history: allHistory,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paymongo_payment_type: 'final_payment',
              updated_at: now
            }).eq('id', resId);

            // Update/Upsert Supabase reservation_payments
            const finalPayload = {
              reservation_id: resId,
              final_payment_amount: finalTotalDue,
              final_payment_status: finalStatus,
              final_method: 'online',
              final_received: newReceived,
              final_remaining: remaining,
              final_change: 0,
              final_paid_at: now,
              final_received_by: `PayMongo Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ' (Online)'}`,
              final_ref_id: paymongoPaymentId || receiptRefId,
              final_paymongo_id: paymongoPaymentId || null,
              final_history: finalHistory,
              payment_history: allHistory,
              paymongo_payment_id: paymongoPaymentId || undefined,
              paymongo_payment_type: 'final_payment',
              updated_at: now
            };
            const { error: pmUpdErr } = await sb.from('reservation_payments').update(finalPayload).eq('reservation_id', resId);
            if (pmUpdErr) {
              await sb.from('reservation_payments').upsert(finalPayload, { onConflict: 'reservation_id' });
            }

            // Update meetings
            await sb.from('meetings').update({
              final_payment_status: finalStatus,
              final_method: 'online',
              final_received: newReceived,
              final_paid_at: now
            }).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);

            // Automated Email Notification for online final payment
            const notifService = window.HalServeNotifications || window.SmartServeNotifications;
            if (notifService && typeof notifService.notifyPaymentMade === 'function') {
              const custEmail = (window.currentUser && window.currentUser.email) || curRes.email || curRes.client_email;
              const clientName = (window.currentUser && (window.currentUser.name || window.currentUser.full_name)) || curRes.client || curRes.client_name || 'Customer';
              notifService.notifyPaymentMade({
                customerEmail: custEmail,
                customerName: clientName,
                reservationId: resId,
                paymentType: `Final Payment${isSettled ? '' : ' (Partial Payment)'}`,
                amount: amtPaid > 0 ? amtPaid : finalTotalDue,
                paymentMethod: `PayMongo Online Gateway${paymongoPaymentId ? ' (' + paymongoPaymentId + ')' : ''}`,
                referenceId: receiptRefId,
                transactionDate: new Date().toLocaleString('en-PH')
              });
            }
          }

          // Sync Firestore reservations for final payment
          const { doc, updateDoc } = window.firebaseFns || {};
          if (doc && updateDoc && window.firebaseDB) {
            try {
              await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
                final_payment_status: finalSt,
                finalPaymentStatus: finalSt,
                settled: finalSt === 'paid',
                final_method: 'online',
                finalMethod: 'online',
                final_received: finalRec,
                final_remaining: finalRem,
                final_history: finalHistory,
                final_paid_at: now
              });
            } catch (fErr) {}
          }

          try {
            sessionStorage.removeItem('paymongo_session_' + resId);
            localStorage.removeItem('paymongo_session_' + resId);
            sessionStorage.removeItem('paymongo_fee_type_' + resId);
            localStorage.removeItem('paymongo_fee_type_' + resId);
          } catch (e) {}
        }

      // Case E: Standard Reservation Payment Fallback
      } else {
        if (sb && resId) {
          await sb.from('reservations').update({
            payment_status: 'paid',
            updated_at: now
          }).eq('id', resId);
        }
        const { doc, updateDoc } = window.firebaseFns || {};
        if (doc && updateDoc && window.firebaseDB && resId) {
          await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
            paymentStatus: 'paid',
            paidAt: now
          });
        }
      }
      // Re-render payments and reservation details tabs if currently visible
      if (typeof renderCustomerPayments === 'function') renderCustomerPayments();
      if (typeof renderPaymentTab === 'function') renderPaymentTab();
    } catch (e) {
      console.warn('[PayMongo return] Could not mark paid:', e);
    }

    // Show toast notification without emojis
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:999999;background:linear-gradient(135deg,#2d8a4e,#3aaa60);color:#fff;padding:14px 28px;border-radius:14px;font-family:Arial,sans-serif;font-size:14px;font-weight:700;box-shadow:0 8px 32px rgba(0,0,0,0.4);text-align:center;';
    toast.textContent = "Payment successful. Thank you for booking with Halden's Catering.";
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 6000);

  } else if (payment === 'cancel') {
    const fromSource = params.get('from') || params.get('source') || '';
    const tabParam = params.get('tab') || '';
    const isMeetingRoom = fromSource === 'meeting' || (meetingId && fromSource !== 'payments' && fromSource !== 'customer' && !tabParam);

    if (isMeetingRoom && (meetingId || resId)) {
      try {
        const sb = window.supabaseClient;
        if (sb) {
          let targetMeeting = null;
          if (meetingId) {
            const { data: mtRow } = await sb.from('meetings').select('*').eq('id', meetingId).maybeSingle();
            targetMeeting = mtRow;
          }
          if (!targetMeeting && resId) {
            const { data: mtRow } = await sb.from('meetings').select('*').or(`reservation_id.eq.${resId},reservationId.eq.${resId}`).order('created_at', { ascending: false }).limit(1).maybeSingle();
            targetMeeting = mtRow;
          }
          if (targetMeeting && typeof openCustomerMeetingHub === 'function') {
            await openCustomerMeetingHub(targetMeeting);
            if (typeof startMeetingRoomListener === 'function') {
              startMeetingRoomListener(targetMeeting.id);
            }
          }
        }
      } catch (cErr) {
        console.warn('[handlePaymentReturn] Cancel meeting reopen error:', cErr);
      }
      const toast = document.createElement('div');
      toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:999999;background:#1a1007;border:1px solid #c49a3c;color:#e8dcc8;padding:14px 28px;border-radius:14px;font-family:Arial,sans-serif;font-size:14px;font-weight:600;box-shadow:0 8px 32px rgba(0,0,0,0.4);text-align:center;';
      toast.textContent = 'Payment was cancelled. You have returned to the meeting room.';
      document.body.appendChild(toast);
      setTimeout(() => toast.remove(), 7000);
    } else {
      const targetTab = tabParam || (fromSource === 'payments' ? 'payments' : (fromSource || 'payments'));
      if (typeof switchDashTab === 'function') {
        setTimeout(() => switchDashTab(targetTab), 350);
      }
      const toast = document.createElement('div');
      toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:999999;background:#1a1007;border:1px solid #c49a3c;color:#e8dcc8;padding:14px 28px;border-radius:14px;font-family:Arial,sans-serif;font-size:14px;font-weight:600;box-shadow:0 8px 32px rgba(0,0,0,0.4);text-align:center;';
      toast.textContent = 'Payment was cancelled. You have returned to the ' + (targetTab === 'payments' ? 'payments tab' : 'dashboard') + '.';
      document.body.appendChild(toast);
      setTimeout(() => toast.remove(), 7000);
    }
  }
})();

let chatUnsubscribe = null;

function scrollChatToBottom() {
  const box = document.getElementById('customer-chat-box');
  if (box) setTimeout(() => box.scrollTop = box.scrollHeight, 100);
}

async function sendCustomerMsg() {
  const input = document.getElementById('cust-chat-input');
  const text = input.value.trim();
  if (!text || !currentUser) return;

  try {
    const { collection, addDoc } = window.firebaseFns;
    if (!currentUser.uid) throw new Error("User ID is missing. Please log out and back in.");

    await addDoc(collection(window.firebaseDB, 'messages'), {
      uid: currentUser.uid,
      userName: currentUser.displayName || 'Customer',
      userEmail: currentUser.email,
      text: text,
      sender: 'customer',
      timestamp: Date.now()
    });
    input.value = '';
    scrollChatToBottom();
  } catch (err) {
    console.error('Chat error:', err);
    alert("Could not send message: " + err.message);
  }
}
window.sendCustomerMsg = sendCustomerMsg;

function toggleNotifPanel() {
  const p = document.getElementById('dash-notif-panel');
  if (!p) return;
  p.classList.toggle('on');
  if (p.classList.contains('on')) {
    const badge = document.getElementById('dash-notif-badge');
    if (badge) badge.style.display = 'none';
  }
}
window.toggleNotifPanel = toggleNotifPanel;

async function listenToCustomerChat() {
  if (chatUnsubscribe) return; // already listening

  const { collection, query, where, onSnapshot, orderBy } = window.firebaseFns;
  const q = query(
    collection(window.firebaseDB, 'messages'),
    where('uid', '==', currentUser.uid),
    orderBy('timestamp', 'asc')
  );

  chatUnsubscribe = onSnapshot(q, (snap) => {
    const box = document.getElementById('customer-chat-box');
    if (!box) return;

    // Reset box but keep welcome if needed
    box.innerHTML = `
      <div class="chat-welcome">
        <div class="chat-ava">H</div>
        <p>Hello! How can we help you with your event planning today? </p>
      </div>
    `;

    snap.forEach(doc => {
      const msg = doc.data();
      const time = new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const wrap = document.createElement('div');
      wrap.className = `chat-bubble ${msg.sender}`;
      wrap.innerHTML = `
        <div class="chat-text">${escapeHTML(msg.text)}</div>
        <div class="chat-time">${time}</div>
      `;
      box.appendChild(wrap);
    });
    scrollChatToBottom();
  });
}

// ===== DESKTOP DRAGGABLE CAROUSEL =====
function initCarousel() {
  const container = document.getElementById('carousel-container');
  const track = document.getElementById('carousel-track');
  if (!container || !track) return;
  if (!track.dataset.cloned) {
    const items = Array.from(track.children);
    items.forEach(item => track.appendChild(item.cloneNode(true)));
    track.dataset.cloned = 'true';
  }
  if (container.dataset.carouselInit) return;
  container.dataset.carouselInit = 'true';

  let isDown = false, startX, scrollLeft, animationId;
  const scrollSpeed = 0.8;
  const startDrag = (e) => { isDown = true; container.style.cursor = 'grabbing'; startX = (e.pageX || e.touches?.[0]?.pageX || 0) - container.offsetLeft; scrollLeft = container.scrollLeft; cancelAnimationFrame(animationId); };
  const stopDrag = () => { isDown = false; container.style.cursor = 'grab'; startAutoScroll(); };
  const moveDrag = (e) => { if (!isDown) return; const x = (e.pageX || e.touches?.[0]?.pageX || 0) - container.offsetLeft; container.scrollLeft = scrollLeft - (x - startX) * 1.5; };
  container.addEventListener('mousedown', startDrag);
  container.addEventListener('mouseleave', stopDrag);
  container.addEventListener('mouseup', stopDrag);
  container.addEventListener('mousemove', moveDrag);
  container.addEventListener('touchstart', startDrag, { passive: true });
  container.addEventListener('touchend', stopDrag);
  container.addEventListener('touchmove', moveDrag, { passive: true });
  function startAutoScroll() {
    cancelAnimationFrame(animationId);
    function play() { container.scrollLeft += scrollSpeed; if (container.scrollLeft >= track.scrollWidth / 2) container.scrollLeft = 0; animationId = requestAnimationFrame(play); }
    animationId = requestAnimationFrame(play);
  }
  container.style.scrollBehavior = 'auto';
  startAutoScroll();
}

// ===== MOBILE HERO FIGMA-STYLE CAROUSEL =====
let _hmcInterval = null;
function initMobileHeroCarousel() {
  if (window.innerWidth > 768) return; // mobile only

  const track = document.getElementById('hmc-track');
  if (!track || !HERO_IMAGES.length) return;

  if (_hmcInterval) clearInterval(_hmcInterval);
  track.innerHTML = '';

  // Build items
  HERO_IMAGES.forEach((img, i) => {
    const el = document.createElement('div');
    el.className = 'hmc-item' + (i === 0 ? ' active' : '');
    el.style.backgroundImage = `url('${img.url}')`;
    track.appendChild(el);
  });

  let current = 0;

  function goTo(idx) {
    const items = track.querySelectorAll('.hmc-item');
    if (!items.length) return;
    items[current].classList.remove('active');
    current = (idx + items.length) % items.length;
    items[current].classList.add('active');

    // Center the active card in the viewport
    const screenW = window.innerWidth;
    const itemW = items[current].offsetWidth;
    // Each item is 52vw wide + 16px gap
    const itemStep = itemW + 16;
    // Translate so active card is centered
    const offset = (screenW / 2) - (current * itemStep) - (itemW / 2) - 20; // 20 = padding
    track.style.transform = `translateX(${offset}px)`;
  }

  // Initial position
  goTo(0);

  // Auto-advance every 10 seconds
  _hmcInterval = setInterval(() => goTo(current + 1), 10000);
}

// ===== MOBILE FADING SQUARE CAROUSEL (Moments section) =====
let _mfcInterval = null;
function initMobileFadeCarousel() {
  if (window.innerWidth > 768) return; // mobile only

  const container = document.getElementById('mob-fade-carousel');
  if (!container || !HERO_IMAGES.length) return;

  if (_mfcInterval) clearInterval(_mfcInterval);
  container.innerHTML = '';

  // Build slides + label
  HERO_IMAGES.forEach((img, i) => {
    const slide = document.createElement('div');
    slide.className = 'mfc-slide' + (i === 0 ? ' active' : '');
    slide.style.backgroundImage = `url('${img.url}')`;
    container.appendChild(slide);
  });

  // Single label element that updates
  const label = document.createElement('div');
  label.className = 'mfc-label';
  label.textContent = HERO_IMAGES[0].label;
  container.appendChild(label);

  let cur = 0;

  _mfcInterval = setInterval(() => {
    const slides = container.querySelectorAll('.mfc-slide');
    slides[cur].classList.remove('active');
    cur = (cur + 1) % slides.length;
    if (slides[cur]) slides[cur].classList.add('active');
    if (HERO_IMAGES[cur]) label.textContent = HERO_IMAGES[cur].label || '';
  }, 3500);
}

// ===== SUPABASE CAROUSEL PICTURES LOADER =====
async function loadCarouselPicturesFromSupabase() {
  const sb = window.supabaseClient || window.supabase;
  if (!sb) return;

  try {
    const { data, error } = await sb
      .from('carousel_pictures')
      .select('*')
      .order('sort_order', { ascending: true })
      .order('created_at', { ascending: true });

    if (error) {
      console.warn('[CarouselPictures] Could not fetch pictures from Supabase:', error.message);
      return;
    }

    if (data && data.length > 0) {
      HERO_IMAGES.length = 0;
      data.forEach(item => {
        HERO_IMAGES.push({
          url: item.image_url,
          label: item.label || ''
        });
      });

      // Update Desktop Carousel
      const track = document.getElementById('carousel-track');
      if (track) {
        track.innerHTML = HERO_IMAGES.map(img => `
          <div class="c-item">
            <div class="c-img" style="background: url('${img.url}') center/cover;">
              <p style="color:white;text-shadow:0 3px 8px rgba(0,0,0,0.9);margin-top:auto;margin-bottom:16px;">${img.label || ''}</p>
            </div>
          </div>
        `).join('');

        // Clone for seamless infinite scrolling
        const items = Array.from(track.children);
        items.forEach(item => track.appendChild(item.cloneNode(true)));
        track.dataset.cloned = 'true';
      }

      // Update Mobile Carousels
      if (window.innerWidth <= 768) {
        initMobileHeroCarousel();
        initMobileFadeCarousel();
      }
    }
  } catch (err) {
    console.warn('[CarouselPictures] Error loading from Supabase:', err);
  }
}
window.loadCarouselPicturesFromSupabase = loadCarouselPicturesFromSupabase;


// ===== SCROLL REVEAL =====
function initScrollReveal() {
  const reveals = document.querySelectorAll('.reveal');
  if (!reveals.length) return;
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) entry.target.classList.add('active');
      else entry.target.classList.remove('active');
    });
  }, { root: null, rootMargin: '0px', threshold: 0.02 });
  reveals.forEach(el => observer.observe(el));
}

// ===== CINEMATIC HERO SLIDER =====
const HERO_SLIDES_DATA = [
  { label: 'Grand Wedding Reception' },
  { label: 'Debut Celebrations' },
  { label: 'Elegant Dinner Setups' },
  { label: 'Milestone Birthdays' },
  { label: 'Corporate Events' }
];

let _heroIdx = 0;
let _heroTimer = null;
let _heroProgressTimer = null;
let _heroProgressStart = null;
const HERO_DURATION = 6000; // ms per slide

function initHeroSlider() {
  const slides = document.querySelectorAll('.hero-slide');
  if (!slides.length) return;

  // Assign alt Ken Burns to odd slides
  slides.forEach((s, i) => { if (i % 2 !== 0) s.classList.add('kb-alt'); });

  _heroGoToSlide(0);
}

function _heroGoToSlide(idx) {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  const label = document.getElementById('hero-hud-label');
  const counter = document.querySelector('.hero-counter-cur');

  // Remove active from all
  slides.forEach(s => {
    s.classList.remove('active');
    // Force restart Ken Burns by removing/re-adding
    s.style.animation = 'none';
  });
  dots.forEach(d => d.classList.remove('active'));

  _heroIdx = (idx + slides.length) % slides.length;

  // Activate chosen slide : force reflow to restart animation
  const active = slides[_heroIdx];
  void active.offsetWidth; // reflow
  active.style.animation = '';
  active.classList.add('active');

  if (dots[_heroIdx]) dots[_heroIdx].classList.add('active');
  if (label) label.textContent = HERO_SLIDES_DATA[_heroIdx]?.label || '';
  if (counter) counter.textContent = String(_heroIdx + 1).padStart(2, '0');

  _heroStartProgress();
  clearTimeout(_heroTimer);
  _heroTimer = setTimeout(() => _heroGoToSlide(_heroIdx + 1), HERO_DURATION);
}

function _heroStartProgress() {
  const bar = document.getElementById('hero-progress-fill');
  if (!bar) return;
  bar.style.transition = 'none';
  bar.style.width = '0%';
  void bar.offsetWidth;
  bar.style.transition = `width ${HERO_DURATION}ms linear`;
  bar.style.width = '100%';
}

function heroNav(dir) { _heroGoToSlide(_heroIdx + dir); }
function heroGoTo(idx) { _heroGoToSlide(idx); }
window.heroNav = heroNav;
window.heroGoTo = heroGoTo;

window.addEventListener('load', () => {
  setTimeout(initHeroSlider, 50);
  setTimeout(initMobileHeroCarousel, 80);   // mobile hero bg carousel
  setTimeout(initMobileFadeCarousel, 100);  // mobile moments square
  setTimeout(initCarousel, 100);            // desktop strip carousel
  setTimeout(initScrollReveal, 100);
});


