// ===== PUBLIC EVENT CALENDAR =====
let _publicCalendar = null;
let _publicCalInited = false;

function _normalizeDateKey(raw) {
  if (!raw) return null;
  if (typeof raw === 'object' && raw.seconds) {
    return new Date(raw.seconds * 1000).toISOString().split('T')[0];
  }
  const s = String(raw).trim();
  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  return null;
}

function _buildPublicCalendarEvents(reservations) {
  const events = [];
  const activeStatuses = ['confirmed', 'approved', 'pending', 'procurement', 'procuring', 'preparing', 'on-going', 'paid', 'downpayment_paid', 'initial_fee_paid', 'scheduled'];

  reservations.forEach(function (ev) {
    const status = String(ev.status || ev.reservation_status || '').toLowerCase().trim();
    const isAct = activeStatuses.includes(status) || ev.confirmed || ev.is_confirmed;
    const isDone = status === 'cancelled' || status === 'canceled' || status === 'rejected' || status === 'completed';
    if (!isAct || isDone) return;

    const eventDate = _normalizeDateKey(ev.date || ev.event_date || ev.reservation_date);
    if (!eventDate) return;

    let evStart = eventDate;
    let evEnd = null;
    let evAllDay = true;

    const evTf = ev.time || ev.timeframe || ev.reservation_time;
    if (evTf && typeof evTf === 'string' && evTf !== 'TBD') {
      function _parse24h(t) {
        if (!t) return null;
        t = String(t).trim();
        // Already HH:MM 24h
        if (/^\d{2}:\d{2}$/.test(t)) return t;
        // 12h AM/PM
        const m = t.match(/(\d{1,2}):(\d{2})\s*(AM|PM|am|pm)?/i);
        if (!m) return null;
        let h = parseInt(m[1], 10);
        const min = m[2];
        const period = (m[3] || '').toUpperCase();
        if (period === 'PM' && h < 12) h += 12;
        if (period === 'AM' && h === 12) h = 0;
        return String(h).padStart(2, '0') + ':' + min;
      }
      const sep = evTf.includes(' - ') ? ' - ' : (evTf.includes(' - ') ? ' - ' : null) || (evTf.match(/ ?- ?/) ? evTf.match(/ ?- ?/)[0] : null);
      if (sep && evTf.includes(sep)) {
        const parts = evTf.split(sep).map(x => x.trim());
        const t1 = _parse24h(parts[0]);
        if (t1) {
          evStart = eventDate + 'T' + t1 + ':00';
          evAllDay = false;
        }
        const t2 = _parse24h(parts[1]);
        if (t2 && t2 !== t1) {
          evEnd = eventDate + 'T' + t2 + ':00';
        }
      } else {
        const t1 = _parse24h(evTf);
        if (t1) {
          evStart = eventDate + 'T' + t1 + ':00';
          evAllDay = false;
        }
      }
    }

    const evObj = {
      id: ev.id,
      title: 'Reserved',
      start: eventDate,
      allDay: true,
      color: '#eab308',
      backgroundColor: '#eab308',
      borderColor: '#eab308',
      textColor: '#ffffff',
      extendedProps: { type: 'event', eventType: ev.type || ev.occasion || 'Private Event', pax: ev.pax || ev.guest_count, status: ev.status }
    };
    
    events.push(evObj);
  });
  return events;
}

function _renderPublicSidebar(reservations) {
  const container = document.getElementById('ev-cal-event-list');
  if (!container) return;

  const activeStatuses = ['confirmed', 'approved', 'pending', 'procurement', 'procuring', 'preparing', 'on-going', 'paid', 'downpayment_paid', 'initial_fee_paid', 'scheduled'];
  const today = new Date().toISOString().split('T')[0];

  const upcoming = reservations
    .filter(r => {
      const status = String(r.status || r.reservation_status || '').toLowerCase().trim();
      const isAct = activeStatuses.includes(status) || r.confirmed || r.is_confirmed;
      const isDone = status === 'cancelled' || status === 'canceled' || status === 'rejected' || status === 'completed';
      const dKey = _normalizeDateKey(r.date || r.event_date || r.reservation_date);
      return isAct && !isDone && dKey && dKey >= today;
    })
    .sort((a, b) => (_normalizeDateKey(a.date || a.event_date) || '').localeCompare(_normalizeDateKey(b.date || b.event_date) || ''))
    .slice(0, 12);

  if (!upcoming.length) {
    container.innerHTML = '<div class="ev-cal-empty">No upcoming events scheduled yet.</div>';
    return;
  }

  container.innerHTML = upcoming.map(r => {
    const dateStr = _normalizeDateKey(r.date || r.event_date || r.reservation_date);
    const d = dateStr ? new Date(dateStr + 'T00:00:00') : null;
    const dayNum = d ? d.getDate() : '?';
    const monStr = d ? d.toLocaleString('en-US', { month: 'short' }).toUpperCase() : '';
    const rawStatus = String(r.status || 'Confirmed');
    const statusClass = rawStatus.toLowerCase().includes('confirm') || rawStatus.toLowerCase().includes('approve') ? 'confirmed' : 'preparing';
    const statusLabel = rawStatus.charAt(0).toUpperCase() + rawStatus.slice(1);

    return `
      <div class="ev-cal-event-card">
        <div class="ev-cal-event-date-box">
          <div class="ev-cal-date-day">${dayNum}</div>
          <div class="ev-cal-date-mon">${monStr}</div>
        </div>
        <div class="ev-cal-event-info">
          <div class="ev-cal-event-type">${r.type || r.occasion || 'Private Event'}</div>
          <div class="ev-cal-event-meta">${r.pax || r.guest_count || ':'} pax</div>
          <div class="ev-cal-event-status ${statusClass}">${statusLabel}</div>
        </div>
      </div>`;
  }).join('');
}

async function initPublicCalendar(forceRefresh = false) {
  const el = document.getElementById('public-calendar');
  if (!el) return;

  if (_publicCalInited && !forceRefresh) {
    if (_publicCalendar) _publicCalendar.render();
    return;
  }

  // Load reservations from Local Cache + Supabase + Firestore + window.RESERVATIONS
  const resMap = new Map();

  // 0. Local Storage Cache (instant load regardless of auth permissions)
  try {
    const cached = localStorage.getItem('halden_public_calendar_cache');
    if (cached) {
      const parsed = JSON.parse(cached);
      if (Array.isArray(parsed)) {
        parsed.forEach(item => {
          if (item && item.id) resMap.set(String(item.id), item);
        });
      }
    }
  } catch (e) { }

  // 1. Supabase Unauthenticated Anon Fetch (Bypasses user-scoped JWT RLS to fetch all public confirmed reservations)
  try {
    let sbAnon = null;
    if (window.supabase && typeof SUPABASE_URL !== 'undefined' && typeof SUPABASE_ANON !== 'undefined') {
      sbAnon = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON);
    } else {
      sbAnon = window.supabaseClient || window.supabase;
    }

    if (sbAnon) {
      const { data: sbData, error: sbErr } = await sbAnon.from('reservations').select('*');
      if (!sbErr && sbData && sbData.length) {
        sbData.forEach(item => {
          if (item && item.id) {
            const existing = resMap.get(String(item.id)) || {};
            resMap.set(String(item.id), { ...existing, ...item });
          }
        });
      }
    }
  } catch (e) {
    console.warn('Public calendar: Supabase anon fetch failed', e);
  }

  // 3. User's own reservations cache & profile cache
  if (Array.isArray(window.RESERVATIONS)) {
    window.RESERVATIONS.forEach(item => {
      if (item && item.id) {
        const existing = resMap.get(String(item.id)) || {};
        resMap.set(String(item.id), { ...existing, ...item });
      }
    });
  }
  if (window._profileResCache) {
    Object.values(window._profileResCache).forEach(item => {
      if (item && item.id) {
        const existing = resMap.get(String(item.id)) || {};
        resMap.set(String(item.id), { ...existing, ...item });
      }
    });
  }

  const reservations = Array.from(resMap.values());

  // Update local cache so future renders never drop confirmed events
  try {
    if (reservations.length > 0) {
      localStorage.setItem('halden_public_calendar_cache', JSON.stringify(reservations));
    }
  } catch (e) { }

  const calEvents = _buildPublicCalendarEvents(reservations);
  _renderPublicSidebar(reservations);

  if (_publicCalendar) {
    _publicCalendar.removeAllEvents();
    _publicCalendar.addEventSource(calEvents);
    _publicCalendar.render();
  } else {
    _publicCalendar = new FullCalendar.Calendar(el, {
      initialView: 'dayGridMonth',
      headerToolbar: {
        left: 'prev',
        center: 'title',
        right: 'next'
      },
      eventTimeFormat: {
        hour: 'numeric',
        minute: '2-digit',
        meridiem: 'short'
      },
      displayEventEnd: true,
      height: 'auto',
      contentHeight: 'auto',
      expandRows: true,
      handleWindowResize: true,
      events: calEvents,
      eventContent: function (info) {
        return {
          html: '<div class="ev-cal-reserved-pill">Reserved</div>'
        };
      },
      eventDidMount: function (info) {
        if (info.event.extendedProps.type === 'event') {
          info.el.title = (info.event.extendedProps.eventType || 'Event') + ' : ' + (info.event.extendedProps.pax || '') + ' pax';
        } else {
          info.el.title = 'Preparation in progress';
        }
      },
      eventClick: function (info) { info.jsEvent.preventDefault(); }
    });
    _publicCalendar.render();
    setTimeout(() => { if (_publicCalendar) _publicCalendar.updateSize(); }, 150);
  }
  _publicCalInited = true;
  if (!window._publicCalResizeAttached) {
    window._publicCalResizeAttached = true;
    window.addEventListener('resize', () => {
      if (_publicCalendar) _publicCalendar.updateSize();
    });
  }
}

window.initPublicCalendar = initPublicCalendar;

// ===== INITIAL RENDER =====
window.addEventListener('DOMContentLoaded', () => {
  // If on customer dashboard page, skip the index-only initialization
  if (window.CUSTOMER_PAGE) {
    return;
  }

  // IMMEDIATE session restore : check localStorage before Firebase even loads.
  // If the user was logged in, show their dashboard right away.
  const wasLoggedIn = localStorage.getItem('halden_logged_in') === 'true';
  const isAdmin = localStorage.getItem('halden_user_type') === 'admin';
  const isStaff = localStorage.getItem('halden_user_type') === 'staff';

  if (wasLoggedIn && !isAdmin && !isStaff) {
    // Hide splash immediately : don't let it flash
    const splash = document.getElementById('authPromptModal');
    if (splash) { splash.classList.add('hidden'); splash.style.display = 'none'; }
  } else {
    // Not logged in : run the normal splash check
    checkAuthPrompt();
  }

  renderPkgs();
  renderFullCatalog();
  renderCat();
  renderCustomPkg();
  renderCart();
  initAI('desk');

  // Safe event listener : guard against element not existing
  const mobFab = document.getElementById('mob-ai-fab');
  if (mobFab) mobFab.addEventListener('click', () => { setTimeout(() => initAI('mob'), 50); });

  // Lazy-init the public calendar when it scrolls into view
  const calSection = document.getElementById('event-calendar');
  if (calSection && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          initPublicCalendar();
          observer.unobserve(calSection);
        }
      });
    }, { rootMargin: '200px' });
    observer.observe(calSection);
  }
});



// ===== CUSTOMER MEETING & PAYMENT LOGIC =====
let custCalendar = null;
let activePaymentResId = null;

function renderCustomerCalendar() {
  const el = document.getElementById('customer-calendar');
  if (!el) return;
  if (custCalendar) {
    custCalendar.destroy();
    custCalendar = null;
  }

  custCalendar = new FullCalendar.Calendar(el, {
    initialView: 'dayGridMonth',
    headerToolbar: { left: 'prev,next', center: 'title', right: '' },
    displayEventTime: false,
    height: 'auto',
    events: async function (info, successCallback, failureCallback) {
      try {
        const { collection, getDocs, query, where } = window.firebaseFns;
        const db = window.firebaseDB;

        // Same helper used in admin.js : converts "Jul 31, 2026" or any format to "2026-07-31"
        function normalizeDateKey(dateStr) {
          if (!dateStr) return dateStr;
          if (typeof dateStr === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return dateStr;
          const d = new Date(dateStr);
          if (isNaN(d.getTime())) return dateStr;
          const y = d.getFullYear();
          const m = String(d.getMonth() + 1).padStart(2, '0');
          const day = String(d.getDate()).padStart(2, '0');
          return `${y}-${m}-${day}`;
        }

        // Reservations
        const resSnap = await getDocs(query(collection(db, 'reservations'), where('email', '==', currentUser.email)));
        const userResIds = (resSnap.docs || []).map(r => r.id);

        // Safe Meetings Fetch
        let mtDocs = [];
        try {
          const sb = window.supabaseClient;
          let fetchedMeetings = new Map();

          if (userResIds.length > 0 && sb) {
            try {
              const { data } = await sb.from('meetings').select('*').in('reservation_id', userResIds);
              (data || []).forEach(m => fetchedMeetings.set(m.id, window.firebaseFns.mapFromDB ? window.firebaseFns.mapFromDB('meetings', m) : m));
            } catch (e) {}
          }
          if (sb) {
            try {
              const { data } = await sb.from('meetings').select('*');
              (data || []).forEach(m => {
                const mapped = window.firebaseFns.mapFromDB ? window.firebaseFns.mapFromDB('meetings', m) : m;
                const rId = mapped.reservationId || mapped.reservation_id;
                const matchesRes = rId && userResIds.includes(rId);
                const matchesEmail = currentUser.email && (
                  (mapped.customerEmail && mapped.customerEmail.toLowerCase() === currentUser.email.toLowerCase()) ||
                  (mapped.customer_email && mapped.customer_email.toLowerCase() === currentUser.email.toLowerCase())
                );
                if (matchesRes || matchesEmail) {
                  fetchedMeetings.set(mapped.id, mapped);
                }
              });
            } catch (e) {}
          }
          mtDocs = Array.from(fetchedMeetings.values());
        } catch (e) { console.warn('Calendar meetings fetch error:', e); }

        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const day = String(now.getDate()).padStart(2, '0');
        const todayStr = `${year}-${month}-${day}`;
        const currentMinutes = now.getHours() * 60 + now.getMinutes();

        const mtEvents = mtDocs
          .filter(data => {
            const s = (data.status || '').toLowerCase();
            if (['rejected', 'expired', 'completed', 'done'].includes(s)) return false;
            if (!data.date || data.date === 'TBD') return false;
            if (data.date < todayStr) return false; // Hide meetings from past days

            const parentRes = resSnap.docs.find(r => r.id === (data.reservationId || data.reservation_id));
            if (parentRes) {
              const pData = parentRes.data();
              const pStatus = (pData.status || '').toLowerCase();
              const pCancelStatus = String(pData.cancellation_status || pData.cancellationStatus || '').toLowerCase();
              const isCancelledRes = (pStatus === 'cancelled' || pCancelStatus === 'cancelled');
              const isUnresolvedRes = (pStatus === 'unresolved' || pCancelStatus === 'unresolved');
              const dpPaid = (pData.downpayment_status === 'paid' || pData.downpaymentStatus === 'paid' || pData.downpayment_paid === true);
              const finalPaid = (pData.final_payment_status === 'paid' || pData.finalPaymentStatus === 'paid' || pData.settled === true);
              const hasPendingBal = (!dpPaid || !finalPaid);
              const isEligibleCancelled = isCancelledRes && (hasPendingBal || !isUnresolvedRes);
              if (!isEligibleCancelled && (pStatus === 'cancelled' || pStatus === 'rejected')) return false;
            } else if (s === 'cancelled') {
              return false;
            }
            return true;
          })
          .map(data => {
            // Display only the meeting time range in 1-12 AM/PM format without agenda name
            const timeStr = _fmtTimeRange(data.time || '10:00', data.timeEnd || data.time_end);
            return {
              title: timeStr,
              start: `${data.date}T${data.time || '10:00:00'}`,
              color: 'var(--gold)',
              textColor: (document.documentElement.getAttribute('data-theme') === 'dark') ? '#ffffff' : '#1a1008'
            };
          });

        function getReservationPrepStartDate(res) {
          const eventDate = normalizeDateKey(res.date);
          if (!eventDate) return eventDate;
          const eventObj = new Date(eventDate + 'T00:00:00');
          if (isNaN(eventObj.getTime())) return eventDate;

          const minPrepObj = new Date(eventObj);
          minPrepObj.setDate(minPrepObj.getDate() - 7);

          const rawSubmitted = res.submittedDate || res.createdAt || res.requestedAt || res.bookedAt;
          const submitted = rawSubmitted ? normalizeDateKey(rawSubmitted) : null;
          if (submitted) {
            const submittedObj = new Date(submitted + 'T00:00:00');
            if (!isNaN(submittedObj.getTime()) && submittedObj < eventObj) {
              return (submittedObj > minPrepObj ? submittedObj : minPrepObj).toISOString().split('T')[0];
            }
          }
          return eventDate;
        }

        const resEvents = [];
        resSnap.docs.forEach(d => {
          const ev = { id: d.id, ...d.data() };
          if ((ev.status || '').toLowerCase() !== 'confirmed') return;

          const eventDate = normalizeDateKey(ev.date);
          if (!eventDate) return; // skip if date can't be parsed
          const prepStart = getReservationPrepStartDate(ev);

          if (prepStart && prepStart !== eventDate) {
            resEvents.push({
              title: '',
              start: prepStart,
              end: eventDate,
              allDay: true,
              color: '#d35400',
              textColor: '#fff',
              className: 'prep-event'
            });
          }
          resEvents.push({
            title: `Event: ${ev.packageName || ev.eventType || ev.type || 'Reservation'}`,
            start: eventDate,
            color: '#d35400',
            textColor: '#fff'
          });
        });

        successCallback([...mtEvents, ...resEvents]);
      } catch (e) { failureCallback(e); }
    }
  });
  custCalendar.render();
}

async function renderCustomerMeetings() {
  const container = document.getElementById('customer-meetings-list');
  if (!container) return;

  // Show placeholder immediately
  container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-dim); font-size:13px;">Loading your meetings...</div>';
  setTimeout(initOfficeMap, 100);

  try {
    const user = window.auth?.currentUser || JSON.parse(localStorage.getItem('halden_customer') || 'null');
    if (!user) { container.innerHTML = '<div class="cp-res-empty">Please log in to view meetings.</div>'; return; }

    const sb = window.supabaseClient;
    const { updateDoc, doc } = window.firebaseFns;
    const db = window.firebaseDB;

    let userEmail = (user.email || '').toLowerCase().trim();
    let userId = user.uid || user.id || '';
    let userName = (user.displayName || user.name || '').toLowerCase().trim();

    if ((!userEmail || !userId) && sb) {
      try {
        const authUser = (await sb.auth.getUser())?.data?.user;
        if (authUser) {
          if (!userId) userId = authUser.id;
          if (!userEmail) userEmail = (authUser.email || '').toLowerCase().trim();
          if (!userName) userName = (authUser.user_metadata?.full_name || '').toLowerCase().trim();
        }
      } catch (e) {}
    }

    const fetchAndRender = async () => {
      try {
        const customerResMap = new Map();

        // 1. Fetch customer reservations
        if (sb) {
          if (userEmail) {
            try {
              const { data: r1 } = await sb.from('reservations').select('*').ilike('client_email', userEmail);
              (r1 || []).forEach(r => customerResMap.set(r.id, r));
            } catch (e) {}
          }
          if (userId) {
            try {
              const { data: r2 } = await sb.from('reservations').select('*').eq('user_id', userId);
              (r2 || []).forEach(r => customerResMap.set(r.id, r));
            } catch (e) {}
          }
        }

        const userResIds = Array.from(customerResMap.keys());

        // 2. Fetch customer meetings safely
        const fetchedMeetings = new Map();
        if (sb) {
          if (userResIds.length > 0) {
            try {
              const { data: m1, error: e1 } = await sb.from('meetings').select('*').in('reservation_id', userResIds);
              if (!e1 && Array.isArray(m1)) {
                m1.forEach(raw => {
                  const m = window.firebaseFns.mapFromDB ? window.firebaseFns.mapFromDB('meetings', raw) : raw;
                  fetchedMeetings.set(m.id, m);
                });
              }
            } catch (e) {}
          }

          try {
            const { data: m2, error: e2 } = await sb.from('meetings').select('*');
            if (!e2 && Array.isArray(m2)) {
              m2.forEach(raw => {
                const m = window.firebaseFns.mapFromDB ? window.firebaseFns.mapFromDB('meetings', raw) : raw;
                const rId = m.reservationId || m.reservation_id;
                const matchesRes = rId && customerResMap.has(rId);
                const matchesEmail = userEmail && (
                  (m.customerEmail && m.customerEmail.toLowerCase() === userEmail) ||
                  (m.customer_email && m.customer_email.toLowerCase() === userEmail)
                );
                const matchesName = userName && (
                  (m.clientName && m.clientName.toLowerCase() === userName) ||
                  (m.client_name && m.client_name.toLowerCase() === userName) ||
                  (m.customerName && m.customerName.toLowerCase() === userName) ||
                  (m.customer_name && m.customer_name.toLowerCase() === userName)
                );
                if (matchesRes || matchesEmail || matchesName) {
                  fetchedMeetings.set(m.id, m);
                }
              });
            }
          } catch (e) {}
        }

        // 3. Current time evaluation in local time
        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const day = String(now.getDate()).padStart(2, '0');
        const todayStr = `${year}-${month}-${day}`;
        const currentMinutes = now.getHours() * 60 + now.getMinutes();

        const isSlotInPast = (slot) => {
          if (!slot || !slot.date) return true;
          if (slot.date < todayStr) return true;
          if (slot.date === todayStr) {
            const timeVal = slot.end || slot.start || '23:59';
            const [h, m] = timeVal.split(':').map(Number);
            if (!isNaN(h) && (h * 60 + (m || 0)) <= currentMinutes) return true;
          }
          return false;
        };

        const activeMeetings = [];

        for (const m of fetchedMeetings.values()) {
          const status = (m.status || 'pending').toLowerCase();
          const rId = m.reservationId || m.reservation_id;
          const parentRes = rId ? customerResMap.get(rId) : null;
          let isEligibleCancelled = false;

          if (parentRes) {
            const pStatus = (parentRes.status || '').toLowerCase();
            const pCancelStatus = String(parentRes.cancellation_status || parentRes.cancellationStatus || '').toLowerCase();
            const isCancelledRes = (pStatus === 'cancelled' || pCancelStatus === 'cancelled');
            const isUnresolvedRes = (pStatus === 'unresolved' || pCancelStatus === 'unresolved');
            const dpPaid = (parentRes.downpayment_status === 'paid' || parentRes.downpaymentStatus === 'paid' || parentRes.downpayment_paid === true);
            const finalPaid = (parentRes.final_payment_status === 'paid' || parentRes.finalPaymentStatus === 'paid' || parentRes.settled === true);
            const isLateCancel = !!(parentRes.cancellation_requested || parentRes.cancellationRequested || parentRes.cancellation_type === 'late' || parentRes.cancellationType === 'late');
            const isEarlyCancel = !isLateCancel;
            if (isCancelledRes) {
              if (isEarlyCancel) continue;
              if (hasPendingBal && !isUnresolvedRes) {
                isEligibleCancelled = true;
              } else {
                continue;
              }
            } else if (pStatus === 'rejected') {
              continue;
            }

            // Completed reservations must not appear in the customer meetings tab
            const isParentCompleted = pStatus === 'completed' || !!parentRes.exec_finalized_at || !!(parentRes.executionPlan && parentRes.executionPlan.completedAt);
            if (isParentCompleted) {
              continue;
            }

            m._reservationName = parentRes.package_name || parentRes.packageName || parentRes.type || 'Custom Package';
          } else {
            // Check if meeting's reservationId is completed in local cache
            if (rId) {
              const matchedLocal = (window.RESERVATIONS || []).find(r => r.id === rId) || (window._profileResCache && window._profileResCache[rId]);
              if (matchedLocal) {
                const mlStatus = String(matchedLocal.status || '').toLowerCase();
                if (mlStatus === 'completed' || matchedLocal.exec_finalized_at) {
                  continue;
                }
              }
            }
            m._reservationName = m.agenda || m.topic || 'Consultation Meeting';
          }
          m._isEligibleCancelled = isEligibleCancelled;

          // Normalize date/time if only scheduled_at is present
          if (!m.date && m.scheduled_at) {
            try {
              const dt = new Date(m.scheduled_at);
              if (!isNaN(dt.getTime())) {
                const yy = dt.getFullYear();
                const mm = String(dt.getMonth() + 1).padStart(2, '0');
                const dd = String(dt.getDate()).padStart(2, '0');
                m.date = `${yy}-${mm}-${dd}`;
                const hh = String(dt.getHours()).padStart(2, '0');
                const mi = String(dt.getMinutes()).padStart(2, '0');
                if (!m.time) m.time = `${hh}:${mi}`;
              }
            } catch (e) {}
          }
          m.timeEnd = m.timeEnd || m.time_end || '';
          m.time_end = m.time_end || m.timeEnd || '';

          if (['rejected', 'expired', 'completed', 'done'].includes(status)) continue;
          if (status === 'cancelled' && !isEligibleCancelled) continue;

          if (status === 'awaiting_customer') {
            if (m.createdAt || m.created_at) {
              const createdTime = new Date(m.createdAt || m.created_at).getTime();
              if (!isNaN(createdTime) && (now.getTime() - createdTime) > 24 * 60 * 60 * 1000) {
                try {
                  await updateDoc(doc(db, 'meetings', m.id), { status: 'expired', updatedAt: new Date().toISOString() });
                  if (m.reservationId) {
                    await updateDoc(doc(db, 'reservations', m.reservationId), {
                      status: 'cancelled',
                      cancellationNote: 'Automatically cancelled: customer did not select a proposed meeting schedule within 24 hours.',
                      updatedAt: new Date().toISOString()
                    });
                  }
                  // Automated EmailJS Notification to Admin: proposal expired
                  if (window.SmartServeNotifications && typeof window.SmartServeNotifications.notifyAdminMeetingProposalExpired === 'function') {
                    window.SmartServeNotifications.notifyAdminMeetingProposalExpired({
                      customerName: m._reservationName || m.customerName || m.clientName || 'Customer',
                      reservationId: m.reservationId || m.reservation_id,
                      agenda: m.agenda || 'Consultation',
                      meetingId: m.id
                    });
                  }
                } catch (e) {}
                continue;
              }
            }

            const rawSlots = m.adminProposedTimes || m.admin_proposed_times || m.proposed_times || m.meeting_times || [];
            const validSlots = Array.isArray(rawSlots) ? rawSlots.filter(s => !isSlotInPast(s)) : [];
            if (validSlots.length === 0) continue; // All slots in past: drop!

            m._validSlots = validSlots;
            activeMeetings.push(m);
          } else {
            // Drop meetings that have no scheduled date or are marked as TBD
            const dVal = String(m.date || '').trim().toUpperCase();
            if (!dVal || dVal === 'TBD') {
              continue;
            }
            // Filter out past days meetings (meetings scheduled for today remain visible all day)
            if (m.date < todayStr) continue;
            activeMeetings.push(m);
          }
        }

        if (activeMeetings.length === 0) {
          container.innerHTML = '<div class="cp-res-empty">No active meetings found.</div>';
          return;
        }

        let cards = '';
        const nowMs = Date.now();

        for (const m of activeMeetings) {
          const status = (m.status || '').toLowerCase();

          // Action required card (awaiting customer response)
          if (status === 'awaiting_customer') {
            const created = new Date(m.createdAt || m.created_at || nowMs).getTime();
            const expiresAt = created + 24 * 60 * 60 * 1000;
            const remaining = Math.max(0, expiresAt - nowMs);
            const hrs = Math.floor(remaining / 3600000);
            const mins = Math.floor((remaining % 3600000) / 60000);
            const countdownId = `cmt-countdown-${m.id}`;
            const slots = m._validSlots || [];
            window._cmtSlots = window._cmtSlots || {};
            window._cmtSlots[m.id] = slots;

            if (remaining > 0) {
              setTimeout(() => {
                let rem = remaining;
                const tick = setInterval(() => {
                  rem -= 60000;
                  const el = document.getElementById(countdownId);
                  if (!el || rem <= 0) { clearInterval(tick); return; }
                  const h = Math.floor(rem / 3600000), mn = Math.floor((rem % 3600000) / 60000);
                  el.textContent = `${h}h ${mn}m`;
                }, 60000);
              }, 0);
            }

            cards += `
            <div style="background:var(--bg3); border:2px solid #e67e22; border-radius:16px; overflow:hidden; margin-bottom:20px; box-shadow:0 8px 32px rgba(230,126,34,0.18);">
              <div style="padding:16px 20px; background:rgba(230,126,34,0.10); display:flex; justify-content:space-between; align-items:center;">
                <div>
                  <div style="font-size:14px; font-weight:800; color:#e67e22;">ACTION REQUIRED - Choose a Meeting Time</div>
                  <div style="font-size:12px; color:var(--text-mid); margin-top:4px;">The organizer has proposed meeting times for: <strong>${m.agenda || 'Consultation'}</strong></div>
                </div>
                <div style="text-align:right; min-width:120px;">
                  <div style="font-size:11px; color:var(--text-dim);">Expires in</div>
                  <div id="${countdownId}" style="font-size:16px; font-weight:800; color:#e67e22;">${hrs}h ${mins}m</div>
                </div>
              </div>
              <div style="padding:20px;">
                <div style="font-size:12px; color:var(--text-dim); margin-bottom:12px; padding:0; background:transparent; border:none;">
                  <strong style="color:#c0392b;">Important:</strong> If you do not select a time within the deadline, your reservation will be automatically cancelled.
                </div>
                <div style="font-size:12px; font-weight:700; color:var(--text); margin-bottom:10px;">Select one of the proposed times:</div>
                <div style="display:flex; flex-direction:column; gap:8px; margin-bottom:16px;">
                  ${slots.map((s, idx) => `
                    <label style="display:flex; align-items:center; gap:12px; padding:12px 16px; border:2px solid var(--border); border-radius:10px; cursor:pointer; transition:border-color 0.2s;"
                      onmouseover="this.style.borderColor='#e67e22'" onmouseout="this.style.borderColor='var(--border)'">
                      <input type="radio" name="cmt_slot_${m.id}" value="${idx}"
                        style="width:16px; height:16px; accent-color:#e67e22;"
                        onchange="const b = document.getElementById('cmt-select-btn-${m.id}'); if (b) { b.disabled=false; b.style.opacity='1'; }" />
                      <div>
                        <div style="font-size:14px; font-weight:700; color:var(--text);">${s.date}</div>
                        <div style="font-size:12px; color:var(--text-dim);">${_fmtTimeAmPm(s.start)} - ${_fmtTimeAmPm(s.end)}</div>
                      </div>
                    </label>
                  `).join('')}
                </div>
                <button id="cmt-select-btn-${m.id}" disabled
                  onclick="selectAdminProposedTime('${m.id}', '${m.reservationId || m.reservation_id || ''}')"
                  style="width:100%; padding:14px; background:#e67e22; color:#fff; border:none; border-radius:12px; font-weight:800; font-size:14px; cursor:pointer; opacity:0.5; transition:opacity 0.2s;"
                  onmouseover="if(!this.disabled)this.style.opacity='0.85'" onmouseout="if(!this.disabled)this.style.opacity='1'">
                  Confirm Selected Time
                </button>
              </div>
            </div>`;
            continue;
          }

          // Normal meeting card (scheduled / live / pending)
          const roomId = m.meetingRoomId || m.roomId || `MTG-${m.id.substring(0, 8).toUpperCase()}`;
          const dateStr = m.date || 'TBD';
          const time = m.time || 'TBD';
          const isLive = status === 'live';

          cards += `
          <div style="background:var(--bg3); border:1px solid ${isLive ? 'var(--gold)' : 'var(--border)'}; border-radius:16px; overflow:hidden; box-shadow:0 8px 24px rgba(0,0,0,0.12); margin-bottom:20px;">
            <div style="padding:20px; border-bottom:1px solid rgba(0,0,0,0.05); display:flex; justify-content:space-between; align-items:center; background:rgba(0,0,0,0.02);">
              <div style="display:flex; align-items:center; gap:12px;">
                <div style="background:transparent !important; color:var(--gold); padding:0 !important; border:none !important; font-size:11px; font-weight:800; letter-spacing:1px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:220px;">${m._reservationName || roomId}${m._isEligibleCancelled ? ' [Cancelled]' : ''}</div>
                <div style="font-size:12px; font-weight:700; color:var(--text-dim); text-transform:uppercase;">${m.type || 'Consultation'}</div>
              </div>
              ${m._isEligibleCancelled ? '<span style="color:#ef4444; font-size:11px; font-weight:800; text-transform:uppercase; background:transparent; border:none; padding:0;">CANCELLED</span>' : `<div class="badge ${isLive ? 'live' : (status === 'completed' ? 'confirmed' : 'pending')}" style="padding:6px 14px; border-radius:10px; font-size:10px; font-weight:800;">${status.toUpperCase()}</div>`}
            </div>
            <div style="padding:24px; display:grid; grid-template-columns:1fr 1fr; gap:30px;">
              <div>
                <div style="margin-bottom:20px;">
                  <div style="font-size:11px; color:var(--gold); font-weight:700; text-transform:uppercase; margin-bottom:5px;">Meeting Schedule</div>
                  <div style="font-size:16px; font-weight:700; color:var(--text); display:flex; align-items:center; gap:10px;">
                    <span>${dateStr}</span><span style="color:var(--border);">|</span><span>${_fmtTimeRange(time, m.timeEnd || m.time_end)}</span>
                  </div>
                </div>
                <div>
                  <div style="font-size:11px; color:var(--gold); font-weight:700; text-transform:uppercase; margin-bottom:5px;">Discussion Agenda</div>
                  <div style="font-size:13px; color:var(--text-mid); line-height:1.6; background:rgba(0,0,0,0.03); padding:12px; border-radius:10px; border:1px solid rgba(0,0,0,0.05);">
                    ${m.agenda || 'General consultation.'}
                  </div>
                </div>
              </div>
              <div style="display:flex; flex-direction:column; justify-content:space-between;">
                <div style="background:transparent; border:none; padding:4px 0; margin-bottom:12px;">
                  <p style="margin:0; font-size:11px; color:#c0392b; line-height:1.4; font-weight:600;">
                    <strong>IMPORTANT:</strong> Failure to attend the scheduled meeting may lead to automatic cancellation of your reservation.
                  </p>
                </div>
                <div style="display:flex; gap:12px; margin-top:20px; flex-wrap:wrap;">
                  ${isLive ? `<button onclick="joinMeetingRoom('${roomId}')" style="flex:1.5; background:var(--cp-gold, #c49a3c); color:#ffffff; border:none; padding:12px 14px; border-radius:12px; font-weight:800; cursor:pointer; box-shadow:0 6px 15px rgba(196,154,60,0.3);">Join Live Room →</button>` : ''}
                  <button onclick="exportMeetingReservationQuotation('${m.reservation_id || m.reservationId || ''}')" style="flex:1; background:var(--cp-gold, #c49a3c); color:#ffffff; border:none; padding:12px 14px; border-radius:12px; font-weight:700; cursor:pointer; font-size:13px; font-family:inherit;">Export Quotation</button>
                  <button onclick="showMeetingDetails('${m.id}')" style="flex:1; background:#4b5563; color:#ffffff; border:none; padding:12px 14px; border-radius:12px; font-weight:700; cursor:pointer; transition:background 0.3s; font-size:13px; font-family:inherit;">Details &amp; Maps</button>
                </div>
              </div>
            </div>
          </div>`;
        }

        container.innerHTML = cards || '<div class="cp-res-empty">No active meetings found.</div>';
      } catch (err) {
        console.error('fetchAndRender meetings error:', err);
        container.innerHTML = '<div class="cp-res-empty">Failed to load meetings. Please refresh.</div>';
      }
    };

    // Initial load
    await fetchAndRender();

    // Realtime listener
    if (window._custMeetingsChannel && sb) {
      try { sb.removeChannel(window._custMeetingsChannel); } catch (e) {}
    }
    if (sb) {
      window._custMeetingsChannel = sb
        .channel('customer-meetings-' + Date.now())
        .on('postgres_changes', { event: '*', schema: 'public', table: 'meetings' }, () => {
          fetchAndRender();
        })
        .subscribe();
    }
  } catch (e) {
    console.error('renderCustomerMeetings error:', e);
    container.innerHTML = '<div class="cp-res-empty">Failed to load meetings. Please refresh.</div>';
  }
}

async function selectAdminProposedTime(meetingId, reservationId, slotsArg = null) {
  const slots = slotsArg || window._cmtSlots?.[meetingId] || [];
  const selected = document.querySelector(`input[name="cmt_slot_${meetingId}"]:checked`);
  if (!selected) { alert('Please select a time slot first.'); return; }

  const idx = parseInt(selected.value);
  const slot = Array.isArray(slots) ? slots[idx] : null;
  if (!slot) { alert('Invalid selection. Please try again.'); return; }

  const btn = document.getElementById(`cmt-select-btn-${meetingId}`);
  if (btn) { btn.textContent = 'Confirming...'; btn.disabled = true; }

  try {
    const { updateDoc, doc } = window.firebaseFns;
    const db = window.firebaseDB;
    const nowIso = new Date().toISOString();

    await updateDoc(doc(db, 'meetings', meetingId), {
      status: 'scheduled',
      date: slot.date,
      time: slot.start,
      timeEnd: slot.end || '',
      time_end: slot.end || '',
      adminProposedTimes: [],
      admin_proposed_times: [],
      proposed_times: [],
      timeType: 'customer_selected',
      updatedAt: nowIso
    });

    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from('meetings').update({
          status: 'scheduled',
          date: slot.date,
          time: slot.start,
          time_end: slot.end || '',
          scheduled_at: `${slot.date}T${slot.start}:00Z`,
          admin_proposed_times: [],
          proposed_times: [],
          time_type: 'customer_selected',
          updated_at: nowIso
        }).eq('id', meetingId);
      } catch (sbErr) { console.warn('Direct SB update fallback:', sbErr); }
    }

    if (reservationId && window.supabaseClient) {
      try {
        await window.supabaseClient.from('reservations').update({
          cancellation_request_status: 'meeting_scheduled',
          updated_at: nowIso
        }).eq('id', reservationId);
      } catch (rErr) { console.warn('Reservation status update warning:', rErr); }
    }
    if (reservationId && db && updateDoc && doc) {
      try {
        await updateDoc(doc(db, 'reservations', reservationId), {
          cancellation_request_status: 'meeting_scheduled',
          updatedAt: nowIso
        });
      } catch (rErr) {}
    }

    const t = document.createElement('div');
    t.className = 'toast';
    t.textContent = `Meeting confirmed for ${slot.date} at ${slot.start}!`;
    document.body.appendChild(t);
    setTimeout(() => t.classList.add('show'), 10);
    setTimeout(() => { t.classList.remove('show'); setTimeout(() => t.remove(), 300); }, 5000);

    // Automated EmailJS Notification to Admin
    if (window.SmartServeNotifications && typeof window.SmartServeNotifications.notifyAdminCustomerChoseMeetingTime === 'function') {
      const clientName = (window.currentUser && (window.currentUser.name || window.currentUser.full_name)) || 'Customer';
      window.SmartServeNotifications.notifyAdminCustomerChoseMeetingTime({
        customerName: clientName,
        date: slot.date,
        time: slot.start,
        agenda: 'Consultation',
        meetingId: meetingId,
        reservationId: reservationId
      });
    }

    await renderCustomerMeetings();
    if (typeof renderCustomerCalendar === 'function') {
      try { renderCustomerCalendar(); } catch (e) {}
    }
  } catch (e) {
    console.error('selectAdminProposedTime error:', e);
    alert('Failed to confirm time. Please try again.');
    if (btn) { btn.textContent = 'Confirm Selected Time'; btn.disabled = false; }
  }
}
window.selectAdminProposedTime = selectAdminProposedTime;



function initOfficeMap() {
  const container = document.getElementById('office-map');
  if (!container || container._leaflet_id) return;

  const map = L.map('office-map', { zoomControl: false }).setView([14.6156, 120.9942], 16);
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
    attribution: '&copy; OpenStreetMap contributors'
  }).addTo(map);
  L.marker([14.6156, 120.9942]).addTo(map).bindPopup("<b>Halden's Office</b><br>18 Basilio St");

  // Force recalculation of container size
  setTimeout(() => map.invalidateSize(), 200);
}

