/**
 * Helper to determine if a reservation is cancelled but still has pending balances.
 * Rule:
 * - If status is 'cancelled':
 *   - If marked as 'unresolved', it is finalized and does NOT remain in active handling/payments.
 *   - If all balances are paid (totalDue === 0), it does NOT remain in active handling/payments.
 *   - If there are unpaid balances (totalDue > 0), returns true.
 */
function isCancelledWithPendingBalance(res) {
  if (!res) return false;
  const st = String(res.status || '').toLowerCase().trim();
  const cancelStatus = String(res.cancellation_status || res.cancellationStatus || res.cancellation_request_status || '').toLowerCase().trim();

  // Only applicable if the reservation is cancelled
  if (st !== 'cancelled' && cancelStatus !== 'cancelled') return false;

  // If marked as unresolved, it is excluded from active handling and payments
  if (st === 'unresolved' || cancelStatus === 'unresolved') return false;

  // Early cancellations have no cancellation fees or pending balances
  const isLateCancel = !!(res.cancellation_requested || res.cancellationRequested || res.cancellation_type === 'late' || res.cancellationType === 'late');
  if (!isLateCancel) return false;

  // Check if business cancelled - keep visible until 200% business compensation is disbursed
  const origin = (typeof getCancellationOrigin === 'function') ? getCancellationOrigin(res) : (res.cancellation_by || 'customer');
  if (origin === 'business') {
    const isBizPaid = !!(res.business_liability_paid || res.cancellation_business_paid || (res.cancellation_status === 'settled' && res.cancellation_payout_status === 'paid'));
    return !isBizPaid;
  }

  // Customer cancellation - check remaining cancellation balances
  let totalDue = 0;
  if (typeof computeCustomerCancellationBalances === 'function') {
    const bal = computeCustomerCancellationBalances(res);
    totalDue = bal ? (bal.totalDue || 0) : 0;
  } else {
    const dpPaid = (res.downpayment_status === 'paid' || res.downpaymentStatus === 'paid' || res.downpayment_paid === true);
    const finalPaid = (res.final_payment_status === 'paid' || res.finalPaymentStatus === 'paid' || res.settled === true);
    const amt = parseFloat(res.amount || res.total_amount || 0);
    const dp = Math.round(amt * 0.5);
    if (!dpPaid) totalDue += dp;
    if (!finalPaid) totalDue += (amt - dp);
  }

  return totalDue > 0;
}
window.isCancelledWithPendingBalance = isCancelledWithPendingBalance;

// Populate the Reservation Details dropdown when the tab opens
window.initCustomerResDetails = async function () {
  const selector = document.getElementById('resd-approved-selector');
  if (!selector || !currentUser) return;

  const userEmail = (currentUser.email || '').trim();
  const { collection, query, where, onSnapshot } = window.firebaseFns;

  if (window._customerResListenerUnsub) {
    window._customerResListenerUnsub();
  }
  if (window._customerResListenerUnsub2) {
    window._customerResListenerUnsub2();
  }

  const chkCancelled = document.getElementById('c-chk-show-cancelled-res');
  const showCancelled = chkCancelled ? chkCancelled.checked : false;

  const filterCustomerRes = (r) => {
    const st = (r.status || '').toLowerCase().trim();
    const cancelStatus = String(r.cancellation_status || r.cancellationStatus || r.cancellation_request_status || '').toLowerCase().trim();
    const isCanc = st === 'cancelled' || cancelStatus === 'cancelled';
    const isUnresolved = st === 'unresolved' || cancelStatus === 'unresolved';
    const hasPendingBal = isCancelledWithPendingBalance(r);

    if (showCancelled) {
      return isCanc || isUnresolved;
    }
    if (isCanc || isUnresolved) {
      return false;
    }
    return ['approved', 'confirmed', 'procurement', 'procuring', 'preparing', 'on-going', 'completed', 'semi-approved', 'semi_approved', 'semi approved', 'pending'].includes(st);
  };

  const processRes = (myRes) => {
    if (myRes.length === 0) {
      selector.innerHTML = showCancelled ? '<option value="">No cancelled reservations found.</option>' : '<option value="">No reservations found.</option>';
      const contentEl = document.getElementById('resd-content');
      if (contentEl) {
        contentEl.innerHTML = `
          <div style="text-align:center; padding:100px 20px; color:var(--text-dim);">
            <div style="font-size:16px; font-weight:600; color:var(--text-mid);">${showCancelled ? 'No Cancelled Reservations' : 'No Reservation Selected'}</div>
            <div style="font-size:13px; margin-top:5px;">${showCancelled ? 'No cancelled bookings match this view.' : 'Once your reservation is confirmed, you can track all logistics and planning details here.'}</div>
          </div>
        `;
      }
      if (typeof window.updateCustomerResDetailCancelButtons === 'function') {
        window.updateCustomerResDetailCancelButtons(null);
      }
      return;
    }

    const currentVal = selector.value;
    selector.innerHTML = '<option value="">-- Select a Reservation --</option>' +
      myRes.map(r => {
        const isCanc = String(r.status || '').toLowerCase() === 'cancelled';
        const isSemi = ['semi-approved', 'semi_approved', 'semi approved'].includes(String(r.status || '').toLowerCase());
        const isPending = String(r.status || '').toLowerCase() === 'pending';
        const prefix = isCanc ? '[CANCELLED] ' : (isSemi ? '[SEMI-APPROVED] ' : (isPending ? '[PENDING] ' : ''));
        return `<option value="${r.id}">${prefix}${r.packageName || r.type || 'Event'} : ${r.date}</option>`;
      }).join('');

    if (currentVal && myRes.find(r => r.id === currentVal)) {
      selector.value = currentVal;
    }

    if (!window.RESERVATIONS) window.RESERVATIONS = [];
    myRes.forEach(r => {
      const idx = window.RESERVATIONS.findIndex(x => x.id === r.id);
      if (idx !== -1) window.RESERVATIONS[idx] = r;
      else window.RESERVATIONS.push(r);
    });

    if (activeResDetailId && window.switchResDetailsTab && resDetailsActiveTab) {
      window.switchResDetailsTab(resDetailsActiveTab);
    }

    // Dynamically update the Logging of Activities section regardless of active tab
    // This ensures task completions appear in real-time without a page refresh or tab switch
    const _activeRes = (window.RESERVATIONS || []).find(r => r.id === activeResDetailId);
    if (_activeRes) {
      const logsContainer = document.getElementById('resd-activity-logs');
      if (logsContainer) {
        const _tasks = Array.isArray(_activeRes.timelineTasks) ? _activeRes.timelineTasks : [];
        const completedTasks = _tasks.filter(t => t.status === 'done' || t.autoCheck);
        if (completedTasks.length > 0) {
          logsContainer.innerHTML = completedTasks.map(t => `
            <div style="background:var(--bg); border:1px solid var(--border); border-radius:10px; padding:12px; display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
              <div style="display:flex; gap:12px; align-items:center;">
                <div style="width:8px; height:8px; border-radius:50%; background:var(--green);"></div>
                <div>
                  <div style="font-size:13px; font-weight:600; color:var(--text);">${esc(t.title)}</div>
                  <div style="font-size:11px; color:var(--text-dim);">Completed on ${esc(t.logAt ? new Date(t.logAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : (t.date || ''))}</div>
                </div>
              </div>
              <div style="font-size:10px; font-weight:800; color:var(--text-dim); text-transform:uppercase;">VERIFIED</div>
            </div>
          `).join('');
        } else {
          logsContainer.innerHTML = '<div style="padding:15px; text-align:center; color:var(--text-dim);">No completed activities to log yet.</div>';
        }
      }
    }
  };

  const q = query(collection(window.firebaseDB, 'reservations'), where('email', '==', userEmail));
  window._customerResListenerUnsub = onSnapshot(q, (snap) => {
    let myRes = snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(filterCustomerRes);

    if (myRes.length > 0) {
      processRes(myRes);
    } else {
      const q2 = query(collection(window.firebaseDB, 'reservations'), where('customerEmail', '==', userEmail));
      window._customerResListenerUnsub2 = onSnapshot(q2, (snap2) => {
        let myRes2 = snap2.docs.map(d => ({ id: d.id, ...d.data() })).filter(filterCustomerRes);
        processRes(myRes2);
      });
    }
  });
};



window.customerSelectReservation = function (resId) {
  window.customerModifyMode = false;
  window.customerModifyingRes = null;
  window.customerModifyingItems = [];
  if (typeof window.syncCustomerAIFabVisibility === 'function') window.syncCustomerAIFabVisibility();
  if (!resId) {
    activeResDetailId = null;
    const tabCancelBtn = document.getElementById('resd-tab-cancellation');
    if (tabCancelBtn) tabCancelBtn.style.display = 'none';
    if (typeof window.updateCustomerResDetailCancelButtons === 'function') {
      window.updateCustomerResDetailCancelButtons(null);
    }
    return;
  }
  activeResDetailId = resId;

  const selRes = (window.RESERVATIONS || []).find(r => r.id === resId || String(r.id) === String(resId));
  if (typeof window.updateCustomerResDetailCancelButtons === 'function') {
    window.updateCustomerResDetailCancelButtons(selRes);
  }

  const isCancelled = selRes && (
    String(selRes.status || '').toLowerCase() === 'cancelled' ||
    String(selRes.cancellation_status || '').toLowerCase() === 'cancelled' ||
    String(selRes.cancellation_status || '').toLowerCase() === 'settled' ||
    String(selRes.cancellation_status || '').toLowerCase() === 'unresolved' ||
    selRes.cancellation_request_status === 'settled' ||
    selRes.cancellation_request_status === 'unresolved'
  );

  const tabCancelBtn = document.getElementById('resd-tab-cancellation');
  if (tabCancelBtn) {
    tabCancelBtn.style.display = isCancelled ? 'inline-block' : 'none';
  }
  const modifyBtn = document.getElementById('resd-modify-btn');
  if (modifyBtn) {
    modifyBtn.style.display = (selRes && !isCancelled) ? 'inline-flex' : 'none';
  }

  if (isCancelled) {
    resDetailsActiveTab = 'cancellation';
  } else if (resDetailsActiveTab === 'cancellation') {
    resDetailsActiveTab = 'details';
  }

  if (typeof window.switchResDetailsTab === 'function') {
    const curTab = resDetailsActiveTab || 'details';
    const tabBtn = document.getElementById('resd-tab-' + curTab);
    window.switchResDetailsTab(curTab, tabBtn);
  } else {
    renderReservationDetailContent();
  }
};


window.activePaymentResId = null;
window.renderCustomerPayments = async function () {
  const container = document.getElementById('dash-tab-payments');
  if (!container) return;

  if (!currentUser) return;
  const userEmail = (currentUser.email || '').trim();
  const { collection, getDocs, query, where } = window.firebaseFns;

  const innerExists = document.getElementById('c-payment-tab-inner');
  if (!innerExists) {
    container.innerHTML = `
      <div style="padding:40px; text-align:center;">
         <div class="spinner" style="margin:0 auto 20px;"></div>
         <div style="color:var(--text-dim); font-weight:600;">Generating Statements...</div>
      </div>
    `;
  }

  try {
    const q = query(collection(window.firebaseDB, 'reservations'), where('email', '==', userEmail));
    const snap = await getDocs(q);
    let myRes = snap.docs.map(d => ({ id: d.id, ...d.data() })).filter(r => {
      const st = (r.status || '').toLowerCase().trim();
      const isActive = ['approved', 'confirmed', 'procuring', 'procurement', 'preparing', 'on-going', 'completed'].includes(st);
      return isActive || isCancelledWithPendingBalance(r);
    });

    if (myRes.length === 0) {
      container.innerHTML = `
        <div style="padding:80px 40px; text-align:center; background:var(--bg2); border-radius:24px; border:1px dashed var(--border);">
           <h3 style="color:var(--gold);">No Pending Payments</h3>
           <p style="color:var(--text-dim); max-width:400px; margin:10px auto;">Once your reservations are approved, your billing statements will appear here.</p>
        </div>
      `;
      return;
    }

    // Merge myRes into window.RESERVATIONS so renderPaymentTab can locate reservation details
    window.RESERVATIONS = window.RESERVATIONS || [];
    myRes.forEach(r => {
      const idx = window.RESERVATIONS.findIndex(x => x.id === r.id);
      if (idx >= 0) {
        Object.assign(window.RESERVATIONS[idx], r);
      } else {
        window.RESERVATIONS.push(r);
      }
    });

    if (!window.activePaymentResId || !myRes.find(r => r.id === window.activePaymentResId)) {
      window.activePaymentResId = myRes[0].id;
    }

    if (!innerExists) {
      let topDropdownHtml = `
        <div class="cp-sel-bar" style="margin-bottom:24px; background:var(--bg3); border-radius:12px; padding:16px 20px; border:1px solid var(--border);">
          <div class="cp-sel-lbl" style="margin-bottom:8px; font-size:10px; color:var(--gold); font-weight:700; letter-spacing:1px; text-transform:uppercase;">ACTIVE RESERVATION PAYMENT</div>
          <select class="cp-sel-field" onchange="window.activePaymentResId = this.value; window.renderCustomerPayments()" style="width:100%; max-width:100%; height:44px; background:var(--bg2); color:var(--cream); border:1px solid var(--border); border-radius:8px; padding:0 12px; outline:none; cursor:pointer;">
            ${myRes.map(r => `<option value="${r.id}" ${r.id === window.activePaymentResId ? 'selected' : ''}>${r.packageName || r.type || 'Event'} : ${r.date}</option>`).join('')}
          </select>
        </div>
        <div id="c-payment-tab-inner"></div>
      `;
      container.innerHTML = topDropdownHtml;
    }

    await renderPaymentTab('c-payment-tab-inner', window.activePaymentResId);

  } catch (e) {
    console.error("renderCustomerPayments error:", e);
    if (!innerExists) {
      container.innerHTML = '<div style="padding:40px; text-align:center; color:var(--red);">Failed to retrieve billing statements. Please try again later.</div>';
    }
  }
};

// Supabase Realtime Dynamic Sync for Customer Payments
if (window.supabaseClient && !window._customerPaymentRealtimeSub) {
  try {
    window._customerPaymentRealtimeSub = window.supabaseClient
      .channel('customer-payments-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reservation_payments' }, (payload) => {
        const paymentsTab = document.getElementById('dash-tab-payments');
        if (paymentsTab && (paymentsTab.classList.contains('active') || paymentsTab.style.display !== 'none')) {
          if (typeof window.renderCustomerPayments === 'function') {
            window.renderCustomerPayments();
          }
        }
      })
      .subscribe();
  } catch (err) {
    console.warn('Realtime subscription error for reservation_payments:', err);
  }
}

// 3.5s Smart Silent Polling for Customer Payments
if (!window._customerPaymentPollTimer) {
  window._customerPaymentPollTimer = setInterval(() => {
    const paymentsTab = document.getElementById('dash-tab-payments');
    if (paymentsTab && (paymentsTab.classList.contains('active') || paymentsTab.style.display === 'block')) {
      if (document.getElementById('c-payment-tab-inner') && window.activePaymentResId) {
        if (typeof renderPaymentTab === 'function') {
          renderPaymentTab('c-payment-tab-inner', window.activePaymentResId);
        }
      }
    }
  }, 3500);
}

window.payInstallment = function (resId, amount, label) {
  openPaymentModal(resId, amount, label);
};

// =====================================================================
// CUSTOMER SUMMARY & FEEDBACK (COMPLETED RESERVATIONS ONLY)
// =====================================================================
window._custFeedbacksData = window._custFeedbacksData || {};

window.renderCustomerReviews = async function () {
  const container = document.getElementById('c-reviews-list');
  if (!container) return;

  container.innerHTML = `
    <div style="padding:40px; text-align:center; color:var(--cp-text-dim, #6b7280);">
      <i class="fas fa-circle-notch fa-spin" style="font-size:24px; color:var(--cp-gold, #c49a3c); margin-bottom:12px; display:inline-block;"></i>
      <div>Loading completed events and feedback...</div>
    </div>
  `;

  // Fetch customer reservations
  const user = currentUser || JSON.parse(localStorage.getItem('currentUser') || sessionStorage.getItem('currentUser') || '{}');
  const userEmail = (user.email || '').toLowerCase().trim();
  const userId = user.id || user.uid || '';

  let allRes = [];
  const seenIds = new Set();
  const addIfNew = r => {
    if (!r || !r.id || seenIds.has(r.id)) return;
    seenIds.add(r.id);
    allRes.push(r);
  };

  if (window._profileResCache) Object.values(window._profileResCache).forEach(addIfNew);
  if (Array.isArray(window.RESERVATIONS)) window.RESERVATIONS.forEach(addIfNew);
  if (Array.isArray(window.MY_RESERVATIONS)) window.MY_RESERVATIONS.forEach(addIfNew);

  if (typeof _fetchCustomerReservationsDirectly === 'function') {
    const fetched = await _fetchCustomerReservationsDirectly();
    if (Array.isArray(fetched)) fetched.forEach(addIfNew);
  }

  // Filter strictly to current user's reservations that are COMPLETED or ON-GOING
  const targetRes = allRes.filter(r => {
    const rUid = r.userId || r.user_id || '';
    const rEmail = (r.clientEmail || r.email || r.client_email || '').toLowerCase().trim();
    const isOwner = (userId && rUid && String(rUid) === String(userId)) ||
                    (userEmail && rEmail && rEmail === userEmail) ||
                    (window._profileResCache && window._profileResCache[r.id]);
    if (!isOwner) return false;

    const st = String(r.status || '').toLowerCase();
    const isCompleted = st === 'completed' || !!r.exec_finalized_at;
    const isOngoing = st === 'on-going' || st === 'ongoing' || st === 'in-progress' || st === 'in_progress';
    return isCompleted || isOngoing;
  });

  if (targetRes.length === 0) {
    container.innerHTML = `
      <div class="cp-res-empty" style="padding:56px 20px; background:var(--cp-sidebar, #ffffff); border:1px solid var(--cp-border); border-radius:16px; text-align:center; box-shadow:0 4px 16px rgba(0,0,0,0.04);">
        <div style="font-size:42px; margin-bottom:14px; color:var(--cp-gold, #c49a3c);"><i class="fas fa-clipboard-check"></i></div>
        <div style="font-size:18px; font-weight:800; color:var(--cp-text, #111827);">No Ongoing or Completed Events Yet</div>
        <div style="font-size:13.5px; font-weight:500; color:var(--cp-text-dim, #6b7280); max-width:440px; margin:8px auto 0; line-height:1.6;">
          Once your reservation is on-going or has concluded, your event summary, pictures, and review form will be available here.
        </div>
      </div>
    `;
    return;
  }

  // Selected ongoing or completed reservation from dropdown
  const selectedResId = window._selectedFeedbackResId || (targetRes[0] ? targetRes[0].id : null);
  const res = targetRes.find(r => String(r.id) === String(selectedResId)) || targetRes[0];
  window._selectedFeedbackResId = res.id;

  let finalHtml = `
    <!-- Reservation Filter Dropdown Selector for Ongoing & Completed Events -->
    <div style="margin-bottom:24px; background:var(--cp-sidebar, #ffffff); border:1px solid var(--cp-border); border-radius:14px; padding:18px 22px; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:16px; box-shadow:0 4px 14px rgba(0,0,0,0.03);">
      <div>
        <div style="font-size:11px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:0.8px;">
          Select Reservation
        </div>
        <div style="font-size:13px; color:var(--cp-text-dim, #6b7280); margin-top:2px;">
          Select your ongoing or completed event to view pictures and submit your review:
        </div>
      </div>
      <div style="flex:1; max-width:440px; min-width:280px;">
        <select id="cust-feedback-reservation-select" onchange="window.selectCustomerFeedbackRes(this.value)"
          style="width:100%; padding:10px 14px; font-size:13.5px; font-weight:600; border-radius:10px; border:1.5px solid var(--cp-border); background:var(--cp-bg, #faf8f4); color:var(--cp-text, #111827); outline:none; cursor:pointer;">
          ${targetRes.map(r => {
            const isOng = ['on-going', 'ongoing', 'in-progress', 'in_progress'].includes(String(r.status || '').toLowerCase());
            const pName = r.packageName || r.package_name || r.package || r.type || 'Catering Package';
            const dStr = r.date || r.event_date || 'Date TBD';
            const isSel = (String(r.id) === String(res.id));
            return `<option value="${r.id}" ${isSel ? 'selected' : ''}>[${isOng ? 'On-Going' : 'Completed'}] ${pName} - ${dStr}</option>`;
          }).join('')}
        </select>
      </div>
    </div>
  `;

  {
    const isOngoing = ['on-going', 'ongoing', 'in-progress', 'in_progress'].includes(String(res.status || '').toLowerCase());
    const pkgName = res.packageName || res.package_name || res.package || res.type || 'Custom Catering Event';
    const evDate = res.date || res.event_date || '—';
    const evTime = res.time || res.timeframe || '—';
    const evVenue = res.venue || res.venueAddress || res.venue_location || '—';

    // Financial calculations: Initial fee (₱5,000) + Downpayment + Final payment + Additional charges in ONE single amount
    const initialFee = 5000;
    const dpAmt = parseFloat(res.downpaymentAmount || res.downpayment_amount || (res.amount ? res.amount * 0.5 : 0)) || 0;
    const finalAmt = parseFloat(res.finalPaymentAmount || res.final_payment_amount || (res.amount ? res.amount * 0.5 : 0)) || 0;
    const addCharges = parseFloat(res.exec_total_charges || res.additional_charges || (res.exec_summary && res.exec_summary.totalCharges) || 0) || 0;
    const overallPrice = initialFee + dpAmt + finalAmt + addCharges;

    // Fetch pictures for this reservation (Supabase event_pictures + fallback)
    let pictures = [];
    if (window.supabaseClient) {
      try {
        const { data: picData } = await window.supabaseClient
          .from('event_pictures')
          .select('*')
          .eq('reservation_id', String(res.id))
          .order('created_at', { ascending: false });
        if (picData && picData.length) pictures = picData;
      } catch(e) {}
    }
    if (!pictures.length && Array.isArray(res.event_pictures) && res.event_pictures.length) {
      pictures = res.event_pictures;
    }
    if (!pictures.length) {
      try {
        const localPics = JSON.parse(localStorage.getItem('event_pictures_' + res.id) || '[]');
        if (Array.isArray(localPics) && localPics.length) pictures = localPics;
      } catch(e) {}
    }

    // Fetch existing feedback for this reservation (Supabase customer_feedbacks + reservations.execution_plan + fallback)
    let existingFb = null;
    if (window.supabaseClient) {
      try {
        const { data: fbData } = await window.supabaseClient
          .from('customer_feedbacks')
          .select('*')
          .eq('reservation_id', String(res.id))
          .maybeSingle();
        if (fbData && fbData.comment) existingFb = fbData;
      } catch(e) {}
    }
    // Check res.execution_plan in Supabase reservation object
    if (!existingFb && res && res.execution_plan) {
      let exec = typeof res.execution_plan === 'object' ? res.execution_plan : null;
      if (!exec) {
        try { exec = JSON.parse(res.execution_plan); } catch(e) {}
      }
      if (exec && exec.customer_feedback && exec.customer_feedback.comment) {
        existingFb = exec.customer_feedback;
      }
    }
    // Also check direct res.customer_feedback if present
    if (!existingFb && res && res.customer_feedback) {
      let cfb = typeof res.customer_feedback === 'object' ? res.customer_feedback : null;
      if (!cfb) {
        try { cfb = JSON.parse(res.customer_feedback); } catch(e) {}
      }
      if (cfb && cfb.comment) existingFb = cfb;
    }
    // Fallback to localStorage
    if (!existingFb) {
      try {
        const localFb = JSON.parse(localStorage.getItem('cust_feedback_' + res.id) || 'null');
        if (localFb && localFb.comment) existingFb = localFb;
      } catch(e) {}
    }

    const hasSavedFeedback = !!existingFb && !!existingFb.comment;
    const savedRating = existingFb ? (parseInt(existingFb.rating, 10) || 5) : 5;
    const savedComment = existingFb ? (existingFb.comment || '') : '';

    // Initialize in-memory feedback state
    window._custFeedbacksData[res.id] = {
      rating: savedRating,
      comment: savedComment,
      originalRating: savedRating,
      originalComment: savedComment,
      locked: hasSavedFeedback
    };

    finalHtml += `
      <div style="background:var(--cp-sidebar, #ffffff); border:1.5px solid var(--cp-border); border-radius:18px; padding:28px; margin-bottom:32px; box-shadow:0 6px 20px rgba(0,0,0,0.05);">
        
        <!-- Header row (Centered) -->
        <div style="display:flex; flex-direction:column; align-items:center; text-align:center; gap:8px; margin-bottom:24px; border-bottom:1px solid var(--cp-border); padding-bottom:20px;">
          <div style="display:flex; align-items:center; justify-content:center; gap:8px; margin-bottom:4px;">
            <span style="font-size:11px; font-weight:800; color:${isOngoing ? 'var(--cp-gold, #855800)' : '#16a34a'}; text-transform:uppercase; letter-spacing:0.5px;">
              [ ${isOngoing ? 'On-Going Event' : 'Completed Event'} ]
            </span>
            <span style="font-size:11px; font-weight:700; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:0.5px;">
              ID: ${escHtml(res.id)}
            </span>
          </div>
          <h2 style="font-size:24px; font-weight:800; color:var(--cp-text, #111827); margin:0; text-align:center;">
            ${escHtml(pkgName)}
          </h2>
          <div style="font-size:13.5px; color:var(--cp-text-dim, #6b7280); text-align:center;">
            Client: <strong style="color:var(--cp-text, #111827);">${escHtml(res.client || res.client_name || user.displayName || 'Valued Client')}</strong>
          </div>

          <!-- Overall price of the package in ONE single amount (Centered) -->
          <div style="text-align:center; margin-top:10px;">
            <div style="font-size:11px; font-weight:800; color:var(--cp-text-dim, #6b7280); text-transform:uppercase; letter-spacing:1px;">
              Overall Package Price
            </div>
            <div style="font-size:28px; font-weight:800; color:var(--cp-gold, #855800); margin-top:2px; letter-spacing:-0.5px;">
              ₱${overallPrice.toLocaleString()}
            </div>
            <div style="font-size:11px; color:var(--cp-text-dim, #6b7280); margin-top:3px; max-width:320px; line-height:1.3; margin-left:auto; margin-right:auto;">
              (Total sum of reservation fee, downpayment, final payment &amp; additional charges)
            </div>
          </div>
        </div>

        <!-- Basic Informations Grid: Date, Time Frame, Venue (Centered) -->
        <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(180px, 1fr)); gap:12px; margin-bottom:24px;">
          <div style="background:var(--cp-bg, #faf8f4); border:1px solid var(--cp-border); border-radius:10px; padding:14px 16px; text-align:center;">
            <div style="font-size:10.5px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:0.5px;">Date Occurred</div>
            <div style="font-size:14.5px; font-weight:700; color:var(--cp-text, #111827); margin-top:4px;">${escHtml(evDate)}</div>
          </div>
          <div style="background:var(--cp-bg, #faf8f4); border:1px solid var(--cp-border); border-radius:10px; padding:14px 16px; text-align:center;">
            <div style="font-size:10.5px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:0.5px;">Time Frame</div>
            <div style="font-size:14.5px; font-weight:700; color:var(--cp-text, #111827); margin-top:4px;">${escHtml(evTime)}</div>
          </div>
          <div style="background:var(--cp-bg, #faf8f4); border:1px solid var(--cp-border); border-radius:10px; padding:14px 16px; text-align:center; grid-column: 1 / -1;">
            <div style="font-size:10.5px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:0.5px;">Venue Location</div>
            <div style="font-size:14px; font-weight:700; color:var(--cp-text, #111827); margin-top:4px; line-height:1.4;">${escHtml(evVenue)}</div>
          </div>
        </div>

        <!-- Event Pictures Gallery (Strictly 5 pictures per each row) -->
        <div style="margin-bottom:28px; border-top:1px solid var(--cp-border); padding-top:20px;">
          <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:4px; margin-bottom:16px;">
            <div style="font-size:12px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:1px; display:inline-flex; align-items:center; gap:8px;">
              <i class="fas fa-camera"></i> Event Pictures (${pictures.length})
            </div>
            <span style="font-size:11px; color:var(--cp-text-dim, #6b7280);">Arranged 5 photos per row</span>
          </div>

          ${pictures.length > 0 ? `
            <div style="display:grid; grid-template-columns:repeat(5, 1fr); gap:12px;">
              ${pictures.map((pic, pIdx) => {
                const picUrl = pic.url || pic.secure_url || pic.picture_url || (typeof pic === 'string' ? pic : '');
                const picCaption = pic.caption || pic.title || `Event Photo ${pIdx + 1}`;
                return `
                  <div style="position:relative; border-radius:10px; overflow:hidden; border:1px solid var(--cp-border); background:#000; aspect-ratio:1/1; cursor:pointer; box-shadow:0 2px 8px rgba(0,0,0,0.1); transition:transform 0.2s;"
                    onmouseenter="this.style.transform='scale(1.03)'"
                    onmouseleave="this.style.transform='scale(1)'"
                    onclick="window.open('${picUrl}', '_blank')"
                    title="${escHtml(picCaption)} (Click to view full image)">
                    <img src="${picUrl}" alt="${escHtml(picCaption)}" style="width:100%; height:100%; object-fit:cover; display:block;" loading="lazy" />
                    <div style="position:absolute; inset:0; background:linear-gradient(to top, rgba(0,0,0,0.6) 0%, transparent 60%); opacity:0; transition:opacity 0.2s; display:flex; align-items:flex-end; padding:8px;"
                      onmouseenter="this.style.opacity='1'"
                      onmouseleave="this.style.opacity='0'">
                      <span style="color:#fff; font-size:11px; font-weight:600; text-overflow:ellipsis; overflow:hidden; white-space:nowrap;">${escHtml(picCaption)}</span>
                    </div>
                  </div>
                `;
              }).join('')}
            </div>
          ` : `
            <div style="padding:32px 20px; background:var(--cp-bg, #faf8f4); border:1.5px dashed var(--cp-border); border-radius:12px; text-align:center; color:var(--cp-text-dim, #6b7280);">
              <i class="fas fa-images" style="font-size:28px; color:var(--cp-gold, #c49a3c); margin-bottom:8px; display:inline-block;"></i>
              <div style="font-size:13.5px; font-weight:700; color:var(--cp-text, #111827);">No Event Pictures Uploaded Yet</div>
              <div style="font-size:12px; margin-top:4px;">Photographs captured during your event will appear here once uploaded by the coordinator.</div>
            </div>
          `}
        </div>

        <!-- Customer Experience Feedback & Star Rating Section (Centered) -->
        <div style="border-top:1px solid var(--cp-border); padding-top:22px; text-align:center;">
          <div style="font-size:12px; font-weight:800; color:var(--cp-gold, #855800); text-transform:uppercase; letter-spacing:1px; margin-bottom:6px; text-align:center;">
            Client Review &amp; Experience Rating
          </div>
          <p style="font-size:13px; color:var(--cp-text-dim, #6b7280); margin:0 auto 16px; max-width:650px; text-align:center;">
            Please share your feedback regarding our food quality, event management, and team service. Your review helps us continue providing excellent experiences.
          </p>

          <!-- 1 to 5 Star Rating selector (Centered) -->
          <div style="margin-bottom:18px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; text-align:center;">
            <span style="font-size:13px; font-weight:700; color:var(--cp-text, #111827);">Your Rating:</span>
            <div id="cust-fb-stars-${res.id}" style="display:inline-flex; justify-content:center; gap:8px; font-size:28px; user-select:none; cursor:${hasSavedFeedback ? 'default' : 'pointer'};">
              ${[1, 2, 3, 4, 5].map(starNum => `
                <span class="cust-fb-star" onclick="setCustFeedbackStars('${res.id}', ${starNum})"
                  style="color:${starNum <= savedRating ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-text-dim, #9ca3af)'}; transition:all 0.15s;">
                  ${starNum <= savedRating ? '★' : '☆'}
                </span>
              `).join('')}
            </div>
          </div>

          <!-- Huge Text Area for feedback -->
          <div style="margin-bottom:16px;">
            <textarea id="cust-fb-text-${res.id}" rows="5"
              placeholder="Write your detailed feedback here... Tell us what you loved about our food, table setups, and service!"
              ${hasSavedFeedback ? 'disabled readonly' : ''}
              style="width:100%; min-height:140px; padding:16px; border-radius:12px; border:1.5px solid var(--cp-border); background:${hasSavedFeedback ? 'var(--cp-bg, #faf8f4)' : 'var(--cp-sidebar, #ffffff)'}; color:var(--cp-text, #111827); font-size:14px; font-family:inherit; line-height:1.6; resize:vertical; outline:none; transition:all 0.2s; opacity:${hasSavedFeedback ? '0.88' : '1'};">${escHtml(savedComment)}</textarea>
          </div>

          <!-- Notification feedback banner -->
          <div id="cust-fb-msg-${res.id}" style="display:none; padding:10px 14px; border-radius:8px; font-size:12.5px; font-weight:700; background:rgba(34,197,94,0.12); color:#16a34a; border:1px solid rgba(34,197,94,0.3); margin-bottom:14px; text-align:center;"></div>

          <!-- Save / Modify / Cancel button area (Centered) -->
          <div id="cust-fb-buttons-${res.id}" style="display:flex; justify-content:center; gap:10px;">
            ${hasSavedFeedback ? `
              <button onclick="enableModifyCustomerFeedback('${res.id}')"
                style="padding:11px 26px; background:var(--cp-gold, #c49a3c); color:#ffffff; font-weight:800; font-size:13px; border:none; border-radius:8px; cursor:pointer; box-shadow:0 2px 8px rgba(196,154,60,0.3); transition:all 0.2s;">
                Modify Feedback
              </button>
            ` : `
              <button onclick="saveCustomerFeedback('${res.id}')"
                style="padding:11px 26px; background:var(--cp-gold, #c49a3c); color:#ffffff; font-weight:800; font-size:13px; border:none; border-radius:8px; cursor:pointer; box-shadow:0 2px 8px rgba(196,154,60,0.3); transition:all 0.2s;">
                Save Feedback
              </button>
            `}
          </div>

        </div>

      </div>
    `;
  }

  container.innerHTML = finalHtml;
};

window.selectCustomerFeedbackRes = function (resId) {
  window._selectedFeedbackResId = resId;
  window.renderCustomerReviews();
};

window.setCustFeedbackStars = function (resId, rating) {
  if (!window._custFeedbacksData[resId]) window._custFeedbacksData[resId] = {};
  if (window._custFeedbacksData[resId].locked) return; // Prevent change if locked in saved state
  window._custFeedbacksData[resId].rating = rating;

  const starContainer = document.getElementById(`cust-fb-stars-${resId}`);
  if (starContainer) {
    const starSpans = starContainer.querySelectorAll('.cust-fb-star');
    starSpans.forEach((s, idx) => {
      const active = (idx + 1) <= rating;
      s.textContent = active ? '★' : '☆';
      s.style.color = active ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-text-dim, #9ca3af)';
    });
  }
};

window.enableModifyCustomerFeedback = function (resId) {
  const data = window._custFeedbacksData[resId] || {};
  data.locked = false;
  data.originalComment = document.getElementById(`cust-fb-text-${resId}`)?.value || data.comment || '';
  data.originalRating = data.rating || 5;

  const txtArea = document.getElementById(`cust-fb-text-${resId}`);
  if (txtArea) {
    txtArea.disabled = false;
    txtArea.readOnly = false;
    txtArea.style.opacity = '1';
    txtArea.style.background = 'var(--cp-sidebar, #ffffff)';
    txtArea.focus();
  }

  const starContainer = document.getElementById(`cust-fb-stars-${resId}`);
  if (starContainer) {
    starContainer.style.cursor = 'pointer';
  }

  const btnBox = document.getElementById(`cust-fb-buttons-${resId}`);
  if (btnBox) {
    btnBox.innerHTML = `
      <div style="display:flex; gap:10px; align-items:center;">
        <button onclick="saveCustomerFeedback('${resId}')"
          style="padding:11px 24px; background:var(--cp-gold, #c49a3c); color:#ffffff; font-weight:800; font-size:13px; border:none; border-radius:8px; cursor:pointer; box-shadow:0 2px 8px rgba(196,154,60,0.3);">
          Save Modifications
        </button>
        <button onclick="cancelModifyCustomerFeedback('${resId}')"
          style="padding:11px 20px; background:#4b5563; color:#ffffff; font-weight:700; font-size:13px; border:none; border-radius:8px; cursor:pointer;">
          Cancel
        </button>
      </div>
    `;
  }
};

window.cancelModifyCustomerFeedback = function (resId) {
  const data = window._custFeedbacksData[resId] || {};
  data.locked = true;
  data.rating = data.originalRating || data.rating || 5;

  const txtArea = document.getElementById(`cust-fb-text-${resId}`);
  if (txtArea) {
    txtArea.value = data.originalComment || data.comment || '';
    txtArea.disabled = true;
    txtArea.readOnly = true;
    txtArea.style.opacity = '0.88';
    txtArea.style.background = 'var(--cp-bg, #faf8f4)';
  }

  // Restore stars visual
  const starContainer = document.getElementById(`cust-fb-stars-${resId}`);
  if (starContainer) {
    starContainer.style.cursor = 'default';
    const starSpans = starContainer.querySelectorAll('.cust-fb-star');
    starSpans.forEach((s, idx) => {
      const active = (idx + 1) <= data.rating;
      s.textContent = active ? '★' : '☆';
      s.style.color = active ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-text-dim, #9ca3af)';
    });
  }

  const btnBox = document.getElementById(`cust-fb-buttons-${resId}`);
  if (btnBox) {
    btnBox.innerHTML = `
      <button onclick="enableModifyCustomerFeedback('${resId}')"
        style="padding:11px 26px; background:var(--cp-gold, #c49a3c); color:#ffffff; font-weight:800; font-size:13px; border:none; border-radius:8px; cursor:pointer; box-shadow:0 2px 8px rgba(196,154,60,0.3);">
        Modify Feedback
      </button>
    `;
  }
};

window.saveCustomerFeedback = async function (resId) {
  const txtArea = document.getElementById(`cust-fb-text-${resId}`);
  const comment = (txtArea?.value || '').trim();
  if (!comment) {
    alert('Please write your feedback in the box before saving.');
    return;
  }

  const data = window._custFeedbacksData[resId] || {};
  const rating = data.rating || 5;

  const user = currentUser || JSON.parse(localStorage.getItem('currentUser') || sessionStorage.getItem('currentUser') || '{}');
  const clientName = user.displayName || user.name || user.fname || 'Valued Client';
  const uid = user.id || user.uid || null;

  const res = (window._profileResCache && window._profileResCache[resId]) || (window.RESERVATIONS || []).find(r => r.id === resId) || {};
  const pkgName = res.packageName || res.package_name || res.package || res.type || 'Catering Package';

  // 1. Dual-save to Supabase: both customer_feedbacks table and reservations.execution_plan
  if (window.supabaseClient) {
    try {
      await window.supabaseClient.from('customer_feedbacks').upsert({
        reservation_id: String(resId),
        user_id: uid ? String(uid) : null,
        client_name: clientName,
        package_name: pkgName,
        rating: rating,
        comment: comment,
        updated_at: new Date().toISOString()
      }, { onConflict: 'reservation_id' });
    } catch(e) {
      console.warn('[saveCustomerFeedback] Supabase upsert notice:', e);
    }

    try {
      let curExec = {};
      const { data: curRes } = await window.supabaseClient.from('reservations').select('execution_plan').eq('id', resId).maybeSingle();
      if (curRes && curRes.execution_plan) {
        curExec = (typeof curRes.execution_plan === 'object') ? curRes.execution_plan : JSON.parse(curRes.execution_plan);
      }
      curExec.customer_feedback = {
        rating: rating,
        comment: comment,
        client_name: clientName,
        package_name: pkgName,
        saved_at: new Date().toISOString()
      };
      await window.supabaseClient.from('reservations').update({
        execution_plan: curExec
      }).eq('id', resId);

      if (res) {
        if (!res.execution_plan) res.execution_plan = {};
        if (typeof res.execution_plan === 'string') {
          try { res.execution_plan = JSON.parse(res.execution_plan); } catch(e) {}
        }
        res.execution_plan.customer_feedback = curExec.customer_feedback;
      }
      if (window._profileResCache && window._profileResCache[resId]) {
        window._profileResCache[resId].execution_plan = curExec;
      }
    } catch(e) {
      console.warn('[saveCustomerFeedback] Supabase update reservations execution_plan notice:', e);
    }
  }

  // 2. Persist in localStorage for instant access & offline guarantee
  const fbObj = {
    reservation_id: String(resId),
    user_id: uid,
    client_name: clientName,
    package_name: pkgName,
    rating: rating,
    comment: comment,
    saved_at: new Date().toISOString()
  };
  try {
    localStorage.setItem('cust_feedback_' + resId, JSON.stringify(fbObj));
    const all = JSON.parse(localStorage.getItem('all_customer_feedbacks') || '[]');
    const idx = all.findIndex(f => f.reservation_id === String(resId));
    if (idx >= 0) all[idx] = fbObj;
    else all.push(fbObj);
    localStorage.setItem('all_customer_feedbacks', JSON.stringify(all));
  } catch(e) {}

  // 3. Invalidate any local insights cache so admin analytics immediately reflects saved feedback
  if (window._insightsDataCache) {
    window._insightsDataCache = null;
  }
  if (typeof window.fetchInsightsLiveSources === 'function') {
    try { window.fetchInsightsLiveSources(); } catch(e) {}
  }

  // 4. Lock area and update buttons to Modify
  data.comment = comment;
  data.originalComment = comment;
  data.originalRating = rating;
  data.locked = true;

  if (txtArea) {
    txtArea.disabled = true;
    txtArea.readOnly = true;
    txtArea.style.opacity = '0.88';
    txtArea.style.background = 'var(--cp-bg, #faf8f4)';
  }

  const starContainer = document.getElementById(`cust-fb-stars-${resId}`);
  if (starContainer) {
    starContainer.style.cursor = 'default';
  }

  const btnBox = document.getElementById(`cust-fb-buttons-${resId}`);
  if (btnBox) {
    btnBox.innerHTML = `
      <button onclick="enableModifyCustomerFeedback('${resId}')"
        style="padding:11px 26px; background:var(--cp-gold, #c49a3c); color:#ffffff; font-weight:800; font-size:13px; border:none; border-radius:8px; cursor:pointer; box-shadow:0 2px 8px rgba(196,154,60,0.3);">
        Modify Feedback
      </button>
    `;
  }

  // Visual success banner
  const msgEl = document.getElementById(`cust-fb-msg-${resId}`);
  if (msgEl) {
    msgEl.style.display = 'block';
    msgEl.textContent = '✓ Feedback saved successfully! Thank you for sharing your experience.';
    setTimeout(() => { if (msgEl) msgEl.style.display = 'none'; }, 4000);
  }
};

// =====================================================================
// PUBLIC CLIENT REVIEWS FEED (INDEX.HTML CLIENT REVIEWS SECTION)
// Displays: 1. Message first, 2. Client name under it, 3. Rating under it
// =====================================================================
window.loadPublicClientReviews = async function () {
  const track = document.getElementById('reviews-track');
  if (!track) return;

  let reviews = [];
  const sb = window.supabaseClient;
  if (sb) {
    // 1. Try customer_feedbacks table
    try {
      const { data, error } = await sb
        .from('customer_feedbacks')
        .select('*')
        .order('created_at', { ascending: false });
      if (data && data.length) {
        reviews = data;
      }
    } catch(e) {}

    // 2. Fetch directly from reservations.execution_plan.customer_feedback in Supabase
    try {
      const { data: resList } = await sb
        .from('reservations')
        .select('id, client_name, package_name, execution_plan, created_at');
      if (Array.isArray(resList)) {
        resList.forEach(r => {
          if (!r.execution_plan) return;
          let exec = null;
          try {
            exec = typeof r.execution_plan === 'object' ? r.execution_plan : JSON.parse(r.execution_plan);
          } catch(e) {}
          if (exec && exec.customer_feedback && exec.customer_feedback.comment) {
            const fb = exec.customer_feedback;
            const rId = String(r.id);
            if (!reviews.some(x => String(x.reservation_id || x.id) === rId)) {
              reviews.push({
                id: rId,
                reservation_id: rId,
                client_name: fb.client_name || r.client_name || 'Valued Client',
                package_name: fb.package_name || r.package_name || 'Catering Package',
                rating: fb.rating || 5,
                comment: fb.comment || '',
                created_at: fb.saved_at || r.created_at || new Date().toISOString(),
                is_hidden: fb.is_hidden === true
              });
            }
          }
        });
      }
    } catch(e) {
      console.warn('[loadPublicClientReviews] reservations execution_plan fetch notice:', e);
    }
  }

  // Fallback and merge from localStorage
  try {
    const localAll = JSON.parse(localStorage.getItem('all_customer_feedbacks') || '[]');
    if (Array.isArray(localAll) && localAll.length) {
      localAll.forEach(lr => {
        if (!reviews.some(r => String(r.reservation_id || r.id) === String(lr.reservation_id || lr.id))) {
          reviews.push(lr);
        }
      });
    }
  } catch(e) {}

  // Filter out reviews hidden from web
  let hiddenIds = new Set();
  try {
    const rawHidden = JSON.parse(localStorage.getItem('hidden_feedback_ids') || '[]');
    if (Array.isArray(rawHidden)) hiddenIds = new Set(rawHidden.map(String));
  } catch(e) {}

  reviews = reviews.filter(r => {
    const fid = String(r.id || r.reservation_id || '');
    if (r.is_hidden === true || r.hidden_from_web === true || hiddenIds.has(fid)) {
      return false;
    }
    return true;
  });

  if (!reviews.length) return;

  const marqueeGroups = track.querySelectorAll('.marquee-group');
  if (!marqueeGroups.length) return;

  // Build review cards: message first, client name under it, rating under it
  const cardsHtml = reviews.map(r => {
    const numStars = Math.max(1, Math.min(5, parseInt(r.rating, 10) || 5));
    const starsStr = '★'.repeat(numStars) + '☆'.repeat(5 - numStars);
    const commentSafe = escHtml(r.comment || '');
    const clientSafe = escHtml(r.client_name || 'Valued Client');
    const safeJsName = clientSafe.replace(/'/g, "\\'");
    const safeJsText = commentSafe.replace(/'/g, "\\'");
    return `
      <div class="review-card dynamic-review-card" onclick="openReviewModal('${safeJsName}', '${starsStr}', '${safeJsText}')">
        <p class="rc-text">"${commentSafe}"</p>
        <div class="rc-author">- ${clientSafe}</div>
        <div class="rc-stars">${starsStr}</div>
      </div>
    `;
  }).join('');

  marqueeGroups.forEach(group => {
    group.querySelectorAll('.dynamic-review-card').forEach(c => c.remove());
    group.insertAdjacentHTML('afterbegin', cardsHtml);
  });
};

// Auto-trigger on landing page if reviews-track is present
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      if (document.getElementById('reviews-track')) {
        window.loadPublicClientReviews();
      }
    });
  } else {
    if (document.getElementById('reviews-track')) {
      window.loadPublicClientReviews();
    }
  }
}

window.initResdMap = async function (address, existingCoords, targetId) {
  if (!address) return;
  const targetEl = (targetId ? document.getElementById(targetId) : null)
    || document.getElementById('resd-venue-map-header')
    || document.getElementById('resd-venue-map')
    || document.getElementById('resd-map');
  if (!targetEl) return;

  const containerId = targetEl.id || 'resd-venue-map-header';
  window._resdMapInstances = window._resdMapInstances || {};

  // Safely cleanup previous map instance on this container
  if (window._resdMapInstances[containerId]) {
    try {
      window._resdMapInstances[containerId].remove();
    } catch (e) { }
    delete window._resdMapInstances[containerId];
  } else if (targetEl._leaflet_id) {
    try {
      targetEl._leaflet_id = null;
    } catch (e) { }
  }

  try {
    let coords = null;
    // 1. Use existingCoords if valid
    if (existingCoords) {
      if (typeof existingCoords === 'object') {
        const lat = existingCoords.lat ?? existingCoords.latitude ?? (Array.isArray(existingCoords) ? existingCoords[0] : null);
        const lon = existingCoords.lon ?? existingCoords.lng ?? existingCoords.longitude ?? (Array.isArray(existingCoords) ? existingCoords[1] : null);
        if (lat !== null && lon !== null && !isNaN(lat) && !isNaN(lon)) {
          coords = { lat: parseFloat(lat), lon: parseFloat(lon) };
        }
      }
    }

    // 2. Geocode using Nominatim if no coords provided
    if (!coords) {
      const rawKey = String(address).trim().toLowerCase();
      try {
        const cached = sessionStorage.getItem('geo_cache_' + rawKey);
        if (cached) {
          coords = JSON.parse(cached);
        }
      } catch (e) { }

      if (!coords) {
        try {
          const url = 'https://nominatim.openstreetmap.org/search?format=json&q=' + encodeURIComponent(address) + '&limit=1';
          const resp = await fetch(url, { headers: { 'Accept-Language': 'en-US,en;q=0.5' } });
          const data = await resp.json();
          if (Array.isArray(data) && data.length > 0) {
            coords = { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon) };
            try {
              sessionStorage.setItem('geo_cache_' + rawKey, JSON.stringify(coords));
            } catch (e) { }
          }
        } catch (fetchErr) {
          console.warn('Geocoding fetch warning:', fetchErr);
        }
      }
    }

    // 3. Fallback to Metro Manila coordinates
    const finalCoords = coords || { lat: 14.5995, lon: 120.9842 };

    if (!window.L || !L.map) return;

    // Double-check element still exists in DOM
    const curMapEl = document.getElementById(containerId);
    if (!curMapEl) return;

    const map = L.map(curMapEl).setView([finalCoords.lat, finalCoords.lon], coords ? 15 : 12);
    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap'
    }).addTo(map);

    L.marker([finalCoords.lat, finalCoords.lon]).addTo(map)
      .bindPopup(address + (coords ? '' : ' (Approximate Location)'))
      .openPopup();

    window._resdMapInstances[containerId] = map;
    window.resdMapObj = map;

    // Dismiss loading overlay
    const parent = curMapEl.parentElement;
    if (parent) {
      const loadingEl = parent.querySelector('#resd-venue-map-loading');
      if (loadingEl) loadingEl.style.display = 'none';
      const divs = parent.querySelectorAll('div');
      divs.forEach(d => {
        if (d !== curMapEl && d.textContent && d.textContent.includes('Loading Map')) {
          d.style.display = 'none';
        }
      });
    }

    // Force Leaflet to resize correctly once visible
    setTimeout(() => {
      try { map.invalidateSize(); } catch (e) { }
    }, 150);

    const etaEl = document.getElementById('resd-map-eta');
    if (etaEl) etaEl.textContent = '35 - 50 mins';
  } catch (e) {
    console.error('Map error safely caught:', e);
    const parent = targetEl.parentElement;
    if (parent) {
      const loadingEl = parent.querySelector('#resd-venue-map-loading');
      if (loadingEl) loadingEl.style.display = 'none';
    }
  }
};

