  const isCanc = String(res.status || '').toLowerCase() === 'cancelled' ||
                 String(res.cancellation_status || '').toLowerCase() === 'settled' ||
                 String(res.cancellation_status || '').toLowerCase() === 'cancelled';
  const cancMethod = combinedData.cancellation_payment_method || combinedData.cancellation_method || res.cancellation_payment_method || res.cancellation_method;
