// === DAY 5: XSS SANITIZATION ===
window.escapeHTML = function (str) {
  if (typeof str !== 'string') return '';
  return str.split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;')
    .split('"').join('&quot;')
    .split("'").join('&#39;');
};


// ===== CROSS-BROWSER CART POLLING SYNC =====
// Polls Supabase every 10 seconds and also syncs whenever the tab becomes visible.
// This is the bulletproof fallback for browsers that do not support Realtime over localhost.
let _cartPollInterval = null;

function startCartPolling() {
  stopCartPolling();
  _cartPollInterval = setInterval(async () => {
    if (document.hidden) return;
    const uid = typeof getCartUserId === 'function' ? getCartUserId() : null;
    if (!uid) return;
    try {
      const sb = window.supabaseClient || window.supabase;
      if (!sb) return;
      const { data, error } = await sb
        .from('customer_cart')
        .select('cart_data, updated_at')
        .eq('user_id', uid)
        .maybeSingle();
      if (error || !data || !data.cart_data) return;
      const loaded = JSON.parse(data.cart_data || '[]');
      if (!Array.isArray(loaded)) return;
      // Only update if the Supabase version differs from local cart
      const localStr = JSON.stringify(cart.map(c => c.id));
      const remoteStr = JSON.stringify(loaded.map(c => c.id));
      if (localStr !== remoteStr) {
        console.log('[Cart Sync] Detected cart difference : syncing from Supabase.');
        cart = loaded.slice(0, 3);
        if (typeof saveCartToStorage === 'function') saveCartToStorage();
        if (typeof renderCart === 'function') renderCart();
      }
    } catch (e) {
      // Silently ignore network errors during polling
    }
  }, 20000); // every 20 seconds while tab active (tab-switch triggers immediate sync)
}

function stopCartPolling() {
  if (_cartPollInterval) {
    clearInterval(_cartPollInterval);
    _cartPollInterval = null;
  }
}

// When tab becomes visible again (user switches back), immediately sync from Supabase
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') {
    const uid = typeof getCartUserId === 'function' ? getCartUserId() : null;
    if (uid && typeof loadCartFromSupabase === 'function') {
      console.log('[Cart Sync] Tab became visible : syncing cart from Supabase.');
      loadCartFromSupabase();
    }
  }
});

// Auto-start polling once a user is logged in; hook into setLoggedIn
const _origSetLoggedIn = typeof setLoggedIn === 'function' ? setLoggedIn : null;
(function patchCartPolling() {
  if (typeof startCartPolling === 'function') {
    // Watch for currentUser to be set, then start polling
    let _pollWatcher = setInterval(() => {
      const uid = typeof getCartUserId === 'function' ? getCartUserId() : null;
      if (uid) {
        clearInterval(_pollWatcher);
        startCartPolling();
        console.log('[Cart Sync] Polling started for user:', uid);
      }
    }, 1000);
  }
})();

window.startCartPolling = startCartPolling;
window.stopCartPolling = stopCartPolling;






window.validateMeetingTimeModal = function() {
  let allValid = true;
  const dateEl = document.getElementById('mt-date-input');
  const startEl = document.getElementById('mt-start-input');
  const endEl = document.getElementById('mt-end-input');
  if (!dateEl || !startEl || !endEl) return false;

  const setError = (el, msg) => {
    el.classList.add('field-error');
    el.classList.remove('field-valid');
    let tooltip = el.parentElement.querySelector('.cpkg-field-tooltip');
    if (!tooltip) {
      tooltip = document.createElement('span');
      tooltip.className = 'cpkg-field-tooltip';
      el.parentElement.style.position = 'relative';
      el.parentElement.appendChild(tooltip);
    }
    tooltip.textContent = msg;
    el.title = msg;
  };

  const setValid = (el) => {
    el.classList.remove('field-error');
    el.classList.add('field-valid');
    let tooltip = el.parentElement.querySelector('.cpkg-field-tooltip');
    if (tooltip) tooltip.remove();
    el.title = '';
  };

  [dateEl, startEl, endEl].forEach(setValid);

  if (!dateEl.value) { setError(dateEl, 'Please select a date.'); allValid = false; }
  if (!startEl.value) { setError(startEl, 'Please select a start time.'); allValid = false; }
  if (!endEl.value) { setError(endEl, 'Please select an end time.'); allValid = false; }

  if (dateEl.value) {
    const meetDate = new Date(dateEl.value + 'T00:00:00');
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const minMeetDate = new Date(today); minMeetDate.setDate(today.getDate() + 1); minMeetDate.setHours(0, 0, 0, 0);
    const maxMeetDate = new Date(today); maxMeetDate.setDate(today.getDate() + 7); maxMeetDate.setHours(23, 59, 59, 999);
    
    if (meetDate < minMeetDate || meetDate > maxMeetDate) {
      setError(dateEl, 'Date must be between tomorrow and 7 days from now.');
      allValid = false;
    }
  }

  if (startEl.value && endEl.value) {
    const toMinutes = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
    const startMin = toMinutes(startEl.value);
    const endMin = toMinutes(endEl.value);
    if ((endMin - startMin) < 120) {
      setError(startEl, 'Meeting must be at least 2 hours.');
      setError(endEl, 'Meeting must be at least 2 hours.');
      allValid = false;
    }
  }
  return allValid;
};
function toggleCpkgBottom(show) {
  const wrapper = document.getElementById('cpkg-bottom-wrapper');
  const hideBtn = document.getElementById('cpkg-bottom-hide-btn');
  const showBtn = document.getElementById('cpkg-bottom-show-btn');
  if (show) {
    if(wrapper) wrapper.style.display = 'block';
    if(hideBtn) hideBtn.style.display = 'block';
    if(showBtn) showBtn.style.display = 'none';
  } else {
    if(wrapper) wrapper.style.display = 'none';
    if(hideBtn) hideBtn.style.display = 'none';
    if(showBtn) showBtn.style.display = 'block';
  }
}
window.toggleCpkgBottom = toggleCpkgBottom;











// --- SAVED PACKAGES (TEMPLATES) ---
async function getEffectiveCustomerAuth() {
  let uEmail = (window.currentUser && window.currentUser.email) || (window.supabaseUser && window.supabaseUser.email) || '';
  let uId = (window.currentUser && (window.currentUser.uid || window.currentUser.id)) || (window.supabaseUser && window.supabaseUser.id) || '';

  if (!uEmail || !uId) {
    try {
      const stored = localStorage.getItem('halden_customer');
      if (stored) {
        const p = JSON.parse(stored);
        if (p.email && !uEmail) uEmail = p.email;
        if ((p.uid || p.id) && !uId) uId = p.uid || p.id;
      }
    } catch(e) {}
  }

  if ((!uEmail || !uId) && window.supabaseClient) {
    try {
      const authUser = (await window.supabaseClient.auth.getUser())?.data?.user;
      if (authUser) {
        if (!uId) uId = authUser.id;
        if (!uEmail) uEmail = authUser.email;
      }
    } catch (e) {}
  }

  if ((!uEmail || !uId) && window.supabaseClient) {
    try {
      const authSession = (await window.supabaseClient.auth.getSession())?.data?.session?.user;
      if (authSession) {
        if (!uId) uId = authSession.id;
        if (!uEmail) uEmail = authSession.email;
      }
    } catch (e) {}
  }

  return { email: uEmail, id: uId };
}

window.saveReservationTemplate = async function(resId) {
  if (!window.supabaseClient && !window.supabaseBackupClient) return alert('Database connection not established.');

  const resData = window._profileResCache && window._profileResCache[resId];
  if (!resData) return alert('Reservation data not found.');

  const btn = event?.currentTarget;
  const oldText = btn ? btn.textContent : 'Save';
  if (btn) {
    btn.textContent = 'Saving...';
    btn.disabled = true;
  }

  try {
    const auth = await getEffectiveCustomerAuth();
    if (!auth.id && !auth.email) {
      alert('You must be logged in to save a reservation template.');
      return;
    }

    const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(auth.id || '');
    const effectiveUserId = isUUID ? auth.id : null;

    if (!resData.email && auth.email) resData.email = auth.email;
    if (!resData.client_email && auth.email) resData.client_email = auth.email;
    if (auth.id) resData.user_id = auth.id;

    // Check count on client
    const client = window.supabaseClient || window.supabaseBackupClient;
    if (effectiveUserId && client) {
      const { count, error: countErr } = await client.from('saved_reservations').select('*', { count: 'exact', head: true }).eq('user_id', effectiveUserId);
      if (!countErr && count >= 10) {
        alert('You have reached the maximum limit of 10 saved packages. Please delete an existing package before saving a new one.');
        return;
      }
    }

    // Ensure full items array with all customizations (customQty, specifications, customPax) is captured
    if (!resData.items || !resData.items.length) {
      if (Array.isArray(window.customPkgItems) && window.customPkgItems.length > 0) {
        resData.items = JSON.parse(JSON.stringify(window.customPkgItems));
      } else if (resData.packageItems && resData.packageItems.length > 0) {
        resData.items = JSON.parse(JSON.stringify(resData.packageItems));
      }
    }
    const rowPayload = {
      user_id: effectiveUserId,
      reservation_data: resData
    };

    let savedOk = false;
    if (window.supabaseClient) {
      const { error } = await window.supabaseClient.from('saved_reservations').insert([rowPayload]);
      if (!error) savedOk = true;
    }
    if (window.supabaseBackupClient) {
      try {
        await window.supabaseBackupClient.from('saved_reservations').insert([rowPayload]);
        savedOk = true;
      } catch(e) {}
    }

    if (!savedOk) {
      throw new Error('Failed to save to database.');
    }

    alert('Reservation saved successfully! You can find it in the Saved Packages tab.');
    if (typeof renderSavedReservations === 'function') renderSavedReservations();
  } catch (err) {
    console.error('Error saving template:', err);
    alert('Failed to save template. Please try again.');
  } finally {
    if (btn) {
      btn.textContent = oldText;
      btn.disabled = false;
    }
  }
};

window.renderSavedReservations = async function() {
  const container = document.getElementById('saved-res-list');
  if (!container) return;

  if (!window.supabaseClient && !window.supabaseBackupClient) {
    container.innerHTML = '<div style="color:var(--red);">Database not connected.</div>';
    return;
  }

  container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--cp-text-dim);">Loading saved templates...</div>';

  try {
    const auth = await getEffectiveCustomerAuth();
    if (!auth.id && !auth.email) {
      container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--cp-text-dim);">Please log in to view saved templates.</div>';
      return;
    }

    const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(auth.id || '');
    const allDocs = new Map();
    const clients = [window.supabaseClient, window.supabaseBackupClient].filter(Boolean);

    for (const c of clients) {
      try {
        if (isUUID) {
          const { data: byId } = await c.from('saved_reservations').select('*').eq('user_id', auth.id).order('created_at', { ascending: false });
          (byId || []).forEach(row => { if (row && row.id) allDocs.set(row.id, row); });
        }
      } catch (e) {}

      try {
        const { data: allRows } = await c.from('saved_reservations').select('*').order('created_at', { ascending: false });
        (allRows || []).forEach(row => {
          if (!row || !row.id || allDocs.has(row.id)) return;
          const r = row.reservation_data || {};
          const rEmail = String(r.email || r.client_email || r.clientEmail || r.customerEmail || '').toLowerCase();
          const targetEmail = String(auth.email || '').toLowerCase();
          const matchesEmail = targetEmail && rEmail === targetEmail;
          const matchesId = auth.id && (row.user_id === auth.id || r.user_id === auth.id || r.uid === auth.id);
          if (matchesEmail || matchesId) {
            allDocs.set(row.id, row);
          }
        });
      } catch (e) {}
    }

    const data = Array.from(allDocs.values());
    data.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));

    if (data.length === 0) {
      container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--cp-text-dim); background:var(--cp-bg3); border-radius:12px; border:1px solid var(--cp-border);">No saved reservation templates yet. Save one from My Reservations!</div>';
      return;
    }

    // Cache the saved templates so modify can access the data
    window._savedTemplatesCache = {};

    container.innerHTML = data.map(saved => {
      const res = saved.reservation_data || {};
      window._savedTemplatesCache[saved.id] = res;

      const pkgName = res.packageName || 'Custom Package';
      const type = res.type || 'Event';
      const pax = res.pax || 0;
      const amount = res.amount || res.total || res.price || 0;
      const venue = res.venue || res.venueAddress || 'No venue specified';
      const createdDate = new Date(saved.created_at).toLocaleDateString();

      return `
        <div style="background:var(--cp-bg2); border:1px solid var(--cp-border); border-radius:12px; padding:20px; box-shadow:0 2px 8px rgba(0,0,0,0.2); cursor:pointer;" onclick="openSavedReservationModal('${saved.id}')">
          <div style="display:flex; justify-content:space-between; align-items:flex-start;">
            <div>
              <div style="font-size:16px; font-weight:700; color:var(--cp-cream); margin-bottom:4px;">${escHtml(pkgName)}</div>
              <div style="font-size:12px; color:var(--cp-text-mid); margin-bottom:10px;">Saved on ${createdDate} &bull; ${escHtml(type)}</div>
              <div style="font-size:12px; color:var(--cp-text-dim); display:flex; gap:12px; margin-bottom:10px;">
                <span>${pax} pax</span>
                <span>|</span>
                <span style="color:var(--cp-gold); font-weight:700;">&#8369;${safeNum(amount).toLocaleString()}</span>
              </div>
              <div style="font-size:12px; color:var(--cp-text-dim);">${escHtml(venue)}</div>
            </div>
            <div style="display:flex; gap:10px; flex-direction:column;">
              <button onclick="event.stopPropagation(); modifySavedReservation('${saved.id}')" style="background:var(--cp-gold, #c49a3c); color:#ffffff; border:none; border-radius:6px; padding:8px 16px; font-size:12px; font-weight:700; cursor:pointer; width:100px;">Modify</button>
              <button onclick="event.stopPropagation(); deleteSavedReservation('${saved.id}')" style="background:#dc2626; color:#ffffff; border:none; border-radius:6px; padding:8px 16px; font-size:12px; font-weight:700; cursor:pointer; width:100px;">Delete</button>
            </div>
          </div>
        </div>
      `;
    }).join('');

  } catch (err) {
    console.error('Error fetching saved packages:', err);
    container.innerHTML = '<div style="color:var(--cp-red);">Failed to load saved templates.</div>';
  }
};

window.openSavedReservationModal = function(savedId) {
  const resData = (window._savedTemplatesCache && window._savedTemplatesCache[savedId]) || (window._profileResCache && window._profileResCache[savedId]);
  if (!resData) return;

  if (!window._profileResCache) window._profileResCache = {};
  window._profileResCache[savedId] = resData;
  window._currentSavedTemplateId = savedId;

  window.openCustomerResModal(savedId);

  const btnExport = document.getElementById('btn-export-quotation');
  if (btnExport) btnExport.style.display = 'none';

  let btnMod = document.getElementById('btn-modal-modify-template');
  if (!btnMod && btnExport && btnExport.parentElement) {
    btnMod = document.createElement('button');
    btnMod.id = 'btn-modal-modify-template';
    btnMod.style.cssText = 'padding:8px 18px; background:linear-gradient(135deg,#b8860b,#c9a040); color:#fff; border:none; border-radius:9px; font-size:12px; font-weight:700; cursor:pointer; letter-spacing:0.5px; box-shadow:0 4px 14px rgba(184,134,11,0.30); margin-right:8px;';
    btnMod.textContent = 'Modify Package';
    btnMod.onclick = function() {
      if (typeof window.closeCustomerResModal === 'function') window.closeCustomerResModal();
      window.modifySavedReservation(window._currentSavedTemplateId);
    };
    btnExport.parentElement.insertBefore(btnMod, btnExport);
  }
  if (btnMod) btnMod.style.display = 'inline-block';

  const statusBadge = document.getElementById('crm-status-badge');
  if (statusBadge) statusBadge.textContent = 'Saved Template';
};

window.modifySavedReservation = function(savedId) {
  let resData = (window._savedTemplatesCache && window._savedTemplatesCache[savedId])
    || (window._profileResCache && window._profileResCache[savedId]);
  
  if (!resData && window._savedTemplatesCache) {
    const list = Object.values(window._savedTemplatesCache);
    resData = list.find(r => r && (r.id === savedId || r.reservation_id === savedId));
  }

  if (!resData) {
    alert('Template data not found. Please refresh and try again.');
    return;
  }

  const cleanObj = {
    id: resData.id,
    packageName: resData.packageName || resData.package_name || 'Custom Package',
    pax: resData.pax,
    date: resData.date,
    time: resData.time || resData.timeframe || '',
    callTime: resData.callTime || resData.call_time || '',
    venue: resData.venue || '',
    venueLocation: resData.venueLocation || resData.venue_location || '',
    theme: resData.theme || '',
    type: resData.type || '',
    description: resData.description || '',
    isVIP: !!resData.isVIP,
    vipCount: resData.vipCount || 0,
    vipService: resData.vipService || '',
    eventSetup: resData.eventSetup || 'Custom Setup',
    eventSetupSlug: resData.eventSetupSlug || 'custom',
    packageOrigin: 'custom',
    pricingMode: 'item-based',
    items: resData.items || resData.custom_items || resData.packageItems || [],
    custom_items: resData.items || resData.custom_items || resData.packageItems || [],
    packageItems: (resData.packageItems || resData.items || []).map(i => typeof i === 'string' ? i : (i.name || '')),
    proposedMeetingTimes: resData.proposedMeetingTimes || resData.meeting_times || []
  };

  try {
    const str = JSON.stringify(cleanObj);
    sessionStorage.setItem('halden_modify_res', str);
    localStorage.setItem('halden_modify_res_backup', str);
  } catch(e) {
    console.error('Error saving modify reservation:', e);
  }

  window.location.href = 'index.html?action=modify#catalog';
};

window.deleteSavedReservation = async function(savedId) {
  if (!confirm('Are you sure you want to delete this saved reservation template?')) return;

  try {
    if (window.supabaseClient) {
      await window.supabaseClient.from('saved_reservations').delete().eq('id', savedId);
    }
    if (window.supabaseBackupClient) {
      try {
        await window.supabaseBackupClient.from('saved_reservations').delete().eq('id', savedId);
      } catch(e) {}
    }
    if (typeof renderSavedReservations === 'function') renderSavedReservations();
  } catch (err) {
    console.error('Error deleting template:', err);
    alert('Failed to delete template.');
  }
};



