window._customCalYear = null;
window._customCalMonth = null;

function openCustomEventDateCalendarModal(targetYear, targetMonth) {
  const modal = document.getElementById('custom-event-date-modal');
  const backdrop = document.getElementById('custom-event-date-backdrop');
  if (!modal || !backdrop) return;

  const now = new Date();
  const curVal = document.getElementById('cpkg-date')?.value || document.getElementById('cmod-date')?.value;
  
  if (typeof targetYear === 'number' && typeof targetMonth === 'number') {
    window._customCalYear = targetYear;
    window._customCalMonth = targetMonth;
  } else if (curVal && /^\d{4}-\d{2}-\d{2}$/.test(curVal)) {
    const parts = curVal.split('-').map(Number);
    window._customCalYear = parts[0];
    window._customCalMonth = parts[1] - 1;
  } else if (window._customCalYear === null) {
    window._customCalYear = now.getFullYear();
    window._customCalMonth = now.getMonth();
  }

  renderCustomEventCalendar();
  backdrop.style.display = 'block';
  modal.style.display = 'block';
}

function closeCustomEventDateCalendarModal() {
  const modal = document.getElementById('custom-event-date-modal');
  const backdrop = document.getElementById('custom-event-date-backdrop');
  if (modal) modal.style.display = 'none';
  if (backdrop) backdrop.style.display = 'none';
}

function populateCustomCalYearSelect(selectEl, baseYear, selectedYear) {
  if (!selectEl) return;
  const startY = baseYear || new Date().getFullYear();
  const endY = startY + 50;
  let opts = '';
  for (let yr = startY; yr <= endY; yr++) {
    const sel = (selectedYear && parseInt(selectedYear, 10) === yr) ? ' selected' : '';
    opts += `<option value="${yr}"${sel}>${yr}</option>`;
  }
  selectEl.innerHTML = opts;
  if (selectedYear) {
    selectEl.value = String(selectedYear);
  }
}
window.populateCustomCalYearSelect = populateCustomCalYearSelect;

function onCustomCalSelectChange() {
  const mSel = document.getElementById('custom-cal-month-select');
  const ySel = document.getElementById('custom-cal-year-select');
  if (!mSel || !ySel) return;
  const now = new Date();
  let y = parseInt(ySel.value, 10);
  let m = parseInt(mSel.value, 10);
  if (isNaN(y)) y = now.getFullYear();
  if (isNaN(m)) m = now.getMonth();

  // Keep year within allowed range (current year to +50 years)
  const maxLimitYear = now.getFullYear() + 50;
  if (y > maxLimitYear) {
    y = maxLimitYear;
    ySel.value = String(y);
  } else if (y < now.getFullYear()) {
    y = now.getFullYear();
    ySel.value = String(y);
  }

  window._customCalYear = y;
  window._customCalMonth = m;
  renderCustomEventCalendar();
}
window.onCustomCalSelectChange = onCustomCalSelectChange;

function navCustomEventCalendar(delta) {
  if (window._customCalYear === null) {
    const now = new Date();
    window._customCalYear = now.getFullYear();
    window._customCalMonth = now.getMonth();
  }
  let y = window._customCalYear;
  let m = window._customCalMonth + delta;
  if (m < 0) {
    m = 11;
    y--;
  } else if (m > 11) {
    m = 0;
    y++;
  }

  // Prevent navigating before current year
  const now = new Date();
  if (y < now.getFullYear()) {
    return;
  }
  // Max 50 years ahead
  const maxLimitYear = now.getFullYear() + 50;
  if (y > maxLimitYear) {
    return;
  }

  window._customCalYear = y;
  window._customCalMonth = m;
  renderCustomEventCalendar();
}

function renderCustomEventCalendar() {
  const y = window._customCalYear;
  const m = window._customCalMonth;
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  
  const titleEl = document.getElementById('custom-cal-month-year');
  const gridEl = document.getElementById('custom-cal-days-grid');
  const prevBtn = document.getElementById('btn-custom-cal-prev');
  const nextBtn = document.getElementById('btn-custom-cal-next');

  const mSel = document.getElementById('custom-cal-month-select');
  const ySel = document.getElementById('custom-cal-year-select');

  if (mSel && ySel) {
    if (!ySel.options || ySel.options.length === 0 || !ySel.querySelector(`option[value="${y}"]`)) {
      if (typeof populateCustomCalYearSelect === 'function') {
        populateCustomCalYearSelect(ySel, now.getFullYear(), y);
      }
    }
    ySel.value = String(y);

    // Months are never locked in the dropdown area - keep all months unlocked and selectable
    Array.from(mSel.options).forEach(opt => {
      opt.disabled = false;
    });
    mSel.value = String(m);
  } else if (titleEl) {
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    titleEl.textContent = `${monthNames[m]} ${y}`;
  }

  // Prev / Next button states
  if (prevBtn) {
    prevBtn.disabled = (y <= now.getFullYear() && m <= 0);
  }
  if (nextBtn) {
    const maxLimitYear2 = now.getFullYear() + 50;
    nextBtn.disabled = (y >= maxLimitYear2 && m >= 11);
  }

  if (!gridEl) return;

  // Build reservations count per date map from all cached reservations
  const resCountMap = {};
  const allRes = (Array.isArray(window._allReservationsCache) && window._allReservationsCache.length > 0)
    ? window._allReservationsCache
    : ((typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS : []);

  allRes.forEach(r => {
    const st = String(r.status || '').toLowerCase().trim();
    if (st === 'cancelled' || st === 'rejected') return;
    const dKey = (typeof _normalizeDateKey === 'function' ? _normalizeDateKey(r.date) : null) || (r.date ? String(r.date).split('T')[0] : null);
    if (dKey) {
      resCountMap[dKey] = (resCountMap[dKey] || 0) + 1;
    }
  });

  const selectedDateVal = document.getElementById('cpkg-date')?.value || document.getElementById('cmod-date')?.value || '';

  // Calculate days in month
  const firstDay = new Date(y, m, 1).getDay(); // 0 = Sunday
  const daysInMonth = new Date(y, m + 1, 0).getDate();

  let html = '';

  // Empty cells for leading days
  for (let i = 0; i < firstDay; i++) {
    html += '<div class="custom-cal-day-cell cal-day-empty"></div>';
  }

  // Event booking window: minimum 14 days, up to 50 years ahead
  const minEventDateObj = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 14);
  const minEventDateStr = `${minEventDateObj.getFullYear()}-${String(minEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(minEventDateObj.getDate()).padStart(2, '0')}`;
  const maxEventDateObj = new Date(now.getFullYear() + 50, now.getMonth(), now.getDate());
  const maxEventDateStr = `${maxEventDateObj.getFullYear()}-${String(maxEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(maxEventDateObj.getDate()).padStart(2, '0')}`;

  // Populate days of month
  for (let dayNum = 1; dayNum <= daysInMonth; dayNum++) {
    const dateKey = `${y}-${String(m + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
    const isPast = (dateKey < todayStr);
    const isWithin14Days = (!isPast && dateKey < minEventDateStr);
    const isBeyond50Years = (!isPast && dateKey > maxEventDateStr);
    const count = resCountMap[dateKey] || 0;
    const isDisabledByAdmin = (window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(dateKey));
    const isHardDisabled = (typeof isDayHardDisabled === 'function' && isDayHardDisabled(dateKey));
    const isLockedFull = (count >= 3);
    const isSelected = (selectedDateVal === dateKey);

    let cellClasses = ['custom-cal-day-cell'];
    let badgeText = '';

    if (isPast) {
      cellClasses.push('cal-day-past');
      badgeText = '<span class="custom-cal-day-badge">Past</span>';
    } else if (isWithin14Days) {
      cellClasses.push('cal-day-locked cal-day-near');
      badgeText = '<span class="custom-cal-day-badge">Within 14 Days</span>';
    } else if (isBeyond50Years) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Beyond 50 Yrs</span>';
    } else if (isHardDisabled) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Hard Disabled</span>';
    } else if (isDisabledByAdmin) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Unavailable</span>';
    } else if (isLockedFull) {
      cellClasses.push('cal-day-locked');
      badgeText = '<span class="custom-cal-day-badge">Locked (3/3)</span>';
    } else if (count === 2) {
      cellClasses.push('cal-day-2events');
      badgeText = '<span class="custom-cal-day-badge">2 events</span>';
    } else if (count === 1) {
      cellClasses.push('cal-day-1event');
      badgeText = '<span class="custom-cal-day-badge">1 event</span>';
    } else {
      cellClasses.push('cal-day-avail');
      badgeText = '<span class="custom-cal-day-badge">Available</span>';
    }

    if (isSelected) {
      cellClasses.push('cal-day-selected');
    }

    const clickAttr = (!isPast && !isWithin14Days && !isBeyond50Years && !isDisabledByAdmin && !isHardDisabled && !isLockedFull)
      ? `onclick="selectCustomEventDate('${dateKey}')"`
      : '';

    html += `
      <div class="${cellClasses.join(' ')}" ${clickAttr} title="${dateKey}: ${count} reservation(s)">
        <span class="custom-cal-day-num">${dayNum}</span>
        ${badgeText}
      </div>
    `;
  }

  gridEl.innerHTML = html;
}

function selectCustomEventDate(dateKey) {
  const now = new Date();
  const minEventDateObj = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 14);
  const minEventDateStr = `${minEventDateObj.getFullYear()}-${String(minEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(minEventDateObj.getDate()).padStart(2, '0')}`;
  const maxEventDateObj = new Date(now.getFullYear() + 50, now.getMonth(), now.getDate());
  const maxEventDateStr = `${maxEventDateObj.getFullYear()}-${String(maxEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(maxEventDateObj.getDate()).padStart(2, '0')}`;

  if (dateKey < minEventDateStr) {
    const msg = 'Your event date is too soon. The business requires a minimum of 14 days notice for event preparation. Please select a date at least 14 days from today.';
    if (typeof showToast === 'function') showToast(msg, 'warning');
    else alert(msg);
    return;
  }
  if (dateKey > maxEventDateStr) {
    const msg = 'The event date you selected is too far into the future. The business does not accept bookings more than 50 years in advance.';
    if (typeof showToast === 'function') showToast(msg, 'warning');
    else alert(msg);
    return;
  }
  const dateInput = document.getElementById('cpkg-date');
  if (dateInput) {
    dateInput.value = dateKey;
  }
  const cmodDate = document.getElementById('cmod-date');
  if (cmodDate) {
    cmodDate.value = dateKey;
    if (window.customerModifyingRes) {
      window.customerModifyingRes.date = dateKey;
      window.customerModifyingRes.event_date = dateKey;
    }
  }
  if (typeof renderCustomPkg === 'function') renderCustomPkg();
  if (typeof validateCpkgField === 'function') validateCpkgField('cpkg-date');
  if (typeof checkEventDateConflicts === 'function') checkEventDateConflicts();
  if (typeof debouncedSyncCustomerActiveDraft === 'function') debouncedSyncCustomerActiveDraft();
  closeCustomEventDateCalendarModal();
}

window.openCustomEventDateCalendarModal = openCustomEventDateCalendarModal;
window.closeCustomEventDateCalendarModal = closeCustomEventDateCalendarModal;
window.navCustomEventCalendar = navCustomEventCalendar;
window.renderCustomEventCalendar = renderCustomEventCalendar;
window.selectCustomEventDate = selectCustomEventDate;



