window.HARD_DISABLED_DAYS = [];

async function loadHardDisabledDays() {
  try {
    const saved = localStorage.getItem('smartserve_hard_disabled_days');
    if (saved) {
      window.HARD_DISABLED_DAYS = JSON.parse(saved);
    }
  } catch (e) {}

  try {
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      const { data, error } = await sb.from('hard_disabled_days').select('*').order('day_of_week', { ascending: true });
      if (!error && Array.isArray(data) && data.length > 0) {
        window.HARD_DISABLED_DAYS = data;
        localStorage.setItem('smartserve_hard_disabled_days', JSON.stringify(data));
      }
    }
  } catch (e) {
    // Graceful fallback if table is not yet created
  }
  return window.HARD_DISABLED_DAYS;
}
window.loadHardDisabledDays = loadHardDisabledDays;
try { loadHardDisabledDays(); } catch (e) {}

window.customerModifyingCatFilter = 'all';
window.customerModifyingSearch = '';

function isDayHardDisabled(dateVal) {
  if (!dateVal) return false;
  let d = null;
  if (dateVal instanceof Date) d = dateVal;
  else if (typeof dateVal === 'string') {
    const parts = dateVal.split('-');
    if (parts.length === 3) d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    else d = new Date(dateVal);
  }
  if (!d || isNaN(d.getTime())) return false;
  const dow = d.getDay(); // 0 is Sunday, 1 is Monday ...
  
  const list = window.HARD_DISABLED_DAYS;
  if (Array.isArray(list)) {
    const match = list.find(x => x.day_of_week === dow);
    if (match && match.is_disabled) return true;
  }
  try {
    const saved = localStorage.getItem('smartserve_hard_disabled_days');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        const match = parsed.find(x => x.day_of_week === dow);
        if (match && match.is_disabled) return true;
      }
    }
  } catch (e) {}
  return false;
}
window.isDayHardDisabled = isDayHardDisabled;

window.syncCustomerAIFabVisibility = function (forcedDashTab) {
  const deskAiFab = document.getElementById('desk-ai-fab');
  if (!deskAiFab) return;
  const resDetailsTabEl = document.getElementById('dash-tab-resdetails');
  // Only apply strict hide rules on customer.html
  if (!resDetailsTabEl) return;

  const isResDetailsDashActive = forcedDashTab
    ? (forcedDashTab === 'resdetails')
    : resDetailsTabEl.classList.contains('active');
  const isMainDetailsSubTab = (typeof resDetailsActiveTab === 'undefined' || resDetailsActiveTab === 'details');
  const shouldShow = !!(isResDetailsDashActive && isMainDetailsSubTab && window.customerModifyMode);

  deskAiFab.style.display = shouldShow ? 'flex' : 'none';
  if (!shouldShow && typeof window.closeDeskAI === 'function') {
    window.closeDeskAI();
  }
};

window.getCustomerModifyOrigin = function (resObj) {
  const res = resObj || window.customerModifyingRes;
  if (!res) return 'custom';
  const mode = String(res.pricingMode || res.pricing_mode || '').toLowerCase();
  if (mode === 'majorly_set' || mode === 'majorly set' || mode === 'tiered') return 'majorly set';
  if (mode === 'per_head' || mode === 'per head' || mode === 'dynamically_set' || mode === 'dynamically set') return 'dynamically set';

  const storedOrigin = String(res.packageOrigin || res.package_origin || '').toLowerCase();
  if (storedOrigin === 'majorly set' || storedOrigin === 'majorly_set') return 'majorly set';
  if (storedOrigin === 'dynamically set' || storedOrigin === 'dynamically_set') return 'dynamically set';

  const tiers = res.priceTiers || res.price_tiers;
  if (Array.isArray(tiers) && tiers.length > 0) return 'majorly set';
  const pph = parseFloat(res.pricePerHead || res.price_per_head || 0);
  if (pph > 0) return 'dynamically set';

  const premadeName = res.premadePackageName || res.premade_package_name || '';
  const pkgLookupName = premadeName || res.packageName || res.package_name || '';
  const matchedPkg = (typeof PKGS !== 'undefined' && Array.isArray(PKGS))
    ? PKGS.find(p => p && p.name && p.name.toLowerCase() === pkgLookupName.toLowerCase())
    : null;
  if (matchedPkg) {
    const pm = String(matchedPkg.pricingMode || matchedPkg.pricing_mode || '').toLowerCase();
    if (pm === 'majorly_set' || pm === 'tiered' || (Array.isArray(matchedPkg.priceTiers) && matchedPkg.priceTiers.length > 0)) return 'majorly set';
    return 'dynamically set';
  }
  if (premadeName) return 'majorly set';
  return 'custom';
};

window.isCustomerModifySubOption = function (item) {
  if (!item) return false;
  const ident = String(item.identify || '').toLowerCase();
  const cat = String(item.cat || item.category || '').toLowerCase();
  if (ident === 'mobile_bar_option' || ident === 'ice_cream_option') return true;
  if (cat === 'drink' && ident !== 'drinks_package' && ident !== 'mobile_bar' && !(item.name || '').toLowerCase().includes('unlimited drinks')) return true;
  if (typeof window.getSpecialParentKey === 'function' && window.getSpecialParentKey(item)) return true;
  return false;
};

window.computeCustomerModifyItemPrice = function (item, currentPax) {
  if (!item || item.isFree) return 0;
  if (window.isCustomerModifySubOption(item)) return 0;
  const pCount = parseInt(currentPax) || 50;
  const cat = String(item.cat || item.category || '').toLowerCase();
  const isEq = cat === 'equipment';

  // If snapshotPrice is already set and user hasn't invalidated it, use it directly for 0 discrepancy
  if (item.snapshotPrice != null && !isNaN(Number(item.snapshotPrice)) && Number(item.snapshotPrice) >= 0 && !item._needsRecalc) {
    return Number(item.snapshotPrice);
  }

  const cItem = (typeof CAT !== 'undefined' && Array.isArray(CAT))
    ? CAT.find(c => String(c.id) === String(item.id) || (c.name && item.name && c.name.toLowerCase() === item.name.toLowerCase()))
    : null;
  const unitP = parseFloat(item.price ?? cItem?.price ?? 0) || 0;

  if (isEq) {
    const qty = parseInt(item.customQty ?? item.autoQty ?? 1) || 1;
    return unitP * qty;
  }

  const effPax = (item.customPax != null && parseInt(item.customPax) > 0) ? parseInt(item.customPax) : pCount;
  const pType = String(item.pricingType || cItem?.pricingType || '').toLowerCase();
  const itemNameLow = String(item.name || '').toLowerCase();
  if (pType === 'per_5_pax' && (itemNameLow.includes('ice cream') || itemNameLow.includes('unlimited drinks'))) {
    // Check if Unlimited Drinks was originally saved as 4 batches (20 * ceil(pax/5)) vs 20 * pax
    if (itemNameLow.includes('unlimited drinks') && item._origUnitMode === 'per_5_batch') {
      return Math.ceil(effPax / 5) * unitP;
    }
    if (itemNameLow.includes('ice cream')) {
      return Math.ceil(effPax / 5) * unitP;
    }
  }

  if (item.customPax != null && parseInt(item.customPax) > 0) {
    const tempObj = Object.assign({}, cItem || {}, item, { customPax: parseInt(item.customPax) });
    if (typeof getDynamicPrice === 'function') return getDynamicPrice(tempObj, pCount);
    return unitP * parseInt(item.customPax);
  }

  if (cItem && typeof getDynamicPrice === 'function') {
    return getDynamicPrice(Object.assign({}, cItem, item), pCount);
  }
  if (typeof getDynamicPrice === 'function') {
    return getDynamicPrice(item, pCount);
  }
  return unitP;
};

window.computeCustomerModifyPricing = function () {
  const res = window.customerModifyingRes || {};
  const origin = window.getCustomerModifyOrigin(res);
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';
  const paxEl = document.getElementById('cmod-pax');
  const currentPax = parseInt(paxEl?.value) || parseInt(res.pax) || 50;

  const cityEl = document.getElementById('cmod-city');
  const venueEl = document.getElementById('cmod-venue');
  const cityVal = cityEl ? cityEl.value : (res.venueLocation || res.venue_location || res.city || 'Malabon');
  const venueVal = venueEl ? venueEl.value : (res.venueAddress || res.venue || '');
  const isMalabon = (String(cityVal) + ' ' + String(venueVal)).toLowerCase().includes('malabon');

  let foodBase = 0, equipBase = 0, decorBase = 0, otherBase = 0;
  let basePrice = 0;
  let extraItemsTotal = 0;
  const extraItemsBreakdown = [];

  if (isPremade) {
    const parseCur = v => { if (typeof v === 'number') return v; const c = String(v || '').replace(/[^\d.-]/g, ''); return parseFloat(c) || 0; };
    if (origin === 'majorly set') {
      let tiers = res.priceTiers || res.price_tiers || [];
      if (!Array.isArray(tiers) || tiers.length === 0) {
        const pkgName = res.premadePackageName || res.premade_package_name || res.packageName || res.package_name || '';
        const foundPkg = (typeof PKGS !== 'undefined' ? PKGS : []).find(p => p && p.name && p.name.toLowerCase() === pkgName.toLowerCase());
        if (foundPkg && Array.isArray(foundPkg.priceTiers || foundPkg.price_tiers)) {
          tiers = foundPkg.priceTiers || foundPkg.price_tiers;
        }
      }
      const matchTier = Array.isArray(tiers) ? tiers.find(t => parseInt(t.pax || t.label) === currentPax) : null;
      if (matchTier && matchTier.price) {
        basePrice = parseCur(matchTier.price);
      } else if (parseCur(res.basePrice || res.base_price) > 0) {
        basePrice = parseCur(res.basePrice || res.base_price);
      } else {
        const tot = parseCur(res.amount || res.total_amount || 0);
        const stOtc = parseCur(res.outOfTownCharge || res.out_of_town_charge || 0);
        basePrice = Math.max(0, tot - stOtc);
      }
    } else {
      let perHead = parseCur(res.pricePerHead || res.price_per_head || 0);
      if (perHead <= 0) {
        const pkgName = res.premadePackageName || res.premade_package_name || res.packageName || res.package_name || '';
        const foundPkg = (typeof PKGS !== 'undefined' ? PKGS : []).find(p => p && p.name && p.name.toLowerCase() === pkgName.toLowerCase());
        if (foundPkg) perHead = parseCur(foundPkg.pricePerHead || foundPkg.price_per_head || 0);
      }
      if (perHead <= 0 && currentPax > 0) {
        const tot = parseCur(res.amount || res.total_amount || 0);
        const stOtc = parseCur(res.outOfTownCharge || res.out_of_town_charge || 0);
        perHead = Math.round(Math.max(0, tot - stOtc) / currentPax);
      }
      basePrice = currentPax * perHead;
    }

    (window.customerModifyingItems || []).forEach(item => {
      if (item && (item.isAdditional || item.addedAsExtra || item.isExtra) && !item.isFree) {
        const pVal = window.computeCustomerModifyItemPrice(item, currentPax);
        if (pVal > 0) {
          extraItemsTotal += pVal;
          extraItemsBreakdown.push({ name: item.name, price: pVal });
        }
      }
    });
    foodBase = basePrice;
  } else {
    (window.customerModifyingItems || []).forEach(item => {
      if (!item || item.isFree) return;
      const pVal = window.computeCustomerModifyItemPrice(item, currentPax);
      item.snapshotPrice = pVal;
      const cat = String(item.cat || item.category || '').toLowerCase();
      if (cat === 'equipment') equipBase += pVal;
      else if (['food', 'dessert', 'drink'].includes(cat)) foodBase += pVal;
      else if (cat === 'decoration') decorBase += pVal;
      else otherBase += pVal;
    });
    basePrice = foodBase + equipBase + decorBase + otherBase;
  }

  const subtotalBeforeOtc = basePrice + extraItemsTotal;
  const distInfo = (typeof getDistanceFeeRate === 'function')
    ? getDistanceFeeRate(cityVal, res.coordinates || res.venue_coordinates || window.lastMapCoords)
    : { percentage: 5 };
  const otcRate = (distInfo.percentage != null ? parseFloat(distInfo.percentage) : 5) / 100;
  const outOfTownCharge = isMalabon ? 0 : Math.round( basePrice * otcRate );
  const svcPct = parseFloat(res.service_charge_pct || res.serviceChargePct || 0) || 0;
  const serviceChargeAmt = svcPct > 0 ? Math.round(subtotalBeforeOtc * (svcPct / 100)) : 0;
  const grandTotal = subtotalBeforeOtc + outOfTownCharge + serviceChargeAmt;
  const downpaymentVal = Math.round(basePrice * 0.5);
  const finalBalanceVal = (basePrice - downpaymentVal) + extraItemsTotal + outOfTownCharge + serviceChargeAmt;

  return {
    origin,
    isPremade,
    currentPax,
    isMalabon,
    cityVal,
    foodBase,
    equipBase,
    decorBase,
    otherBase,
    basePrice,
    extraItemsTotal,
    extraItemsBreakdown,
    subtotal: subtotalBeforeOtc,
    outOfTownCharge,
    svcPct,
    serviceChargeAmt,
    grandTotal,
    downpaymentVal,
    finalBalanceVal
  };
};

window.buildCustomerModifyAIContext = function () {
  const res = window.customerModifyingRes;
  if (!res) return null;
  const pricing = window.computeCustomerModifyPricing();
  const budget = document.getElementById('cmod-budget')?.value.trim() || res.budget || '';
  const desc = document.getElementById('cmod-desc')?.value.trim() || res.description || '';
  const occSel = document.getElementById('cmod-occasion')?.value || res.occasion || res.type || '';
  const occOther = document.getElementById('cmod-occasion-other')?.value.trim() || '';
  const occasion = (occSel === 'Others' && occOther) ? occOther : occSel;
  const themeSel = document.getElementById('cmod-theme')?.value || res.theme || '';
  const themeOther = document.getElementById('cmod-theme-other')?.value.trim() || '';
  const theme = (themeSel === 'Others' && themeOther) ? themeOther : themeSel;
  const pax = pricing.currentPax;
  const date = document.getElementById('cmod-date')?.value.trim() || res.date || '';
  const calltime = document.getElementById('cmod-calltime')?.value.trim() || res.callTime || '';
  const tfStart = document.getElementById('cmod-timeframe-start')?.value.trim() || '';
  const tfEnd = document.getElementById('cmod-timeframe-end')?.value.trim() || '';
  const timeframe = (tfStart && tfEnd) ? `${tfStart} - ${tfEnd}` : (res.timeframe || res.time || '');
  const venueLoc = pricing.cityVal || '';
  const venue = document.getElementById('cmod-venue')?.value.trim() || res.venue || '';
  const setupEl = document.getElementById('cmod-setup');
  const setupType = setupEl ? (setupEl.options[setupEl.selectedIndex]?.text || setupEl.value) : (res.eventSetup || 'Complete Setup');
  const isCustomSetup = String(setupType).toLowerCase().includes('custom');
  const vipCheck = document.getElementById('cmod-vip-check')?.checked ?? !!(res.vip?.enabled || res.isVIP);
  const vipCount = document.getElementById('cmod-vip-count')?.value || res.vip?.count || res.vipCount || 0;
  const vipService = document.getElementById('cmod-vip-service')?.value || res.vip?.service || res.vipService || 'Properly Catered';

  let ctx = ((typeof buildAiBookingAndMeetingAvailabilityContext === 'function') ? (buildAiBookingAndMeetingAvailabilityContext() + '\n') : '') +
    "[CURRENT MODIFYING RESERVATION PACKAGE DETAILS]\n";
  ctx += `Reservation ID: #${res.id}
`;
  ctx += `Package Name: ${res.packageName || res.package_name || 'Custom Package'} (${pricing.isPremade ? 'Premade Package - Locked' : 'Custom Package'})
`;
  if (occasion) ctx += `Occasion: ${occasion}
`;
  if (theme) ctx += `Theme / Style: ${theme}
`;
  ctx += `Guest Count: ${pax} pax
`;
  if (budget) ctx += `Target Budget: ₱${parseFloat(budget).toLocaleString()}
`;
  if (date) ctx += `Event Date: ${date}
`;
  if (calltime) ctx += `Call Time: ${calltime}
`;
  if (timeframe) ctx += `Time Frame: ${timeframe}
`;
  if (venueLoc) ctx += `Venue City/Location: ${venueLoc}
`;
  if (venue) ctx += `Pinned Venue Address: ${venue}
`;
  ctx += `Event Setup Type: ${setupType} ${isCustomSetup ? '(Custom Setup Active: Automatic equipment allocation is disabled)' : '(Predefined Setup: Equipment is auto-allocated based on pax)'}
`;
  if (vipCheck) ctx += `VIP Service: ${vipCount} pax (${vipService})
`;
  if (desc) ctx += `Event Description / Special Requests: ${desc}
`;

  const itemsList = (window.customerModifyingItems || []).map(it => {
    const catLbl = String(it.cat || 'item').toUpperCase();
    const pVal = window.computeCustomerModifyItemPrice(it, pax);
    const eqInfo = (String(it.cat || '').toLowerCase() === 'equipment') ? ` [Qty: ${it.customQty || it.autoQty || 1} pcs]` : '';
    const paxInfo = it.customPax ? ` [Custom Pax: ${it.customPax}]` : '';
    const specInfo = it.specifications ? ` [Notes: "${it.specifications}"]` : '';
    return `${it.name} [${catLbl}]${eqInfo}${paxInfo}${specInfo} (${it.isFree ? 'Included' : '₱' + pVal.toLocaleString()})`;
  });

  ctx += `Included Package Items (${itemsList.length}): ${itemsList.join('; ')}
`;
  ctx += `OFFICIAL ESTIMATED PACKAGE TOTAL DISPLAYED ON SCREEN: ₱${pricing.grandTotal.toLocaleString()}
`;
  ctx += `OFFICIAL COST BREAKDOWN DISPLAYED ON SCREEN:
`;
  if (pricing.isPremade) {
    ctx += `- Premade Base Package Price: ₱${pricing.basePrice.toLocaleString()}
`;
    if (pricing.extraItemsTotal > 0) ctx += `- Extra Items Added: +₱${pricing.extraItemsTotal.toLocaleString()}
`;
  } else {
    ctx += `- Food & Beverages Subtotal: ₱${pricing.foodBase.toLocaleString()}
`;
    ctx += `- Equipment & Setup Subtotal (${setupType} for ${pax} pax): ₱${pricing.equipBase.toLocaleString()}
`;
    if (pricing.decorBase > 0) ctx += `- Styling & Decor Subtotal: ₱${pricing.decorBase.toLocaleString()}
`;
    if (pricing.otherBase > 0) ctx += `- Add-ons & Entertainment: ₱${pricing.otherBase.toLocaleString()}
`;
  }
  if (pricing.outOfTownCharge > 0) ctx += `- Out-of-Town Surcharge (+5% outside Malabon): +₱${pricing.outOfTownCharge.toLocaleString()}
`;
  if (pricing.serviceChargeAmt > 0) ctx += `- Service Charge (+${pricing.svcPct}%): +₱${pricing.serviceChargeAmt.toLocaleString()}
`;
  if (budget && !isNaN(parseFloat(budget)) && parseFloat(budget) > 0) {
    const diff = parseFloat(budget) - pricing.grandTotal;
    if (diff < 0) ctx += `Budget Warning: Current selection exceeds target budget by ₱${Math.abs(diff).toLocaleString()}
`;
    else ctx += `Remaining Budget Available: ₱${diff.toLocaleString()}
`;
  }
  return ctx;
};

window.executeAICustomerModifyAction = function (actionData, rawUserText = '') {
  const res = window.customerModifyingRes;
  if (!res) return { success: false, message: 'No active reservation in Modify Mode.' };
  const origin = window.getCustomerModifyOrigin(res);
  if (origin !== 'custom') {
    const pkgName = res.premadePackageName || res.packageName || 'Premade Package';
    return {
      success: false,
      isPremadeBlocked: true,
      message: `The active reservation uses a pre-made package ("${pkgName}"), so its package items are locked and cannot be added or removed.`
    };
  }

  window.syncCustomerModifyFormToRes();
  if (Array.isArray(window.customPkgItems) && window.customPkgItems.length > 0 && customPkgItems.length === 0) {
    customPkgItems = window.customPkgItems;
  }

  let modifiedPax = null;
  const addedItems = [];
  const removedItems = [];
  let allEquipRemoved = false;

  let targetPax = actionData?.pax || window._aiActivePax;
  if (targetPax) {
    const pVal = parseInt(targetPax, 10);
    if (!isNaN(pVal) && pVal >= 10 && pVal <= 200) {
      const paxInp = document.getElementById('cmod-pax');
      if (paxInp && parseInt(paxInp.value, 10) !== pVal) {
        paxInp.value = pVal;
        window.onCustomerModifyPaxInput(pVal);
        modifiedPax = pVal;
      }
    }
  }

  const curPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(res.pax) || 50;

  // Completely overwrite previous package in modify mode into new plan (unless combining)
  if (actionData && !actionData.combine_package && (actionData.replace_menu || actionData.is_recommended_menu || actionData.overwrite_package || actionData.action === 'apply_plan')) {
    const keepNames = [];
    const keepRegex = /(?:keep|retain|except|save|wag\s+(?:alisin|tanggalin)|huwag\s+(?:alisin|tanggalin))\s+(?:the\s+)?([A-Za-z0-9\s,'"-]+)/i;
    const keepMatch = String(rawUserText || '').match(keepRegex);
    if (keepMatch && keepMatch[1]) {
      const phrases = keepMatch[1].split(/,|and|at/i).map(s => s.trim().toLowerCase()).filter(Boolean);
      (window.customerModifyingItems || []).forEach(i => {
        const iname = String(i.name || '').toLowerCase();
        if (phrases.some(p => iname.includes(p) || p.includes(iname))) {
          keepNames.push(iname);
        }
      });
    }

    const newTargetNames = (actionData.add_items || []).map(x => (typeof x === 'string' ? x : x.name || '').toLowerCase().trim());

    window.customerModifyingItems = (window.customerModifyingItems || []).filter(i => {
      const iname = String(i.name || '').toLowerCase().trim();
      const isAutoEq = !!i.isEventSetupEquipment || !!i.isAutoAdded;
      if (isAutoEq) return true;
      if (keepNames.includes(iname)) return true;
      if (newTargetNames.includes(iname)) return true;
      removedItems.push(i.name);
      return false;
    });
  }

  if (actionData && (actionData.remove_all_equipment || actionData.action === 'remove_all_equipment')) {
    window.customerModifyingItems = (window.customerModifyingItems || []).filter(i => String(i.cat || '').toLowerCase() !== 'equipment');
    allEquipRemoved = true;
  }

  if (actionData && Array.isArray(actionData.remove_items) && actionData.remove_items.length > 0) {
    actionData.remove_items.forEach(remName => {
      const cleanRem = String(remName || '').toLowerCase().trim();
      const idx = (window.customerModifyingItems || []).findIndex(i => {
        const iname = String(i.name || '').toLowerCase().trim();
        return iname === cleanRem || iname.includes(cleanRem) || cleanRem.includes(iname);
      });
      if (idx > -1) {
        const remItem = window.customerModifyingItems[idx];
        window.customerModifyingItems.splice(idx, 1);
        removedItems.push(remItem.name);
        if (remItem.identify === 'drinks_package') {
          window.customerModifyingItems = window.customerModifyingItems.filter(c => !(c.cat === 'drink' && c.identify !== 'drinks_package' && c.identify !== 'mobile_bar' && c.identify !== 'mobile_bar_option'));
        }
        if (remItem.identify === 'mobile_bar') {
          window.customerModifyingItems = window.customerModifyingItems.filter(c => c.identify !== 'mobile_bar_option');
        }
        if (remItem.identify === 'ice_cream') {
          window.customerModifyingItems = window.customerModifyingItems.filter(c => c.identify !== 'ice_cream_flavor');
        }
      }
    });
  }

  if (actionData && Array.isArray(actionData.add_items) && actionData.add_items.length > 0) {
    actionData.add_items.forEach(itemInput => {
      const reqName = typeof itemInput === 'string' ? itemInput : itemInput?.name;
      const cleanReq = String(reqName || '').toLowerCase().trim();
      if (!cleanReq) return;
      const catItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => {
        if (!c || c.hidden || c.is_available === false) return false;
        const cn = String(c.name || '').toLowerCase().trim();
        return cn === cleanReq || cn.includes(cleanReq) || cleanReq.includes(cn);
      });
      if (!catItem) return;
      let existing = (window.customerModifyingItems || []).find(c => String(c.id) === String(catItem.id) || String(c.name || '').toLowerCase().trim() === String(catItem.name || '').toLowerCase().trim());
      if (!existing) {
        const isEq = String(catItem.cat || '').toLowerCase() === 'equipment';
        const autoQ = isEq && typeof getEquipmentAllocatedQty === 'function'
          ? getEquipmentAllocatedQty(catItem, curPax, window.customerModifyingItems)
          : 1;
        const customQ = (typeof itemInput === 'object' && itemInput.customQty) ? parseInt(itemInput.customQty) : (isEq ? autoQ : null);
        const customP = (typeof itemInput === 'object' && itemInput.customPax) ? parseInt(itemInput.customPax) : null;
        const specs = (typeof itemInput === 'object' && (itemInput.specs || itemInput.specifications)) ? (itemInput.specs || itemInput.specifications) : '';
        const newItem = {
          ...catItem,
          id: catItem.id,
          name: catItem.name,
          cat: catItem.cat || 'other',
          price: catItem.price || 0,
          image: catItem.image || catItem.image_url || 'haldens_logo.png',
          desc: catItem.desc || '',
          customQty: customQ,
          autoQty: isEq ? autoQ : null,
          customPax: customP,
          specifications: specs,
          isCustomized: !!( (typeof itemInput === 'object' && (itemInput.customQty || itemInput.customPax || specs)) ),
          isFree: window.isCustomerModifySubOption(catItem),
          _needsRecalc: true,
          _showCustomize: false
        };
        newItem.snapshotPrice = window.computeCustomerModifyItemPrice(newItem, curPax);
        delete newItem._needsRecalc;
        window.customerModifyingItems.push(newItem);
        addedItems.push(newItem.name);
      } else if (typeof itemInput === 'object') {
        if (itemInput.customQty) { existing.customQty = parseInt(itemInput.customQty); existing.isCustomized = true; existing._needsRecalc = true; }
        if (itemInput.customPax) { existing.customPax = parseInt(itemInput.customPax); existing.isCustomized = true; existing._needsRecalc = true; }
        if (itemInput.specs || itemInput.specifications) { existing.specifications = itemInput.specs || itemInput.specifications; existing.isCustomized = true; }
        existing.snapshotPrice = window.computeCustomerModifyItemPrice(existing, curPax);
        delete existing._needsRecalc;
      }
    });
  }

  if (actionData && Array.isArray(actionData.customizations) && actionData.customizations.length > 0) {
    actionData.customizations.forEach(cust => {
      const custName = String(cust.item_name || cust.name || '').toLowerCase().trim();
      const inPkg = (window.customerModifyingItems || []).find(i => String(i.name || '').toLowerCase().trim() === custName);
      if (inPkg) {
        if (cust.quantity || cust.customQty) { inPkg.customQty = parseInt(cust.quantity || cust.customQty); inPkg.isCustomized = true; inPkg._needsRecalc = true; }
        if (cust.pax || cust.customPax) { inPkg.customPax = parseInt(cust.pax || cust.customPax); inPkg.isCustomized = true; inPkg._needsRecalc = true; }
        if (cust.specs || cust.specifications) { inPkg.specifications = cust.specs || cust.specifications; inPkg.isCustomized = true; }
        inPkg.snapshotPrice = window.computeCustomerModifyItemPrice(inPkg, curPax);
        delete inPkg._needsRecalc;
      }
    });
  }

  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
  if (typeof updateDawContextBar === 'function') updateDawContextBar();

  const updatedPricing = window.computeCustomerModifyPricing();
  let confirmMsg = "I have updated your package in the Modify Package workspace.";
  const details = [];
  if (modifiedPax) details.push(`Guest count set to ${modifiedPax} pax`);
  if (addedItems.length > 0) details.push(`Added: ${addedItems.join(', ')}`);
  if (removedItems.length > 0) details.push(`Removed: ${removedItems.join(', ')}`);
  if (allEquipRemoved) details.push(`Removed all equipment`);
  if (details.length > 0) confirmMsg += ` (${details.join('; ')}).`;
  confirmMsg += `

Your updated package total is strictly ₱${updatedPricing.grandTotal.toLocaleString()} (including food, equipment, and applicable venue charges for ${updatedPricing.currentPax} guests).`;

  return {
    success: true,
    total: updatedPricing.grandTotal,
    message: confirmMsg,
    addedItems,
    removedItems,
    pax: modifiedPax
  };
};

window.modifyCustomerPackage = async function (resParam) {
  let res = resParam || null;
  if (!res && activeResDetailId) {
    res = (window.RESERVATIONS || []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  }
  if (!res && window.activeCustomerReservation) {
    res = window.activeCustomerReservation;
  }
  if (!res) {
    alert('Please select an active reservation to modify.');
    return;
  }

  // Sync full reservation row from Supabase first so rich items, customPax, customQty, specifications, and pricing fields are guaranteed present
  const sb = window.supabaseClient || window.supabase;
  if (sb && res.id) {
    try {
      const { data: sbRow } = await sb.from('reservations')
        .select('items, custom_items, package_items, execution_plan, package_origin, pricing_mode, price_tiers, price_per_head, premade_package_name, vip, event_setup, amount, base_price, out_of_town_charge, service_charge_pct, description, venue, venue_location, date, timeframe, call_time, pax, type, theme, is_locked')
        .eq('id', res.id)
        .maybeSingle();
      if (sbRow) {
        if (sbRow.is_locked != null) res.is_locked = !!sbRow.is_locked;
        if (Array.isArray(sbRow.items) && sbRow.items.length > 0) res.items = sbRow.items;
        if (Array.isArray(sbRow.custom_items) && sbRow.custom_items.length > 0) res.custom_items = sbRow.custom_items;
        if (Array.isArray(sbRow.package_items) && sbRow.package_items.length > 0) res.package_items = sbRow.package_items;
        if (sbRow.execution_plan) { res.execution_plan = sbRow.execution_plan; res.executionPlan = sbRow.execution_plan; }
        if (sbRow.package_origin) { res.packageOrigin = sbRow.package_origin; res.package_origin = sbRow.package_origin; }
        if (sbRow.pricing_mode) { res.pricingMode = sbRow.pricing_mode; res.pricing_mode = sbRow.pricing_mode; }
        if (sbRow.price_tiers) { res.priceTiers = sbRow.price_tiers; res.price_tiers = sbRow.price_tiers; }
        if (sbRow.price_per_head) { res.pricePerHead = sbRow.price_per_head; res.price_per_head = sbRow.price_per_head; }
        if (sbRow.premade_package_name) { res.premadePackageName = sbRow.premade_package_name; res.premade_package_name = sbRow.premade_package_name; }
        if (sbRow.vip) res.vip = sbRow.vip;
        if (sbRow.event_setup) { res.eventSetup = sbRow.event_setup; res.event_setup = sbRow.event_setup; }
        if (sbRow.amount != null) res.amount = sbRow.amount;
        if (sbRow.base_price != null) { res.basePrice = sbRow.base_price; res.base_price = sbRow.base_price; }
        if (sbRow.out_of_town_charge != null) { res.outOfTownCharge = sbRow.out_of_town_charge; res.out_of_town_charge = sbRow.out_of_town_charge; }
        if (sbRow.service_charge_pct != null) { res.serviceChargePct = sbRow.service_charge_pct; res.service_charge_pct = sbRow.service_charge_pct; }
        if (sbRow.description && !res.description) res.description = sbRow.description;
        if (sbRow.venue && !res.venue) res.venue = sbRow.venue;
        if (sbRow.venue_location && !res.venueLocation) { res.venueLocation = sbRow.venue_location; res.venue_location = sbRow.venue_location; }
        if (sbRow.date && !res.date) res.date = sbRow.date;
        if (sbRow.timeframe && !res.timeframe) { res.timeframe = sbRow.timeframe; res.time = sbRow.timeframe; }
        if (sbRow.call_time && !res.callTime) { res.callTime = sbRow.call_time; res.call_time = sbRow.call_time; }
        if (sbRow.pax && !res.pax) res.pax = sbRow.pax;
        if (sbRow.type && !res.type) res.type = sbRow.type;
        if (sbRow.theme && !res.theme) res.theme = sbRow.theme;
      }
    } catch (e) {
      console.warn('[modifyCustomerPackage] Supabase sync notice:', e);
    }
  }

  if (res.is_locked || res.isLocked) {
    alert('Reservation is locked because equipment allocations have been assigned.');
    return;
  }
  const st = String(res.status || '').toLowerCase();
  if (st === 'cancelled' || st === 'completed') {
    alert('Cannot modify a ' + st + ' reservation.');
    return;
  }

  window.customerModifyMode = true;
  window.customerModifyingRes = JSON.parse(JSON.stringify(res));
  // Snapshot original state before live edits so changes are logged with 100% precision
  window._customerModOriginalRes = {
    items: JSON.parse(JSON.stringify(res.items || res.custom_items || res.packageItems || [])),
    pax: res.pax,
    amount: res.amount,
    type: res.type || res.occasion,
    theme: res.theme,
    date: res.date,
    time: res.time || res.timeframe,
    venue: res.venue || res.venueAddress,
    city: res.city || res.venueLocation
  };
  const origin = window.getCustomerModifyOrigin(window.customerModifyingRes);
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';

  // Prioritize rich item objects from res.items, res.custom_items, or execution_plan
  const rawItems = (Array.isArray(res.items) && res.items.length > 0 && typeof res.items[0] === 'object')
    ? res.items
    : ((Array.isArray(res.custom_items) && res.custom_items.length > 0 && typeof res.custom_items[0] === 'object')
      ? res.custom_items
      : ((res.execution_plan && res.execution_plan._firebase_extras && Array.isArray(res.execution_plan._firebase_extras.items))
        ? res.execution_plan._firebase_extras.items
        : ((res.executionPlan && res.executionPlan._firebase_extras && Array.isArray(res.executionPlan._firebase_extras.items))
          ? res.executionPlan._firebase_extras.items
          : (Array.isArray(res.packageItems) && res.packageItems.length > 0 ? res.packageItems : (Array.isArray(res.package_items) ? res.package_items : [])))));

  const pCount = parseInt(res.pax) || 50;
  window.customerModifyingItems = rawItems.map((ri, idx) => {
    const riName = typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : 'Item ' + (idx + 1));
    const cItem = (typeof CAT !== 'undefined' && Array.isArray(CAT))
      ? CAT.find(c => (ri && ri.id && String(c.id) === String(ri.id)) || (c.name && c.name.toLowerCase() === riName.toLowerCase()))
      : null;
    const isEq = (cItem && cItem.cat === 'equipment') || (typeof ri === 'object' && ri && ri.cat === 'equipment');

    let customQ = null;
    let autoQ = null;
    let isCust = false;
    if (typeof ri === 'object' && ri) {
      if (ri.customQty != null) {
        customQ = parseInt(ri.customQty);
        isCust = !!(ri.isCustomized || ri.isLocked);
      } else if (ri.custom_qty != null) {
        customQ = parseInt(ri.custom_qty);
        isCust = true;
      }
      if (ri.autoQty != null) {
        autoQ = parseInt(ri.autoQty);
      }
    }
    if (isEq) {
      const resolved = Object.assign({}, cItem || {}, typeof ri === 'object' ? ri : { name: riName });
      const computedAuto = typeof getEquipmentAllocatedQty === 'function' ? getEquipmentAllocatedQty(resolved, pCount, rawItems) : 1;
      if (autoQ === null) autoQ = computedAuto;
      if (customQ === null) {
        const storedSnap = (typeof ri === 'object' && ri && (ri.snapshotPrice ?? ri.dynamic_price));
        const unitP = parseFloat((cItem && cItem.price) || (typeof ri === 'object' && ri && ri.price) || 0);
        if (storedSnap != null && Number(storedSnap) > 0 && unitP > 0) {
          const derivedQ = Math.round(Number(storedSnap) / unitP);
          customQ = derivedQ > 0 ? derivedQ : autoQ;
        } else {
          customQ = autoQ;
        }
      }
      if (customQ !== autoQ) isCust = true;
    }

    const customPaxVal = (typeof ri === 'object' && ri && (ri.customPax || ri.portion_pax)) ? parseInt(ri.customPax || ri.portion_pax) : null;
    const specsVal = (typeof ri === 'object' && ri) ? (ri.specifications || ri.specs || '') : '';
    if (customPaxVal || (specsVal && String(specsVal).trim().length > 0)) {
      isCust = true;
    }

    let dynamicP = (typeof ri === 'object' && ri && (ri.snapshotPrice != null ? ri.snapshotPrice : ri.dynamic_price)) ?? null;
    const uP = parseFloat((cItem && cItem.price) || (typeof ri === 'object' && ri && ri.price) || 0) || 0;
    let origUnitMode = null;
    if (dynamicP != null && riName.toLowerCase().includes('unlimited drinks') && uP > 0) {
      if (Number(dynamicP) === Math.ceil(pCount / 5) * uP) {
        origUnitMode = 'per_5_batch';
      }
    }
    if (dynamicP === null || dynamicP === undefined) {
      if (isEq) {
        dynamicP = uP * (customQ || autoQ || 1);
      } else if (customPaxVal) {
        const tempObj = Object.assign({}, cItem || {}, typeof ri === 'object' ? ri : {}, { customPax: customPaxVal });
        dynamicP = (typeof getDynamicPrice === 'function') ? getDynamicPrice(tempObj, pCount) : (uP * customPaxVal);
      } else if (cItem && typeof getDynamicPrice === 'function') {
        dynamicP = getDynamicPrice(cItem, pCount);
      } else {
        dynamicP = uP;
      }
    }

    const isSubOpt = window.isCustomerModifySubOption(cItem || ri);
    // CRITICAL FIX: Never mark isAutoAdded or isEventSetupEquipment as isFree on a custom package!
    const itemIsFree = isPremade
      ? !(typeof ri === 'object' && ri && (ri.isAdditional || ri.addedAsExtra || ri.isExtra))
      : !!(isSubOpt || (typeof ri === 'object' && ri && (ri.isFree === true || ri.isFreeChoiceApplied === true || ri.isFreebie === true)));

    return {
      ...(cItem || {}),
      ...(typeof ri === 'object' && ri ? ri : {}),
      id: (cItem && cItem.id) || (typeof ri === 'object' && ri && ri.id) || ('item_' + idx),
      name: riName,
      cat: (cItem && cItem.cat) || (typeof ri === 'object' && ri && ri.cat) || 'other',
      price: uP,
      image: (cItem && cItem.image) || (typeof ri === 'object' && ri && (ri.image || ri.image_url)) || 'haldens_logo.png',
      desc: (cItem && cItem.desc) || (typeof ri === 'object' && ri && ri.desc) || '',
      snapshotPrice: Number(dynamicP) || 0,
      customQty: customQ,
      autoQty: autoQ,
      customPax: customPaxVal,
      specifications: specsVal,
      isCustomized: isCust,
      isFree: itemIsFree,
      isEventSetupEquipment: typeof ri === 'object' && ri ? !!ri.isEventSetupEquipment : false,
      isAutoAdded: typeof ri === 'object' && ri ? !!ri.isAutoAdded : false,
      _origUnitMode: origUnitMode,
      _showCustomize: false
    };
  });

  window.customerModifyingCatFilter = 'all';
  window.customerModifyingSearch = '';

  window.renderCustomerModifyWorkspace();
  window.syncCustomerAIFabVisibility();
};

window.syncCustomerModifyFormToRes = function () {
  const res = window.customerModifyingRes;
  if (!res) return;
  const budgetEl = document.getElementById('cmod-budget');
  if (budgetEl) res.budget = budgetEl.value.trim();
  const descEl = document.getElementById('cmod-desc');
  if (descEl) res.description = descEl.value;
  const occSel = document.getElementById('cmod-occasion');
  const occOther = document.getElementById('cmod-occasion-other');
  if (occSel) {
    res.occasion = (occSel.value === 'Others' && occOther) ? occOther.value.trim() : occSel.value;
    res.type = res.occasion;
  }
  const themeSel = document.getElementById('cmod-theme');
  const themeOther = document.getElementById('cmod-theme-other');
  if (themeSel) {
    res.theme = (themeSel.value === 'Others' && themeOther) ? themeOther.value.trim() : themeSel.value;
  }
  const setupEl = document.getElementById('cmod-setup');
  if (setupEl) {
    res.eventSetup = setupEl.value;
    res.event_setup = setupEl.value;
  }
  const paxEl = document.getElementById('cmod-pax');
  if (paxEl && parseInt(paxEl.value) > 0) {
    res.pax = parseInt(paxEl.value);
  }
  const ctEl = document.getElementById('cmod-calltime');
  if (ctEl) {
    res.callTime = ctEl.value;
    res.call_time = ctEl.value;
  }
  const dtEl = document.getElementById('cmod-date');
  if (dtEl) {
    res.date = dtEl.value;
    res.event_date = dtEl.value;
  }
  const tStartEl = document.getElementById('cmod-timeframe-start');
  const tEndEl = document.getElementById('cmod-timeframe-end');
  if (tStartEl && tEndEl && tStartEl.value && tEndEl.value) {
    res.timeframe = `${tStartEl.value} - ${tEndEl.value}`;
    res.time = res.timeframe;
  }
  const vipCheckEl = document.getElementById('cmod-vip-check');
  const vipCountEl = document.getElementById('cmod-vip-count');
  const vipSvcEl = document.getElementById('cmod-vip-service');
  if (vipCheckEl) {
    res.vip = {
      enabled: vipCheckEl.checked,
      count: vipCheckEl.checked ? (parseInt(vipCountEl?.value) || 1) : 0,
      service: vipSvcEl?.value || 'Properly Catered'
    };
    res.isVIP = vipCheckEl.checked;
    res.vipCount = res.vip.count;
    res.vipService = res.vip.service;
  }
  const cityEl = document.getElementById('cmod-city');
  if (cityEl) {
    res.venueLocation = cityEl.value;
    res.venue_location = cityEl.value;
    res.city = cityEl.value;
  }
  const venueEl = document.getElementById('cmod-venue');
  if (venueEl) {
    res.venue = venueEl.value;
    res.venueAddress = venueEl.value;
  }
};

window.renderCustomerModifyCatalog = function () {
  const gridEl = document.getElementById('cmod-catalog-grid');
  const filtersEl = document.getElementById('cmod-cat-filters');
  const countEl = document.getElementById('cmod-pkg-item-count');
  if (!gridEl || !window.customerModifyingRes) return;

  const res = window.customerModifyingRes;
  const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const origin = window.getCustomerModifyOrigin(res);
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';
  const currentPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(res.pax) || 50;

  if (countEl) {
    countEl.textContent = `${(window.customerModifyingItems || []).length} Items in Package`;
  }

  if (filtersEl) {
    filtersEl.innerHTML = ['all', 'food', 'dessert', 'drink', 'special', 'equipment', 'decoration', 'entertainment'].map(t => {
      const active = (window.customerModifyingCatFilter || 'all') === t;
      let lbl = t.toUpperCase();
      if (t === 'entertainment') lbl = 'ADD-ONS';
      if (t === 'special') lbl = 'SPECIAL ITEMS';
      if (t === 'decoration') lbl = 'DECOR';
      return `
        <button type="button" class="fb ${active ? 'active' : ''}" onclick="window.setCustomerModifyCatTab('${t}')" style="padding:6px 12px; border-radius:6px; font-size:11px; font-weight:700; cursor:pointer; text-transform:uppercase; border:1px solid ${active ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-border, rgba(180,140,60,0.25))'}; background:${active ? 'var(--cp-gold, #c49a3c)' : 'transparent'}; color:${active ? '#1a1612' : 'var(--cp-text, #fff)'}; transition:0.2s;">
          ${lbl}
        </button>
      `;
    }).join('');
  }

  const searchQ = String(window.customerModifyingSearch || '').toLowerCase().trim();
  const catTab = window.customerModifyingCatFilter || 'all';

  // Combine CAT with any items currently in customerModifyingItems that might not be in CAT
  const baseCatalog = Array.isArray(CAT) ? [...CAT] : [];
  (window.customerModifyingItems || []).forEach(pkgIt => {
    const existsInCat = baseCatalog.some(c => String(c.id) === String(pkgIt.id) || (c.name && pkgIt.name && c.name.toLowerCase() === pkgIt.name.toLowerCase()));
    if (!existsInCat) baseCatalog.push(pkgIt);
  });

  let filteredCatalog = baseCatalog.filter(c => {
    const inPkg = (window.customerModifyingItems || []).find(i => String(i.id) === String(c.id) || (i.name && c.name && i.name.toLowerCase() === c.name.toLowerCase()));
    if (!inPkg) {
      if (c.hidden === true || c.is_hidden === true || c.is_available === false) return false;
    }
    if (c.cat === 'equipment') {
      if (c.is_batch || c.batch_id || c.parent_asset_id) return false;
      const n = String(c.name || '').toLowerCase();
      if (n.includes('(batch') || / batch-\d+/i.test(n)) return false;
    }
    if (c.name === 'Free Choices of Food From Menu') return false;
    // Only show child options if their parent special item is currently in the package
    if (typeof window.isParentSpecialItemInPackage === 'function') {
      if (!window.isParentSpecialItemInPackage(c, window.customerModifyingItems)) return false;
    }
    return true;
  });

  if (catTab === 'all') {
    if (typeof window.sortCatByFoodFirst === 'function') {
      filteredCatalog = window.sortCatByFoodFirst(filteredCatalog);
    }
  } else if (catTab === 'special') {
    filteredCatalog = filteredCatalog.filter(c => typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(c));
  } else {
    filteredCatalog = filteredCatalog.filter(c => {
      const cCat = String(c.cat || c.category || '').toLowerCase();
      if (catTab === 'entertainment' || catTab === 'add-ons') return ['entertainment', 'addon', 'add-ons', 'fun', 'photography'].includes(cCat);
      return cCat === catTab;
    });
  }

  if (searchQ) {
    filteredCatalog = filteredCatalog.filter(c =>
      String(c.name || '').toLowerCase().includes(searchQ) ||
      String(c.desc || c.description || '').toLowerCase().includes(searchQ)
    );
  }

  // CRITICAL REQUIREMENT: Sort all added items in the package to the TOP of the list!
  const catRankOrder = ['food', 'dessert', 'drink', 'special', 'decoration', 'equipment', 'entertainment', 'other'];
  filteredCatalog.sort((a, b) => {
    const aIn = (window.customerModifyingItems || []).some(i => String(i.id) === String(a.id) || (i.name && a.name && i.name.toLowerCase() === a.name.toLowerCase())) ? 0 : 1;
    const bIn = (window.customerModifyingItems || []).some(i => String(i.id) === String(b.id) || (i.name && b.name && i.name.toLowerCase() === b.name.toLowerCase())) ? 0 : 1;
    if (aIn !== bIn) return aIn - bIn;
    const aCat = catRankOrder.indexOf(String(a.cat || 'other').toLowerCase());
    const bCat = catRankOrder.indexOf(String(b.cat || 'other').toLowerCase());
    const rA = aCat === -1 ? 99 : aCat;
    const rB = bCat === -1 ? 99 : bCat;
    if (rA !== rB) return rA - rB;
    return String(a.name || '').localeCompare(String(b.name || ''));
  });

  if (filteredCatalog.length === 0) {
    gridEl.innerHTML = `<div style="grid-column:1/-1; padding:32px; text-align:center; color:var(--cp-text-dim, #9a8a7c); font-size:13px;">No matching items found in catalog.</div>`;
    return;
  }

  gridEl.innerHTML = filteredCatalog.map(catItem => {
    const inPkgIdx = (window.customerModifyingItems || []).findIndex(c => String(c.id) === String(catItem.id) || (c.name && catItem.name && c.name.toLowerCase() === catItem.name.toLowerCase()));
    const inPkg = inPkgIdx !== -1 ? window.customerModifyingItems[inPkgIdx] : null;
    const itemCatLow = String((inPkg && inPkg.cat) || catItem.cat || catItem.category || 'other').toLowerCase();
    const isEq = itemCatLow === 'equipment';
    const isSubOpt = window.isCustomerModifySubOption(catItem);
    const isSpecialItemOrParent = (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(catItem)) || itemCatLow === 'special' || itemCatLow === 'special items' || String(catItem.name || '').toLowerCase().includes('unlimited drinks') || String(catItem.name || '').toLowerCase().includes('ice cream');
    const isScalableFood = !isEq && !isSubOpt && (
      isSpecialItemOrParent ||
      ['food', 'dessert', 'desserts', 'drink', 'drinks'].includes(itemCatLow) ||
      (typeof isItemPerPaxScalable === 'function' && isItemPerPaxScalable(catItem))
    );

    let subcatLbl = String(catItem.subcategory || catItem.category || catItem.cat || 'ITEM').toUpperCase();
    if (subcatLbl === 'ENTERTAINMENT') subcatLbl = 'ADD-ONS';
    const imgSrc = (inPkg && inPkg.image) || catItem.image || catItem.image_url || 'haldens_logo.png';

    // Equipment allocated quantity
    let eqQty = 1;
    let isCustQty = false;
    if (isEq) {
      if (inPkg) {
        eqQty = parseInt(inPkg.customQty ?? inPkg.autoQty ?? 1) || 1;
        isCustQty = !!(inPkg.isCustomized && inPkg.customQty != null);
      } else {
        eqQty = (typeof getEquipmentAllocatedQty === 'function')
          ? getEquipmentAllocatedQty(catItem, currentPax, window.customerModifyingItems)
          : 1;
      }
    }

    // Price display rules:
    // For Premade packages: DO NOT show prices on equipment items (or base items).
    let priceHtml = '';
    if (isPremade) {
      if (isEq) {
        priceHtml = '';
      } else if (inPkg) {
        priceHtml = `<div style="font-size:11px; font-weight:700; color:var(--cp-text-dim, #9a8a7c); margin-top:6px; text-transform:uppercase;">Included in Package</div>`;
      }
    } else {
      if (isSubOpt || (inPkg && inPkg.isFree)) {
        priceHtml = `<div style="font-size:11px; font-weight:700; color:var(--cp-text-dim, #9a8a7c); margin-top:6px; text-transform:uppercase;">Included</div>`;
      } else {
        const pVal = inPkg
          ? window.computeCustomerModifyItemPrice(inPkg, currentPax)
          : ((typeof getDynamicPrice === 'function') ? getDynamicPrice(catItem, currentPax) : (parseFloat(catItem.price) || 0));
        const customPaxNote = (inPkg && inPkg.customPax) ? ` <span style="font-size:10.5px; font-weight:600; color:var(--cp-text-dim, #9a8a7c);">(Custom: ${inPkg.customPax} pax)</span>` : '';
        priceHtml = `<div class="cat-price" style="font-size:13px; font-weight:800; color:var(--cp-gold, #c49a3c); margin-top:6px;">₱${Number(pVal).toLocaleString()}${customPaxNote}</div>`;
      }
    }

    const eqBadgeHtml = isEq ? `
      <div style="margin-top:6px; font-size:11px; font-weight:700; color:var(--cp-gold, #c49a3c); border-top:1px dashed rgba(196,154,60,0.25); padding-top:5px;">
        Quantity Allocated: ${eqQty} pcs ${(!isPremade && isCustQty) ? '<span style="font-size:10px; font-weight:600;">(Customized)</span>' : ''}
      </div>
    ` : '';

    // Action button + Inline Customization Controls (merged directly into the catalog card!)
    let actionAndCustomizeHtml = '';
    const itemKey = String((inPkg && inPkg.id) || catItem.id);

    if (isPremade) {
      // PREMADE PACKAGE: Items are locked, NO Customize buttons, ONLY text input area for notes/specifications!
      actionAndCustomizeHtml = `
        <button type="button" disabled style="width:100%; padding:7px 10px; font-size:11px; font-weight:700; background:transparent; color:var(--cp-text-dim, #9a8a7c); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:6px; cursor:not-allowed; text-transform:uppercase; letter-spacing:0.4px;">
          ${inPkg ? 'Locked - Included in Package' : 'Locked - Premade Package'}
        </button>
        ${inPkg ? `
          <div class="item-custom-pax-box" style="margin-top:8px; padding-top:8px; border-top:1px dashed rgba(196,154,60,0.3);">
            <label style="display:block; font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:0.5px; margin-bottom:4px;">Specifications / Notes</label>
            <input type="text" maxlength="100" placeholder="Enter notes or special requests..." value="${esc(inPkg.specifications || '')}" oninput="window.updateCustomerItemSpecsById('${esc(itemKey)}', this.value)" style="width:100%; padding:6px 8px; font-size:11px; background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
          </div>
        ` : ''}
      `;
    } else {
      // CUSTOM PACKAGE: Full Make a Reservation Add/Added button + inline Customize Pax / Customize Equipment / Customize Notes
      if (inPkg) {
        const hasSpecs = !!(inPkg.specifications && String(inPkg.specifications).trim().length > 0);
        const hasCustomPax = !!(inPkg.customPax && parseInt(inPkg.customPax) > 0);
        const hasCustomQty = !!(isEq && inPkg.isCustomized && inPkg.customQty != null);

        let customizeBtnLabel = 'Customize Notes';
        if (isScalableFood) {
          customizeBtnLabel = hasCustomPax ? `Custom Pax: ${inPkg.customPax} pax` : (hasSpecs ? 'Customized Notes' : 'Customize Pax');
        } else if (isEq) {
          customizeBtnLabel = hasCustomQty ? `Custom Count: ${eqQty} pcs` : (hasSpecs ? 'Customized Notes' : 'Customize Equipment');
        } else {
          customizeBtnLabel = hasSpecs ? 'Customized Notes' : 'Customize Notes';
        }

        actionAndCustomizeHtml = `
          <div style="display:flex; flex-direction:column; gap:6px;">
            <button type="button" class="btn-cat-add" onclick="window.toggleCustomerModifyItem('${esc(itemKey)}')" style="width:100%; padding:7px 10px; font-size:11px; font-weight:700; background:var(--cp-gold, #c49a3c); color:#1a1612; border:none; border-radius:6px; cursor:pointer;" title="Click to remove from package">
              Added (Click to Remove)
            </button>
            ${!isSubOpt ? `
              <button type="button" onclick="window.toggleCustomerModifyFoodCustomize('${esc(itemKey)}', event)" style="width:100%; padding:6px 10px; font-size:11px; font-weight:700; background:transparent; color:var(--cp-gold, #c49a3c); border:1px solid var(--cp-gold, #c49a3c); border-radius:6px; cursor:pointer;">
                ${esc(customizeBtnLabel)}
              </button>
            ` : ''}
          </div>
          ${(!isSubOpt && inPkg._showCustomize) ? `
            <div class="item-custom-pax-box" style="margin-top:8px; padding:10px; background:var(--cp-bg2, #18120c); border:1px solid rgba(196,154,60,0.35); border-radius:6px; font-size:11px;">
              ${isScalableFood ? `
                <div style="margin-bottom:8px;">
                  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                    <label style="font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase;">Portion Pax (Max: 999)</label>
                    <button type="button" onclick="window.resetCustomerModifyItemCustomization('${esc(itemKey)}')" style="background:transparent; border:1px solid rgba(196,154,60,0.4); color:var(--cp-gold, #c49a3c); font-size:9.5px; font-weight:700; padding:2px 6px; border-radius:4px; cursor:pointer;">Reset</button>
                  </div>
                  <input type="number" min="1" max="999" maxlength="3" value="${inPkg.customPax || currentPax}" onchange="window.updateCustomerItemPax('${esc(itemKey)}', this.value)" style="width:100%; padding:5px 8px; font-size:11px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
                </div>
                <div>
                  <label style="display:block; font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase; margin-bottom:4px;">Specifications (Max 100 chars)</label>
                  <input type="text" maxlength="100" placeholder="e.g. Less spicy, sauce on side..." value="${esc(inPkg.specifications || '')}" oninput="window.updateCustomerItemSpecsById('${esc(itemKey)}', this.value)" style="width:100%; padding:5px 8px; font-size:11px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
                </div>
              ` : (isEq ? `
                <div style="margin-bottom:8px;">
                  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                    <label style="font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase;">Allocated Quantity (1 - 999)</label>
                    <button type="button" onclick="window.resetCustomerModifyItemCustomization('${esc(itemKey)}')" style="background:transparent; border:1px solid rgba(196,154,60,0.4); color:var(--cp-gold, #c49a3c); font-size:9.5px; font-weight:700; padding:2px 6px; border-radius:4px; cursor:pointer;">Reset</button>
                  </div>
                  <div style="display:flex; align-items:center; gap:6px;">
                    <button type="button" onclick="window.changeCustomerEquipmentQty(${inPkgIdx}, -1)" style="width:28px; height:28px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); color:var(--cp-text, #fff); border-radius:4px; cursor:pointer; font-weight:700;">-</button>
                    <input type="number" min="1" max="999" value="${eqQty}" onchange="window.setCustomerEquipmentQty('${esc(itemKey)}', this.value)" style="flex:1; text-align:center; padding:5px 6px; font-size:11px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
                    <button type="button" onclick="window.changeCustomerEquipmentQty(${inPkgIdx}, 1)" style="width:28px; height:28px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); color:var(--cp-text, #fff); border-radius:4px; cursor:pointer; font-weight:700;">+</button>
                  </div>
                </div>
                <div>
                  <label style="display:block; font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase; margin-bottom:4px;">Specifications / Notes</label>
                  <input type="text" maxlength="100" placeholder="e.g. White cloth, specific arrangement..." value="${esc(inPkg.specifications || '')}" oninput="window.updateCustomerItemSpecsById('${esc(itemKey)}', this.value)" style="width:100%; padding:5px 8px; font-size:11px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
                </div>
              ` : `
                <div>
                  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                    <label style="font-size:10px; font-weight:700; color:var(--cp-gold, #c49a3c); text-transform:uppercase;">Specifications / Preferences</label>
                    <button type="button" onclick="window.resetCustomerModifyItemCustomization('${esc(itemKey)}')" style="background:transparent; border:1px solid rgba(196,154,60,0.4); color:var(--cp-gold, #c49a3c); font-size:9.5px; font-weight:700; padding:2px 6px; border-radius:4px; cursor:pointer;">Clear</button>
                  </div>
                  <input type="text" maxlength="100" placeholder="e.g. Color motif, placement, flavor notes..." value="${esc(inPkg.specifications || '')}" oninput="window.updateCustomerItemSpecsById('${esc(itemKey)}', this.value)" style="width:100%; padding:5px 8px; font-size:11px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.3)); border-radius:4px; color:var(--cp-text, #fff); box-sizing:border-box;">
                </div>
              `)}
            </div>
          ` : ''}
        `;
      } else {
        actionAndCustomizeHtml = `
          <button type="button" class="btn-cat-add" onclick="window.toggleCustomerModifyItem('${esc(catItem.id)}')" style="width:100%; padding:7px 10px; font-size:11px; font-weight:700; background:transparent; color:var(--cp-gold, #c49a3c); border:1px solid var(--cp-gold, #c49a3c); border-radius:6px; cursor:pointer;">
            + Add to Package
          </button>
        `;
      }
    }

    const isCustomizedFlag = !!(inPkg && (inPkg.isCustomized || inPkg.customPax || (isEq && inPkg.customQty != null && inPkg.autoQty != null && inPkg.customQty !== inPkg.autoQty) || (inPkg.specifications && String(inPkg.specifications).trim().length > 0)));

    return `
      <div class="cat-card" style="background:var(--cp-bg3, #221a12); border:${inPkg ? '1.5px solid var(--cp-gold, #c49a3c)' : '1px solid var(--cp-border, rgba(180,140,60,0.22))'}; border-radius:10px; padding:12px; display:flex; flex-direction:column; justify-content:space-between; position:relative; transition:0.2s;">
        <div>
          <div class="cat-thumb" style="width:100%; height:120px; border-radius:6px; overflow:hidden; margin-bottom:8px; background:#0d0a07;">
            <img src="${imgSrc}" alt="${esc(catItem.name)}" loading="lazy" style="width:100%; height:100%; object-fit:cover;" onerror="this.onerror=null;this.src='haldens_logo.png';">
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; gap:4px; margin-bottom:3px;">
            <div class="cat-cat-lbl" style="font-size:9.5px; color:var(--cp-gold, #c49a3c); font-weight:700; text-transform:uppercase; letter-spacing:0.6px;">${esc(subcatLbl)}</div>
            ${inPkg ? `<div style="font-size:9px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:0.5px;">${isCustomizedFlag ? 'ADDED • CUSTOMIZED' : 'ADDED'}</div>` : ''}
          </div>
          <div class="cat-name" style="font-size:13.5px; font-weight:700; color:var(--cp-text, #fff); line-height:1.25;">${esc(catItem.name)}</div>
          <div class="cat-desc" style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); margin-top:4px; line-height:1.35; max-height:44px; overflow:hidden;">${esc(catItem.desc || catItem.description || '')}</div>
          ${eqBadgeHtml}
          ${priceHtml}
        </div>
        <div style="margin-top:10px;">
          ${actionAndCustomizeHtml}
        </div>
      </div>
    `;
  }).join('');
};

window.renderCustomerModifyWorkspace = function () {
  const contentEl = document.getElementById('resd-content');
  if (!contentEl || !window.customerModifyingRes) return;
  const res = window.customerModifyingRes;
  const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  window.syncCustomerAIFabVisibility();

  // Toggle header buttons
  const modBtn = document.getElementById('resd-modify-btn');
  const expBtn = document.getElementById('resd-export-btn');
  const reqCancelBtn = document.getElementById('resd-req-cancel-btn');
  const saveBtn = document.getElementById('resd-save-mod-btn');
  const cancelBtn = document.getElementById('resd-cancel-mod-btn');

  if (modBtn) modBtn.style.display = 'none';
  if (expBtn) expBtn.style.display = 'none';
  if (reqCancelBtn) reqCancelBtn.style.display = 'none';
  if (saveBtn) {
    saveBtn.style.display = 'inline-flex';
    saveBtn.disabled = false;
    saveBtn.textContent = 'Save Changes';
  }
  if (cancelBtn) cancelBtn.style.display = 'inline-flex';

  const origin = window.getCustomerModifyOrigin(res);
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';
  const isMajorlySet = origin === 'majorly set';
  const currentPax = parseInt(res.pax) || 50;
  const pricing = window.computeCustomerModifyPricing();

  // Parse time range: start and end
  let tStart = '13:00';
  let tEnd = '18:00';
  const rawTime = res.timeframe || res.time || '';
  if (rawTime) {
    const sep = rawTime.toLowerCase().includes(' to ') ? / to /i : /-/;
    const parts = rawTime.split(sep).map(p => p.trim());
    const parseTime = str => {
      if (!str) return null;
      if (/^\d{1,2}:\d{2}$/.test(str)) return str.padStart(5, '0');
      const m = str.match(/(\d{1,2}):?(\d{2})?\s*(AM|PM)?/i);
      if (!m) return null;
      let h = parseInt(m[1], 10);
      const min = m[2] || '00';
      const ap = (m[3] || '').toUpperCase();
      if (ap === 'PM' && h < 12) h += 12;
      if (ap === 'AM' && h === 12) h = 0;
      return `${String(h).padStart(2, '0')}:${min}`;
    };
    if (parts.length >= 2) {
      const p0 = parseTime(parts[0]);
      const p1 = parseTime(parts[parts.length - 1]);
      if (p0) tStart = p0;
      if (p1) tEnd = p1;
    }
  }

  let tCallTime = res.callTime || res.call_time || tStart;
  if (tCallTime && !/^\d{2}:\d{2}$/.test(tCallTime)) {
    const m = String(tCallTime).match(/(\d{1,2}):?(\d{2})?\s*(AM|PM)?/i);
    if (m) {
      let h = parseInt(m[1], 10);
      const min = m[2] || '00';
      const ap = (m[3] || '').toUpperCase();
      if (ap === 'PM' && h < 12) h += 12;
      if (ap === 'AM' && h === 12) h = 0;
      tCallTime = `${String(h).padStart(2, '0')}:${min}`;
    }
  }

  // Parse VIP
  const isVIP = !!(res.vip?.enabled || res.isVIP || (res.vip_count && parseInt(res.vip_count) > 0) || (res.vipCount && parseInt(res.vipCount) > 0));
  const vipCount = Math.min(currentPax, Math.max(1, parseInt(res.vip?.count || res.vipCount || res.vip_count || 1) || 1));
  const vipService = res.vip?.service || res.vipService || 'Properly Catered';

  // Setup options
  const setupsPool = (Array.isArray(window.EVENT_SETUPS) && window.EVENT_SETUPS.length > 0)
    ? window.EVENT_SETUPS
    : [
      { slug: 'complete_setup', name: 'Complete Setup' },
      { slug: 'simple_setup', name: 'Simple Setup' },
      { slug: 'classic_banquet', name: 'Classic Banquet' },
      { slug: 'grand_floral', name: 'Grand Floral' },
      { slug: 'modern_minimalist', name: 'Modern Minimalist' },
      { slug: 'custom', name: 'Custom Setup' }
    ];

  const rawSetup = String(res.eventSetup || res.event_setup || 'Complete Setup');
  const currentSetupSlug = rawSetup.toLowerCase().replace(/\s+/g, '_');
  const isCustomSetupSelected = currentSetupSlug.includes('custom');
  const setupOptionsHtml = setupsPool.map(s => {
    const sSlug = String(s.slug || s.name || '').toLowerCase().replace(/\s+/g, '_');
    const isSel = (sSlug === currentSetupSlug) || (String(s.name || '').toLowerCase() === rawSetup.toLowerCase());
    return `<option value="${esc(s.name || s.slug)}" ${isSel ? 'selected' : ''}>${esc(s.name)}</option>`;
  }).join('');

  const knownOccasions = ['Wedding', 'Birthday', 'Corporate', 'Private'];
  const occ = res.occasion || res.type || 'Wedding';
  const isKnownOcc = knownOccasions.includes(occ);

  const knownThemes = (Array.isArray(window.ADMIN_THEMES) && window.ADMIN_THEMES.length > 0)
    ? window.ADMIN_THEMES.filter(t => t !== 'Others')
    : ['Classic', 'Modern Minimalist', 'Rustic', 'Garden', 'Filipiniana', 'Glamour'];
  const theme = res.theme || 'Classic';
  const isKnownTheme = knownThemes.includes(theme);

  const ncrCities = ['Malabon', 'Manila', 'Quezon City', 'Caloocan', 'Las Piñas', 'Makati', 'Mandaluyong', 'Marikina', 'Muntinlupa', 'Navotas', 'Parañaque', 'Pasay', 'Pasig', 'San Juan', 'Taguig', 'Valenzuela'];
  const cityVal = res.venueLocation || res.venue_location || res.city || 'Malabon';

  // Pax input or Majorly Set tier selector
  let paxControlHtml = '';
  if (isMajorlySet) {
    let tiers = res.priceTiers || res.price_tiers || [];
    if (!Array.isArray(tiers) || tiers.length === 0) {
      const pkgName = res.premadePackageName || res.premade_package_name || res.packageName || res.package_name || '';
      const foundPkg = (typeof PKGS !== 'undefined' ? PKGS : []).find(p => p && p.name && p.name.toLowerCase() === pkgName.toLowerCase());
      if (foundPkg && Array.isArray(foundPkg.priceTiers || foundPkg.price_tiers)) {
        tiers = foundPkg.priceTiers || foundPkg.price_tiers;
      }
    }
    if (Array.isArray(tiers) && tiers.length > 0) {
      const opts = tiers.map(t => {
        const pNum = parseInt(t.pax || t.label) || 50;
        const isSel = pNum === currentPax;
        return `<option value="${pNum}" ${isSel ? 'selected' : ''}>${pNum} Pax : ₱${Number(t.price).toLocaleString()}</option>`;
      }).join('');
      paxControlHtml = `<select id="cmod-pax" onchange="window.onCustomerModifyPaxInput(this.value)" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">${opts}</select>`;
    } else {
      paxControlHtml = `<input type="number" id="cmod-pax" value="${currentPax}" disabled style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text-dim, #9a8a7c); font-size:12px; box-sizing:border-box;">`;
    }
  } else {
    paxControlHtml = `
      <input type="number" id="cmod-pax" min="10" max="200" value="${currentPax}" oninput="window.onCustomerModifyPaxInput(this.value)" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
      <div id="cmod-pax-err" style="display:none; color:#ef4444; font-size:10.5px; margin-top:3px; font-weight:600;">Pax must be between 10 and 200 guests.</div>
    `;
  }

  contentEl.innerHTML = `
    <!-- Top Workspace Header -->
    <div style="background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:12px; padding:16px 20px; margin-bottom:20px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
      <div>
        <div style="font-size:15px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:1px;">
          Modify Reservation Package Workspace
        </div>
        <div style="font-size:12px; color:var(--cp-text-dim, #9a8a7c); margin-top:3px;">
          Editing Reservation: <strong>#${esc(res.id)}</strong> &bull; Package: <strong>${esc(res.packageName || res.package_name || 'Custom Package')}</strong> (${isPremade ? 'Premade Package - Items Locked' : 'Custom Package'})
        </div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:10.5px; color:var(--cp-text-dim, #9a8a7c); text-transform:uppercase; letter-spacing:0.8px;">Official Package Total</div>
        <div id="cmod-hdr-total" style="font-size:20px; font-weight:800; color:var(--cp-gold, #c49a3c);">₱${pricing.grandTotal.toLocaleString()}</div>
      </div>
    </div>

    <!-- Main Workspace 2-Column Grid (Make a Reservation Layout) -->
    <div style="display:grid; grid-template-columns: minmax(340px, 0.95fr) minmax(420px, 1.35fr); gap:22px; align-items:start;">
      
      <!-- LEFT COLUMN: Event Details + Venue & Guests + Pricing Summary -->
      <div style="display:flex; flex-direction:column; gap:18px;">
        
        <!-- Section 1: Budget & Event Details -->
        <div style="background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:12px; padding:18px;">
          <div style="font-size:12px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:1px; margin-bottom:14px; border-bottom:1px solid rgba(196,154,60,0.2); padding-bottom:6px;">
            Event Details
          </div>
          
          <div style="margin-bottom:12px;">
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Target Budget (₱) ${isPremade ? '(Locked for Premade Package)' : '(Optional)'}</label>
            <input type="number" id="cmod-budget" value="${esc(res.budget || '')}" ${isPremade ? 'disabled' : ''} placeholder="${isPremade ? 'Locked for Premade Package' : 'e.g. 50000'}" oninput="window.syncCustomerModifyFormToRes(); window.updateModifyPricingLive();" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
          </div>

          <div style="margin-bottom:12px;">
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Event Description *</label>
            <textarea id="cmod-desc" rows="2" placeholder="Describe your event occasion, vibe, special requests..." oninput="window.syncCustomerModifyFormToRes()" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">${esc(res.description || '')}</textarea>
          </div>

          <div style="display:grid; grid-template-columns: 1fr 1fr; gap:12px; margin-bottom:12px;">
            <div>
              <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Occasion *</label>
              <select id="cmod-occasion" onchange="document.getElementById('cmod-occasion-other-wrap').style.display=(this.value==='Others'?'block':'none'); window.syncCustomerModifyFormToRes();" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px;">
                ${knownOccasions.map(o => `<option value="${o}" ${(isKnownOcc && occ === o) ? 'selected' : ''}>${o}</option>`).join('')}
                <option value="Others" ${!isKnownOcc ? 'selected' : ''}>Others</option>
              </select>
              <div id="cmod-occasion-other-wrap" style="display:${!isKnownOcc ? 'block' : 'none'}; margin-top:6px;">
                <input type="text" id="cmod-occasion-other" value="${esc(!isKnownOcc ? occ : '')}" placeholder="Specify occasion..." oninput="window.syncCustomerModifyFormToRes()" style="width:100%; padding:7px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
              </div>
            </div>
            <div>
              <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Theme / Style *</label>
              <select id="cmod-theme" onchange="document.getElementById('cmod-theme-other-wrap').style.display=(this.value==='Others'?'block':'none'); window.syncCustomerModifyFormToRes();" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px;">
                ${knownThemes.map(t => `<option value="${esc(t)}" ${(isKnownTheme && theme === t) ? 'selected' : ''}>${esc(t)}</option>`).join('')}
                <option value="Others" ${!isKnownTheme ? 'selected' : ''}>Others</option>
              </select>
              <div id="cmod-theme-other-wrap" style="display:${!isKnownTheme ? 'block' : 'none'}; margin-top:6px;">
                <input type="text" id="cmod-theme-other" value="${esc(!isKnownTheme ? theme : '')}" placeholder="Specify theme..." oninput="window.syncCustomerModifyFormToRes()" style="width:100%; padding:7px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
              </div>
            </div>
          </div>

          <div>
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Event Setup Type * ${isPremade ? '(Locked)' : ''}</label>
            <select id="cmod-setup" ${isPremade ? 'disabled' : ''} onchange="window.onCustomerModifySetupChange(this.value)" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px;">
              ${setupOptionsHtml}
            </select>
            <div id="cmod-custom-setup-notice" style="display:${isCustomSetupSelected ? 'block' : 'none'}; margin-top:8px; padding:10px 12px; border:1px solid rgba(196,154,60,0.4); border-radius:6px; font-size:11px; color:var(--cp-text-dim, #9a8a7c);">
              <div style="font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; margin-bottom:2px;">Custom Setup Active — Manual Selection Required</div>
              <div>Automatic equipment allocation is disabled. Please select and customize your required tables, chairs, and buffet equipment from the catalog.</div>
            </div>
          </div>
        </div>

        <!-- Section 2: Venue & Guests -->
        <div style="background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:12px; padding:18px;">
          <div style="font-size:12px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:1px; margin-bottom:14px; border-bottom:1px solid rgba(196,154,60,0.2); padding-bottom:6px;">
            Venue &amp; Guests
          </div>

          <div style="display:grid; grid-template-columns: 1fr 1fr; gap:12px; margin-bottom:12px;">
            <div>
              <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Guest Count (Pax) *</label>
              ${paxControlHtml}
            </div>
            <div>
              <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Call Time *</label>
              <input type="time" id="cmod-calltime" value="${esc(tCallTime)}" onchange="window.validateCustomerModifyTimeAndCalltime()" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
              <div id="cmod-calltime-err" style="display:none; color:#ef4444; font-size:10.5px; margin-top:3px; font-weight:600;">Call time cannot be later than event start time.</div>
            </div>
          </div>

          <div style="margin-bottom:12px;">
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Event Date *</label>
            <div style="position:relative; width:100%;">
              <input type="text" id="cmod-date" value="${esc(res.date || res.event_date || '')}" placeholder="YYYY-MM-DD" readonly onclick="openCustomEventDateCalendarModal()" style="width:100%; padding:8px 34px 8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; cursor:pointer; box-sizing:border-box;">
              <span onclick="openCustomEventDateCalendarModal()" style="position:absolute; right:10px; top:50%; transform:translateY(-50%); cursor:pointer; color:var(--cp-gold, #c49a3c); font-size:13px;" title="Open calendar">
                <i class="fas fa-calendar-alt"></i>
              </span>
            </div>
          </div>

          <!-- Dual Timeframe Inputs with Clock Pickers -->
          <div style="margin-bottom:12px;">
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Event Time Frame (Min 1 Hour) *</label>
            <div style="display:flex; align-items:center; gap:8px;">
              <input type="time" id="cmod-timeframe-start" value="${esc(tStart)}" onchange="window.validateCustomerModifyTimeAndCalltime()" style="flex:1; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
              <span style="color:var(--cp-text-dim, #9a8a7c); font-size:12px; font-weight:600;">to</span>
              <input type="time" id="cmod-timeframe-end" value="${esc(tEnd)}" onchange="window.validateCustomerModifyTimeAndCalltime()" style="flex:1; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
            </div>
            <div id="cmod-timeframe-err" style="display:none; color:#ef4444; font-size:10.5px; margin-top:3px; font-weight:600;">Event time frame must be at least 1 hour.</div>
          </div>

          <!-- VIP Checkbox and Fields (Strict Rule: 1 <= VIP Count <= Pax) -->
          <div style="margin-bottom:12px; padding:10px 12px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:8px;">
            <div style="display:flex; align-items:center; justify-content:space-between; gap:10px;">
              <label style="font-size:12px; font-weight:700; margin:0; display:flex; align-items:center; gap:8px; cursor:pointer; color:var(--cp-text, #fff);">
                <input type="checkbox" id="cmod-vip-check" ${isVIP ? 'checked' : ''} onchange="window.toggleCustomerModifyVIP(this.checked)">
                Include VIP Guests?
              </label>
              <span style="font-size:10.5px; color:var(--cp-text-dim, #9a8a7c);">Max VIPs: <strong id="cmod-vip-max-lbl">${currentPax}</strong> pax</span>
            </div>
            <div id="cmod-vip-fields" style="display:${isVIP ? 'grid' : 'none'}; grid-template-columns: 110px 1fr; gap:10px; margin-top:10px; padding-top:10px; border-top:1px dashed rgba(196,154,60,0.25);">
              <div>
                <label style="font-size:10px; color:var(--cp-text-dim, #9a8a7c); margin-bottom:3px; display:block; font-weight:700;">VIP Count *</label>
                <input type="number" id="cmod-vip-count" min="1" max="${currentPax}" value="${vipCount}" oninput="window.onCustomerModifyVIPCountInput(this)" style="width:100%; padding:6px 8px; font-size:12px; background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); box-sizing:border-box;">
              </div>
              <div>
                <label style="font-size:10px; color:var(--cp-text-dim, #9a8a7c); margin-bottom:3px; display:block; font-weight:700;">VIP Service Style</label>
                <select id="cmod-vip-service" onchange="window.syncCustomerModifyFormToRes()" style="width:100%; padding:6px 8px; font-size:12px; background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); box-sizing:border-box;">
                  <option value="Properly Catered" ${vipService.toLowerCase().includes('proper') ? 'selected' : ''}>Properly Catered</option>
                  <option value="Plated" ${vipService.toLowerCase().includes('plate') ? 'selected' : ''}>Plated</option>
                </select>
              </div>
              <div id="cmod-vip-err" style="display:none; grid-column:1/-1; color:#ef4444; font-size:10.5px; font-weight:600;">
                VIP count must be between 1 and total guest count (${currentPax} pax).
              </div>
            </div>
          </div>

          <div style="margin-bottom:12px;">
            <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); display:block; margin-bottom:4px; font-weight:700;">Venue Location (City) *</label>
            <select id="cmod-city" onchange="window.syncCustomerModifyFormToRes(); window.recalcCustomerModifyPricing();" style="width:100%; padding:8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px;">
              ${ncrCities.map(c => `<option value="${esc(c)}" ${cityVal.toLowerCase().includes(c.toLowerCase()) ? 'selected' : ''}>${esc(c)}${c === 'Malabon' ? ' (Local - No Surcharge)' : ' (+5% Out-of-Town)'}</option>`).join('')}
              ${!ncrCities.some(c => cityVal.toLowerCase().includes(c.toLowerCase())) ? `<option value="${esc(cityVal)}" selected>${esc(cityVal)} (+5% Out-of-Town)</option>` : ''}
            </select>
          </div>

          <div style="margin-bottom:12px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
              <label style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); font-weight:700;">Venue Address *</label>
              <span onclick="openMapModal()" style="font-size:11px; color:var(--cp-gold, #c49a3c); cursor:pointer; text-decoration:underline; font-weight:700;">[Open Map]</span>
            </div>
            <div style="position:relative;">
              <input type="text" id="cmod-venue" value="${esc(res.venueAddress || res.venue || '')}" placeholder="Click '[Open Map]' to pin your venue..." readonly onclick="openMapModal()" style="width:100%; padding:8px 32px 8px 10px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; cursor:pointer; box-sizing:border-box;">
              <span onclick="openMapModal()" style="position:absolute; right:10px; top:50%; transform:translateY(-50%); cursor:pointer; color:var(--cp-gold, #c49a3c); display:flex; align-items:center;" title="Open map">
                <i class="fas fa-map-marker-alt"></i>
              </span>
            </div>
          </div>

          <div id="cmod-otc-notice" style="display:${!pricing.isMalabon ? 'block' : 'none'}; padding:8px 12px; border:1px solid rgba(196,154,60,0.35); border-radius:6px; font-size:11.5px; color:var(--cp-gold, #c49a3c); font-weight:700;">
            Out-of-Town Venue (+5% Charge): +₱${pricing.outOfTownCharge.toLocaleString()}
          </div>
        </div>

        <!-- Section 3: Dynamic Pricing Summary -->
        <div style="background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:12px; padding:18px;">
          <div style="font-size:12px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:1px; margin-bottom:12px; border-bottom:1px solid rgba(196,154,60,0.2); padding-bottom:6px;">
            Pricing Summary
          </div>
          <div style="display:flex; flex-direction:column; gap:8px; font-size:13px;">
            ${isPremade ? `
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Premade Package Base (${currentPax} pax)</span>
                <span id="cmod-sum-food" style="color:var(--cp-text, #fff); font-weight:600;">₱${pricing.basePrice.toLocaleString()}</span>
              </div>
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Additional Item Charges</span>
                <span id="cmod-sum-other" style="color:var(--cp-text, #fff); font-weight:600;">+₱${pricing.extraItemsTotal.toLocaleString()}</span>
              </div>
            ` : `
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Food &amp; Beverage Subtotal</span>
                <span id="cmod-sum-food" style="color:var(--cp-text, #fff); font-weight:600;">₱${pricing.foodBase.toLocaleString()}</span>
              </div>
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Equipment &amp; Setup Subtotal</span>
                <span id="cmod-sum-equip" style="color:var(--cp-text, #fff); font-weight:600;">₱${pricing.equipBase.toLocaleString()}</span>
              </div>
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Styling &amp; Decor Subtotal</span>
                <span id="cmod-sum-decor" style="color:var(--cp-text, #fff); font-weight:600;">₱${pricing.decorBase.toLocaleString()}</span>
              </div>
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Add-ons &amp; Entertainment</span>
                <span id="cmod-sum-other" style="color:var(--cp-text, #fff); font-weight:600;">₱${pricing.otherBase.toLocaleString()}</span>
              </div>
            `}
            <div style="display:flex; justify-content:space-between;">
              <span style="color:var(--cp-text-dim, #9a8a7c);">Out-of-Town Charges (5%)</span>
              <span id="cmod-sum-oot" style="color:var(--cp-gold, #c49a3c); font-weight:600;">+₱${pricing.outOfTownCharge.toLocaleString()}</span>
            </div>
            ${pricing.serviceChargeAmt > 0 ? `
              <div style="display:flex; justify-content:space-between;">
                <span style="color:var(--cp-text-dim, #9a8a7c);">Service Charge (${pricing.svcPct}%)</span>
                <span id="cmod-sum-svc" style="color:var(--cp-gold, #c49a3c); font-weight:600;">+₱${pricing.serviceChargeAmt.toLocaleString()}</span>
              </div>
            ` : ''}
            <div style="border-top:1px solid rgba(196,154,60,0.3); margin-top:4px; padding-top:8px; display:flex; justify-content:space-between; font-size:15px; font-weight:800;">
              <span style="color:var(--cp-gold, #c49a3c);">Official Total Amount</span>
              <span id="cmod-sum-total" style="color:var(--cp-gold, #c49a3c);">₱${pricing.grandTotal.toLocaleString()}</span>
            </div>
            <div style="display:flex; justify-content:space-between; font-size:12px; color:var(--cp-text-dim, #9a8a7c); margin-top:4px;">
              <span>Required Downpayment (50% Base)</span>
              <span id="cmod-sum-dp">₱${pricing.downpaymentVal.toLocaleString()}</span>
            </div>
            <div style="display:flex; justify-content:space-between; font-size:12px; color:var(--cp-text-dim, #9a8a7c);">
              <span>Remaining Balance (50% + Charges)</span>
              <span id="cmod-sum-bal">₱${pricing.finalBalanceVal.toLocaleString()}</span>
            </div>
          </div>

          <div style="display:flex; gap:10px; justify-content:flex-end; margin-top:20px; border-top:1px solid var(--cp-border, rgba(180,140,60,0.2)); padding-top:16px;">
            <button type="button" onclick="window.cancelCustomerPackageModification()" style="padding:10px 18px; border-radius:8px; border:1px solid var(--cp-border, rgba(180,140,60,0.3)); background:transparent; color:var(--cp-text, #fff); font-weight:600; cursor:pointer;">
              Cancel
            </button>
            <button type="button" id="cmod-save-btn-bottom" onclick="window.saveCustomerModifiedPackage()" style="padding:10px 26px; border-radius:8px; border:none; background:var(--cp-gold, #c49a3c); color:#1a1612; font-weight:700; cursor:pointer;">
              Save Modifications
            </button>
          </div>
        </div>

      </div>

      <!-- RIGHT COLUMN: Unified Catalog & Package Customizations (Added Items at Top) -->
      <div class="cwo-catalog-side" style="background:var(--cp-bg2, #18120c); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:12px; padding:18px; position:sticky; top:20px; max-height:calc(100vh - 80px); overflow-y:auto; display:flex; flex-direction:column; gap:14px;">
        <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid rgba(196,154,60,0.2); padding-bottom:8px; flex-wrap:wrap; gap:8px;">
          <div>
            <div style="font-size:13px; font-weight:800; color:var(--cp-gold, #c49a3c); text-transform:uppercase; letter-spacing:1px;">
              Add &amp; Customize Package Items
            </div>
            <div style="font-size:11px; color:var(--cp-text-dim, #9a8a7c); margin-top:2px;">
              Selected package items appear at the top of the catalog for direct customization.
            </div>
          </div>
          <div id="cmod-pkg-item-count" style="font-size:11.5px; font-weight:700; color:var(--cp-gold, #c49a3c); border:1px solid rgba(196,154,60,0.4); border-radius:6px; padding:4px 10px;">
            ${(window.customerModifyingItems || []).length} Items in Package
          </div>
        </div>
        <div>
          <input type="text" id="cmod-search" placeholder="Search menu, drinks, decor &amp; equipment..." value="${esc(window.customerModifyingSearch || '')}" oninput="window.filterCustomerModifyCatalog(this.value)" style="width:100%; padding:9px 12px; background:var(--cp-bg3, #221a12); border:1px solid var(--cp-border, rgba(180,140,60,0.25)); border-radius:6px; color:var(--cp-text, #fff); font-size:12px; box-sizing:border-box;">
        </div>
        <div id="cmod-cat-filters" class="cat-filters" style="display:flex; flex-wrap:wrap; gap:6px;"></div>
        <div id="cmod-catalog-grid" class="cat-grid" style="display:grid; grid-template-columns: repeat(auto-fill, minmax(195px, 1fr)); gap:12px;"></div>
      </div>

    </div>
  `;

  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.updateModifyPricingLive = function () {
  const pricing = window.computeCustomerModifyPricing();

  const foodEl = document.getElementById('cmod-sum-food');
  if (foodEl) foodEl.textContent = `₱${(pricing.isPremade ? pricing.basePrice : pricing.foodBase).toLocaleString()}`;
  const equipEl = document.getElementById('cmod-sum-equip');
  if (equipEl) equipEl.textContent = `₱${pricing.equipBase.toLocaleString()}`;
  const decorEl = document.getElementById('cmod-sum-decor');
  if (decorEl) decorEl.textContent = `₱${pricing.decorBase.toLocaleString()}`;
  const otherEl = document.getElementById('cmod-sum-other');
  if (otherEl) otherEl.textContent = pricing.isPremade ? `+₱${pricing.extraItemsTotal.toLocaleString()}` : `₱${pricing.otherBase.toLocaleString()}`;
  const ootEl = document.getElementById('cmod-sum-oot');
  if (ootEl) ootEl.textContent = `+₱${pricing.outOfTownCharge.toLocaleString()}`;
  const svcEl = document.getElementById('cmod-sum-svc');
  if (svcEl) svcEl.textContent = `+₱${pricing.serviceChargeAmt.toLocaleString()}`;
  const totalEl = document.getElementById('cmod-sum-total');
  if (totalEl) totalEl.textContent = `₱${pricing.grandTotal.toLocaleString()}`;
  const hdrTotalEl = document.getElementById('cmod-hdr-total');
  if (hdrTotalEl) hdrTotalEl.textContent = `₱${pricing.grandTotal.toLocaleString()}`;
  const dpEl = document.getElementById('cmod-sum-dp');
  if (dpEl) dpEl.textContent = `₱${pricing.downpaymentVal.toLocaleString()}`;
  const balEl = document.getElementById('cmod-sum-bal');
  if (balEl) balEl.textContent = `₱${pricing.finalBalanceVal.toLocaleString()}`;

  const otcNotice = document.getElementById('cmod-otc-notice');
  if (otcNotice) {
    otcNotice.style.display = !pricing.isMalabon ? 'block' : 'none';
    otcNotice.textContent = `Out-of-Town Venue (+5% Charge): +₱${pricing.outOfTownCharge.toLocaleString()}`;
  }
  if (typeof updateDawContextBar === 'function') updateDawContextBar();
};

window.recalcCustomerModifyPricing = function () {
  window.updateModifyPricingLive();
};

window.toggleCustomerModifyVIP = function (checked) {
  const fields = document.getElementById('cmod-vip-fields');
  if (fields) fields.style.display = checked ? 'grid' : 'none';
  window.syncCustomerModifyFormToRes();
};

window.onCustomerModifyVIPCountInput = function (inpEl) {
  if (!inpEl) return;
  const currentPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(window.customerModifyingRes?.pax) || 50;
  inpEl.max = currentPax;
  const errEl = document.getElementById('cmod-vip-err');
  let val = parseInt(inpEl.value, 10);
  if (isNaN(val) || val < 1) {
    if (errEl) {
      errEl.textContent = `VIP count must be at least 1.`;
      errEl.style.display = 'block';
    }
    inpEl.style.borderColor = '#ef4444';
  } else if (val > currentPax) {
    inpEl.value = currentPax;
    if (errEl) {
      errEl.textContent = `VIP count cannot exceed total guest count (${currentPax} pax).`;
      errEl.style.display = 'block';
    }
    inpEl.style.borderColor = '#ef4444';
  } else {
    if (errEl) errEl.style.display = 'none';
    inpEl.style.borderColor = 'var(--cp-border, rgba(180,140,60,0.25))';
  }
  window.syncCustomerModifyFormToRes();
};

window.validateCustomerModifyTimeAndCalltime = function () {
  const ctEl = document.getElementById('cmod-calltime');
  const tsEl = document.getElementById('cmod-timeframe-start');
  const teEl = document.getElementById('cmod-timeframe-end');
  const ctErr = document.getElementById('cmod-calltime-err');
  const tfErr = document.getElementById('cmod-timeframe-err');
  const toMin = t => {
    if (!t) return null;
    const [h, m] = t.split(':').map(Number);
    return (isNaN(h) || isNaN(m)) ? null : h * 60 + m;
  };
  const sMin = toMin(tsEl?.value);
  const eMin = toMin(teEl?.value);
  const cMin = toMin(ctEl?.value);

  if (sMin !== null && eMin !== null) {
    let dur = eMin - sMin;
    if (dur <= 0) dur = (eMin + 1440) - sMin;
    if (tfErr) tfErr.style.display = dur < 60 ? 'block' : 'none';
  }
  if (cMin !== null && sMin !== null) {
    if (ctErr) ctErr.style.display = cMin > sMin ? 'block' : 'none';
  }
  window.syncCustomerModifyFormToRes();
};

window.onCustomerModifySetupChange = function (newSetupVal) {
  window.syncCustomerModifyFormToRes();
  const isCustom = String(newSetupVal || '').toLowerCase().includes('custom');
  const noticeEl = document.getElementById('cmod-custom-setup-notice');
  if (noticeEl) noticeEl.style.display = isCustom ? 'block' : 'none';

  const res = window.customerModifyingRes || {};
  if (window.getCustomerModifyOrigin(res) !== 'custom') return;
  const currentPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(res.pax) || 50;

  if (!isCustom && typeof calculateLiveSetupEquipment === 'function') {
    const foodCount = (window.customerModifyingItems || []).filter(i => ['food', 'dessert'].includes(String(i.cat || '').toLowerCase())).length || 4;
    const liveEq = calculateLiveSetupEquipment(newSetupVal, currentPax, foodCount);
    if (liveEq && Array.isArray(liveEq.items) && liveEq.items.length > 0) {
      // Keep non-equipment items and user-customized equipment, refresh auto-allocated equipment
      const nonEq = (window.customerModifyingItems || []).filter(i => String(i.cat || '').toLowerCase() !== 'equipment');
      const newEqItems = liveEq.items.map((eq, idx) => {
        const cItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => String(c.id) === String(eq.id) || (c.name && eq.name && c.name.toLowerCase() === eq.name.toLowerCase()));
        const uP = parseFloat(eq.price ?? cItem?.price ?? 0) || 0;
        const qty = parseInt(eq.qty || eq.quantity || eq.customQty || 1) || 1;
        return {
          ...(cItem || {}),
          ...eq,
          id: (cItem && cItem.id) || eq.id || ('eq_' + idx),
          name: eq.name || (cItem && cItem.name),
          cat: 'equipment',
          price: uP,
          image: (cItem && cItem.image) || eq.image || 'haldens_logo.png',
          desc: (cItem && cItem.desc) || eq.desc || '',
          customQty: qty,
          autoQty: qty,
          snapshotPrice: uP * qty,
          isCustomized: false,
          isFree: false,
          isAutoAdded: true,
          _showCustomize: false
        };
      });
      window.customerModifyingItems = [...nonEq, ...newEqItems];
    }
  }
  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.onCustomerModifyPaxInput = function (newPaxRaw) {
  const paxInput = document.getElementById('cmod-pax');
  const paxErr = document.getElementById('cmod-pax-err');
  const parsed = parseInt(newPaxRaw, 10);
  if (isNaN(parsed) || parsed < 10 || parsed > 200) {
    if (paxErr) paxErr.style.display = 'block';
    if (paxInput) paxInput.style.borderColor = '#ef4444';
  } else {
    if (paxErr) paxErr.style.display = 'none';
    if (paxInput) paxInput.style.borderColor = 'var(--cp-border, rgba(180,140,60,0.25))';
  }
  const p = Math.min(200, Math.max(10, isNaN(parsed) ? 10 : parsed));
  if (window.customerModifyingRes) window.customerModifyingRes.pax = p;

  // Update VIP Max & clamp VIP count if needed
  const vipMaxLbl = document.getElementById('cmod-vip-max-lbl');
  if (vipMaxLbl) vipMaxLbl.textContent = String(p);
  const vipCountInput = document.getElementById('cmod-vip-count');
  if (vipCountInput) {
    vipCountInput.max = p;
    if (parseInt(vipCountInput.value, 10) > p) {
      vipCountInput.value = p;
    }
  }

  // Recalculate item prices and auto equipment quantities for the new Pax
  const origin = window.getCustomerModifyOrigin(window.customerModifyingRes);
  if (origin === 'custom') {
    (window.customerModifyingItems || []).forEach(item => {
      const cItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => String(c.id) === String(item.id) || (c.name && item.name && c.name.toLowerCase() === item.name.toLowerCase()));
      const isEq = String(item.cat || '').toLowerCase() === 'equipment';
      if (item.customPax && parseInt(item.customPax) > p) {
        item.customPax = p;
      }
      if (isEq) {
        const resolved = Object.assign({}, cItem || {}, item);
        const newAuto = (typeof getEquipmentAllocatedQty === 'function')
          ? getEquipmentAllocatedQty(resolved, p, window.customerModifyingItems)
          : (item.autoQty || 1);
        item.autoQty = newAuto;
        if (!item.isCustomized) {
          item.customQty = newAuto;
        }
      }
      item._needsRecalc = true;
      item.snapshotPrice = window.computeCustomerModifyItemPrice(item, p);
      delete item._needsRecalc;
    });
  }

  window.syncCustomerModifyFormToRes();
  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.toggleCustomerModifyItem = function (itemId) {
  const res = window.customerModifyingRes || {};
  const origin = window.getCustomerModifyOrigin(res);
  if (origin !== 'custom') {
    alert('Premade package items are locked and cannot be added or removed.');
    return;
  }

  window.syncCustomerModifyFormToRes();
  const existingIdx = (window.customerModifyingItems || []).findIndex(c =>
    String(c.id) === String(itemId) ||
    (c.name && typeof CAT !== 'undefined' && CAT.some(cat => String(cat.id) === String(itemId) && cat.name.toLowerCase() === c.name.toLowerCase()))
  );

  if (existingIdx !== -1) {
    const removedItem = window.customerModifyingItems[existingIdx];
    const catItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => String(c.id) === String(removedItem.id) || (c.name && removedItem.name && c.name.toLowerCase() === removedItem.name.toLowerCase()));
    window.customerModifyingItems.splice(existingIdx, 1);

    // If removing a special parent item, also remove its child options
    if (catItem && typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(catItem) && typeof window.removeChildItemsForSpecialParent === 'function') {
      window.customerModifyingItems = window.removeChildItemsForSpecialParent(catItem.name || catItem.identify, window.customerModifyingItems);
    }
  } else {
    const catItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => String(c.id) === String(itemId));
    if (!catItem) return;
    const pCount = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(res.pax) || 50;
    const catLower = String(catItem.cat || catItem.category || '').toLowerCase();
    const isEq = catLower === 'equipment';

    // Special child option validation (parent must be in package, max 3 child options)
    const parentKey = typeof window.getSpecialParentKey === 'function' ? window.getSpecialParentKey(catItem) : null;
    if (parentKey) {
      if (typeof window.isParentSpecialItemInPackage === 'function' && !window.isParentSpecialItemInPackage(catItem, window.customerModifyingItems)) {
        alert('Please add the parent special item to the package before selecting its options.');
        return;
      }
      const currentChildren = (window.customerModifyingItems || []).filter(c => {
        const ck = typeof window.getSpecialParentKey === 'function' ? window.getSpecialParentKey(c) : null;
        return ck && ck === parentKey;
      });
      if (currentChildren.length >= 3) {
        alert('You can only select up to 3 included options for this special item.');
        return;
      }
    }

    // Dessert limit rule (max 3 regular desserts)
    if (catLower === 'dessert' && !(typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(catItem)) && catItem.identify !== 'ice_cream_option') {
      const currentDesserts = (window.customerModifyingItems || []).filter(i => String(i.cat || '').toLowerCase() === 'dessert' && !(typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(i)) && i.identify !== 'ice_cream_option');
      if (currentDesserts.length >= 3) {
        alert('You are only allowed to have up to 3 dessert items in the package.');
        return;
      }
    }

    let autoQ = 1;
    if (isEq && typeof getEquipmentAllocatedQty === 'function') {
      autoQ = getEquipmentAllocatedQty(catItem, pCount, window.customerModifyingItems);
    }
    const isSubOpt = window.isCustomerModifySubOption(catItem);
    const dynamicP = isSubOpt ? 0 : (isEq ? (parseFloat(catItem.price) || 0) * autoQ : ((typeof getDynamicPrice === 'function') ? getDynamicPrice(catItem, pCount) : (parseFloat(catItem.price) || 0)));

    // Target Budget guard (if Target Budget > 0 on Custom Package)
    const budgetVal = parseFloat(document.getElementById('cmod-budget')?.value || 0);
    if (budgetVal > 0 && dynamicP > 0) {
      const curPricing = window.computeCustomerModifyPricing();
      if ((curPricing.subtotal + dynamicP) > budgetVal) {
        alert(`Cannot add "${catItem.name}" (₱${Number(dynamicP).toLocaleString()}): Adding this item would exceed your Target Budget of ₱${budgetVal.toLocaleString()}.`);
        return;
      }
    }

    const newItem = {
      ...catItem,
      id: catItem.id,
      name: catItem.name,
      cat: catItem.cat || 'other',
      price: catItem.price || 0,
      image: catItem.image || catItem.image_url || 'haldens_logo.png',
      desc: catItem.desc || '',
      snapshotPrice: dynamicP,
      customQty: isEq ? autoQ : null,
      autoQty: isEq ? autoQ : null,
      customPax: null,
      specifications: '',
      isCustomized: false,
      isFree: isSubOpt,
      _showCustomize: false
    };
    window.customerModifyingItems.push(newItem);

    // Auto-select default child item when adding a Special Parent Item
    if (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(catItem)) {
      const pIdent = String(catItem.identify || '').toLowerCase();
      const pName = String(catItem.name || '').toLowerCase();
      const childPool = (typeof CAT !== 'undefined' ? CAT : []).filter(c => {
        if (window.isSpecialParentItem(c)) return false;
        const pk = window.getSpecialParentKey ? window.getSpecialParentKey(c) : null;
        if (pIdent === 'drinks_package' || pName.includes('unlimited drinks')) return pk === 'drinks_package' || (c.cat === 'drink' && !window.isSpecialParentItem(c));
        if (pIdent === 'mobile_bar' || pName.includes('mobile bar')) return pk === 'mobile_bar' || (c.identify && c.identify.includes('mobile_bar'));
        if (pIdent === 'ice_cream' || pName.includes('ice cream')) return pk === 'ice_cream' || (c.identify && c.identify.includes('ice_cream'));
        return pk === catItem.id || pk === catItem.name || pk === pIdent;
      });

      if (childPool.length > 0) {
        const defaultChild = (pIdent === 'drinks_package' || pName.includes('unlimited drinks'))
          ? (childPool.find(c => c.name.toLowerCase().includes('water')) || childPool[0])
          : childPool[0];
        if (defaultChild && !window.customerModifyingItems.some(c => String(c.id) === String(defaultChild.id) || (c.name && c.name.toLowerCase() === defaultChild.name.toLowerCase()))) {
          window.customerModifyingItems.push({
            ...defaultChild,
            id: defaultChild.id,
            name: defaultChild.name,
            cat: defaultChild.cat || 'drink',
            price: 0,
            snapshotPrice: 0,
            image: defaultChild.image || defaultChild.image_url || 'haldens_logo.png',
            desc: defaultChild.desc || '',
            isFree: true,
            isAutoAdded: true,
            _showCustomize: false
          });
        }
      }
    }
  }

  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.removeCustomerModifyItem = function (idx) {
  if (idx >= 0 && idx < window.customerModifyingItems.length) {
    const it = window.customerModifyingItems[idx];
    if (it) window.toggleCustomerModifyItem(it.id || it.name);
  }
};

window.changeCustomerEquipmentQty = function (idx, delta) {
  const item = window.customerModifyingItems[idx];
  if (!item) return;
  const curQ = parseInt(item.customQty ?? item.autoQty ?? 1) || 1;
  const newQ = Math.min(999, Math.max(1, curQ + delta));
  window.setCustomerEquipmentQty(item.id, newQ);
};

window.setCustomerEquipmentQty = function (itemId, rawQty) {
  const item = (window.customerModifyingItems || []).find(c => String(c.id) === String(itemId) || (c.name && String(c.name).toLowerCase() === String(itemId).toLowerCase()));
  if (!item) return;
  const newQ = Math.min(999, Math.max(1, parseInt(rawQty, 10) || 1));
  const unitP = parseFloat(item.price) || 0;
  const newSnap = unitP * newQ;

  const budgetVal = parseFloat(document.getElementById('cmod-budget')?.value || 0);
  if (budgetVal > 0 && newSnap > (item.snapshotPrice || 0)) {
    const curPricing = window.computeCustomerModifyPricing();
    const diff = newSnap - (item.snapshotPrice || 0);
    if ((curPricing.subtotal + diff) > budgetVal) {
      alert(`Increasing quantity to ${newQ} pcs would exceed your Target Budget of ₱${budgetVal.toLocaleString()}.`);
      window.renderCustomerModifyCatalog();
      return;
    }
  }

  item.customQty = newQ;
  item.isCustomized = (item.autoQty != null ? newQ !== item.autoQty : true);
  item.snapshotPrice = newSnap;
  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.updateCustomerItemSpecs = function (idx, val) {
  const item = window.customerModifyingItems[idx];
  if (item) {
    item.specifications = val;
    item.isCustomized = !!(val && val.trim().length > 0) || !!(item.customPax || (item.customQty != null && item.customQty !== item.autoQty));
  }
};

window.updateCustomerItemSpecsById = function (itemId, val) {
  const item = (window.customerModifyingItems || []).find(c =>
    String(c.id) === String(itemId) ||
    (c.name && typeof CAT !== 'undefined' && CAT.some(cat => String(cat.id) === String(itemId) && cat.name.toLowerCase() === c.name.toLowerCase()))
  );
  if (item) {
    item.specifications = val;
    item.isCustomized = !!(val && val.trim().length > 0) || !!(item.customPax || (item.customQty != null && item.customQty !== item.autoQty));
  }
};

window.toggleCustomerModifyFoodCustomize = function (itemId, event) {
  if (event) event.stopPropagation();
  const item = (window.customerModifyingItems || []).find(c =>
    String(c.id) === String(itemId) ||
    (c.name && typeof CAT !== 'undefined' && CAT.some(cat => String(cat.id) === String(itemId) && cat.name.toLowerCase() === c.name.toLowerCase()))
  );
  if (item) {
    item._showCustomize = !item._showCustomize;
    window.renderCustomerModifyCatalog();
  }
};

window.updateCustomerItemPax = function (itemId, newPaxRaw) {
  const item = (window.customerModifyingItems || []).find(c =>
    String(c.id) === String(itemId) ||
    (c.name && typeof CAT !== 'undefined' && CAT.some(cat => String(cat.id) === String(itemId) && cat.name.toLowerCase() === c.name.toLowerCase()))
  );
  if (!item) return;
  const maxPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(window.customerModifyingRes?.pax) || 50;
  let val = parseInt(newPaxRaw, 10);
  if (isNaN(val) || val < 1) val = 1;
  // Allow pax customization to go above the base reservation pax up to 3 digits (limit 999)
  if (val > 999) {
    alert('Custom portion pax cannot exceed 3 digits (999 pax).');
    val = 999;
  }

  const prevPax = item.customPax;
  const prevSnap = item.snapshotPrice;
  item.customPax = (val === maxPax) ? null : val;
  item._needsRecalc = true;
  const newSnap = window.computeCustomerModifyItemPrice(item, maxPax);
  delete item._needsRecalc;

  const budgetVal = parseFloat(document.getElementById('cmod-budget')?.value || 0);
  if (budgetVal > 0 && newSnap > (prevSnap || 0)) {
    const curPricing = window.computeCustomerModifyPricing();
    if (curPricing.subtotal > budgetVal) {
      item.customPax = prevPax;
      item.snapshotPrice = prevSnap;
      alert(`Increasing portion pax to ${val} would exceed your Target Budget of ₱${budgetVal.toLocaleString()}.`);
      window.renderCustomerModifyCatalog();
      return;
    }
  }

  item.snapshotPrice = newSnap;
  item.isCustomized = !!(item.customPax || (item.specifications && item.specifications.trim().length > 0));
  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.resetCustomerModifyItemCustomization = function (itemId) {
  const item = (window.customerModifyingItems || []).find(c => String(c.id) === String(itemId));
  if (!item) return;
  const maxPax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(window.customerModifyingRes?.pax) || 50;
  const isEq = String(item.cat || '').toLowerCase() === 'equipment';
  if (isEq) {
    const cItem = (typeof CAT !== 'undefined' ? CAT : []).find(c => String(c.id) === String(item.id) || (c.name && item.name && c.name.toLowerCase() === item.name.toLowerCase()));
    const resolved = Object.assign({}, cItem || {}, item);
    delete resolved.customQty;
    const autoQ = (typeof getEquipmentAllocatedQty === 'function')
      ? getEquipmentAllocatedQty(resolved, maxPax, window.customerModifyingItems)
      : (item.autoQty || 1);
    item.autoQty = autoQ;
    item.customQty = autoQ;
  } else {
    item.customPax = null;
  }
  item.specifications = '';
  item.isCustomized = false;
  item._needsRecalc = true;
  item.snapshotPrice = window.computeCustomerModifyItemPrice(item, maxPax);
  delete item._needsRecalc;
  window.renderCustomerModifyCatalog();
  window.updateModifyPricingLive();
};

window.setCustomerModifyCatTab = function (tab) {
  window.syncCustomerModifyFormToRes();
  window.customerModifyingCatFilter = tab;
  window.renderCustomerModifyCatalog();
};

window.filterCustomerModifyCatalog = function (q) {
  window.syncCustomerModifyFormToRes();
  window.customerModifyingSearch = q;
  window.renderCustomerModifyCatalog();
};

window.cancelCustomerPackageModification = function () {
  window.customerModifyMode = false;
  window.customerModifyingRes = null;
  window.customerModifyingItems = [];
  window.syncCustomerAIFabVisibility();

  const modBtn = document.getElementById('resd-modify-btn');
  const expBtn = document.getElementById('resd-export-btn');
  const saveBtn = document.getElementById('resd-save-mod-btn');
  const cancelBtn = document.getElementById('resd-cancel-mod-btn');

  if (saveBtn) saveBtn.style.display = 'none';
  if (cancelBtn) cancelBtn.style.display = 'none';
  if (modBtn) modBtn.style.display = 'inline-flex';
  if (expBtn) expBtn.style.display = 'inline-flex';

  window.renderReservationDetailContent();
};

window.saveCustomerModifiedPackage = async function () {
  const res = window.customerModifyingRes;
  if (!res || !res.id) {
    alert('No active reservation is currently being modified.');
    return;
  }

  window.syncCustomerModifyFormToRes();
  const occSel = document.getElementById('cmod-occasion')?.value || res.occasion || res.type || 'Wedding';
  const occOther = document.getElementById('cmod-occasion-other')?.value.trim() || '';
  const occasion = (occSel === 'Others') ? occOther : occSel;

  const themeSel = document.getElementById('cmod-theme')?.value || res.theme || 'Classic';
  const themeOther = document.getElementById('cmod-theme-other')?.value.trim() || '';
  const theme = (themeSel === 'Others') ? themeOther : themeSel;

  const pax = parseInt(document.getElementById('cmod-pax')?.value) || parseInt(res.pax) || 50;
  const setupVal = document.getElementById('cmod-setup')?.value || res.eventSetup || 'Complete Setup';
  const date = document.getElementById('cmod-date')?.value || res.date || '';

  const tStart = document.getElementById('cmod-timeframe-start')?.value || '';
  const tEnd = document.getElementById('cmod-timeframe-end')?.value || '';
  const timeframe = (tStart && tEnd) ? `${tStart} - ${tEnd}` : '';

  const callTime = document.getElementById('cmod-calltime')?.value || res.callTime || '08:00';
  const city = document.getElementById('cmod-city')?.value || res.venueLocation || 'Malabon';
  const venue = document.getElementById('cmod-venue')?.value.trim() || res.venue || '';
  const desc = document.getElementById('cmod-desc')?.value.trim() || '';
  const budgetVal = parseFloat(document.getElementById('cmod-budget')?.value || 0);

  const vipCheck = document.getElementById('cmod-vip-check');
  const vipCount = parseInt(document.getElementById('cmod-vip-count')?.value) || 0;
  const vipService = document.getElementById('cmod-vip-service')?.value || 'Properly Catered';
  const vipObj = {
    enabled: !!(vipCheck && vipCheck.checked),
    count: (vipCheck && vipCheck.checked) ? vipCount : 0,
    service: vipService
  };

  let errors = [];
  if (!desc) errors.push('Event Description is required.');
  if (!occasion) errors.push('Occasion is required.');
  if (!theme) errors.push('Theme / Style is required.');
  if (!pax || pax < 10 || pax > 200) errors.push('Guest Count (Pax) must be between 10 and 200.');
  if (vipObj.enabled) {
    if (vipCount < 1) errors.push('Please enter a valid VIP count (at least 1).');
    else if (vipCount > pax) errors.push(`VIP count (${vipCount}) cannot exceed total guest count (${pax} pax).`);
  }
  if (!date) errors.push('Event Date is required.');
  if (date && typeof isDayHardDisabled === 'function' && isDayHardDisabled(date)) {
    errors.push('The selected event date falls on a day of the week that has been hard disabled.');
  }
  if (!tStart || !tEnd) {
    errors.push('Start and End Time Frame are required.');
  } else {
    const toMinutes = t => { const [h, m] = t.split(':').map(Number); return (isNaN(h) || isNaN(m)) ? null : h * 60 + m; };
    const sMin = toMinutes(tStart);
    const eMin = toMinutes(tEnd);
    const cMin = toMinutes(callTime);
    if (sMin !== null && eMin !== null) {
      let dur = eMin - sMin;
      if (dur <= 0) dur = (eMin + 1440) - sMin;
      if (dur < 60) errors.push('The event time frame must be at least 1 hour.');
    }
    if (cMin !== null && sMin !== null && cMin > sMin) {
      errors.push('Call time cannot be later than event start time.');
    }
  }
  if (!venue) errors.push('Venue Address is required.');

  const hasFood = (window.customerModifyingItems || []).some(i => ['food', 'dessert'].includes(String(i.cat || '').toLowerCase()));
  if (!hasFood) errors.push('Please select at least one item from Food or Dessert.');

  const hasUnlimitedDrinks = (window.customerModifyingItems || []).some(i => i.identify === 'drinks_package' || String(i.name || '').toLowerCase().includes('unlimited drinks'));
  const hasSpecificDrink = (window.customerModifyingItems || []).some(i => String(i.cat || '').toLowerCase() === 'drink' && i.identify !== 'drinks_package' && !String(i.name || '').toLowerCase().includes('unlimited drinks'));
  if (hasUnlimitedDrinks && !hasSpecificDrink) {
    errors.push('Please select at least one drink flavor option for Unlimited Drinks.');
  }

  const pricing = window.computeCustomerModifyPricing();
  if (!pricing.isPremade && budgetVal > 0 && pricing.subtotal > budgetVal) {
    errors.push(`Your package subtotal (₱${pricing.subtotal.toLocaleString()}) exceeds your Target Budget (₱${budgetVal.toLocaleString()}).`);
  }

  if (errors.length > 0) {
    if (typeof openErrorModal === 'function') openErrorModal(errors.join('\n\n'));
    else alert(errors.join('\n'));
    return;
  }

  const grandTotal = pricing.grandTotal;
  const outOfTownCharge = pricing.outOfTownCharge;
  const downpaymentAmt = pricing.downpaymentVal;
  const finalPaymentAmt = pricing.finalBalanceVal;

  const saveBtn = document.getElementById('resd-save-mod-btn');
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = 'Saving...';
  }
  const bottomSaveBtn = document.getElementById('cmod-save-btn-bottom');
  if (bottomSaveBtn) {
    bottomSaveBtn.disabled = true;
    bottomSaveBtn.textContent = 'Saving...';
  }

  const updatedItems = (window.customerModifyingItems || []).map(i => ({
    id: i.id,
    name: i.name,
    cat: i.cat,
    price: i.price,
    snapshotPrice: i.snapshotPrice != null ? i.snapshotPrice : i.price,
    customQty: i.customQty,
    autoQty: i.autoQty,
    customPax: i.customPax,
    specifications: i.specifications || '',
    isCustomized: !!i.isCustomized,
    isFree: !!i.isFree,
    isAdditional: !!i.isAdditional,
    addedAsExtra: !!i.addedAsExtra,
    isEventSetupEquipment: !!i.isEventSetupEquipment,
    isAutoAdded: !!i.isAutoAdded
  }));
  const updatedNames = updatedItems.map(i => i.name).filter(Boolean);

  const existingExecPlan = res.execution_plan || res.executionPlan || {};
  const updatedExecPlan = {
    ...existingExecPlan,
    _firebase_extras: {
      ...(existingExecPlan._firebase_extras || {}),
      items: updatedItems
    }
  };

  const updatePayload = {
    items: updatedItems,
    custom_items: updatedItems,
    packageItems: updatedNames,
    package_items: updatedNames,
    execution_plan: updatedExecPlan,
    executionPlan: updatedExecPlan,
    pax: pax,
    type: occasion,
    occasion: occasion,
    theme: theme,
    eventSetup: setupVal,
    event_setup: setupVal,
    date: date,
    time: timeframe,
    timeframe: timeframe,
    callTime: callTime,
    call_time: callTime,
    venue: venue,
    venueAddress: venue,
    venueLocation: city,
    venue_location: city,
    city: city,
    description: desc,
    basePrice: pricing.basePrice,
    base_price: pricing.basePrice,
    amount: String(grandTotal),
    total_amount: grandTotal,
    totalAmount: grandTotal,
    outOfTownCharge: outOfTownCharge,
    out_of_town_charge: outOfTownCharge,
    vip: vipObj,
    isVIP: vipObj.enabled,
    vipCount: vipObj.count,
    vipService: vipObj.service,
    downpayment_amount: downpaymentAmt,
    downpaymentAmount: downpaymentAmt,
    final_payment_amount: finalPaymentAmt,
    finalPaymentAmount: finalPaymentAmt,
    updatedAt: new Date().toISOString(),
    last_modified_by: 'customer'
  };

  try {
    if (window.firebaseDB && window.firebaseFns) {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'reservations', String(res.id)), updatePayload);
    }

    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      try {
        await sb.from('reservations').update({
          items: updatedItems,
          custom_items: updatedItems,
          package_items: updatedNames,
          execution_plan: updatedExecPlan,
          base_price: pricing.basePrice,
          amount: grandTotal,
          out_of_town_charge: outOfTownCharge,
          vip: vipObj,
          event_setup: setupVal,
          pax: pax,
          type: occasion,
          theme: theme,
          description: desc,
          date: date,
          timeframe: timeframe,
          call_time: callTime,
          venue: venue,
          venue_location: city,
          downpayment_amount: downpaymentAmt,
          final_payment_amount: finalPaymentAmt,
          updated_at: new Date().toISOString()
        }).eq('id', res.id);

        await sb.from('reservation_items').delete().eq('reservation_id', res.id);
        const riRows = updatedItems.map(it => ({
          reservation_id: res.id,
          name: it.name,
          cat: it.cat || 'other',
          price: parseFloat(it.price || 0) || 0,
          dynamic_price: parseFloat(it.snapshotPrice || 0) || 0,
          is_free: !!(it.isFree)
        }));
        if (riRows.length > 0) {
          await sb.from('reservation_items').insert(riRows);
        }
      } catch (sbErr) {
        console.warn('Supabase update notification:', sbErr);
      }
    }

    // Record structured reservation modification history for the Logs tab
    try {
      const _resIdKey = String(res.id);
      const _existingHist = Array.isArray(res.modification_history) ? res.modification_history : [];
      let _storedHist = [];
      try {
        const _rawHist = localStorage.getItem('halden_res_mod_history_' + _resIdKey);
        if (_rawHist) _storedHist = JSON.parse(_rawHist);
      } catch (e) {}
      const _modHist = (_existingHist.length > 0) ? _existingHist : _storedHist;

      const _origSnap = window._customerModOriginalRes || {};
      const origPax = _origSnap.pax;
      const origType = _origSnap.type || _origSnap.occasion;
      const origTheme = _origSnap.theme;
      const origDate = _origSnap.date;
      const origTime = _origSnap.time;
      const origAmount = _origSnap.amount;
      const origVenue = _origSnap.venue;
      const origCity = _origSnap.city;

      const _fieldChanges = [];
      if (date && origDate && String(date) !== String(origDate)) {
        _fieldChanges.push(`Event date changed from ${origDate} to ${date}`);
      }
      if (timeframe && origTime && String(timeframe) !== String(origTime)) {
        _fieldChanges.push(`Time range changed from ${origTime} to ${timeframe}`);
      }
      if (pax && origPax && Number(pax) !== Number(origPax)) {
        _fieldChanges.push(`Guest count changed from ${origPax} pax to ${pax} pax`);
      }
      if (venue && origVenue && String(venue) !== String(origVenue)) {
        _fieldChanges.push(`Venue address changed from "${origVenue}" to "${venue}"`);
      }
      if (city && origCity && String(city) !== String(origCity)) {
        _fieldChanges.push(`Location/City changed from "${origCity}" to "${city}"`);
      }
      if (occasion && origType && String(occasion) !== String(origType)) {
        _fieldChanges.push(`Occasion changed from "${origType}" to "${occasion}"`);
      }
      if (theme && origTheme && String(theme) !== String(origTheme)) {
        _fieldChanges.push(`Theme changed from "${origTheme}" to "${theme}"`);
      }
      if (grandTotal && origAmount && Number(grandTotal) !== Number(origAmount)) {
        _fieldChanges.push(`Total amount changed from ₱${Number(origAmount).toLocaleString()} to ₱${Number(grandTotal).toLocaleString()}`);
      }

      const _beforeItems = Array.isArray(_origSnap.items) ? _origSnap.items : (Array.isArray(res.items) ? res.items : []);
      const _afterItems = updatedItems || [];

      const _beforeNames = _beforeItems.map(i => typeof i === 'string' ? i : (i.name || '')).filter(Boolean);
      const _afterNames = _afterItems.map(i => typeof i === 'string' ? i : (i.name || '')).filter(Boolean);

      const _itemsAdded = _afterNames.filter(n => !_beforeNames.includes(n));
      const _itemsRemoved = _beforeNames.filter(n => !_afterNames.includes(n));

      const _itemsCustomized = [];
      _afterItems.forEach(ai => {
        if (typeof ai !== 'object' || !ai) return;
        const bi = _beforeItems.find(b => typeof b === 'object' && b && (b.name === ai.name || b.id === ai.id));
        const pPax = ai.customPax || ai.portion_pax;
        const pQty = ai.customQty;
        const pSpecs = (ai.specifications || ai.specs || '').trim();

        if (bi) {
          const oldPax = bi.customPax || bi.portion_pax;
          const oldQty = bi.customQty;
          const oldSpecs = (bi.specifications || bi.specs || '').trim();

          if (pPax && pPax !== oldPax) {
            _itemsCustomized.push(`${ai.name}: portion pax changed from ${oldPax || 'base'} to ${pPax} pax`);
          }
          if (pQty != null && pQty !== oldQty) {
            _itemsCustomized.push(`${ai.name}: quantity changed from ${oldQty || 1} to ${pQty} pcs`);
          }
          if (pSpecs && pSpecs !== oldSpecs) {
            _itemsCustomized.push(`${ai.name}: notes updated to "${pSpecs}"`);
          }
        } else {
          if (pPax) _itemsCustomized.push(`${ai.name}: customized to ${pPax} portion pax`);
          if (pQty != null && pQty > 1) _itemsCustomized.push(`${ai.name}: customized to ${pQty} pcs`);
          if (pSpecs) _itemsCustomized.push(`${ai.name}: notes "${pSpecs}"`);
        }
      });

      const nowD = new Date();
      const newModEntry = {
        id: 'mod-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5),
        reservation_id: res.id,
        type: 'modification',
        modified_by: 'Customer',
        timestamp: nowD.toISOString(),
        date_str: nowD.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
        time_str: nowD.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
        field_changes: _fieldChanges,
        items_added: _itemsAdded,
        items_removed: _itemsRemoved,
        items_customized: _itemsCustomized,
        summary: ''
      };

      const summaryParts = [];
      if (newModEntry.items_added.length > 0) summaryParts.push(`Added ${newModEntry.items_added.length} item(s): ${newModEntry.items_added.join(', ')}`);
      if (newModEntry.items_removed.length > 0) summaryParts.push(`Removed ${newModEntry.items_removed.length} item(s): ${newModEntry.items_removed.join(', ')}`);
      if (newModEntry.items_customized.length > 0) summaryParts.push(`Customized: ${newModEntry.items_customized.join('; ')}`);
      if (newModEntry.field_changes.length > 0) summaryParts.push(newModEntry.field_changes.join('; '));
      newModEntry.summary = summaryParts.join(' | ') || 'Customer saved package modifications.';

      _modHist.unshift(newModEntry);
      res.modification_history = _modHist;
      res.activity_logs = _modHist;
      updatePayload.modification_history = _modHist;
      updatePayload.activity_logs = _modHist;
      try {
        localStorage.setItem('halden_res_mod_history_' + _resIdKey, JSON.stringify(_modHist));
      } catch (e) {}

      if (sb) {
        sb.from('reservations').update({ activity_logs: _modHist }).eq('id', res.id).then(() => {}).catch(() => {});
      }
    } catch (_custModErr) {
      console.warn('[Customer Logs] Failed to record customer modification history:', _custModErr);
    }

    const liveRes = (window.RESERVATIONS || []).find(r => String(r.id) === String(res.id));
    if (liveRes) Object.assign(liveRes, updatePayload);
    if (window.activeCustomerReservation && String(window.activeCustomerReservation.id) === String(res.id)) {
      Object.assign(window.activeCustomerReservation, updatePayload);
    }
    if (window._profileResCache && window._profileResCache[res.id]) {
      Object.assign(window._profileResCache[res.id], updatePayload);
    }

    window.customerModifyMode = false;
    window.customerModifyingRes = null;
    window.customerModifyingItems = [];
    window.syncCustomerAIFabVisibility();

    const modBtn = document.getElementById('resd-modify-btn');
    const expBtn = document.getElementById('resd-export-btn');
    const saveBtnEl = document.getElementById('resd-save-mod-btn');
    const cancelBtnEl = document.getElementById('resd-cancel-mod-btn');

    if (saveBtnEl) {
      saveBtnEl.style.display = 'none';
      saveBtnEl.disabled = false;
      saveBtnEl.textContent = 'Save Changes';
    }
    if (cancelBtnEl) cancelBtnEl.style.display = 'none';
    if (modBtn) modBtn.style.display = 'inline-flex';
    if (expBtn) expBtn.style.display = 'inline-flex';

    alert('Your reservation package modifications have been successfully saved! The total amount is now ₱' + grandTotal.toLocaleString() + '.');
    window.renderReservationDetailContent();
  } catch (err) {
    console.error('Failed to save customer modified package:', err);
    alert('Failed to save modifications: ' + (err.message || err));
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save Changes'; }
    if (bottomSaveBtn) { bottomSaveBtn.disabled = false; bottomSaveBtn.textContent = 'Save Modifications'; }
  }
};

window.saveModifiedReservation = async function () {
  const resId = window._modifyingReservationId;
  if (!resId) {
    if (typeof openErrorModal === 'function') openErrorModal('No active reservation is currently being modified.');
    else alert('No active reservation is currently being modified.');
    return;
  }

  const getV = window.getSmartV;
  const desc = getV('cpkg-desc');
  const theme = getV('cpkg-theme');
  const pax = getV('cpkg-pax');
  const date = getV('cpkg-date');
  const occasion = getV('cpkg-occasion');
  const venueLocation = getV('cpkg-venue-location');
  const venue = getV('cpkg-venue');
  const timeframe = getV('cpkg-timeframe');
  const callTime = document.getElementById('cpkg-calltime')?.value || '';
  const eventSetupSlug = document.getElementById('cpkg-event-setup')?.value || '';

  let errors = [];
  if (!desc) errors.push('Event Description is required.');
  if (!occasion) errors.push('Occasion is required.');
  if (!theme) errors.push('Theme / Style is required.');
  if (!eventSetupSlug) errors.push('Setup Type is required.');
  if (!pax) errors.push('Pax (Guest Count) is required.');
  if (pax) {
    const pNum = parseInt(pax);
    if (pNum < 10) errors.push('The catering service requires a minimum of 10 guests.');
    if (pNum > 200) errors.push('The catering service cannot accommodate more than 200 guests.');
  }

  const vipEnabled = document.getElementById('cpkg-vip-check')?.checked;
  const vipCountStr = document.getElementById('cpkg-vip-count')?.value;
  const vipCount = parseInt(vipCountStr) || 0;
  const vipService = document.getElementById('cpkg-vip-service')?.value || '';
  if (vipEnabled) {
    if (!vipCountStr || vipCount <= 0) errors.push('Please enter a valid VIP count.');
    else if (pax && vipCount > parseInt(pax)) errors.push('VIPs cannot exceed total guest count (Pax).');
  }

  let tfStart = null, tfEnd = null;
  if (timeframe) {
    const tfParts = timeframe.split('-').map(s => s.trim());
    if (tfParts.length < 2) errors.push('Please select a valid event time frame with a start and end time.');
    else {
      const toMinutes = t => { const [h, m] = t.split(':').map(Number); return (isNaN(h) || isNaN(m)) ? null : h * 60 + m; };
      tfStart = toMinutes(tfParts[0]);
      tfEnd = toMinutes(tfParts[1]);
      if (tfStart === null || tfEnd === null) errors.push('Please select a valid event time frame.');
      else {
        let tfDuration = tfEnd - tfStart;
        if (tfDuration <= 0) tfDuration = (tfEnd + 1440) - tfStart;
        if (tfDuration < 60) errors.push('The event time frame must be at least 1 hour.');
      }
    }
  }

  if (callTime && tfStart !== null) {
    const toMin = t => { const [h, m] = t.split(':').map(Number); return (isNaN(h) || isNaN(m)) ? null : h * 60 + m; };
    const ctMin = toMin(callTime);
    if (ctMin !== null && ctMin > tfStart) {
      errors.push('Call time cannot be later than event start time.');
    }
  }

  const hasFood = customPkgItems.some(i => i.cat === 'food' || i.cat === 'dessert');
  const hasUnlimitedDrinks = customPkgItems.some(i => i.identify === 'drinks_package');
  const hasSpecificDrink = customPkgItems.some(i => i.cat === 'drink' && i.identify !== 'drinks_package');

  if (!hasFood) errors.push('Please select at least one item from Food or Dessert.');
  if (hasUnlimitedDrinks && !hasSpecificDrink) errors.push('Please select a specific flavor/drink choice for Unlimited Drinks.');

  if (errors.length > 0) {
    if (typeof openErrorModal === 'function') openErrorModal(errors.join('\n\n'));
    else alert(errors.join('\n\n'));
    return;
  }

  const pCount = parseInt(pax) || 0;
  let basePackageTotal = 0;
  let additionalCharges = 0;

  if (activePkg) {
    const pm = (activePkg.pricingMode || activePkg.pricing_mode || '').toLowerCase();
    const tiers = activePkg.priceTiers || activePkg.price_tiers || [];
    const isPerHead = pm === 'per_head' || pm === 'per head' || pm === 'dynamically_set' || pm === 'dynamically set' || (!pm && activePkg.pricePerHead > 0 && !activePkg.fixedPrice);

    if (window.activeTier && window.activeTier.price) {
      basePackageTotal = window.activeTier.price;
    } else if (tiers.length > 0 && !isPerHead) {
      const matched = tiers.find(t => (t.pax === pCount || parseInt(t.label) === pCount));
      basePackageTotal = matched ? matched.price : (tiers[0].price || 0);
    } else if (isPerHead) {
      basePackageTotal = (activePkg.pricePerHead || 0) * pCount;
    } else {
      basePackageTotal = activePkg.fixedPrice || activePkg.price || 0;
    }

    const origItemIds = new Set(activePkg.itemIds || []);
    customPkgItems.forEach(item => {
      const isOriginal = origItemIds.has(item.id);
      if (!isOriginal && !item.isFree && !item.isAutoAdded && !item.isFreebie) {
        additionalCharges += getDynamicPrice(item, pCount);
      }
    });
  } else {
    basePackageTotal = customPkgItems.reduce((s, i) => s + getDynamicPrice(i, pCount), 0);
  }

  const subtotalBeforeOtc = basePackageTotal + additionalCharges;
  const isOutOfTown = venueLocation && !venueLocation.toLowerCase().includes('malabon');
  const distInfo = (typeof getDistanceFeeRate === 'function')
    ? getDistanceFeeRate(venueLocation, window.lastMapCoords)
    : { percentage: 5 };
  const otcRate = (distInfo.percentage != null ? parseFloat(distInfo.percentage) : 5) / 100;
  const outOfTownCharge = isOutOfTown ? Math.round(subtotalBeforeOtc * otcRate) : 0;
  const finalDisplayTotal = subtotalBeforeOtc + outOfTownCharge;

  const _eventSetupObj = (window.EVENT_SETUPS || []).find(s => s.slug === eventSetupSlug) || null;
  const eventSetupName = _eventSetupObj?.name || eventSetupSlug;

  const updatedItems = customPkgItems.map(i => ({
    ...i,
    snapshotPrice: getDynamicPrice(i, pCount)
  }));
  const updatedNames = updatedItems.map(i => i.name).filter(Boolean);

  const saveBtn = document.querySelector('.btn-finalize');
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = 'Saving modifications...';
  }

  try {
    const { doc, updateDoc } = window.firebaseFns;
    const resDocRef = doc(window.firebaseDB, 'reservations', resId);
    const firestoreUpdate = {
      items: updatedItems,
      custom_items: updatedItems,
      packageItems: updatedNames,
      package_items: updatedNames,
      packageName: activePkg ? activePkg.name : (window._modifyingReservation?.packageName || 'Custom Package'),
      package_name: activePkg ? activePkg.name : (window._modifyingReservation?.packageName || 'Custom Package'),
      amount: String(finalDisplayTotal),
      pax: pCount,
      type: occasion,
      occasion: occasion,
      theme: theme,
      description: desc,
      date: date,
      time: timeframe,
      timeframe: timeframe,
      callTime: callTime,
      call_time: callTime,
      venue: venue,
      venueLocation: venueLocation,
      venue_location: venueLocation,
      coords: window.lastMapCoords || window._modifyingReservation?.coords || null,
      eventSetup: eventSetupName,
      eventSetupSlug: eventSetupSlug,
      event_setup: eventSetupName,
      event_setup_slug: eventSetupSlug,
      isVIP: vipEnabled,
      vipCount: vipCount,
      vipService: vipService,
      outOfTownCharge: outOfTownCharge,
      out_of_town_charge: outOfTownCharge,
      updatedAt: new Date().toISOString(),
      last_modified_by: 'customer'
    };
    await updateDoc(resDocRef, firestoreUpdate);

    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      try {
        await sb.from('reservations').update({
          items: updatedItems,
          custom_items: updatedItems,
          package_items: updatedNames,
          package_name: firestoreUpdate.packageName,
          amount: finalDisplayTotal,
          pax: pCount,
          type: occasion,
          theme: theme,
          description: desc,
          date: date,
          timeframe: timeframe,
          venue: venue,
          venue_location: venueLocation,
          updated_at: new Date().toISOString()
        }).eq('id', resId);

        await sb.from('reservation_items').delete().eq('reservation_id', resId);
        const riRows = updatedItems.map(it => ({
          reservation_id: resId,
          name: it.name,
          cat: it.cat || 'other',
          price: parseFloat(it.price || 0) || 0,
          dynamic_price: parseFloat(it.snapshotPrice || 0) || 0,
          is_free: !!(it.isFree || it.isAutoAdded)
        }));
        if (riRows.length > 0) {
          await sb.from('reservation_items').insert(riRows);
        }
      } catch (sbErr) {
        console.warn('Supabase reservation update notice:', sbErr);
      }
    }

    const returnPage = sessionStorage.getItem('halden_modify_return') || localStorage.getItem('halden_modify_return_backup') || 'customer.html';
    sessionStorage.removeItem('halden_modify_res');
    sessionStorage.removeItem('halden_modify_mode');
    sessionStorage.removeItem('halden_modify_return');
    sessionStorage.removeItem('halden_modify_caller');
    localStorage.removeItem('halden_modify_res_backup');
    localStorage.removeItem('halden_modify_mode_backup');
    localStorage.removeItem('halden_modify_return_backup');
    window._isModifyingActiveReservation = false;
    window._modifyingReservationId = null;
    window._modifyingReservation = null;

    alert('Your package modifications have been successfully saved! The total has been updated to ₱' + finalDisplayTotal.toLocaleString() + '.');
    window.location.href = returnPage;
  } catch (err) {
    console.error('Failed to save reservation modifications:', err);
    alert('Failed to save changes: ' + (err.message || err));
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = 'Save Modification';
    }
  }
};

// ===== RESERVATION LOGS & AUDIT TRAIL TAB (CUSTOMER) =====
window._resdCustLogsPage = 1;

window.changeResdCustLogsPage = function(delta) {
  window._resdCustLogsPage = Math.max(1, (window._resdCustLogsPage || 1) + delta);
  if (typeof window.renderCustomerResdLogsTab === 'function') window.renderCustomerResdLogsTab();
};

window.renderCustomerResdLogsTab = function() {
  const container = document.getElementById('resd-customer-logs-content');
  if (!container) return;

  const esc = (typeof escHtml === 'function') ? escHtml : (s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'));
  window.esc = esc;

  let res = (window.RESERVATIONS || []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  if (!res) {
    const sel = document.getElementById('resd-approved-selector');
    if (sel && sel.value) {
      activeResDetailId = sel.value;
      res = (window.RESERVATIONS || []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
    }
  }
  if (!res && window.activeCustomerReservation) {
    res = window.activeCustomerReservation;
  }
  if (!res && typeof activeCustomerReservation !== 'undefined' && activeCustomerReservation) {
    res = activeCustomerReservation;
  }
  if (!res) {
    container.innerHTML = '<div style="text-align:center; padding:50px 20px; color:var(--cp-text-dim); font-size:13px;">Please choose an active reservation from the dropdown above to view its logs.</div>';
    return;
  }

  const resIdStr = String(res.id);
  const combinedLogs = [];

  // 1. Modification history (combines res.activity_logs from Supabase, res.modification_history, and local storage)
  let modHist = [];
  if (Array.isArray(res.activity_logs)) modHist.push(...res.activity_logs);
  if (Array.isArray(res.modification_history)) {
    res.modification_history.forEach(m => {
      if (!modHist.some(ex => ex.id === m.id || (ex.timestamp === m.timestamp && ex.details === m.details))) {
        modHist.push(m);
      }
    });
  }
  if (res.execution_plan && Array.isArray(res.execution_plan.modification_history)) {
    res.execution_plan.modification_history.forEach(m => {
      if (!modHist.some(ex => ex.id === m.id || (ex.timestamp === m.timestamp && ex.details === m.details))) {
        modHist.push(m);
      }
    });
  }
  try {
    const rawLocal = localStorage.getItem('halden_res_mod_history_' + resIdStr);
    if (rawLocal) {
      const parsedLocal = JSON.parse(rawLocal);
      if (Array.isArray(parsedLocal)) {
        parsedLocal.forEach(pl => {
          if (!modHist.some(m => m.id === pl.id || (m.timestamp === pl.timestamp && m.summary === pl.summary))) {
            modHist.push(pl);
          }
        });
      }
    }
  } catch (e) {}

  modHist.forEach(m => {
    combinedLogs.push({
      id: m.id || ('mod-' + Math.random()),
      timestamp: m.timestamp || new Date().toISOString(),
      date_str: m.date_str || new Date(m.timestamp || Date.now()).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
      time_str: m.time_str || new Date(m.timestamp || Date.now()).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
      modified_by: m.modified_by || 'Customer',
      action: 'Package / Reservation Modification',
      badge_color: m.modified_by === 'Admin' ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-blue, #3b82f6)',
      items_added: m.items_added || [],
      items_removed: m.items_removed || [],
      items_customized: m.items_customized || [],
      field_changes: m.field_changes || [],
      details: m.summary || 'Reservation details updated.'
    });
  });

  // 2. Logging of Activities in Logistics Timeline (completed tasks)
  const timelineTasks = Array.isArray(res.timelineTasks) ? res.timelineTasks : [];
  timelineTasks.forEach((t, tIdx) => {
    if (t.status === 'done' || t.autoCheck) {
      const logTime = t.logAt ? new Date(t.logAt) : (t.date ? new Date(t.date + 'T09:00:00') : new Date());
      combinedLogs.push({
        id: 'timeline-' + (t.id || tIdx),
        timestamp: isNaN(logTime.getTime()) ? new Date().toISOString() : logTime.toISOString(),
        date_str: isNaN(logTime.getTime()) ? (t.date || '—') : logTime.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
        time_str: isNaN(logTime.getTime()) ? '' : logTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
        modified_by: 'Logistics / Operations',
        action: 'Logistics Activity Completed',
        badge_color: 'var(--cp-green, #22c55e)',
        items_added: [],
        items_removed: [],
        items_customized: [],
        field_changes: [],
        details: `Milestone: ${(t.milestoneId || 'Logistics Preparation').toUpperCase()} — "${t.title || 'Operational Task'}" completed and verified.`
      });
    }
  });

  // 3. Admin Activity Logs from global store filtered STRICTLY for this reservation only (never broad client match)
  let adminLogs = window.ADMIN_ACTIVITY_LOGS;
  if (!Array.isArray(adminLogs) || adminLogs.length === 0) {
    try {
      const rawAdminLogs = localStorage.getItem('halden_admin_activity_logs');
      if (rawAdminLogs) adminLogs = JSON.parse(rawAdminLogs);
    } catch (e) {}
  }
  const globalLogs = (Array.isArray(adminLogs) ? adminLogs : []).filter(l => {
    if (!l) return false;
    if (l.reservation_id && (String(l.reservation_id) === resIdStr || l.reservation_id === res.id)) return true;
    const det = String(l.details || '');
    return det.includes('#' + resIdStr) || det.includes(resIdStr);
  });

  globalLogs.forEach(gl => {
    const logTime = gl.time ? new Date(gl.time) : (gl.created_at ? new Date(gl.created_at) : new Date());
    if (!combinedLogs.some(c => c.timestamp === gl.time && c.details === gl.details)) {
      combinedLogs.push({
        id: gl.id || ('act-' + Math.random()),
        timestamp: isNaN(logTime.getTime()) ? new Date().toISOString() : logTime.toISOString(),
        date_str: isNaN(logTime.getTime()) ? '—' : logTime.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
        time_str: isNaN(logTime.getTime()) ? '' : logTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
        modified_by: gl.admin_name || gl.actor || 'Admin',
        action: gl.action || 'Activity Log',
        badge_color: 'var(--cp-gold, #c49a3c)',
        items_added: [],
        items_removed: [],
        items_customized: [],
        field_changes: [],
        details: gl.details || 'Reservation activity recorded by Admin.'
      });
    }
  });

  // Sort chronologically descending
  combinedLogs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  if (combinedLogs.length === 0 && !res._logsLoadedFromDb) {
    res._logsLoadedFromDb = true;
    container.innerHTML = `
      <div style="text-align:center; padding:40px 20px; color:var(--cp-text-dim);">
        <div style="font-size:13px; color:var(--cp-text);">Loading reservation activity logs...</div>
      </div>`;
    (async () => {
      try {
        let fetchedLogs = null;
        if (window.supabaseClient && res.id) {
          const { data } = await window.supabaseClient.from('reservations').select('activity_logs').eq('id', res.id).maybeSingle();
          if (data && Array.isArray(data.activity_logs) && data.activity_logs.length > 0) {
            fetchedLogs = data.activity_logs;
          }
        }
        if (!fetchedLogs && window.firebaseDB && window.firebaseFns && res.id) {
          const { doc, getDoc } = window.firebaseFns;
          const snap = await getDoc(doc(window.firebaseDB, 'reservations', String(res.id)));
          if (snap && snap.exists()) {
            const d = snap.data();
            fetchedLogs = d.activity_logs || d.modification_history;
          }
        }
        if (fetchedLogs && Array.isArray(fetchedLogs) && fetchedLogs.length > 0) {
          res.activity_logs = fetchedLogs;
          res.modification_history = fetchedLogs;
          try {
            localStorage.setItem('halden_res_mod_history_' + resIdStr, JSON.stringify(fetchedLogs));
          } catch (e) {}
        }
      } catch (e) {
        console.warn('[Customer Logs] Error fetching logs:', e);
      }
      if (typeof window.renderCustomerResdLogsTab === 'function') {
        window.renderCustomerResdLogsTab();
      }
    })();
    return;
  }

  if (combinedLogs.length === 0) {
    container.innerHTML = `
      <div style="text-align:center; padding:50px 20px; color:var(--cp-text-dim);">
        <div style="font-size:15px; font-weight:600; color:var(--cp-text);">No Logs Recorded Yet</div>
        <div style="font-size:12px; margin-top:6px;">Package modifications and completed logistics tasks will be tracked here automatically.</div>
      </div>`;
    return;
  }

  // 20 rows per page pagination
  const pageSize = 20;
  const totalLogs = combinedLogs.length;
  const totalPages = Math.ceil(totalLogs / pageSize);
  let currentPage = window._resdCustLogsPage || 1;
  if (currentPage > totalPages) currentPage = totalPages;
  if (currentPage < 1) currentPage = 1;
  window._resdCustLogsPage = currentPage;

  const startIdx = (currentPage - 1) * pageSize;
  const endIdx = Math.min(startIdx + pageSize, totalLogs);
  const pagedLogs = combinedLogs.slice(startIdx, endIdx);

  const rowsHtml = pagedLogs.map((log, rowIdx) => {
    let changeBreakdownHtml = '';
    const parts = [];

    if (log.field_changes && log.field_changes.length > 0) {
      log.field_changes.forEach(fc => {
        parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--cp-text, #fff); line-height:1.4;"><span style="font-weight:700; color:var(--cp-gold, #c49a3c);">&bull; </span>${esc(fc)}</div>`);
      });
    }
    if (log.items_added && log.items_added.length > 0) {
      parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--cp-green, #22c55e); line-height:1.4;"><span style="font-weight:700;">&bull; Added Items: </span>${esc(log.items_added.join(', '))}</div>`);
    }
    if (log.items_removed && log.items_removed.length > 0) {
      parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--cp-red, #ef4444); line-height:1.4;"><span style="font-weight:700;">&bull; Removed Items: </span>${esc(log.items_removed.join(', '))}</div>`);
    }
    if (log.items_customized && log.items_customized.length > 0) {
      log.items_customized.forEach(c => {
        parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--cp-gold, #c49a3c); line-height:1.4;"><span style="font-weight:700;">&bull; Customization: </span>${esc(c)}</div>`);
      });
    }

    if (parts.length > 0) {
      changeBreakdownHtml = parts.join('');
    } else {
      changeBreakdownHtml = `<div style="color:var(--cp-text-dim);">${esc(log.details)}</div>`;
    }

    return `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.05); font-size:12px; transition:background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.02)'" onmouseout="this.style.background='transparent'">
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top;">
          <div style="font-weight:700; color:var(--cp-text);">${esc(log.date_str)}</div>
          <div style="font-family:monospace; font-size:11px; color:var(--cp-text-dim); margin-top:2px;">${esc(log.time_str || '—')}</div>
        </td>
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top;">
          <span style="font-weight:700; color:${log.badge_color}; font-size:12px;">${esc(log.modified_by)}</span>
        </td>
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top; font-weight:600; color:var(--cp-text);">
          ${esc(log.action)}
        </td>
        <td style="padding:12px 14px; vertical-align:top; line-height:1.45;">
          ${changeBreakdownHtml}
        </td>
      </tr>`;
  }).join('');

  container.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; flex-wrap:wrap; gap:10px;">
      <div style="font-size:13px; color:var(--cp-text-dim);">
        Showing <strong style="color:var(--cp-text);">${startIdx + 1} - ${endIdx}</strong> of <strong style="color:var(--cp-text);">${totalLogs}</strong> logs
      </div>
      <div style="display:flex; align-items:center; gap:8px;">
        <button class="btn-outline" onclick="changeResdCustLogsPage(-1)" ${currentPage <= 1 ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : 'style="cursor:pointer;"'} style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; border:1px solid var(--cp-border); background:var(--cp-bg3); color:var(--cp-text);">
          Previous
        </button>
        <span style="font-size:12px; color:var(--cp-text-dim); font-weight:600;">
          Page ${currentPage} of ${totalPages}
        </span>
        <button class="btn-outline" onclick="changeResdCustLogsPage(1)" ${currentPage >= totalPages ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : 'style="cursor:pointer;"'} style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; border:1px solid var(--cp-border); background:var(--cp-bg3); color:var(--cp-text);">
          Next
        </button>
      </div>
    </div>
    <div style="border:1px solid var(--cp-border); border-radius:8px; overflow-x:auto;">
      <table style="width:100%; border-collapse:collapse; text-align:left;">
        <thead>
          <tr style="background:rgba(0,0,0,0.25); border-bottom:1px solid var(--cp-border);">
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--cp-text-dim); text-transform:uppercase; letter-spacing:0.5px;">Date &amp; Time</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--cp-text-dim); text-transform:uppercase; letter-spacing:0.5px;">Modified By</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--cp-text-dim); text-transform:uppercase; letter-spacing:0.5px;">Activity / Action</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--cp-text-dim); text-transform:uppercase; letter-spacing:0.5px;">Details of Changes</th>
          </tr>
        </thead>
        <tbody>
          ${rowsHtml}
        </tbody>
      </table>
    </div>
    <div style="display:flex; justify-content:space-between; align-items:center; margin-top:14px; font-size:12px; color:var(--cp-text-dim);">
      <span>Paging limit: 20 rows per page</span>
      <span>Total: ${totalLogs} recorded logs</span>
    </div>`;
};

window.switchCustomerResdInnerTab = function(tab) {
  const isDashboard = tab !== 'logs';
  const dashBtn = document.getElementById('c-resd-inner-tab-dashboard');
  const logsBtn = document.getElementById('c-resd-inner-tab-logs');
  const dashContent = document.getElementById('resd-content');
  const logsContent = document.getElementById('resd-customer-logs-content');
  const modBtn = document.getElementById('resd-modify-btn');
  const expBtn = document.getElementById('resd-export-btn');
  const cancelBtn = document.getElementById('resd-req-cancel-btn');
  const saveBtn = document.getElementById('resd-save-mod-btn');
  const cancelModBtn = document.getElementById('resd-cancel-mod-btn');

  if (dashBtn) {
    dashBtn.classList.toggle('active', isDashboard);
    dashBtn.style.color = isDashboard ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-text-dim, #999)';
    dashBtn.style.borderBottom = isDashboard ? '2px solid var(--cp-gold, #c49a3c)' : '2px solid transparent';
  }
  if (logsBtn) {
    logsBtn.classList.toggle('active', !isDashboard);
    logsBtn.style.color = !isDashboard ? 'var(--cp-gold, #c49a3c)' : 'var(--cp-text-dim, #999)';
    logsBtn.style.borderBottom = !isDashboard ? '2px solid var(--cp-gold, #c49a3c)' : '2px solid transparent';
  }

  if (dashContent) dashContent.style.display = isDashboard ? 'block' : 'none';
  if (logsContent) logsContent.style.display = !isDashboard ? 'block' : 'none';

  if (!isDashboard) {
    if (modBtn) modBtn.style.display = 'none';
    if (expBtn) expBtn.style.display = 'none';
    if (cancelBtn) cancelBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    if (cancelModBtn) cancelModBtn.style.display = 'none';
    if (typeof window.renderCustomerResdLogsTab === 'function') {
      window.renderCustomerResdLogsTab();
    }
  } else {
    if (modBtn) modBtn.style.display = window.customerModifyMode ? 'none' : 'inline-flex';
    if (expBtn) expBtn.style.display = window.customerModifyMode ? 'none' : 'inline-flex';
    if (saveBtn) saveBtn.style.display = window.customerModifyMode ? 'inline-flex' : 'none';
    if (cancelModBtn) cancelModBtn.style.display = window.customerModifyMode ? 'inline-flex' : 'none';
    const selRes = (window.RESERVATIONS || []).find(r => r.id === activeResDetailId);
    if (typeof window.updateCustomerResDetailCancelButtons === 'function') {
      window.updateCustomerResDetailCancelButtons(selRes);
    }
  }
};
